class Fraction {
  int _numerator;
  int _denominator;

  Fraction(this._numerator, this._denominator) {
    if (_denominator == 0) {
      throw ArgumentError('Denominator cannot be zero');
    }
    _reduce();
  }

  void _reduce() {
    int gcdValue = _gcd(_numerator.abs(), _denominator.abs());
    _numerator ~/= gcdValue;
    _denominator ~/= gcdValue;
    if (_denominator < 0) {
      _numerator = -_numerator;
      _denominator = -_denominator;
    }
  }

  int _gcd(int a, int b) {
    while (b != 0) {
      int temp = b;
      b = a % b;
      a = temp;
    }
    return a;
  }

  Fraction operator +(Fraction other) {
    int newNumerator = _numerator * other._denominator + other._numerator * _denominator;
    int newDenominator = _denominator * other._denominator;
    return Fraction(newNumerator, newDenominator);
  }

  Fraction operator -(Fraction other) {
    int newNumerator = _numerator * other._denominator - other._numerator * _denominator;
    int newDenominator = _denominator * other._denominator;
    return Fraction(newNumerator, newDenominator);
  }

  Fraction operator *(Fraction other) {
    int newNumerator = _numerator * other._numerator;
    int newDenominator = _denominator * other._denominator;
    return Fraction(newNumerator, newDenominator);
  }

  Fraction operator /(Fraction other) {
    if (other._numerator == 0) {
      throw ArgumentError('Cannot divide by zero');
    }
    int newNumerator = _numerator * other._denominator;
    int newDenominator = _denominator * other._numerator;
    return Fraction(newNumerator, newDenominator);
  }

  @override
  String toString() {
    if (_denominator == 1) {
      return '$_numerator';
    }
    return '$_numerator/$_denominator';
  }
}

