  List<int> arr = [170, 45, 75, 90, 802, 24, 2, 66];

  print('Original array: $arr');

  // Find the maximum number to know the number of digits
  int getMax(List<int> arr) {
    int mx = arr[0];
    for (int i = 1; i < arr.length; i++) {
      if (arr[i] > mx) mx = arr[i];
    }
    return mx;
  }

  // A function to do counting sort of arr[] according to
  // the digit represented by exp.
  void countingSort(List<int> arr, int exp) {
    int n = arr.length;
    List<int> output = List<int>.filled(n, 0);
    List<int> count = List<int>.filled(10, 0);

    // Store count of occurrences in count[]
    for (int i = 0; i < n; i++) {
      int digit = (arr[i] ~/ exp) % 10;
      count[digit]++;
    }

    // Change count[i] so that count[i] now contains actual
    // position of this digit in output[]
    for (int i = 1; i < 10; i++) {
      count[i] += count[i - 1];
    }

    // Build the output array
    for (int i = n - 1; i >= 0; i--) {
      int digit = (arr[i] ~/ exp) % 10;
      output[count[digit] - 1] = arr[i];
      count[digit]--;
    }

    // Copy the output array to arr[], so that arr[] now
    // contains sorted numbers according to current digit
    for (int i = 0; i < n; i++) {
      arr[i] = output[i];
    }
  }

  // The main function to that sorts arr[] using Radix Sort
  void radixSort(List<int> arr) {
    int m = getMax(arr);

    // Do counting sort for every digit. Note that instead
    // of passing digit number, exp is passed. exp is 10^i
    // where i is current digit number
    for (int exp = 1; m ~/ exp > 0; exp *= 10) {
      countingSort(arr, exp);
    }
  }

  radixSort(arr);

  print('Sorted array: $arr');
}

