        }
      }
    }
  }

  // Print the shortest distance matrix
  print('All-pairs shortest path matrix:');
  for (int i = 0; i < n; i++) {
    String row = '';
    for (int j = 0; j < n; j++) {
      if (dist[i][j] == INF) {
        row += 'INF'.padLeft(5);
      } else {
        row += dist[i][j].toString().padLeft(5);
      }
    }
