  // Example graph: vertices are 0,1,2,3
  // Edges: (source, dest, weight)
  final edges = [
    [0, 1, 1],
    [0, 2, 4],
    [1, 2, -3],
    [1, 3, 2],
    [2, 3, 3],
  ];
  const int V = 4; // Number of vertices
  const int E = 5; // Number of edges
  const int source = 0;

  // Initialize distances
  List<double> dist = List.filled(V, double.infinity);
  dist[source] = 0;

  // Bellman-Ford algorithm
  for (int i = 1; i < V; i++) {
    for (int j = 0; j < E; j++) {
      int u = edges[j][0];
      int v = edges[j][1];
      int w = edges[j][2];
      if (dist[u] != double.infinity && dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
      }
    }
  }

  // Check for negative-weight cycles
  bool hasNegativeCycle = false;
  for (int j = 0; j < E; j++) {
    int u = edges[j][0];
    int v = edges[j][1];
    int w = edges[j][2];
    if (dist[u] != double.infinity && dist[u] + w < dist[v]) {
      hasNegativeCycle = true;
      break;
    }
  }

  if (hasNegativeCycle) {
    print('Graph contains a negative-weight cycle');
  } else {
    print('Vertex   Distance from Source');
    for (int i = 0; i < V; i++) {
      print('$i\t\t${dist[i] == double.infinity ? "INF" : dist[i]}');
    }
  }
}

