import 'dart:io';
import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Example array
  List<int> arr = [1, 3, 2, 7, 9, 11, 3, 5, 6, 8];
  int n = arr.length;

  // Precompute log2 for each index
  List<int> log2 = List<int>.filled(n + 1, 0);
  for (int i = 2; i <= n; i++) {
    log2[i] = log2[i >> 1] + 1;
  }

  int K = log2[n] + 1; // max power for sparse table

  // Build Sparse Table
  List<List<int>> st = List.generate(
      n, (_) => List<int>.filled(K, 0),
      growable: false);

  // Initialize 0th column
  for (int i = 0; i < n; i++) {
    st[i][0] = arr[i];
  }

  // Precompute values
  for (int j = 1; j < K; j++) {
    for (int i = 0; i + (1 << j) <= n; i++) {
      st[i][j] = min(st[i][j - 1], st[i + (1 << (j - 1))][j - 1]);
    }
  }

  // RMQ query function
  int query(int l, int r) {
    int len = r - l + 1;
    int j = log2[len];
    return min(st[l][j], st[r - (1 << j) + 1][j]);
  }

  // Example queries
  List<List<int>> queries = [
    [0, 4], // min of [1,3,2,7,9] => 1
    [2, 5], // min of [2,7,9,11] => 2
    [3, 8], // min of [7,9,11,3,5,6] => 3
    [6, 9], // min of [3,5,6,8] => 3
  ];

  for (var q in queries) {
    int l = q[0], r = q[1];
    int result = query(l, r);
    print('RMQ($l, $r) = $result');
  }

