    index[v] = currentIndex;
    lowlink[v] = currentIndex;
    currentIndex++;
    stack.add(v);
    onStack[v] = true;

    for (final w in graph[v] ?? []) {
      if (!index.containsKey(w)) {
        strongConnect(w);
        lowlink[v] = lowlink[v]!.compareTo(lowlink[w]!) > 0 ? lowlink[w]! : lowlink[v]!;
