  final List<Point<int>> sites = List.generate(
    numSites,
    (_) => Point<int>(
      rand.nextInt(width),
      rand.nextInt(height),
    ),
  );

  // Assign a unique character to each site
  final List<String> siteChars = '123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
  if (siteChars.length < numSites) {
    stderr.writeln('Too many sites for available characters.');
    exit(1);
  }

  // Prepare grid for Voronoi assignment
  List<List<String>> grid = List.generate(
    height,
    (_) => List.filled(width, '.'),
  );

  // Brute-force: For each grid cell, assign to nearest site
  for (int y = 0; y < height; y++) {
    for (int x = 0; x < width; x++) {
      double minDist = double.infinity;
      int closestSite = -1;
      for (int i = 0; i < sites.length; i++) {
        final dx = x - sites[i].x;
        final dy = y - sites[i].y;
        final dist = dx * dx + dy * dy; // squared distance
        if (dist < minDist) {
          minDist = dist.toDouble();
          closestSite = i;
        }
      }
      grid[y][x] = siteChars[closestSite];
    }
  }

  // Mark sites with '@'
  for (int i = 0; i < sites.length; i++) {
    final p = sites[i];
    grid[p.y][p.x] = '@';
  }

  // Print the grid
  for (int y = 0; y < height; y++) {
    print(grid[y].join());
  }

  // Print site legend
  print('\nSite legend:');
  for (int i = 0; i < sites.length; i++) {
    print('${siteChars[i]}: (${sites[i].x}, ${sites[i].y})');
  }
}

