import 'dart:math';
import 'dart:io';

class Point {
  final double x, y;
  Point(this.x, this.y);

  @override
  bool operator ==(Object other) =>
      other is Point && x == other.x && y == other.y;

  @override
  int get hashCode => x.hashCode ^ y.hashCode;

  @override
  String toString() => '($x, $y)';
}

class Edge {
  final Point p1, p2;
  Edge(this.p1, this.p2);

  @override
  bool operator ==(Object other) =>
      other is Edge &&
      ((p1 == other.p1 && p2 == other.p2) ||
          (p1 == other.p2 && p2 == other.p1));

  @override
  int get hashCode => p1.hashCode ^ p2.hashCode;

  @override
  String toString() => '[$p1 - $p2]';
}

class Triangle {
  final Point a, b, c;
  Triangle(this.a, this.b, this.c);

  bool containsVertex(Point p) {
    return a == p || b == p || c == p;
  }

  bool circumCircleContains(Point p) {
    // Calculate determinant to check if point is inside circumcircle
    double ax = a.x, ay = a.y;
    double bx = b.x, by = b.y;
    double cx = c.x, cy = c.y;
    double dx = p.x, dy = p.y;

    double a11 = ax - dx;
    double a21 = bx - dx;
    double a31 = cx - dx;

    double a12 = ay - dy;
    double a22 = by - dy;
    double a32 = cy - dy;

    double a13 = (ax - dx) * (ax - dx) + (ay - dy) * (ay - dy);
    double a23 = (bx - dx) * (bx - dx) + (by - dy) * (by - dy);
    double a33 = (cx - dx) * (cx - dx) + (cy - dy) * (cy - dy);

    double det = (a11 * (a22 * a33 - a23 * a32) -
        a21 * (a12 * a33 - a13 * a32) +
        a31 * (a12 * a23 - a13 * a22));
    return det > 1e-12;
  }

  List<Edge> get edges => [
        Edge(a, b),
        Edge(b, c),
        Edge(c, a),
      ];

  @override
  bool operator ==(Object other) =>
      other is Triangle &&
      ((a == other.a || a == other.b || a == other.c) &&
          (b == other.a || b == other.b || b == other.c) &&
          (c == other.a || c == other.b || c == other.c));

  @override
  int get hashCode => a.hashCode ^ b.hashCode ^ c.hashCode;

  @override
  String toString() => 'Triangle($a, $b, $c)';
}

@pragma('vm:entry-point')
void main() {
  // Example: Random points in a square
  final random = Random(42);
  int n = 10;
  List<Point> points = List.generate(
      n, (_) => Point(random.nextDouble() * 500, random.nextDouble() * 500));

  // Super triangle: large enough to contain all points
  double minX = points.map((p) => p.x).reduce(min);
  double minY = points.map((p) => p.y).reduce(min);
  double maxX = points.map((p) => p.x).reduce(max);
  double maxY = points.map((p) => p.y).reduce(max);
  double dx = maxX - minX, dy = maxY - minY;
  double deltaMax = max(dx, dy) * 10;

  Point p1 = Point(minX - deltaMax, minY - 3 * deltaMax);
  Point p2 = Point(minX + dx / 2, maxY + 3 * deltaMax);
  Point p3 = Point(maxX + deltaMax, minY - 3 * deltaMax);

  List<Triangle> triangles = [Triangle(p1, p2, p3)];

  for (var point in points) {
    List<Triangle> badTriangles = [];
    for (var triangle in triangles) {
      if (triangle.circumCircleContains(point)) {
        badTriangles.add(triangle);
      }
    }

    // Find the polygonal hole boundary (unique edges)
    List<Edge> polygon = [];
    for (var triangle in badTriangles) {
      for (var edge in triangle.edges) {
        bool isShared = false;
        for (var other in badTriangles) {
          if (other == triangle) continue;
          if (other.edges.contains(edge)) {
            isShared = true;
            break;
          }
        }
        if (!isShared) {
          polygon.add(edge);
        }
      }
    }

    // Remove bad triangles
    triangles.removeWhere((t) => badTriangles.contains(t));

    // Re-triangulate the polygonal hole
    for (var edge in polygon) {
      triangles.add(Triangle(edge.p1, edge.p2, point));
    }
  }

  // Remove triangles that include super triangle vertices
  triangles.removeWhere((t) =>
      t.containsVertex(p1) || t.containsVertex(p2) || t.containsVertex(p3));

  // Output result
  print('Delaunay Triangulation of $n points:');
  for (var t in triangles) {
    print('${t.a} - ${t.b} - ${t.c}');
  }

  // Optionally, output as SVG for visualization
  File('triangulation.svg').writeAsStringSync(_svg(points, triangles));
  print('SVG output to triangulation.svg');
}

// Simple SVG output for visualization
String _svg(List<Point> points, List<Triangle> triangles) {
  double minX = points.map((p) => p.x).reduce(min);
  double minY = points.map((p) => p.y).reduce(min);
