          table1[idx] = curKey;
          curKey = temp;
          table = 1;
        }
      } else {
        int idx = hash2(curKey);
        if (table2[idx] == null) {
          table2[idx] = curKey;
          return true;
        } else if (table2[idx] == curKey) {
