import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Simple Tic-Tac-Toe game representation for alpha-beta pruning demo

  // Board: 0 = empty, 1 = maximizer (X), -1 = minimizer (O)
  List<List<int>> board = [
    [0, 0, 0],
    [0, 0, 0],
    [0, 0, 0],
  ];

  // Returns a list of empty positions as [row, col]
  List<List<int>> getAvailableMoves(List<List<int>> b) {
    List<List<int>> moves = [];
    for (int i = 0; i < 3; ++i) {
      for (int j = 0; j < 3; ++j) {
        if (b[i][j] == 0) moves.add([i, j]);
      }
    }
    return moves;
  }

  // Returns 1 if maximizer wins, -1 if minimizer wins, 0 if draw or ongoing
  int evaluate(List<List<int>> b) {
    // Rows, cols, diagonals
    for (int i = 0; i < 3; ++i) {
      if (b[i][0] != 0 && b[i][0] == b[i][1] && b[i][1] == b[i][2]) return b[i][0];
      if (b[0][i] != 0 && b[0][i] == b[1][i] && b[1][i] == b[2][i]) return b[0][i];
    }
    if (b[0][0] != 0 && b[0][0] == b[1][1] && b[1][1] == b[2][2]) return b[0][0];
    if (b[0][2] != 0 && b[0][2] == b[1][1] && b[1][1] == b[2][0]) return b[0][2];
    return 0;
  }

  // Checks if game is over
  bool isTerminal(List<List<int>> b) {
    return evaluate(b) != 0 || getAvailableMoves(b).isEmpty;
  }

  // Alpha-beta pruning
  int alphaBeta(List<List<int>> b, int depth, int alpha, int beta, bool maximizingPlayer) {
    int eval = evaluate(b);
    if (eval != 0 || getAvailableMoves(b).isEmpty) {
      // Terminal state
      return eval;
    }

    if (maximizingPlayer) {
      int maxEval = -999;
      for (var move in getAvailableMoves(b)) {
        b[move[0]][move[1]] = 1;
        int eval = alphaBeta(b, depth + 1, alpha, beta, false);
        b[move[0]][move[1]] = 0;
        maxEval = max(maxEval, eval);
        alpha = max(alpha, eval);
        if (beta <= alpha) break;
      }
      return maxEval;
    } else {
      int minEval = 999;
      for (var move in getAvailableMoves(b)) {
        b[move[0]][move[1]] = -1;
        int eval = alphaBeta(b, depth + 1, alpha, beta, true);
        b[move[0]][move[1]] = 0;
        minEval = min(minEval, eval);
        beta = min(beta, eval);
        if (beta <= alpha) break;
      }
      return minEval;
    }
  }

  // Find best move for maximizer (X)
  List<int> findBestMove(List<List<int>> b) {
    int bestVal = -999;
    List<int> bestMove = [-1, -1];
    for (var move in getAvailableMoves(b)) {
      b[move[0]][move[1]] = 1;
      int moveVal = alphaBeta(b, 0, -1000, 1000, false);
      b[move[0]][move[1]] = 0;
      if (moveVal > bestVal) {
        bestVal = moveVal;
        bestMove = move;
      }
    }
    return bestMove;
  }

  // Play a demo game: maximizer (X) uses alpha-beta, minimizer (O) picks random move
  Random rng = Random();
  int turn = 1; // 1: maximizer, -1: minimizer

  void printBoard(List<List<int>> b) {
    for (int i = 0; i < 3; ++i) {
      print(b[i].map((v) => v == 1 ? 'X' : v == -1 ? 'O' : '.').join(' '));
    }
    print('');
  }

  print('Initial board:');
  printBoard(board);

  while (!isTerminal(board)) {
    if (turn == 1) {
      List<int> move = findBestMove(board);
      board[move[0]][move[1]] = 1;
      print('Maximizer (X) plays: ${move[0]}, ${move[1]}');
    } else {
      var moves = getAvailableMoves(board);
      var move = moves[rng.nextInt(moves.length)];
      board[move[0]][move[1]] = -1;
      print('Minimizer (O) plays: ${move[0]}, ${move[1]}');
    }
    printBoard(board);
    turn = -turn;
  }

  int result = evaluate(board);
  if (result == 1) {
    print('Maximizer (X) wins!');
  } else if (result == -1) {
    print('Minimizer (O) wins!');
  } else {
    print('Draw!');
  }
}

