import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Example data: 2D points
  List<List<double>> data = [
    [1.0, 2.0],
    [2.0, 2.0],
    [2.0, 3.0],
    [8.0, 7.0],
    [8.0, 8.0],
    [25.0, 80.0],
    [24.0, 79.0],
    [25.5, 80.5],
    [8.5, 8.5],
    [1.5, 2.5],
    [2.5, 2.0],
    [7.0, 7.0],
    [7.5, 7.5],
  ];

  double eps = 2.0; // Neighborhood radius
  int minPts = 2;   // Minimum points to form a dense region

  List<int> labels = dbscan(data, eps, minPts);

  for (int i = 0; i < data.length; i++) {
    print('Point ${data[i]} -> Cluster ${labels[i]}');
  }
}

double euclideanDistance(List<double> a, List<double> b) {
  double sum = 0.0;
  for (int i = 0; i < a.length; i++) {
    sum += pow(a[i] - b[i], 2);
  }
  return sqrt(sum);
}

List<int> dbscan(List<List<double>> data, double eps, int minPts) {
  int n = data.length;
  List<int> labels = List.filled(n, 0); // 0 = unclassified
  int clusterId = 0;

  for (int i = 0; i < n; i++) {
    if (labels[i] != 0) continue; // Already processed

    List<int> neighbors = regionQuery(data, i, eps);

    if (neighbors.length < minPts) {
      labels[i] = -1; // Mark as noise
    } else {
      clusterId++;
      expandCluster(data, labels, i, neighbors, clusterId, eps, minPts);
    }
  }

  return labels;
}

void expandCluster(
    List<List<double>> data,
    List<int> labels,
    int pointIdx,
    List<int> neighbors,
    int clusterId,
    double eps,
    int minPts) {
  labels[pointIdx] = clusterId;

  List<int> seeds = List.from(neighbors);

  int index = 0;
  while (index < seeds.length) {
    int current = seeds[index];

    if (labels[current] == -1) {
      labels[current] = clusterId; // Change noise to border point
    }
    if (labels[current] == 0) {
      labels[current] = clusterId;
      List<int> currentNeighbors = regionQuery(data, current, eps);
      if (currentNeighbors.length >= minPts) {
        // Add new neighbors to seeds
        for (int neighbor in currentNeighbors) {
          if (!seeds.contains(neighbor)) {
            seeds.add(neighbor);
          }
        }
      }
    }
    index++;
  }
}

List<int> regionQuery(List<List<double>> data, int pointIdx, double eps) {
  List<int> neighbors = [];
  for (int i = 0; i < data.length; i++) {
    if (euclideanDistance(data[pointIdx], data[i]) <= eps) {
      neighbors.add(i);
    }
  }
  return neighbors;
}

