  Stream<int> asyncNumbers() async* {
    for (var i = 1; i <= 3; i++) {
      await Future.delayed(Duration(milliseconds: 100));
      yield i;
    }
  }

  // Async generator that yields numbers 100 and 200, then delegates to asyncNumbers
  Stream<int> combinedAsyncGenerator() async* {
    yield 100;
    yield 200;
    yield* asyncNumbers(); // Delegates yielding to another async generator
    yield 300;
  }

  print('Async generator output:');
  await for (var value in combinedAsyncGenerator()) {
    print(value);
  }
}

