void main() {
  // Wildcard pattern matching function using dynamic programming
  bool isMatch(String text, String pattern) {
    int n = text.length;
    int m = pattern.length;

    // dp[i][j] indicates if text[0..i-1] matches pattern[0..j-1]
    List<List<bool>> dp = List.generate(n + 1, (_) => List.filled(m + 1, false));
    dp[0][0] = true; // Empty pattern matches empty text

    // Handle patterns with leading '*' (e.g., *, **, ***)
    for (int j = 1; j <= m; j++) {
      if (pattern[j - 1] == '*') {
        dp[0][j] = dp[0][j - 1];
      }
    }

    // Fill the DP table
    for (int i = 1; i <= n; i++) {
      for (int j = 1; j <= m; j++) {
        if (pattern[j - 1] == '?' || pattern[j - 1] == text[i - 1]) {
          // Match with '?' or exact character
          dp[i][j] = dp[i - 1][j - 1];
        } else if (pattern[j - 1] == '*') {
          // Match with '*': either ignore '*' or use it to match one character
          dp[i][j] = dp[i][j - 1] || dp[i - 1][j];
        }
        // Else, false by default (already initialized)
      }
    }

    return dp[n][m];
  }

  // Test cases for various scenarios
  List<Map<String, String>> tests = [
    {'text': 'abcdef', 'pattern': 'a*d*f'},
    {'text': 'abcdef', 'pattern': 'a?c*'},
    {'text': 'abcdef', 'pattern': 'a*f?'},
    {'text': 'abcdef', 'pattern': 'a*e?'},
    {'text': 'abcdef', 'pattern': '*'},
    {'text': 'abcdef', 'pattern': 'a?b?c?d?e?f?'},
    {'text': 'abcdef', 'pattern': 'a*c?'},
    {'text': 'abcdef', 'pattern': 'a*d?g'},
    {'text': '', 'pattern': '*'},
    {'text': '', 'pattern': '?'},
    {'text': 'a', 'pattern': '?'},
    {'text': 'a', 'pattern': '*?'},
    {'text': '', 'pattern': ''},
    {'text': 'abc', 'pattern': 'abc*'},
    {'text': 'abc', 'pattern': '*abc'},
    {'text': 'abc', 'pattern': '*a*'},
    {'text': 'abc', 'pattern': '*b*'},
    {'text': 'abc', 'pattern': '*d*'},
    {'text': 'abc', 'pattern': 'a*?c'},
    {'text': 'abc', 'pattern': '*?*?*?*'},
  ];

  // Run tests and print results
  for (var test in tests) {
    String text = test['text']!;
    String pattern = test['pattern']!;
    bool matched = isMatch(text, pattern);
    print('Text: "$text", Pattern: "$pattern" => Match: $matched');
  }
