    mainSendPort.send(port.sendPort);

    // Listen for messages from the main isolate
    await for (var message in port) {
      if (message is String) {
        // Echo the message back with a modification
        mainSendPort.send('Isolate received: $message');
      } else if (message == null) {
        // Null message signals to exit
        port.close();
        break;
      }
    }
  }

  // Create a port to receive messages from the isolate
  final receivePort = ReceivePort();

  // Spawn the isolate, passing it our send port
  await Isolate.spawn(isolateEntry, receivePort.sendPort);

  // Get the send port to communicate with the isolate
  final isolateSendPort = await receivePort.first as SendPort;

  // Send a message to the isolate
  isolateSendPort.send('Hello from main!');

  // Listen for a response from the isolate
  final response = await receivePort.first;
  print(response); // Should print: Isolate received: Hello from main!

  // Tell the isolate to exit
  isolateSendPort.send(null);

  // Cleanup
  receivePort.close();
}

