    final choice = int.tryParse(input.trim());
    if (choice == null || choice < 1 || choice > products.length) {
      print('Invalid input. Please try again.\n');
      continue;
    }
    final selectedKey = products.keys.elementAt(choice - 1);
    if (purchased.contains(selectedKey)) {
