import 'dart:io';

@pragma('vm:entry-point')
void main() async {
  print('Simple Calendar Integration Example');
  print('-----------------------------------');
  print('This script will create a basic .ics calendar event file.');
  stdout.write('Enter event title: ');
  final title = stdin.readLineSync() ?? 'Untitled Event';

  stdout.write('Enter event location: ');
  final location = stdin.readLineSync() ?? '';

  stdout.write('Enter event description: ');
  final description = stdin.readLineSync() ?? '';

  stdout.write('Enter start date and time (YYYY-MM-DD HH:MM): ');
  final startInput = stdin.readLineSync();
  DateTime? start;
  try {
    start = DateTime.parse(startInput!.replaceFirst(' ', 'T'));
  } catch (_) {
    print('Invalid start date. Using current time.');
    start = DateTime.now();
  }

  stdout.write('Enter end date and time (YYYY-MM-DD HH:MM): ');
  final endInput = stdin.readLineSync();
  DateTime? end;
  try {
    end = DateTime.parse(endInput!.replaceFirst(' ', 'T'));
  } catch (_) {
    print('Invalid end date. Using start time + 1 hour.');
    end = start.add(Duration(hours: 1));
  }

  String _formatDateTime(DateTime dt) {
    // Format as YYYYMMDDTHHMMSSZ (UTC)
    return dt.toUtc().toIso8601String().replaceAll('-', '').replaceAll(':', '').split('.').first + 'Z';
  }

  final now = DateTime.now().toUtc();
  final uid = '${now.microsecondsSinceEpoch}@dart_calendar';
  final ics = '''
BEGIN:VCALENDAR
VERSION:2.0
PRODID:-//Dart Calendar Integration Example//EN
BEGIN:VEVENT
UID:$uid
DTSTAMP:${_formatDateTime(now)}
DTSTART:${_formatDateTime(start)}
DTEND:${_formatDateTime(end)}
SUMMARY:${title.replaceAll('\n', ' ')}
LOCATION:${location.replaceAll('\n', ' ')}
DESCRIPTION:${description.replaceAll('\n', ' ')}
END:VEVENT
END:VCALENDAR
''';

  final file = File('event.ics');
  await file.writeAsString(ics.trim());
  print('\nCalendar event saved to event.ics');
  print('You can import this file into your calendar application.');
}

