import 'dart:io';

void main() {
  final Map<String, String> contacts = {};

  void printMenu() {
    print('\nContact List Integration');
    print('1. Add Contact');
    print('2. View Contacts');
    print('3. Search Contact');
    print('4. Delete Contact');
    print('5. Exit');
    stdout.write('Select an option (1-5): ');
  }

  void addContact() {
    stdout.write('Enter contact name: ');
    final name = stdin.readLineSync()?.trim();
    if (name == null || name.isEmpty) {
      print('Invalid name.');
      return;
    }
    stdout.write('Enter phone number: ');
    final phone = stdin.readLineSync()?.trim();
    if (phone == null || phone.isEmpty) {
      print('Invalid phone number.');
      return;
    }
    if (contacts.containsKey(name)) {
      print('Contact already exists. Updating phone number.');
    }
    contacts[name] = phone;
    print('Contact saved.');
  }

  void viewContacts() {
    if (contacts.isEmpty) {
      print('No contacts found.');
      return;
    }
    print('\nContacts:');
    contacts.forEach((name, phone) {
      print('- $name: $phone');
    });
  }

  void searchContact() {
    stdout.write('Enter name to search: ');
    final query = stdin.readLineSync()?.trim();
    if (query == null || query.isEmpty) {
      print('Invalid input.');
      return;
    }
    final results = contacts.entries.where((entry) =>
        entry.key.toLowerCase().contains(query.toLowerCase()));
    if (results.isEmpty) {
      print('No contacts found for "$query".');
    } else {
      print('Search results:');
      for (final entry in results) {
        print('- ${entry.key}: ${entry.value}');
      }
    }
  }

  void deleteContact() {
    stdout.write('Enter name to delete: ');
    final name = stdin.readLineSync()?.trim();
    if (name == null || name.isEmpty) {
      print('Invalid input.');
      return;
    }
    if (contacts.remove(name) != null) {
      print('Contact "$name" deleted.');
    } else {
      print('Contact "$name" not found.');
    }
  }

  while (true) {
    printMenu();
