/// Simulates a basic in-app A/B testing mechanism.
/// Assigns users randomly to group 'A' or 'B' and prints the variant to show.
///
/// In a real app, you'd persist the assignment per-user and report analytics.
/// This script demonstrates the core random assignment and variant logic.

@pragma('vm:entry-point')
void main() {
  // Simulate fetching a user ID (could be device ID, user ID, etc.)
  // For demo purposes, we generate a random user ID each run.
  final userId = Random().nextInt(1000000);

  // Assign user to a group based on a hash of their user ID.
  // This ensures the same user gets the same variant each time.
  int hashUserId(int id) {
    // Simple hash: XOR-fold and mod
    int hash = id ^ (id >> 16);
    return hash & 0x7FFFFFFF;
  }

  // Two variants: A and B (50/50 split)
  String assignVariant(int id) {
    int hash = hashUserId(id);
    return (hash % 2 == 0) ? 'A' : 'B';
  }

  // Simulate variant logic
  void showVariant(String variant) {
    if (variant == 'A') {
      print('User #$userId assigned to VARIANT A: Show blue button.');
    } else {
      print('User #$userId assigned to VARIANT B: Show green button.');
    }
  }

  // Run the A/B test assignment and show the variant
  final variant = assignVariant(userId);
  showVariant(variant);

  // In a real app, here you would:
  // - Persist assignment for this user
  // - Track analytics for conversion per variant
  // - Roll out winning variant after test
}

