  List<int> weights = [10, 20, 30];
  int capacity = 50;
  int n = values.length;

  // Create a 2D DP table: dp[i][w] will be the max value for first i items and capacity w
  List<List<int>> dp = List.generate(n + 1, (_) => List<int>.filled(capacity + 1, 0));

  // Fill the DP table
  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {
      // Not taking the item
      dp[i][w] = dp[i - 1][w];

      // Taking the item if possible
      if (weights[i - 1] <= w) {
        dp[i][w] = max(dp[i][w], dp[i - 1][w - weights[i - 1]] + values[i - 1]);
      }
    }
  }

  // The answer is in dp[n][capacity]
  print('Maximum value in Knapsack: ${dp[n][capacity]}');
}

