  // Number of nodes in the DAG
  int numNodes = 6;

  // Adjacency list representation of the graph
  List<List<int>> graph = List.generate(numNodes, (_) => <int>[]);
  graph[5].add(2);
  graph[5].add(0);
  graph[4].add(0);
  graph[4].add(1);
  graph[2].add(3);
  graph[3].add(1);

  // Compute indegrees
  List<int> indegree = List.filled(numNodes, 0);
  for (int u = 0; u < numNodes; u++) {
    for (int v in graph[u]) {
      indegree[v]++;
    }
  }

  // Queue for nodes with indegree 0
  Queue<int> queue = Queue<int>();
  for (int i = 0; i < numNodes; i++) {
    if (indegree[i] == 0) {
      queue.add(i);
    }
  }

  // List to store the topological order
  List<int> topoOrder = <int>[];

  // Process the queue (Kahn's algorithm)
  while (queue.isNotEmpty) {
    int u = queue.removeFirst();
    topoOrder.add(u);

    for (int v in graph[u]) {
      indegree[v]--;
      if (indegree[v] == 0) {
        queue.add(v);
      }
    }
  }

  // Check if topological sort is possible (no cycles)
  if (topoOrder.length == numNodes) {
    print('Topological Sort: ${topoOrder.join(' ')}');
  } else {
    print('Graph contains a cycle, topological sort not possible.');
  }
}

