  int minVal = arr.reduce(math.min);
  int maxVal = arr.reduce(math.max);
  int range = maxVal - minVal + 1;

  // Step 2: Create count array
  List<int> count = List<int>.filled(range, 0);

  // Step 3: Count occurrences
  for (int num in arr) {
    count[num - minVal]++;
  }

