  print('Sorted array: $sorted');
}

// A complete Dart program implementing Kruskal's Minimum Spanning Tree algorithm.
// The graph is hardcoded in the main function for demonstration.

class Edge implements Comparable<Edge> {
  final int u;
  final int v;
  final int weight;

  Edge(this.u, this.v, this.weight);

  @override
  int compareTo(Edge other) {
    return weight - other.weight;
  }

  @override
  String toString() {
    return 'Edge($u - $v: $weight)';
  }
}

class UnionFind {
  late List<int> parent;
  late List<int> rank;

  UnionFind(int size) {
    parent = List<int>.generate(size, (i) => i);
    rank = List<int>.filled(size, 0);
  }

  int find(int x) {
    if (parent[x] != x) {
      parent[x] = find(parent[x]);
    }
    return parent[x];
  }

  bool union(int x, int y) {
    int rootX = find(x);
    int rootY = find(y);
    if (rootX == rootY) {
      return false; // Already in same set, would form cycle
    }
    if (rank[rootX] < rank[rootY]) {
      parent[rootX] = rootY;
    } else if (rank[rootX] > rank[rootY]) {
      parent[rootY] = rootX;
    } else {
      parent[rootY] = rootX;
      rank[rootX]++;
    }
    return true;
  }
}

@pragma('vm:entry-point')
void main() {
  // Sample graph: 4 vertices (0 to 3), undirected weighted edges
  List<Edge> edges = [
    Edge(0, 1, 10),
    Edge(0, 2, 6),
    Edge(0, 3, 5),
    Edge(1, 3, 15),
    Edge(2, 3, 4),
  ];

  int numVertices = 4; // Number of vertices in the graph

  // Sort edges by weight
  edges.sort();

  // Initialize Union-Find
  UnionFind uf = UnionFind(numVertices);

  // List to hold MST edges
  List<Edge> mst = [];
  int totalWeight = 0;

  // Kruskal's algorithm
  for (Edge edge in edges) {
    if (uf.union(edge.u, edge.v)) {
      mst.add(edge);
      totalWeight += edge.weight;
    }
  }

  // Output the result
  print('Minimum Spanning Tree Edges:');
  for (Edge edge in mst) {
    print(edge);
  }
  print('Total Weight: $totalWeight');
}

