  edges.sort((a, b) => a.compareTo(b));

  // Initialize Union-Find data structure
  UnionFind uf = UnionFind(numVertices);

  // List to hold the edges of the MST
  List<Edge> mst = [];
  int totalWeight = 0;

  // Kruskal's algorithm: iterate through sorted edges and add to MST if no cycle
  for (Edge edge in edges) {
    if (uf.union(edge.u, edge.v)) {
      mst.add(edge);
      totalWeight += edge.weight;
    }
  }

  // Output the result
  print('Minimum Spanning Tree Edges:');
  for (Edge edge in mst) {
    print(edge);
  }
