  // Sample input array
  List<int> nums = [10, 9, 2, 5, 3, 7, 101, 18];

  // Implement Longest Increasing Subsequence (LIS) logic (O(n log n) approach)
  if (nums.isEmpty) {
    print('The length of the longest increasing subsequence is 0');
    return;
  }

  List<int> tails = List.filled(nums.length, 0);
  int len = 1;
  tails[0] = nums[0];

  for (int i = 1; i < nums.length; i++) {
    if (nums[i] < tails[0]) {
      // Update the smallest tail
      tails[0] = nums[i];
    } else if (nums[i] > tails[len - 1]) {
      // Extend the subsequence
      tails[len] = nums[i];
      len++;
    } else {
      // Binary search to find the position to replace
      int left = 0;
      int right = len;
      while (left < right) {
        int mid = left + (right - left) ~/ 2;
        if (tails[mid] < nums[i]) {
          left = mid + 1;
        } else {
          right = mid;
        }
      }
      tails[left] = nums[i];
    }
  }

  // Output the result
  print('The length of the longest increasing subsequence is $len');
}

