// A complete Dart program implementing the partition problem using dynamic programming.

@pragma('vm:entry-point')
void main() {
  // Sample input: list of integers
  List<int> nums = [1, 5, 11, 5]; // Should return true (partitions: [1,5,5] and [11])

  // Calculate total sum
  int totalSum = 0;
  for (int num in nums) {
    totalSum += num;
  }

  // If total sum is odd, cannot partition
  if (totalSum % 2 != 0) {
    print(false);
    return;
  }

  // Target sum for each subset
  int target = totalSum ~/ 2;

  // DP array: dp[i] is true if sum i can be achieved with subsets
  List<bool> dp = List<bool>.filled(target + 1, false);
  dp[0] = true; // Sum 0 is always possible

  // Fill DP table
  for (int num in nums) {
    for (int j = target; j >= num; j--) {
      if (dp[j - num]) {
        dp[j] = true;
      }
    }
  }

  // If dp[target] is true, partition is possible
  print(dp[target]);
}

