// A complete Dart program implementing the Traveling Salesman Problem (TSP) using brute force.
// It uses a hardcoded distance matrix for 4 cities and finds the minimum cost path by checking all permutations.

@pragma('vm:entry-point')
void main() {
  // Number of cities
  int n = 4;

  // Distance matrix (symmetric for simplicity)
  List<List<int>> dist = [
    [0, 10, 15, 20],
    [10, 0, 35, 25],
    [15, 35, 0, 30],
    [20, 25, 30, 0]
  ];

  // Recursive function to generate permutations of the remaining cities
  void generatePermutations(
      List<int> current, List<int> remaining, List<List<int>> results) {
    if (remaining.isEmpty) {
      results.add(List.from(current));
      return;
    }
    for (int i = 0; i < remaining.length; i++) {
      int item = remaining.removeAt(i);
      current.add(item);
      generatePermutations(current, remaining, results);
      current.removeLast();
      remaining.insert(i, item);
    }
  }

  // List of cities to permute (excluding starting city 0)
  List<int> cities = [];
  for (int i = 1; i < n; i++) {
    cities.add(i);
  }

  // Generate all permutations
  List<List<int>> permutations = [];
  generatePermutations([], cities, permutations);

  // Initialize minimum cost and path
  int minCost = 9223372036854775807; // Equivalent to int.maxFinite in Dart
  List<int>? minPath;

  // Check each permutation
  for (var perm in permutations) {
    // Full path: start at 0, visit perm, back to 0
    List<int> path = [0, ...perm, 0];

    // Calculate cost
    int cost = 0;
    for (int i = 0; i < path.length - 1; i++) {
      cost += dist[path[i]][path[i + 1]];
    }

    // Update minimum
    if (cost < minCost) {
      minCost = cost;
      minPath = path;
    }
  }

  // Output the result
  print('Minimum cost: $minCost');
  print('Path: $minPath');
}

