  // Sample graph represented as adjacency matrix.
  // This is a graph with 4 vertices forming a cycle: 0-1-2-3-0, which is 2-colorable.
  // But we'll try to color it with up to 3 colors.
  List<List<int>> graph = [
    [0, 1, 0, 1], // Vertex 0 connected to 1 and 3
    [1, 0, 1, 0], // Vertex 1 connected to 0 and 2
    [0, 1, 0, 1], // Vertex 2 connected to 1 and 3
    [1, 0, 1, 0], // Vertex 3 connected to 0 and 2
  ];

  int numVertices = graph.length;
  int numColors = 3; // Maximum number of colors to use
  List<int> colors = List<int>.filled(numVertices, -1); // -1 means uncolored

  // Function to check if it's safe to assign a color to a vertex
  bool isSafe(int vertex, int color, List<List<int>> graph, List<int> colors) {
    for (int i = 0; i < graph.length; i++) {
      if (graph[vertex][i] == 1 && colors[i] == color) {
        return false;
      }
    }
    return true;
  }

  // Recursive backtracking function to color the graph
  bool graphColoringUtil(int vertex, List<List<int>> graph, List<int> colors, int numColors) {
    // If all vertices are colored, we're done
    if (vertex == graph.length) {
      return true;
    }

    // Try each color for the current vertex
    for (int c = 0; c < numColors; c++) {
      if (isSafe(vertex, c, graph, colors)) {
        colors[vertex] = c;
        // Recurse to the next vertex
        if (graphColoringUtil(vertex + 1, graph, colors, numColors)) {
          return true;
        }
        // Backtrack
        colors[vertex] = -1;
      }
    }

    // If no color can be assigned, return false
    return false;
  }

  // Start coloring from vertex 0
  bool success = graphColoringUtil(0, graph, colors, numColors);

  if (success) {
    print('Graph coloring successful with $numColors colors:');
    for (int i = 0; i < numVertices; i++) {
      print('Vertex $i: Color ${colors[i]}');
    }
  } else {
