// A complete Dart program implementing the Rabin-Karp string searching algorithm.
// This script searches for a pattern in a given text and prints the starting indices of matches.

@pragma('vm:entry-point')
void main() {
  // Example text and pattern
  String text = "ABABDABACDABABCABAB";
  String pattern = "ABAB";

  // Parameters for hashing
  int d = 256; // Number of characters in the input alphabet
  int q = 101; // A prime number for modulo to avoid overflow

  int n = text.length;
  int m = pattern.length;

  if (m > n) {
    print("Pattern longer than text, no matches possible.");
    return;
  }

  // Precompute hash for pattern and first window of text
  int patternHash = 0;
  int textHash = 0;
  int h = 1; // h = d^(m-1) % q

  // Compute h
  for (int i = 0; i < m - 1; i++) {
    h = (h * d) % q;
  }

  // Compute initial hashes
  for (int i = 0; i < m; i++) {
    patternHash = (d * patternHash + pattern.codeUnitAt(i)) % q;
    textHash = (d * textHash + text.codeUnitAt(i)) % q;
  }

  // Slide the pattern over text one by one
  bool found = false;
  for (int i = 0; i <= n - m; i++) {
    // If hashes match, check characters
    if (patternHash == textHash) {
      bool match = true;
      for (int j = 0; j < m; j++) {
        if (text[i + j] != pattern[j]) {
          match = false;
          break;
        }
      }
      if (match) {
        print("Pattern found at index $i");
        found = true;
      }
    }

    // Compute hash for next window
    if (i < n - m) {
      textHash = (d * (textHash - text.codeUnitAt(i) * h) + text.codeUnitAt(i + m)) % q;
      // Handle negative hash (in case modulo makes it negative)
      if (textHash < 0) {
        textHash += q;
      }
    }
  }

