// A complete Dart program implementing the LZW compression and decompression algorithm.
// The program compresses a sample string, prints the compressed codes, decompresses it, and prints the result.

@pragma('vm:entry-point')
void main() {
  // LZW Compression function
  List<int> compress(String uncompressed) {
    // Build the dictionary with ASCII characters
    Map<String, int> dictionary = {};
    for (int i = 0; i < 256; i++) {
      dictionary[String.fromCharCode(i)] = i;
    }

    String w = '';
    List<int> result = [];
    for (String c in uncompressed.split('')) {
      String wc = w + c;
      if (dictionary.containsKey(wc)) {
        w = wc;
      } else {
        result.add(dictionary[w]!);
        // Add new entry to dictionary
        dictionary[wc] = dictionary.length;
        w = c;
      }
    }
    // Add the last code
    if (w.isNotEmpty) {
      result.add(dictionary[w]!);
    }
    return result;
  }

  // LZW Decompression function
  String decompress(List<int> compressed) {
    // Build the dictionary with ASCII characters
    Map<int, String> dictionary = {};
    for (int i = 0; i < 256; i++) {
      dictionary[i] = String.fromCharCode(i);
    }

    String w = dictionary[compressed[0]]!;
    StringBuffer result = StringBuffer()..write(w);

    for (int k in compressed.sublist(1)) {
      String entry;
      if (dictionary.containsKey(k)) {
        entry = dictionary[k]!;
      } else if (k == dictionary.length) {
        entry = w + w[0];
      } else {
        throw Exception('Invalid compressed code: $k');
      }
      result.write(entry);

      // Add new entry to dictionary
      dictionary[dictionary.length] = w + entry[0];
      w = entry;
    }
    return result.toString();
  }

  // Sample input
  String original = "TOBEORNOTTOBEORTOBEORNOT";
  print('Original: $original');

  // Compress
  List<int> compressed = compress(original);
  print('Compressed: $compressed');

  // Decompress
  String decompressed = decompress(compressed);
  print('Decompressed: $decompressed');

  // Verify
  print('Decompression successful: ${original == decompressed}');
}

