  int originalM = m;
  int x = 0;
  int y = 1;
  int lastX = 1;
  int lastY = 0;

  if (m == 1) {
    print('Modular inverse of $a mod $m is 0');
    return;
  }

  while (a != 0) {
    int quotient = m ~/ a;
    int temp = a;
    a = m % a;
    m = temp;

    temp = x;
    x = lastX - quotient * x;
    lastX = temp;

    temp = y;
    y = lastY - quotient * y;
    lastY = temp;
  }

  if (m != 1) {
    print('No modular inverse exists for $a mod $originalM (gcd is $m)');
  } else {
    // Adjust lastY to be positive modulo originalM
    int inverse = (lastY % originalM + originalM) % originalM;
    print('Modular inverse of $a mod $originalM is $inverse');
  }
}

