// A complete Dart program implementing the basics of Heavy-Light Decomposition (HLD) on a sample tree.
// The logic is contained within the main function, with helper functions defined inside for clarity.
// We build a sample tree, compute sizes and depths via DFS, then perform HLD to assign chains and positions.

@pragma('vm:entry-point')
void main() {
  // Sample tree adjacency list (1-based indexing, nodes 1 to 6)
  // Tree structure:
  //       1
  //      / \
  //     2   3
  //    / \   \
  //   4   5   6
  List<List<int>> adj = List.generate(7, (_) => []);
  adj[1] = [2, 3];
  adj[2] = [4, 5];
  adj[3] = [6];
  adj[4] = [];
  adj[5] = [];
  adj[6] = [];

  int n = 6; // Number of nodes

  // Arrays for HLD
  List<int> parent = List.filled(n + 1, -1);
  List<int> depth = List.filled(n + 1, 0);
  List<int> size = List.filled(n + 1, 0);
  List<int> heavy = List.filled(n + 1, -1); // Heavy child
  List<int> head = List.filled(n + 1, 0); // Head of the chain
  List<int> pos = List.filled(n + 1, 0); // Position in the chain/segment tree
  int curPos = 0;

  // First DFS to compute size, depth, and parent
  void dfsSize(int v, int p, int d) {
    parent[v] = p;
    depth[v] = d;
    size[v] = 1;
    int maxChildSize = -1;
    int maxChild = -1;
    for (int child in adj[v]) {
      if (child != p) {
        dfsSize(child, v, d + 1);
        size[v] += size[child];
        if (size[child] > maxChildSize) {
          maxChildSize = size[child];
          maxChild = child;
        }
      }
    }
    heavy[v] = maxChild;
  }

  // Second DFS to decompose into heavy-light chains
  void dfsHLD(int v, int p, int h) {
    head[v] = h;
    pos[v] = curPos++;
    if (heavy[v] != -1) {
      dfsHLD(heavy[v], v, h); // Continue the same chain for heavy child
    }
    for (int child in adj[v]) {
      if (child != p && child != heavy[v]) {
        dfsHLD(child, v, child); // Start new chain for light children
      }
    }
  }

  // Perform DFS from root 1
  dfsSize(1, -1, 0);

  // Perform HLD from root 1, starting chain at 1
  dfsHLD(1, -1, 1);

  // Output the results
  print('Node | Parent | Depth | Size | Heavy Child | Chain Head | Position');
  for (int i = 1; i <= n; i++) {
    print('$i | ${parent[i]} | ${depth[i]} | ${size[i]} | ${heavy[i]} | ${head[i]} | ${pos[i]}');
  }

  // Example: Chains formed
  // Chain starting at 1: 1 -> 2 (heavy) -> 4 (heavy, assuming 4 is chosen as heavy of 2)
  // Chain starting at 3: 3 -> 6
  // Chain starting at 5: 5
