import 'dart:io';

/// A simple Point class for 2D coordinates.
class Point {
  final double x;
  final double y;

  Point(this.x, this.y);

  /// Euclidean distance to another point.
  double distanceTo(Point other) {
    final dx = x - other.x;
    final dy = y - other.y;
    return math.sqrt(dx * dx + dy * dy);
  }
}

/// Generates a basic Voronoi diagram in ASCII art.
/// This is a naive implementation: for each grid cell, find the closest site.
@pragma('vm:entry-point')
void main() {
  // Parameters
  const int gridSize = 30; // Grid size for ASCII output
  const int numSites = 10; // Number of random sites
  final random = math.Random();

  // Generate random sites within [0, gridSize)
  final sites = List.generate(numSites, (i) {
    final x = random.nextDouble() * gridSize;
    final y = random.nextDouble() * gridSize;
    return Point(x, y);
  });

  // Print the sites for reference
  print('Generated $numSites sites:');
  for (int i = 0; i < sites.length; i++) {
    print('Site $i: (${sites[i].x.toStringAsFixed(2)}, ${sites[i].y.toStringAsFixed(2)})');
  }
  print('\nASCII Voronoi Diagram (each number represents the closest site index):\n');

  // Build the grid
  final grid = List.generate(gridSize, (_) => List.filled(gridSize, ' '));

  // For each grid cell, find the closest site
  for (int row = 0; row < gridSize; row++) {
    for (int col = 0; col < gridSize; col++) {
      final cellPoint = Point(col.toDouble(), row.toDouble());
      int closestSiteIndex = 0;
      double minDistance = double.infinity;

      for (int i = 0; i < sites.length; i++) {
        final dist = cellPoint.distanceTo(sites[i]);
        if (dist < minDistance) {
          minDistance = dist;
          closestSiteIndex = i;
        }
      }

      // Mark the grid with the site index (as char '0' to '9', or '.' if >9, but we limit to 10)
      grid[row][col] = closestSiteIndex.toString();
    }
  }

  // Print the grid
  for (final row in grid) {
    stdout.writeln(row.join(' '));
  }

  // Highlight site positions approximately
  print('\nNote: Sites are approximately at their integer coordinates in the grid.');
}

