// A complete Dart program implementing Delaunay triangulation using the Bowyer-Watson algorithm.
// This is a self-contained script that computes the triangulation for a set of points and prints the result.

import 'dart:math' as math;

// Point class
class Point {
  final double x;
  final double y;

  Point(this.x, this.y);

  @override
  String toString() => '($x, $y)';

  @override
  bool operator ==(Object other) =>
      other is Point && x == other.x && y == other.y;

  @override
  int get hashCode => Object.hash(x, y);
}

// Triangle class
class Triangle {
  final Point a;
  final Point b;
  final Point c;

  Triangle(this.a, this.b, this.c);

  @override
  String toString() => 'Triangle[$a, $b, $c]';

  bool containsPoint(Point p) {
    return p == a || p == b || p == c;
  }
}

// Function to compute the circumcircle of a triangle and check if a point is inside it
bool inCircumcircle(Point a, Point b, Point c, Point p) {
  final ax = a.x - p.x;
  final ay = a.y - p.y;
  final bx = b.x - p.x;
  final by = b.y - p.y;
  final cx = c.x - p.x;
  final cy = c.y - p.y;

  final det = (ax * (by * cy * (by - cy) - cy * by * (by - cy)) -
          ay * (bx * cy * (bx - cx) - cx * by * (bx - cx)) +
          ax * (bx * cy * (bx - cx) - cx * by * (bx - cx))) /
      2;

  final absDet = det.abs();
  final radius = (ax * ax + ay * ay) *
      (bx * bx + by * by) *
      (cx * cx + cy * cy) /
      (2 * absDet);

  final dist = (p.x - a.x) * (p.x - a.x) + (p.y - a.y) * (p.y - a.y);

  // Simplified check: actual in-circle test using determinant
  final d = ax * (by * (cx * cx + cy * cy) - cy * (bx * bx + by * by)) -
      ay * (bx * (cx * cx + cy * cy) - cx * (bx * bx + by * by)) +
      (ax * (bx * (cx * cx + cy * cy) - cx * (bx * bx + by * by)));

  return d > 0; // Note: This is a simplified version; adjust for edge cases if needed
}

// Function to check if two triangles share an edge
bool sharesEdge(Triangle t1, Triangle t2) {
  final points1 = {t1.a, t1.b, t1.c};
  final points2 = {t2.a, t2.b, t2.c};
  return points1.intersection(points2).length == 2;
}

// Main Delaunay triangulation function
List<Triangle> delaunayTriangulation(List<Point> points) {
  if (points.length < 3) return [];

  // Find min and max to create super triangle
  double minX = points.map((p) => p.x).reduce(math.min);
  double minY = points.map((p) => p.y).reduce(math.min);
  double maxX = points.map((p) => p.x).reduce(math.max);
  double maxY = points.map((p) => p.y).reduce(math.max);

  final dx = maxX - minX;
  final dy = maxY - minY;
  final deltaMax = math.max(dx, dy);
  final midX = (minX + maxX) / 2;
  final midY = (minY + maxY) / 2;

  final p1 = Point(midX - 20 * deltaMax, midY - deltaMax);
  final p2 = Point(midX, midY + 20 * deltaMax);
  final p3 = Point(midX + 20 * deltaMax, midY - deltaMax);

  // Start with super triangle
  List<Triangle> triangles = [Triangle(p1, p2, p3)];

  // Add all points one by one
  for (final point in points) {
    List<Triangle> badTriangles = [];
    for (final triangle in triangles) {
      if (inCircumcircle(triangle.a, triangle.b, triangle.c, point)) {
        badTriangles.add(triangle);
      }
    }

    Set<List<Point>> polygon = {};
    for (final bad in badTriangles) {
      for (final other in triangles) {
        if (other != bad && sharesEdge(bad, other) && !badTriangles.contains(other)) {
          // Find the edge
          final shared = {bad.a, bad.b, bad.c}.intersection({other.a, other.b, other.c}).toList();
          polygon.add([shared[0], shared[1]]);
        }
      }
    }

    // Remove bad triangles
    triangles.removeWhere((t) => badTriangles.contains(t));

    // Add new triangles
    for (final edge in polygon) {
      triangles.add(Triangle(edge[0], edge[1], point));
    }
  }

  // Remove triangles with super triangle vertices
  triangles.removeWhere((t) => t.containsPoint(p1) || t.containsPoint(p2) || t.containsPoint(p3));

  return triangles;
}

