void main() {
  // Hardcoded points for demonstration
  List<Point> points = [
    Point(0, 0),
    Point(1, 0),
    Point(0, 1),
    Point(1, 1),
    Point(0.5, 0.5),
  ];

  final triangulation = delaunayTriangulation(points);

  print('Delaunay Triangulation:');
  for (final triangle in triangulation) {
    print(triangle);
  }
}

