  Rectangle(this.x, this.y, this.width, this.height);

  bool contains(Point point) {
    return (point.x >= x - width &&
        point.x <= x + width &&
        point.y >= y - height &&
        point.y <= y + height);
  }

  bool intersects(Rectangle range) {
    return !(range.x - range.width > x + width ||
        range.x + range.width < x - width ||
        range.y - range.height > y + height ||
        range.y + range.height < y - height);
  }

  @override
  String toString() => 'Rectangle($x, $y, $width, $height)';
}

// QuadTree class definition (as provided in the context)
class QuadTree {
  final Rectangle boundary;
  final int capacity;
  List<Point> points = [];
  QuadTree? northwest;
  QuadTree? northeast;
  QuadTree? southwest;
  QuadTree? southeast;
  bool divided = false;

  QuadTree(this.boundary, this.capacity);

  void insert(Point point) {
    if (!boundary.contains(point)) {
      return;
    }

    if (points.length < capacity && !divided) {
      points.add(point);
    } else {
      if (!divided) {
        subdivide();
      }

      northwest?.insert(point);
      northeast?.insert(point);
      southwest?.insert(point);
      southeast?.insert(point);
    }
  }

  void subdivide() {
    double x = boundary.x;
    double y = boundary.y;
    double w = boundary.width / 2;
    double h = boundary.height / 2;

    northwest = QuadTree(Rectangle(x - w / 2, y - h / 2, w, h), capacity);
    northeast = QuadTree(Rectangle(x + w / 2, y - h / 2, w, h), capacity);
    southwest = QuadTree(Rectangle(x - w / 2, y + h / 2, w, h), capacity);
    southeast = QuadTree(Rectangle(x + w / 2, y + h / 2, w, h), capacity);

    for (var p in points) {
      northwest?.insert(p);
      northeast?.insert(p);
      southwest?.insert(p);
      southeast?.insert(p);
    }
    points.clear();
    divided = true;
  }

  List<Point> query(Rectangle range, [List<Point>? found]) {
    found ??= [];
    if (!boundary.intersects(range)) {
      return found;
    }

    for (var p in points) {
      if (range.contains(p)) {
        found.add(p);
      }
    }

    if (divided) {
      northwest?.query(range, found);
      northeast?.query(range, found);
      southwest?.query(range, found);
      southeast?.query(range, found);
    }

    return found;
  }

  void printTree([int level = 0]) {
    String indent = '  ' * level;
    print('$indent- Boundary: $boundary');
    print('$indent  Points: $points');
    if (divided) {
      print('$indent  Children:');
      northwest?.printTree(level + 1);
      northeast?.printTree(level + 1);
      southwest?.printTree(level + 1);
      southeast?.printTree(level + 1);
    }
  }
}
