import 'dart:math' as math;

@pragma('vm:entry-point')
void main() {
  // Define a small example graph with 4 nodes: A, B, C, D
  // Outgoing links:
  // A -> B, C
  // B -> C
  // C -> A
  // D -> C
  List<String> nodes = ['A', 'B', 'C', 'D'];
  int numNodes = nodes.length;

  Map<String, List<String>> graph = {
    'A': ['B', 'C'],
    'B': ['C'],
    'C': ['A'],
    'D': ['C'],
  };

  // Compute outdegrees
  Map<String, int> outdegrees = {};
  for (String node in nodes) {
    outdegrees[node] = graph[node]?.length ?? 0;
  }

  // Initialize PageRank values
  Map<String, double> pr = {};
  for (String node in nodes) {
    pr[node] = 1.0 / numNodes;
  }

  // Damping factor
  double d = 0.85;

  // Convergence parameters
  double epsilon = 0.0001;
  int maxIterations = 100;
  bool converged = false;

  for (int iter = 0; iter < maxIterations && !converged; iter++) {
    Map<String, double> newPr = {};
    for (String node in nodes) {
      newPr[node] = 0.0;
    }

    // Distribute contributions based on outgoing links
    for (String u in nodes) {
      if (outdegrees[u]! > 0) {
        double contrib = pr[u]! / outdegrees[u]!;
        for (String v in graph[u]!) {
          newPr[v] = newPr[v]! + contrib;
        }
      } else {
        // Handle sink nodes by distributing equally to all (though none in this graph)
        double contrib = pr[u]! / numNodes;
        for (String v in nodes) {
          newPr[v] = newPr[v]! + contrib;
        }
      }
    }

    // Apply damping factor and random jump
    for (String node in nodes) {
      newPr[node] = (1 - d) / numNodes + d * newPr[node]!;
    }

    // Check for convergence
    converged = true;
    double maxDiff = 0.0;
    for (String node in nodes) {
      double diff = (newPr[node]! - pr[node]!).abs();
      if (diff > maxDiff) maxDiff = diff;
      if (diff > epsilon) converged = false;
    }

    // Update PR
    pr = newPr;
  }

  // Print the final PageRank values
  print('Final PageRank values:');
  for (String node in nodes) {
    print('$node: ${pr[node]}');
  }
}

