import 'dart:math' as math;

class Point {
  final double x;
  final double y;

  Point(this.x, this.y);
}

double euclideanDistance(Point a, Point b) {
  return math.sqrt(math.pow(a.x - b.x, 2) + math.pow(a.y - b.y, 2));
}

double clusterDistance(List<int> clusterA, List<int> clusterB, List<Point> points) {
  double minDist = double.infinity;
  for (int i in clusterA) {
    for (int j in clusterB) {
      double dist = euclideanDistance(points[i], points[j]);
      if (dist < minDist) minDist = dist;
    }
  }
  return minDist;
}

@pragma('vm:entry-point')
void main() {
  // Sample data: list of 2D points
  List<Point> points = [
    Point(1, 2),
    Point(3, 4),
    Point(5, 6),
    Point(7, 8),
    Point(1.5, 2.5),
    Point(6, 7),
  ];

  // Initial clusters: each point is its own cluster, represented by index
  List<List<int>> clusters = [];
  for (int i = 0; i < points.length; i++) {
    clusters.add([i]);
  }

  // List to store the hierarchy of merges (for dendrogram-like output)
  List<String> mergeHistory = [];

  print('Starting hierarchical clustering with ${points.length} points.');

  while (clusters.length > 1) {
    // Find the two closest clusters
    double minDist = double.infinity;
    int mergeA = -1;
    int mergeB = -1;

    for (int i = 0; i < clusters.length; i++) {
      for (int j = i + 1; j < clusters.length; j++) {
        double dist = clusterDistance(clusters[i], clusters[j], points);
        if (dist < minDist) {
          minDist = dist;
          mergeA = i;
          mergeB = j;
        }
      }
    }

    // Merge the two closest clusters
    List<int> newCluster = [...clusters[mergeA], ...clusters[mergeB]];
    mergeHistory.add('Merged clusters ${clusters[mergeA]} and ${clusters[mergeB]} at distance $minDist');

    // Remove the old clusters and add the new one
    List<List<int>> newClusters = [];
    for (int k = 0; k < clusters.length; k++) {
      if (k != mergeA && k != mergeB) {
        newClusters.add(clusters[k]);
      }
    }
    newClusters.add(newCluster);
    clusters = newClusters;
  }

  print('Clustering complete. Final cluster: ${clusters[0]}');
  print('Merge history:');
  for (String merge in mergeHistory) {
    print(merge);
  }
}

