// Demonstrates covariant overrides in Dart.
// We define a base class AnimalShelter with a method add(Animal).
// Then a subclass DogShelter overrides it covariantly with add(Dog).

class Animal {
  String name;
  Animal(this.name);
}

class Dog extends Animal {
  Dog(String name) : super(name);
}

class AnimalShelter {
  void add(Animal animal) {
    print('Added animal: ${animal.name}');
  }
}

class DogShelter extends AnimalShelter {
  @override
  void add(covariant Dog dog) {
    print('Added dog: ${dog.name}');
  }
}

@pragma('vm:entry-point')
void main() {
  // Create instances
  final animalShelter = AnimalShelter();
  final dogShelter = DogShelter();

  // Demonstrate base class
  animalShelter.add(Animal('Generic Animal'));

  // Demonstrate covariant override
  dogShelter.add(Dog('Buddy'));

  // Note: Due to covariance, dogShelter.add(Animal('Cat')) would cause a runtime error,
  // but compile-time it's allowed if treated as AnimalShelter.
  // Here we avoid it to keep the example clean.

  // Polymorphism: Treat DogShelter as AnimalShelter
  AnimalShelter polyShelter = dogShelter;
  polyShelter.add(Dog('Fido')); // This works, but internally calls the overridden method.

  // This would fail at runtime: polyShelter.add(Animal('Bird'));
  // But we skip it to prevent errors in this demo.

  print('Covariant override demonstration complete.');
}

