import 'dart:io';
import 'dart:math';

/// Calculates the great-circle distance between two points on the Earth's surface
/// using the Haversine formula. Distances are in kilometers.
double calculateDistance(double lat1, double lon1, double lat2, double lon2) {
  const double earthRadius = 6371.0; // Radius of the Earth in km

  // Convert degrees to radians
  double dLat = (lat2 - lat1) * pi / 180;
  double dLon = (lon2 - lon1) * pi / 180;

  double a = sin(dLat / 2) * sin(dLat / 2) +
             cos(lat1 * pi / 180) * cos(lat2 * pi / 180) *
             sin(dLon / 2) * sin(dLon / 2);
  double c = 2 * atan2(sqrt(a), sqrt(1 - a));
  return earthRadius * c;
}

@pragma('vm:entry-point')
void main() {
  // Simulate current geolocation (in a real app, this would come from GPS APIs)
  // For demonstration, hardcoded user's location (e.g., near New York)
