  double serviceLat = 37.7749;
  double serviceLon = -122.4194;
  print('Service point location: Latitude $serviceLat, Longitude $serviceLon');

  // Calculate distance
  double distance = calculateDistance(userLat, userLon, serviceLat, serviceLon);
  print('Distance to service point: ${distance.toStringAsFixed(2)} km');

  // Geolocation-based service: Check if user is within 1000 km for eligibility
