/// A simple Dart console program that simulates an animated splash screen
/// by displaying a spinning loader with a message, then proceeds to "main" content.
@pragma('vm:entry-point')
void main() async {
  // Clear the console screen (works on most terminals)
  stdout.write('\x1B[2J\x1B[0;0H');

  // Define spinner animation frames
  List<String> spinner = ['|', '/', '-', '\\'];
  int spinnerIndex = 0;

  // Display initial splash message
  stdout.writeln('Welcome to the App!');
  stdout.writeln('Initializing...');

  // Start the animation timer
  Timer timer = Timer.periodic(Duration(milliseconds: 200), (Timer t) {
    // Overwrite the line with the spinner
    stdout.write('\rLoading ${spinner[spinnerIndex]}   ');
    spinnerIndex = (spinnerIndex + 1) % spinner.length;
  });

  // Simulate some loading time (e.g., 3 seconds)
  await Future.delayed(Duration(seconds: 3));

  // Stop the animation
  timer.cancel();

  // Clear the loading line
  stdout.write('\r                    \n');

  // "Transition" to main content
  stdout.writeln('Splash screen complete!');
  stdout.writeln('Now entering the main program...');
  stdout.writeln('Hello, World!');
}

