  print('You can view, update, or reset your settings.');
  print('Type "view" to see current settings.');
  print('Type "update <key> <value>" to change a setting (e.g., "update theme dark").');
  print('Type "reset" to restore defaults.');
  print('Type "exit" to quit.');

  // Loop for user input
  while (true) {
    stdout.write('\nEnter command: ');
    String? input = stdin.readLineSync()?.trim();

    if (input == null || input.toLowerCase() == 'exit') {
      print('Exiting...');
      break;
    } else if (input.toLowerCase() == 'view') {
      print('Current Settings:');
      userSettings.forEach((key, value) {
        print('$key: $value');
      });
    } else if (input.toLowerCase() == 'reset') {
      userSettings = {
        'theme': 'light',
        'language': 'en',
        'notifications': true,
        'fontSize': 14,
      };
      print('Settings reset to defaults.');
    } else if (input.toLowerCase().startsWith('update')) {
      List<String> parts = input.split(' ');
      if (parts.length == 3) {
        String key = parts[1].toLowerCase();
        String value = parts[2];

        if (userSettings.containsKey(key)) {
          // Type checking and conversion
          if (key == 'theme' && (value == 'light' || value == 'dark')) {
            userSettings[key] = value;
          } else if (key == 'language' && (value == 'en' || value == 'fr' || value == 'es')) {
            userSettings[key] = value;
          } else if (key == 'notifications' && (value == 'true' || value == 'false')) {
            userSettings[key] = value.toLowerCase() == 'true';
          } else if (key == 'fontSize') {
            try {
              int fontSize = int.parse(value);
              if (fontSize > 0) {
                userSettings[key] = fontSize;
              } else {
                print('Invalid value for $key. Must be positive integer.');
                continue;
              }
            } catch (e) {
              print('Invalid value for $key. Must be an integer.');
              continue;
            }
          } else {
            print('Invalid value for $key.');
            continue;
          }
          print('Updated $key to $value.');
        } else {
          print('Unknown setting: $key. Available: theme, language, notifications, fontSize.');
        }
      } else {
        print('Invalid update format. Use: update <key> <value>');
      }
    } else {
      print('Unknown command. Try "view", "update <key> <value>", "reset", or "exit".');
    }
  }

  print('Program ended. Final settings:');
  userSettings.forEach((key, value) {
    print('$key: $value');
  });
}

