import 'dart:io';

/// A simple Dart program that simulates deep linking support by parsing
/// a URL provided as a command-line argument and handling it accordingly.
/// 
/// Usage: dart run this_file.dart https://example.com/path?param=value
@pragma('vm:entry-point')
void main(List<String> arguments) {
  if (arguments.isEmpty) {
    print('No deep link provided. Please pass a URL as an argument.');
    exit(1);
  }

  String deepLink = arguments[0];
  print('Received deep link: $deepLink');

  try {
    Uri uri = Uri.parse(deepLink);

    // Example handling logic based on the path and query parameters
    if (uri.scheme != 'https' && uri.scheme != 'http') {
      print('Error: Unsupported scheme ${uri.scheme}. Only http/https supported.');
      exit(1);
    }

    print('Host: ${uri.host}');
    print('Path: ${uri.path}');
    print('Query Parameters: ${uri.queryParameters}');

    // Simulate routing based on path
    if (uri.path.startsWith('/user/')) {
      String userId = uri.pathSegments[1];
      print('Navigating to user profile for ID: $userId');
      if (uri.queryParameters.containsKey('action')) {
        print('Performing action: ${uri.queryParameters['action']}');
      }
    } else if (uri.path == '/home') {
      print('Navigating to home screen.');
    } else {
      print('Unknown path. Defaulting to main screen.');
    }

    print('Deep link handled successfully.');
  } catch (e) {
    print('Error parsing deep link: $e');
    exit(1);
  }
}

