    print('1. Add a contact');
    print('2. View all contacts');
    print('3. Delete a contact');
    print('4. Exit');
    stdout.write('Enter your choice (1-4): ');
    String? choice = stdin.readLineSync();

    switch (choice) {
      case '1':
        addContact();
        break;
      case '2':
        viewContacts();
        break;
      case '3':
        deleteContact();
        break;
      case '4':
        running = false;
        print('Exiting the program. Goodbye!');
        break;
      default:
        print('Invalid choice. Please try again.');
    }
  }
}

void addContact() {
  stdout.write('Enter name: ');
  String? name = stdin.readLineSync();
  stdout.write('Enter phone number: ');
  String? phone = stdin.readLineSync();
  stdout.write('Enter email: ');
  String? email = stdin.readLineSync();

  if (name != null && name.isNotEmpty && phone != null && phone.isNotEmpty) {
    contacts.add({
      'name': name,
      'phone': phone,
      'email': email ?? 'N/A',
    });
    print('Contact added successfully!');
  } else {
    print('Name and phone are required. Contact not added.');
  }
}

void viewContacts() {
  if (contacts.isEmpty) {
    print('No contacts available.');
  } else {
    print('Contact List:');
    for (int i = 0; i < contacts.length; i++) {
      var contact = contacts[i];
      print('$i: Name: ${contact['name']}, Phone: ${contact['phone']}, Email: ${contact['email']}');
    }
  }
}

void deleteContact() {
  viewContacts();
  if (contacts.isNotEmpty) {
    stdout.write('Enter the index of the contact to delete: ');
    String? indexStr = stdin.readLineSync();
    try {
      int index = int.parse(indexStr ?? '-1');
      if (index >= 0 && index < contacts.length) {
        contacts.removeAt(index);
        print('Contact deleted successfully!');
      } else {
        print('Invalid index.');
      }
    } catch (e) {
      print('Invalid input. Please enter a number.');
    }
  }
}

