  // In-memory storage for search history
  List<String> searchHistory = [];

  // Function to add a search query to history
  void addToHistory(String query) {
    if (query.isNotEmpty) {
      // Avoid duplicates: remove if already exists and add to the end
      searchHistory.remove(query);
      searchHistory.add(query);
      // Limit history to last 10 searches
      if (searchHistory.length > 10) {
        searchHistory.removeAt(0);
      }
      print('Added to history: $query');
    }
  }

  // Function to display search history
  void displayHistory() {
    if (searchHistory.isEmpty) {
      print('Search history is empty.');
    } else {
      print('Search History (most recent last):');
      for (int i = 0; i < searchHistory.length; i++) {
        print('${i + 1}. ${searchHistory[i]}');
      }
    }
  }

  // Function to clear search history
  void clearHistory() {
    searchHistory.clear();
    print('Search history cleared.');
  }

  // Main interactive loop
  print('Welcome to In-App Search History Simulator');
  print('Commands:');
  print('  search <query> - Perform a search and add to history');
  print('  history - View search history');
  print('  clear - Clear search history');
  print('  exit - Quit the program');

  while (true) {
    stdout.write('> ');
    String? input = stdin.readLineSync();
    if (input == null || input.trim().isEmpty) continue;

    List<String> parts = input.split(' ');
    String command = parts[0].toLowerCase();

    if (command == 'exit') {
      print('Goodbye!');
      break;
    } else if (command == 'search' && parts.length > 1) {
      String query = parts.sublist(1).join(' ').trim();
      addToHistory(query);
      // Simulate search result
      print('Searching for: $query');
      print('Results: (simulated) Found some results for "$query"');
    } else if (command == 'history') {
      displayHistory();
    } else if (command == 'clear') {
      clearHistory();
    } else {
      print('Unknown command. Try again.');
    }
  }
}

