/// A simple Dart program demonstrating dynamic font scaling.
/// This console-based script allows users to input a base font size
/// and dynamically apply scaling factors to simulate font size adjustments,
/// such as for accessibility or screen size changes.

@pragma('vm:entry-point')
void main() {
  // Welcome message
  print('Welcome to Dynamic Font Scaling Simulator!');
  print('Enter a base font size (e.g., 16.0) and then apply scaling factors dynamically.');
  print('Type "exit" at any prompt to quit.\n');

  // Read base font size
  double? baseFontSize;
  while (baseFontSize == null) {
    stdout.write('Enter base font size (number): ');
    final input = stdin.readLineSync();
    if (input?.toLowerCase() == 'exit') {
      print('Exiting...');
      return;
    }
    try {
      baseFontSize = double.parse(input ?? '');
      if (baseFontSize <= 0) {
        print('Invalid input: Font size must be positive.');
        baseFontSize = null;
      }
    } catch (e) {
      print('Invalid input: Please enter a valid number.');
    }
  }

  print('Base font size set to: $baseFontSize');

  // Loop for dynamic scaling
  while (true) {
    stdout.write('Enter scaling factor (e.g., 1.0 for normal, 1.5 for larger, or "exit"): ');
    final input = stdin.readLineSync();
    if (input?.toLowerCase() == 'exit') {
      print('Exiting...');
      break;
    }
    try {
      final scalingFactor = double.parse(input ?? '');
      if (scalingFactor <= 0) {
        print('Invalid input: Scaling factor must be positive.');
        continue;
      }
      final scaledFontSize = baseFontSize * scalingFactor;
      print('Scaled font size: $scaledFontSize (with factor $scalingFactor)');
    } catch (e) {
      print('Invalid input: Please enter a valid number or "exit".');
    }
  }

  print('Program ended.');
}

