  // Simulate persistent storage for app launch count (in a real app, use shared_preferences or similar).
  // For this console script, we'll use a local variable and simulate multiple launches in a loop.
  int launchCount = 0;
  const int ratingPromptThreshold = 3; // Prompt after 3 launches.
  bool hasRated = false;

  print('Simulating an in-app rating system in a console Dart program.');
  print('This will simulate multiple app "launches". Enter "exit" to quit.');

  while (true) {
    // Simulate an app launch.
    launchCount++;
    print('\n--- App Launch #$launchCount ---');

    // Check if we should prompt for rating.
    if (launchCount >= ratingPromptThreshold && !hasRated) {
      print('You\'ve used the app $launchCount times! Would you like to rate it? (yes/no)');
      String? response = stdin.readLineSync()?.toLowerCase();

      if (response == 'yes') {
        print('Please rate the app from 1 to 5 stars:');
        String? ratingInput = stdin.readLineSync();
        int? rating = int.tryParse(ratingInput ?? '');

        if (rating != null && rating >= 1 && rating <= 5) {
          if (rating >= 4) {
            print('Thanks for the $rating-star rating! In a real app, we\'d redirect to the app store.');
          } else {
            print('Thanks for the $rating-star rating! We\'ll use your feedback to improve.');
          }
          hasRated = true; // Prevent future prompts.
        } else {
          print('Invalid rating. Please enter a number between 1 and 5.');
        }
      } else if (response == 'no') {
        print('No problem! You can rate later.');
      } else {
        print('Invalid response. Skipping rating prompt.');
      }
    } else {
      print('App running normally...');
    }

    // Simulate end of launch and check for exit.
    print('Enter "next" to simulate next launch, or "exit" to quit.');
    String? nextInput = stdin.readLineSync()?.toLowerCase();
