/// A simple Dart program demonstrating an offline queue for synchronization.
/// Tasks (simulated as data strings to sync) are added to a queue when offline.
/// When online, the queue is processed and each task is "synced" (simulated by printing).

@pragma('vm:entry-point')
void main() async {
  // Queue to hold pending sync tasks (e.g., data strings to sync).
  final Queue<String> syncQueue = Queue<String>();

  // Simulated network status.
  bool isOnline = false;

  // Function to simulate syncing data (e.g., to a server).
  Future<void> syncData(String data) async {
    // Simulate network delay.
    await Future.delayed(Duration(seconds: 1));
    print('Synced: $data');
  }

  // Function to add a task to the queue or sync immediately if online.
  void addTask(String data) {
    if (isOnline) {
      syncData(data);
    } else {
      syncQueue.add(data);
      print('Queued (offline): $data');
    }
  }

  // Function to process the queue when going online.
  Future<void> processQueue() async {
    print('Going online. Processing queue...');
    while (syncQueue.isNotEmpty) {
      final data = syncQueue.removeFirst();
      await syncData(data);
    }
    print('Queue processed.');
  }

  // Simulate usage in main.
  print('Starting offline...');

  // Add tasks while offline.
  addTask('Task 1: Update user profile');
  addTask('Task 2: Upload photo');
  addTask('Task 3: Send message');

  // Simulate waiting a bit (e.g., for user interaction).
  await Future.delayed(Duration(seconds: 2));

  // Simulate going online.
  isOnline = true;
  await processQueue();

  // Add a task while online (should sync immediately).
  addTask('Task 4: Delete item');

  // End the program.
  print('Program completed.');
  exit(0);
}

