  // and track a simple metric like "conversion" (e.g., whether they "clicked" something).

  const int numUsers = 100;
  int conversionsA = 0;
  int conversionsB = 0;
  int groupACount = 0;
  int groupBCount = 0;

  final Random random = Random();

  for (int i = 1; i <= numUsers; i++) {
