        conversionsA++;
      }
      print('User $i assigned to Group A');
    } else {
      groupBCount++;
      // Simulate behavior for group B: e.g., 40% conversion rate (variant)
      if (random.nextDouble() < 0.4) {
        conversionsB++;
      }
      print('User $i assigned to Group B');
    }
  }

  // Calculate and print results
  double rateA = (groupACount > 0) ? (conversionsA / groupACount) * 100 : 0;
  double rateB = (groupBCount > 0) ? (conversionsB / groupBCount) * 100 : 0;

  print('\nA/B Testing Results:');
  print('Group A: $groupACount users, $conversionsA conversions, ${rateA.toStringAsFixed(2)}% conversion rate');
  print('Group B: $groupBCount users, $conversionsB conversions, ${rateB.toStringAsFixed(2)}% conversion rate');

  if (rateA > rateB) {
    print('Group A performed better.');
  } else if (rateB > rateA) {
    print('Group B performed better.');
  } else {
    print('Both groups performed equally.');
  }
}

