  int n = Y.length;

  // Initialize a 2D list for storing LCS lengths, filled with zeros
  List<List<int>> lcs = List.generate(m + 1, (_) => List.filled(n + 1, 0));

  // Build the LCS table in a bottom-up manner
  for (int i = 0; i <= m; i++) {
    for (int j = 0; j <= n; j++) {
      if (i == 0 || j == 0) {
        lcs[i][j] = 0;
      } else if (X[i - 1] == Y[j - 1]) {
        lcs[i][j] = lcs[i - 1][j - 1] + 1;
      } else {
        lcs[i][j] = (lcs[i - 1][j] > lcs[i][j - 1]) ? lcs[i - 1][j] : lcs[i][j - 1];
      }
    }
  }

