  String s2 = "sitting";

  // Levenshtein distance implementation
  int editDistance(String a, String b) {
    int m = a.length;
    int n = b.length;

    // Create a 2D list to store distances
    List<List<int>> dp = List.generate(
        m + 1, (_) => List<int>.filled(n + 1, 0, growable: false),
        growable: false);

    // Initialize base cases
    for (int i = 0; i <= m; i++) {
      dp[i][0] = i;
    }
    for (int j = 0; j <= n; j++) {
      dp[0][j] = j;
    }

    // Compute edit distance
    for (int i = 1; i <= m; i++) {
      for (int j = 1; j <= n; j++) {
        if (a[i - 1] == b[j - 1]) {
          dp[i][j] = dp[i - 1][j - 1];
        } else {
          dp[i][j] = 1 +
              [
                dp[i - 1][j], // deletion
                dp[i][j - 1], // insertion
                dp[i - 1][j - 1] // substitution
              ].reduce((a, b) => a < b ? a : b);
        }
      }
    }
    return dp[m][n];
  }

  int distance = editDistance(s1, s2);
  print('Edit distance between "$s1" and "$s2" is $distance');
