  // Example input list
  List<int> nums = [1, 5, 11, 5];

  // Calculate total sum
  int totalSum = nums.fold(0, (a, b) => a + b);

  // If total sum is odd, cannot partition into equal sum subsets
  if (totalSum % 2 != 0) {
    print('Cannot partition: sum is odd.');
    return;
  }

  int target = totalSum ~/ 2;
  int n = nums.length;

  // DP approach: dp[i] is true if sum i can be formed
  List<bool> dp = List.filled(target + 1, false);
  dp[0] = true;

  for (int num in nums) {
    // Traverse backwards to avoid using the same number twice
    for (int i = target; i >= num; i--) {
      if (dp[i - num]) {
        dp[i] = true;
      }
    }
  }

  if (dp[target]) {
    print('Can partition into two subsets with equal sum.');
  } else {
    print('Cannot partition into two subsets with equal sum.');
  }
}

