void main() {
  const int n = 8; // Change this value for different board sizes

  // Helper function to check if placing a queen is safe
  bool isSafe(List<int> queens, int row, int col) {
    for (int i = 0; i < row; i++) {
      int qCol = queens[i];
      if (qCol == col || // Same column
          (i - row).abs() == (qCol - col).abs()) // Same diagonal
        return false;
    }
    return true;
  }

  // Recursive solver
  void solve(int row, List<int> queens, List<List<int>> solutions) {
    if (row == n) {
      solutions.add(List.from(queens));
      return;
    }
    for (int col = 0; col < n; col++) {
      if (isSafe(queens, row, col)) {
        queens[row] = col;
        solve(row + 1, queens, solutions);
      }
    }
  }

  // Print the board
  void printBoard(List<int> queens) {
    for (int i = 0; i < n; i++) {
      String row = List.generate(n, (j) => queens[i] == j ? 'Q' : '.').join(' ');
      print(row);
    }
    print('');
  }

  List<List<int>> solutions = [];
  solve(0, List.filled(n, -1), solutions);

  print('Total solutions for $n-Queens: ${solutions.length}\n');
  for (int i = 0; i < solutions.length; i++) {
    print('Solution ${i + 1}:');
    printBoard(solutions[i]);
  }
}

