import 'dart:io';

@pragma('vm:entry-point')
void main() {
  // Example graph as adjacency matrix
  // 0-1-2
  // |   |
  // 3---4
  List<List<int>> graph = [
    [0, 1, 0, 1, 0], // 0
    [1, 0, 1, 0, 0], // 1
    [0, 1, 0, 0, 1], // 2
    [1, 0, 0, 0, 1], // 3
    [0, 0, 1, 1, 0], // 4
  ];
  int n = graph.length;

  // Hamiltonian Path detection using backtracking
  bool hasHamiltonianPath() {
    List<bool> visited = List.filled(n, false);

    bool dfs(int v, int count) {
      if (count == n) return true;
      visited[v] = true;
      for (int u = 0; u < n; u++) {
        if (graph[v][u] == 1 && !visited[u]) {
          if (dfs(u, count + 1)) return true;
        }
      }
      visited[v] = false;
      return false;
    }

    for (int start = 0; start < n; start++) {
      if (dfs(start, 1)) return true;
    }
    return false;
  }

  // Output result
  if (hasHamiltonianPath()) {
    print('The graph has a Hamiltonian path.');
  } else {
    print('The graph does NOT have a Hamiltonian path.');
  }
}

