    AVLNode x = y.left!;
    AVLNode T2 = x.right!;

    // Perform rotation
    x.right = y;
    y.left = T2;

    // Update heights
    y.height = max(_height(y.left), _height(y.right)) + 1;
    x.height = max(_height(x.left), _height(x.right)) + 1;

    // Return new root
    return x;
  }

  AVLNode _leftRotate(AVLNode x) {
    AVLNode y = x.right!;
    AVLNode T2 = y.left!;

    // Perform rotation
    y.left = x;
    x.right = T2;

    // Update heights
    x.height = max(_height(x.left), _height(x.right)) + 1;
    y.height = max(_height(y.left), _height(y.right)) + 1;

    // Return new root
    return y;
  }

