void main() {
  // Rabin-Karp string search implementation in Dart

  String text = "ababcabcabababd";
  String pattern = "ababd";

  // Prime modulus to reduce hash collisions
  const int prime = 101;
  // Base for the rolling hash
  const int base = 256;

  int n = text.length;
  int m = pattern.length;
  if (m > n) {
    print("Pattern longer than text.");
    return;
  }

  int patternHash = 0; // Hash value for pattern
  int windowHash = 0;  // Hash value for current window of text
  int h = 1;           // The value of base^(m-1)

  // Precompute h = pow(base, m-1) % prime
  for (int i = 0; i < m - 1; i++) {
    h = (h * base) % prime;
  }

  // Calculate the hash value of pattern and first window of text
  for (int i = 0; i < m; i++) {
    patternHash = (base * patternHash + pattern.codeUnitAt(i)) % prime;
    windowHash = (base * windowHash + text.codeUnitAt(i)) % prime;
  }

  List<int> matches = [];

  // Slide the pattern over text one by one
  for (int i = 0; i <= n - m; i++) {
    // Check the hash values of current window of text and pattern
    if (patternHash == windowHash) {
      // If the hash values match, check the characters one by one to confirm
      bool match = true;
      for (int j = 0; j < m; j++) {
