@pragma('vm:entry-point')
void main() {
  // Segment Tree implementation for Range Sum Query

  // Read input array
  print('Enter array elements separated by space:');
  List<int> arr =
      stdin.readLineSync()!.split(' ').map((e) => int.parse(e)).toList();
  int n = arr.length;

  // Build segment tree
  int size = 1;
  while (size < n) size <<= 1;
  List<int> segTree = List.filled(2 * size, 0);

  // Build the tree
  for (int i = 0; i < n; i++) {
    segTree[size + i] = arr[i];
  }
  for (int i = size - 1; i > 0; i--) {
    segTree[i] = segTree[2 * i] + segTree[2 * i + 1];
  }

  // Query function: sum on [l, r)
  int query(int l, int r) {
    l += size;
    r += size;
    int res = 0;
    while (l < r) {
      if (l % 2 == 1) {
        res += segTree[l];
        l++;
      }
      if (r % 2 == 1) {
        r--;
        res += segTree[r];
      }
      l ~/= 2;
      r ~/= 2;
    }
    return res;
  }

  // Update function: set arr[pos] = val
  void update(int pos, int val) {
    pos += size;
    segTree[pos] = val;
    while (pos > 1) {
      pos ~/= 2;
      segTree[pos] = segTree[2 * pos] + segTree[2 * pos + 1];
    }
  }

  print('Segment Tree built. Enter queries:');
  print(
      'Format: "q l r" for range sum query on [l, r) or "u idx val" to update arr[idx] = val. Type "exit" to quit.');

  while (true) {
    String? line = stdin.readLineSync();
    if (line == null || line.trim().toLowerCase() == 'exit') break;
    List<String> parts = line.trim().split(' ');
    if (parts.isEmpty) continue;
    if (parts[0] == 'q' && parts.length == 3) {
      int l = int.parse(parts[1]);
      int r = int.parse(parts[2]);
      if (l < 0 || r > n || l >= r) {
        print('Invalid query range.');
        continue;
      }
      int res = query(l, r);
      print('Sum from $l to ${r - 1}: $res');
    } else if (parts[0] == 'u' && parts.length == 3) {
      int idx = int.parse(parts[1]);
      int val = int.parse(parts[2]);
      if (idx < 0 || idx >= n) {
        print('Invalid index.');
        continue;
      }
      update(idx, val);
      print('Updated index $idx to $val.');
    } else {
      print('Invalid input. Try again.');
    }
  }
  print('Exiting.');
}

