  // Example graph (Adjacency list)
  // 0 -> [1]
  // 1 -> [2,3]
  // 2 -> [0]
  // 3 -> [4]
  // 4 -> []
  final graph = <int, List<int>>{
    0: [1],
    1: [2, 3],
    2: [0],
    3: [4],
    4: [],
  };

  final n = graph.length;
  final index = <int, int>{};
  final lowlink = <int, int>{};
  final onStack = <int, bool>{};
  final stack = <int>[];
  final sccs = <List<int>>[];
  int currentIndex = 0;

  void strongConnect(int v) {
    index[v] = currentIndex;
    lowlink[v] = currentIndex;
    currentIndex++;
    stack.add(v);
    onStack[v] = true;

    for (final w in graph[v] ?? []) {
      if (!index.containsKey(w)) {
        strongConnect(w);
        lowlink[v] = lowlink[v]!.compareTo(lowlink[w]!) > 0 ? lowlink[w]! : lowlink[v]!;
      } else if (onStack[w] == true) {
        lowlink[v] = lowlink[v]!.compareTo(index[w]!) > 0 ? index[w]! : lowlink[v]!;
      }
    }

    if (lowlink[v] == index[v]) {
      final scc = <int>[];
      int w;
      do {
        w = stack.removeLast();
        onStack[w] = false;
        scc.add(w);
      } while (w != v);
      sccs.add(scc);
    }
  }

  for (final v in graph.keys) {
    if (!index.containsKey(v)) {
      strongConnect(v);
    }
  }

  print('Strongly Connected Components:');
  for (final scc in sccs) {
    print(scc);
  }
}

