void main() {
  // Example input: list of points
  List<Point> points = [
    Point(0, 3),
    Point(2, 2),
    Point(1, 1),
    Point(2, 1),
    Point(3, 0),
    Point(0, 0),
    Point(3, 3),
  ];

  if (points.length <= 1) {
    print('Convex hull: $points');
    return;
  }

  // Step 1: Find the point with the lowest y (and leftmost if tie)
  points.sort((a, b) {
    if (a.y != b.y) return a.y - b.y;
    return a.x - b.x;
