          int cp = cross(p0, a, b);
          if (cp == 0) {
            // Collinear: closer comes first
            return dist2(p0, a) - dist2(p0, b);
          }
          return -cp; // Sort by angle (counter-clockwise)
        });

  // Step 3: Graham scan
  List<Point> hull = [];
  for (var p in points) {
    while (hull.length >= 2 &&
        cross(hull[hull.length - 2], hull[hull.length - 1], p) <= 0) {
      hull.removeLast();
    }
    hull.add(p);
  }

  print('Convex hull:');
  for (var p in hull) {
    print(p);
  }
