  double stripClosest(List<Point<double>> strip, double d) {
    double minDist = d;
    strip.sort((a, b) => a.y.compareTo(b.y));
    for (int i = 0; i < strip.length; i++) {
      for (int j = i + 1;
          j < strip.length && (strip[j].y - strip[i].y) < minDist;
          j++) {
        double distVal = dist(strip[i], strip[j]);
        if (distVal < minDist) {
          minDist = distVal;
        }
