      int closestSite = -1;

      for (int i = 0; i < sites.length; i++) {
        final dx = x - sites[i].x;
        final dy = y - sites[i].y;
        final dist = dx * dx + dy * dy; // Use squared distance for efficiency
        if (dist < minDist) {
          minDist = dist.toDouble();
          closestSite = i;
        }
