void main() {
  // Example data: y = 2x + 1 with some noise
  final List<double> X = [1, 2, 3, 4, 5];
  final List<double> Y = [3.1, 4.9, 7.2, 9.0, 10.8];

  // Hyperparameters
  double learningRate = 0.01;
  int epochs = 1000;

  // Initialize parameters
  double w = 0.0; // weight
  double b = 0.0; // bias

  int n = X.length;

  // Training loop
  for (int epoch = 0; epoch < epochs; epoch++) {
    double dw = 0.0;
    double db = 0.0;
    double loss = 0.0;

    // Compute gradients and loss
    for (int i = 0; i < n; i++) {
      double yPred = w * X[i] + b;
      double error = yPred - Y[i];
      dw += X[i] * error;
      db += error;
      loss += error * error;
    }
    dw = (2 / n) * dw;
    db = (2 / n) * db;
    loss = loss / n;

    // Update parameters
    w -= learningRate * dw;
    b -= learningRate * db;

    // Print loss every 100 epochs
    if ((epoch + 1) % 100 == 0) {
      print('Epoch ${epoch + 1}: Loss = ${loss.toStringAsFixed(4)}');
    }
  }

  print('\nTrained parameters:');
  print('w (slope) = ${w.toStringAsFixed(4)}');
  print('b (intercept) = ${b.toStringAsFixed(4)}');

  // Predict on new data
  double xTest = 6.0;
  double yPred = w * xTest + b;
  print('\nPrediction for x = $xTest: y = ${yPred.toStringAsFixed(4)}');
}

