  Iterable<int> lazyCount(int start) sync* {
    int i = start;
    while (true) {
      yield i++;
    }
  }

  // A function that lazily maps another iterable.
  Iterable<T> lazyMap<S, T>(Iterable<S> source, T Function(S) f) sync* {
    for (var value in source) {
      yield f(value);
    }
  }

  // A function that lazily filters another iterable.
  Iterable<T> lazyWhere<T>(Iterable<T> source, bool Function(T) test) sync* {
    for (var value in source) {
      if (test(value)) yield value;
    }
  }

  // Example usage: Generate the first 10 even squares starting from 1.
  var numbers = lazyCount(1); // Infinite sequence: 1, 2, 3, ...
  var evenNumbers = lazyWhere(numbers, (n) => n.isEven); // Lazily filter even numbers
  var squares = lazyMap(evenNumbers, (n) => n * n); // Lazily map to squares

  print('First 10 even squares:');
  print(squares.take(10).toList());
}

