void main() {
  // Generates an infinite lazy iterable of integers starting from [start].
  Iterable<int> lazyCount(int start) sync* {
    int i = start;
    while (true) {
      yield i++;
    }
  }

  // Lazily maps another iterable using the provided function.
  Iterable<T> lazyMap<S, T>(Iterable<S> source, T Function(S) f) sync* {
    for (var value in source) {
      yield f(value);
    }
  }

  // Lazily filters another iterable based on the provided test function.
  Iterable<T> lazyWhere<T>(Iterable<T> source, bool Function(T) test) sync* {
    for (var value in source) {
      if (test(value)) {
        yield value;
      }
    }
  }

  // Example usage: Generate the first 10 even squares starting from 1.
  var numbers = lazyCount(1); // Infinite sequence: 1, 2, 3, ...
  var evenNumbers = lazyWhere(numbers, (n) => n.isEven); // Filter even numbers
  var squares = lazyMap(evenNumbers, (n) => n * n); // Map to squares

  print('First 10 even squares:');
  print(squares.take(10).toList()); // Take first 10 and convert to list for printing
}
```

### Key Points:
- **Lazy Evaluation**: All functions use `sync*` to create lazy iterables, meaning elements are generated on-demand, which is efficient for infinite or large sequences.
