void main() async {
  // A function to run in a separate isolate.
  void isolateEntry(SendPort mainSendPort) async {
    // Create a ReceivePort for this isolate to get messages from main.
    final receivePort = ReceivePort();

    // Send our SendPort to main isolate so it can communicate with us.
    mainSendPort.send(receivePort.sendPort);

    // Listen for incoming messages.
    await for (final message in receivePort) {
      if (message is String) {
        // Echo back the message in uppercase.
        mainSendPort.send('Isolate received: ${message.toUpperCase()}');
        if (message == 'exit') {
          receivePort.close();
          break;
        }
      }
    }
  }

  // Create a ReceivePort for messages from the isolate.
  final mainReceivePort = ReceivePort();

  // Spawn the isolate, passing our SendPort.
  await Isolate.spawn(isolateEntry, mainReceivePort.sendPort);

  // Get the SendPort to communicate with the spawned isolate.
  final isolateSendPort = await mainReceivePort.first as SendPort;

  // Send some messages to the isolate and listen for replies.
  final responsePort = ReceivePort();

  // Listen for responses from the isolate.
  mainReceivePort.listen((message) {
    if (message is String) {
      print('Main received: $message');
    }
  });

  // Send messages
  isolateSendPort.send('hello isolate');
  isolateSendPort.send('dart is fun');
  isolateSendPort.send('exit');

  // Wait a moment to ensure all messages are processed before exit.
  await Future.delayed(Duration(seconds: 1));
  mainReceivePort.close();
}

