  List<int> utf8Bytes = [
    0x48, // H
    0x65, // e
    0x6C, // l
    0x6C, // l
    0x6F, // o
    0x2C, // ,
    0x20, // space
    0xE4, 0xB8, 0x96, // 世
    0xE7, 0x95, 0x8C, // 界
    0x21  // !
  ];

  String decoded = manualUtf8Decode(utf8Bytes);
  print(decoded); // Should print: Hello, 世界!
}

String manualUtf8Decode(List<int> bytes) {
  StringBuffer buffer = StringBuffer();
  int i = 0;
  while (i < bytes.length) {
    int byte1 = bytes[i];
    if (byte1 & 0x80 == 0) {
      // 1-byte (ASCII)
      buffer.writeCharCode(byte1);
      i += 1;
    } else if ((byte1 & 0xE0) == 0xC0) {
      // 2-byte sequence
      if (i + 1 >= bytes.length) throw FormatException("Unexpected end of input");
      int byte2 = bytes[i + 1];
      if ((byte2 & 0xC0) != 0x80) throw FormatException("Invalid UTF-8 continuation byte");
      int codePoint = ((byte1 & 0x1F) << 6) | (byte2 & 0x3F);
      buffer.writeCharCode(codePoint);
      i += 2;
    } else if ((byte1 & 0xF0) == 0xE0) {
      // 3-byte sequence
      if (i + 2 >= bytes.length) throw FormatException("Unexpected end of input");
      int byte2 = bytes[i + 1];
      int byte3 = bytes[i + 2];
      if ((byte2 & 0xC0) != 0x80 || (byte3 & 0xC0) != 0x80) {
        throw FormatException("Invalid UTF-8 continuation byte");
      }
      int codePoint = ((byte1 & 0x0F) << 12) |
                      ((byte2 & 0x3F) << 6) |
                      (byte3 & 0x3F);
      buffer.writeCharCode(codePoint);
      i += 3;
    } else if ((byte1 & 0xF8) == 0xF0) {
      // 4-byte sequence (produces surrogate pair)
      if (i + 3 >= bytes.length) throw FormatException("Unexpected end of input");
      int byte2 = bytes[i + 1];
      int byte3 = bytes[i + 2];
      int byte4 = bytes[i + 3];
      if ((byte2 & 0xC0) != 0x80 ||
          (byte3 & 0xC0) != 0x80 ||
          (byte4 & 0xC0) != 0x80) {
        throw FormatException("Invalid UTF-8 continuation byte");
      }
      int codePoint = ((byte1 & 0x07) << 18) |
                      ((byte2 & 0x3F) << 12) |
                      ((byte3 & 0x3F) << 6) |
                      (byte4 & 0x3F);
      // Encode as surrogate pair
      codePoint -= 0x10000;
      int highSurrogate = 0xD800 + ((codePoint >> 10) & 0x3FF);
      int lowSurrogate = 0xDC00 + (codePoint & 0x3FF);
      buffer.writeCharCode(highSurrogate);
      buffer.writeCharCode(lowSurrogate);
      i += 4;
    } else {
      throw FormatException("Invalid UTF-8 start byte: 0x${byte1.toRadixString(16)}");
    }
  }
  return buffer.toString();
}

