import 'dart:typed_data';

void main() {
  // Initialize a 32-bit integer value
  int value = 0x12345678;

  // Convert to bytes in little endian format
  var bytesLE = ByteData(4);
  bytesLE.setUint32(0, value, Endian.little);

  // Convert to bytes in big endian format
  var bytesBE = ByteData(4);
  bytesBE.setUint32(0, value, Endian.big);

  // Print the original value as an 8-digit hex string
  print('Original value: 0x${value.toRadixString(16).padLeft(8, '0')}');

  // Helper function to convert ByteData to a space-separated hex string
  String toHex(ByteData data) {
    return List.generate(
      data.lengthInBytes,
      (i) => data.getUint8(i).toRadixString(16).padLeft(2, '0'),
    ).join(' ');
  }

  // Print the byte representations
  print('Little endian bytes: ${toHex(bytesLE)}');
  print('Big endian bytes:    ${toHex(bytesBE)}');

  // Read bytes back as integers using the correct endianness
  int fromLE = bytesLE.getUint32(0, Endian.little);
  int fromBE = bytesBE.getUint32(0, Endian.big);

  // Print the read values as 8-digit hex strings
  print('Read from little endian bytes: 0x${fromLE.toRadixString(16).padLeft(8, '0')}');
  print('Read from big endian bytes:    0x${fromBE.toRadixString(16).padLeft(8, '0')}');
}
