  ProcessSignal.sigint.watch().listen((_) {
    print('\nShutting down background scheduler...');
    for (var t in timers) {
      t.cancel();
    }
    print('All tasks cancelled. Exiting.');
    exit(0);
  });

  // Prevent main from exiting
  await Completer<void>().future;
}

