@pragma('vm:entry-point')
void main() {
  // In-app Survey System

  // Define a survey with questions and possible answers
  final survey = <Map<String, dynamic>>[
    {
      'question': 'How satisfied are you with our app?',
      'options': ['Very Satisfied', 'Satisfied', 'Neutral', 'Dissatisfied', 'Very Dissatisfied']
    },
    {
      'question': 'How often do you use the app?',
      'options': ['Daily', 'Weekly', 'Monthly', 'Rarely', 'First time']
    },
    {
      'question': 'Would you recommend our app to others?',
      'options': ['Definitely', 'Probably', 'Not Sure', 'Probably Not', 'Definitely Not']
    },
    {
      'question': 'What feature do you use the most?',
      'options': ['Chat', 'Notifications', 'Profile', 'Settings', 'Other']
    },
    {
      'question': 'Any suggestions for improvement? (Optional)',
      'options': null // Open-ended
    },
  ];

  print('=== Welcome to the In-App Survey! ===\n');

  final responses = <String, String>{};

  for (final q in survey) {
    final question = q['question'] as String;
    final options = q['options'] as List<String>?;

    print(question);

    if (options != null) {
      // Display options
      for (var i = 0; i < options.length; i++) {
        print('  ${i + 1}. ${options[i]}');
      }
      String? input;
      int? selected;
      do {
        stdout.write('Select an option (1-${options.length}): ');
        input = stdin.readLineSync();
        if (input == null) continue;
        selected = int.tryParse(input);
      } while (selected == null || selected < 1 || selected > options.length);

      responses[question] = options[selected - 1];
    } else {
      // Open-ended answer
      stdout.write('Your answer: ');
      final answer = stdin.readLineSync() ?? '';
      responses[question] = answer.trim();
    }
    print('');
  }

  print('Thank you for completing the survey!\n');
  print('=== Your Responses ===');
  responses.forEach((q, a) {
    print('\n$q\n  -> $a');
  });
  print('\nHave a great day!');
}

