  // Define roles and their permissions
  final Map<String, List<String>> rolePermissions = {
    'admin': ['read', 'write', 'delete', 'manage_users'],
    'editor': ['read', 'write'],
    'viewer': ['read'],
  };

  // Simulate users and their roles
  final Map<String, String> users = {
    'alice': 'admin',
    'bob': 'editor',
    'carol': 'viewer',
    'dave': 'unknown', // user with no valid role
  };

  // Function to check if a user has a permission
  bool hasPermission(String username, String permission) {
    final role = users[username];
    if (role == null || !rolePermissions.containsKey(role)) {
      return false;
    }
    return rolePermissions[role]!.contains(permission);
  }

  // Test cases
  final testCases = [
    {'user': 'alice', 'permission': 'delete'},
    {'user': 'bob', 'permission': 'write'},
    {'user': 'carol', 'permission': 'write'},
    {'user': 'carol', 'permission': 'read'},
    {'user': 'dave', 'permission': 'read'},
    {'user': 'alice', 'permission': 'manage_users'},
    {'user': 'bob', 'permission': 'delete'},
  ];

  for (var test in testCases) {
    final user = test['user']!;
    final perm = test['permission']!;
    final allowed = hasPermission(user, perm);
    print(
        'User "$user" with role "${users[user] ?? 'none'}" ${allowed ? "CAN" : "CANNOT"} perform "$perm".');
  }
}

