import 'dart:io';

@pragma('vm:entry-point')
void main() {
  print('=== Simple Dart Form Validation ===');
  String? name;
  String? email;
  String? password;

  // Name validation: Not empty, at least 2 characters
  while (true) {
    stdout.write('Enter your name: ');
    name = stdin.readLineSync();
    if (name == null || name.trim().isEmpty) {
      print('Error: Name cannot be empty.');
    } else if (name.trim().length < 2) {
      print('Error: Name must be at least 2 characters.');
    } else {
      print('Name accepted.');
      break;
    }
  }

  // Email validation: Simple regex check
  final emailRegex = RegExp(r'^[\w\.-]+@[\w\.-]+\.\w{2,}$');
  while (true) {
    stdout.write('Enter your email: ');
    email = stdin.readLineSync();
    if (email == null || email.trim().isEmpty) {
      print('Error: Email cannot be empty.');
    } else if (!emailRegex.hasMatch(email.trim())) {
      print('Error: Invalid email format.');
    } else {
      print('Email accepted.');
      break;
    }
  }

  // Password validation: Minimum 6 characters, at least one number
  final numberRegex = RegExp(r'\d');
  while (true) {
    stdout.write('Enter your password: ');
    password = stdin.readLineSync();
    if (password == null || password.isEmpty) {
      print('Error: Password cannot be empty.');
    } else if (password.length < 6) {
      print('Error: Password must be at least 6 characters.');
    } else if (!numberRegex.hasMatch(password)) {
      print('Error: Password must contain at least one number.');
    } else {
      print('Password accepted.');
      break;
    }
  }

  print('\n=== Form Submitted Successfully! ===');
  print('Name: $name');
  print('Email: $email');
  // Do not print password in real apps
}

