import 'dart:async';

/// A simple Notification class to represent an in-app notification.
class Notification {
  final String id;
  final String title;
  final String message;
  final DateTime timestamp;
  bool isRead;

  Notification({
    required this.id,
    required this.title,
    required this.message,
    required this.timestamp,
    this.isRead = false,
  });

  @override
  String toString() {
    return '[${isRead ? "READ" : "UNREAD"}] $title: $message (${timestamp.toLocal()})';
  }
}

/// NotificationCenter manages notifications and notifies listeners of changes.
class NotificationCenter {
  final List<Notification> _notifications = [];
  final StreamController<List<Notification>> _streamController =
      StreamController.broadcast();

  /// Listen for changes to the notifications list.
  Stream<List<Notification>> get notificationsStream =>
      _streamController.stream;

  /// Add a new notification.
  void addNotification(Notification notification) {
    _notifications.insert(0, notification);
    _streamController.add(List.unmodifiable(_notifications));
  }

  /// Mark a notification as read.
  void markAsRead(String id) {
    for (var n in _notifications) {
      if (n.id == id) {
        n.isRead = true;
        break;
      }
    }
    _streamController.add(List.unmodifiable(_notifications));
  }

  /// Remove a notification.
  void removeNotification(String id) {
    _notifications.removeWhere((n) => n.id == id);
    _streamController.add(List.unmodifiable(_notifications));
  }

  /// Get unread notifications count.
  int get unreadCount =>
      _notifications.where((n) => !n.isRead).length;

  /// Dispose the controller.
  void dispose() {
    _streamController.close();
  }
}

@pragma('vm:entry-point')
void main() async {
  final notificationCenter = NotificationCenter();

  // Listen for notification updates.
  final subscription = notificationCenter.notificationsStream.listen((notifs) {
    print('\n=== Notifications Center ===');
    if (notifs.isEmpty) {
      print('No notifications.');
    } else {
      for (var n in notifs) {
        print(n);
      }
      print('Unread count: ${notificationCenter.unreadCount}');
    }
    print('===========================\n');
  });

  // Simulate adding notifications.
  notificationCenter.addNotification(Notification(
    id: '1',
    title: 'Welcome',
    message: 'Thanks for joining our app!',
    timestamp: DateTime.now(),
  ));

  await Future.delayed(Duration(seconds: 1));

  notificationCenter.addNotification(Notification(
    id: '2',
    title: 'Update',
    message: 'Version 2.0 is now available.',
    timestamp: DateTime.now(),
  ));

  await Future.delayed(Duration(seconds: 1));

  // Simulate marking as read.
  notificationCenter.markAsRead('1');

  await Future.delayed(Duration(seconds: 1));

  // Simulate removing a notification.
  notificationCenter.removeNotification('2');

  await Future.delayed(Duration(seconds: 1));

  // Simulate adding another notification.
  notificationCenter.addNotification(Notification(
    id: '3',
    title: 'Reminder',
    message: 'Don\'t forget to check your messages.',
    timestamp: DateTime.now(),
  ));

  await Future.delayed(Duration(seconds: 1));

  // Cleanup.
  await subscription.cancel();
  notificationCenter.dispose();
}

