import 'dart:io';

@pragma('vm:entry-point')
void main() {
  // Define available widget types
  final widgetTypes = <String, WidgetBuilder>{
    'Clock': () => ClockWidget(),
    'Weather': () => WeatherWidget(),
    'Quote': () => QuoteWidget(),
    'Todo': () => TodoWidget(),
  };

  // User's home screen widgets
  final List<HomeWidget> homeScreen = [];

  print('Welcome to the Customizable Home Screen Widgets Demo!\n');

  while (true) {
    print('\nYour Home Screen:');
    if (homeScreen.isEmpty) {
      print('  (No widgets yet)');
    } else {
      for (var i = 0; i < homeScreen.length; i++) {
        print('  ${i + 1}. ${homeScreen[i].title}');
      }
    }

    print('\nOptions:');
    print('  1. Add Widget');
    print('  2. Remove Widget');
    print('  3. Show Widgets');
    print('  4. Exit');
    stdout.write('Select an option: ');
    final input = stdin.readLineSync();

    if (input == '1') {
      print('\nAvailable Widgets:');
      for (var i = 0; i < widgetTypes.keys.length; i++) {
        print('  ${i + 1}. ${widgetTypes.keys.elementAt(i)}');
      }
      stdout.write('Enter widget number to add: ');
      final widgetInput = stdin.readLineSync();
      final idx = int.tryParse(widgetInput ?? '') ?? -1;
      if (idx < 1 || idx > widgetTypes.length) {
        print('Invalid selection.');
        continue;
      }
      final widgetType = widgetTypes.keys.elementAt(idx - 1);
      final widget = widgetTypes[widgetType]!();
      widget.customize();
      homeScreen.add(widget);
      print('Added $widgetType widget to your home screen.');
    } else if (input == '2') {
      if (homeScreen.isEmpty) {
        print('No widgets to remove.');
        continue;
      }
      stdout.write('Enter widget number to remove: ');
      final removeInput = stdin.readLineSync();
      final idx = int.tryParse(removeInput ?? '') ?? -1;
      if (idx < 1 || idx > homeScreen.length) {
        print('Invalid selection.');
        continue;
      }
      final removed = homeScreen.removeAt(idx - 1);
      print('Removed ${removed.title} widget.');
    } else if (input == '3') {
      print('\nHome Screen Widgets Preview:\n');
      if (homeScreen.isEmpty) {
        print('  (No widgets added yet)');
      } else {
        for (var widget in homeScreen) {
          widget.display();
          print('---');
        }
      }
    } else if (input == '4') {
      print('Exiting. Goodbye!');
      break;
    } else {
      print('Invalid option.');
    }
  }
}

// Abstract widget interface
abstract class HomeWidget {
  String get title;
  void customize();
  void display();
}

typedef WidgetBuilder = HomeWidget Function();

// Clock Widget
class ClockWidget implements HomeWidget {
  String style = '24-hour';

  @override
  String get title => 'Clock ($style)';

  @override
  void customize() {
    print('Customize Clock Widget:');
    print('  1. 12-hour');
    print('  2. 24-hour');
    stdout.write('Choose clock style (default 24-hour): ');
    final input = stdin.readLineSync();
    if (input == '1') {
      style = '12-hour';
    } else {
      style = '24-hour';
    }
  }

  @override
  void display() {
    final now = DateTime.now();
    String time;
    if (style == '12-hour') {
      final hour = now.hour % 12 == 0 ? 12 : now.hour % 12;
      final ampm = now.hour >= 12 ? 'PM' : 'AM';
      time = '${_pad(hour)}:${_pad(now.minute)} $ampm';
    } else {
      time = '${_pad(now.hour)}:${_pad(now.minute)}';
    }
    print('🕒 Clock Widget [$style]');
    print('  Time: $time');
  }

  String _pad(int n) => n.toString().padLeft(2, '0');
}

// Weather Widget
class WeatherWidget implements HomeWidget {
  String city = 'New York';

  @override
  String get title => 'Weather ($city)';

  @override
  void customize() {
    stdout.write('Enter city for Weather Widget (default New York): ');
    final input = stdin.readLineSync();
    if (input != null && input.trim().isNotEmpty) {
      city = input.trim();
    }
  }

  @override
  void display() {
    // Simulated weather
    final temps = {'New York': 22, 'London': 18, 'Tokyo': 25, 'Paris': 20};
    final temp = temps[city] ?? (15 + city.length);
    print('🌤️ Weather Widget [$city]');
    print('  Temperature: $temp°C');
    print('  Condition: Sunny');
  }
}

// Quote Widget
class QuoteWidget implements HomeWidget {
  String category = 'Motivational';

  static const quotes = {
    'Motivational': [
      "Believe you can and you're halfway there.",
      "Don't watch the clock; do what it does. Keep going.",
    ],
    'Funny': [
      "I'm not arguing, I'm just explaining why I'm right.",
      "I'm on a seafood diet. I see food and I eat it.",
    ],
    'Life': [
      "Life is what happens when you're busy making other plans.",
      "To live is the rarest thing in the world.",
    ]
  };

  @override
  String get title => 'Quote ($category)';

  @override
  void customize() {
    print('Quote categories:');
    final cats = quotes.keys.toList();
    for (var i = 0; i < cats.length; i++) {
      print('  ${i + 1}. ${cats[i]}');
    }
    stdout.write('Choose category (default Motivational): ');
    final input = stdin.readLineSync();
    final idx = int.tryParse(input ?? '') ?? 1;
    if (idx >= 1 && idx <= cats.length) {
      category = cats[idx - 1];
    }
  }

  @override
  void display() {
    final catQuotes = quotes[category] ?? quotes['Motivational']!;
    final quote = catQuotes[DateTime.now().second % catQuotes.length];
    print('💡 Quote Widget [$category]');
    print('  "$quote"');
  }
}

// Todo Widget
class TodoWidget implements HomeWidget {
  final List<String> tasks = [];

  @override
  String get title => 'Todo (${tasks.length} tasks)';

  @override
  void customize() {
    print('Enter your todo items (empty line to finish):');
    while (true) {
      stdout.write('  > ');
      final input = stdin.readLineSync();
      if (input == null || input.trim().isEmpty) break;
      tasks.add(input.trim());
    }
    if (tasks.isEmpty) {
      tasks.add('Sample Task');
    }
  }

  @override
  void display() {
    print('📝 Todo Widget');
    for (var i = 0; i < tasks.length; i++) {
      print('  [ ] ${tasks[i]}');
    }
  }
}

