import 'dart:io';
import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // In-memory user database
  final Map<String, User> users = {};
  final Map<String, String> referralCodes = {}; // code -> userId

  // Helper to generate unique referral codes
  String generateReferralCode() {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    final rand = Random.secure();
    String code;
    do {
      code = List.generate(6, (_) => chars[rand.nextInt(chars.length)]).join();
    } while (referralCodes.containsKey(code));
    return code;
  }

  // Register a new user
  User registerUser(String name, [String? referralCode]) {
    final userId = 'u${users.length + 1}';
    final code = generateReferralCode();
    final user = User(userId, name, code);
    users[userId] = user;
    referralCodes[code] = userId;

    if (referralCode != null && referralCodes.containsKey(referralCode)) {
      final referrerId = referralCodes[referralCode]!;
      if (referrerId != userId) {
        // Reward both users
        users[referrerId]!.rewardPoints += 100;
        user.rewardPoints += 50;
        print(
            "Referral successful! ${users[referrerId]!.name} (+100 pts), ${user.name} (+50 pts)");
      }
    }
    return user;
  }

