  // Assign user to a group based on a hash of their user ID.
  // This ensures the same user gets the same variant each time.
  int hashUserId(int id) {
    // Simple hash: XOR-fold and mod
    int hash = id ^ (id >> 16);
    return hash & 0x7FFFFFFF;
  }

  // Two variants: A and B (50/50 split)
  String assignVariant(int id) {
    int hash = hashUserId(id);
    return (hash % 2 == 0) ? 'A' : 'B';
