void main() {
  // Example input: a list of integers to sort.
  final list = [33, 10, 55, 71, 29, 5, 5, 90, 1, -4, 33, 18];

  print('Before: $list');

  // Iterative in-place Quick Sort using a manual stack and Lomuto partition scheme.
  if (list.isNotEmpty) {
    final stackLow = <int>[];
    final stackHigh = <int>[];

    // Initialize stack with the full range.
    stackLow.add(0);
    stackHigh.add(list.length - 1);

    while (stackLow.isNotEmpty) {
      final low = stackLow.removeLast();
      final high = stackHigh.removeLast();

      if (low >= high) {
        continue; // No need to sort ranges of size 0 or 1.
      }

      // Partition (Lomuto scheme) with pivot as the last element.
      final pivot = list[high];
      var i = low - 1;
      for (var j = low; j < high; j++) {
        if (list[j] <= pivot) {
          i++;
          final tmp = list[i];
          list[i] = list[j];
          list[j] = tmp;
        }
      }
      // Place pivot to its correct position.
      final tmp = list[i + 1];
      list[i + 1] = list[high];
      list[high] = tmp;
      final p = i + 1;

      // Push subranges to stack (left and right of pivot).
      if (p - 1 > low) {
        stackLow.add(low);
        stackHigh.add(p - 1);
      }
      if (p + 1 < high) {
        stackLow.add(p + 1);
        stackHigh.add(high);
      }
    }
  }

  print('After:  $list');
}

