    print('Please provide a non-negative integer (e.g., "dart run main.dart 20").');
    return;
  }

  // Initialize a memoization map with base cases for Fibonacci sequence
  final Map<int, BigInt> memo = {0: BigInt.zero, 1: BigInt.one};

  // Recursive Fibonacci function with memoization
  BigInt fib(int k) {
    // Check if the value is already computed and stored in memo
    final cached = memo[k];
    if (cached != null) return cached;

    // Compute the Fibonacci number recursively and store it in memo
    final value = fib(k - 1) + fib(k - 2);
    memo[k] = value;
    return value;
  }

