  // Iterative bottom-up merge sort (stable, O(n log n) time, O(n) extra space).
  final List<int> buffer = List<int>.filled(n, 0);
  int width = 1;
  while (width < n) {
    int i = 0;
    while (i < n) {
      final int left = i;
      final int mid = (i + width < n) ? i + width : n;
      final int right = (i + 2 * width < n) ? i + 2 * width : n;

      int li = left;   // index into left run [left, mid)
      int ri = mid;    // index into right run [mid, right)
      int di = left;   // index into buffer

      // Merge from arr into buffer
      while (li < mid && ri < right) {
        if (arr[li] <= arr[ri]) {
          buffer[di++] = arr[li++];
        } else {
          buffer[di++] = arr[ri++];
        }
      }
      // Copy any remaining elements
