      while (ri < right) buffer[di++] = arr[ri++];

      // Copy merged run back to arr
      for (int k = left; k < right; k++) {
        arr[k] = buffer[k];
      }

      i += 2 * width;
    }
    width *= 2;
  }

  print('After:  $arr');
}

