  for (final v in data) {
    if (v < minVal) minVal = v;
    if (v > maxVal) maxVal = v;
  }

  final int rangeSize = maxVal - minVal + 1;
  // Threshold to keep counting sort memory small. Adjust as needed.
  const int maxRangeForCountingSort = 1000000;

  List<int> sorted;
  if (rangeSize <= maxRangeForCountingSort) {
    // Counting sort for small ranges (stable).
    final counts = Uint32List(rangeSize); // zero-initialized
    for (final v in data) {
