    print('  dart run program.dart 3            # subsets of [1, 2, 3]');
    print('  dart run program.dart red blue     # subsets of [red, blue]');
    print('');
  } else if (args.length == 1) {
    final n = int.tryParse(args[0]);
    if (n != null && n >= 0) {
      elements = List<String>.generate(n, (i) => '${i + 1}');
    } else {
      elements = args;
    }
  } else {
    elements = args;
  }

  final n = elements.length;
  final total = 1 << n; // 2^n

  // Print input elements and total subsets
  print('Input elements ($n): [${elements.join(', ')}]');
  print('Total subsets: $total');
  print('Subsets:');

  // Generate all subsets using bitmasking
  for (int mask = 0; mask < total; mask++) {
    final buffer = StringBuffer();
    buffer.write('[');
    bool first = true;
    for (int i = 0; i < n; i++) {
      if ((mask & (1 << i)) != 0) {
        if (!first) {
          buffer.write(', ');
        }
        buffer.write(elements[i]);
        first = false;
      }
    }
    buffer.write(']');
    print(buffer.toString());
  }
}
```

### Explanation:
- **Element Handling**: The code checks the command-line arguments and sets `elements` accordingly, with a default case and support for numeric input.
- **Subset Calculation**: The total number of subsets is calculated using bit shifting (`1 << n`), which is efficient for powers of two.
- **Bitmasking Loop**: For each possible mask (from 0 to `total - 1`), it checks which bits are set to include the corresponding elements in the subset, using `StringBuffer` to build the output string neatly.
- **Output**: The program prints the input elements, the total number of subsets, and each subset in a formatted list.

This code is idiomatic Dart, using common practices like `List.generate`, `StringBuffer`, and bitwise operations for clarity and efficiency.

