void main() {
  // Items with their weights and values
  final weights = [2, 1, 3, 2];
  final values = [12, 10, 20, 15];
  final capacity = 5;
  final n = weights.length;

  // Create DP table
  final dp = List.generate(n + 1, (_) => List.filled(capacity + 1, 0));

  // Fill the DP table
  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {
      // If current item's weight is more than current capacity, skip it
      if (weights[i - 1] > w) {
        dp[i][w] = dp[i - 1][w];
      } else {
        // Take maximum of including or excluding current item
        dp[i][w] = dp[i - 1][w] > (dp[i - 1][w - weights[i - 1]] + values[i - 1])
            ? dp[i - 1][w]
            : dp[i - 1][w - weights[i - 1]] + values[i - 1];
      }
    }
  }

  // Find which items were selected
