    [0, 0, 0, 0, 8, 0, 0, 7, 9]
  ];

  print('Original Sudoku puzzle:');
  for (var row in board) {
    print(row.map((cell) => cell == 0 ? '.' : cell.toString()).join(' '));
  }
  print('');

  // Function to check if a number is valid in a given position
  bool isValid(List<List<int>> board, int row, int col, int num) {
    // Check row
    for (int x = 0; x < 9; x++) {
      if (board[row][x] == num) {
        return false;
      }
    }

    // Check column
    for (int x = 0; x < 9; x++) {
      if (board[x][col] == num) {
        return false;
      }
    }

    // Check 3x3 box
    int startRow = row - row % 3;
    int startCol = col - col % 3;
    for (int i = 0; i < 3; i++) {
      for (int j = 0; j < 3; j++) {
        if (board[i + startRow][j + startCol] == num) {
          return false;
        }
      }
    }

    return true;
  }

  // Function to find empty cell
  List<int>? findEmpty(List<List<int>> board) {
    for (int i = 0; i < 9; i++) {
      for (int j = 0; j < 9; j++) {
        if (board[i][j] == 0) {
          return [i, j];
        }
      }
    }
    return null;
  }

  // Recursive function to solve Sudoku using backtracking
  bool solve(List<List<int>> board) {
    var empty = findEmpty(board);
    if (empty == null) {
      return true; // No empty cells, puzzle solved
    }

    int row = empty[0];
    int col = empty[1];

    for (int num = 1; num <= 9; num++) {
      if (isValid(board, row, col, num)) {
        board[row][col] = num;

        if (solve(board)) {
          return true;
        }

        // Backtrack
        board[row][col] = 0;
      }
    }

    return false;
  }

  // Solve the puzzle
  if (solve(board)) {
    print('Solved Sudoku puzzle:');
    for (var row in board) {
      print(row.join(' '));
    }
  } else {
    print('No solution exists for this Sudoku puzzle.');
  }
}

