  int count = 0;
  while (iterator.moveNext() && count < 5) {
    print("  Rune at position $count: ${iterator.current} "
          "-> '${String.fromCharCode(iterator.current)}'");
    count++;
  }
  print("");

  // Practical example: Reversing a string with emojis correctly
  String toReverse = "Hello 👋🏽 World 🌍!";
  print("Original string: $toReverse");

  // Wrong way (breaks emojis)
  String wrongReverse = toReverse.split('').reversed.join('');
  print("Wrong reverse (split): $wrongReverse");

  // Correct way (using runes)
  String correctReverse = String.fromCharCodes(toReverse.runes.toList().reversed);
  print("Correct reverse (runes): $correctReverse");
  print("");

  // Checking if a string contains specific Unicode characters
