  int searchEmoji = 0x1F50D; // 🔍
  bool containsSearchEmoji = searchText.runes.contains(searchEmoji);
  print("Text: $searchText");
  print("Contains 🔍 emoji: $containsSearchEmoji");

  // Finding position of emoji
  List<int> searchRunes = searchText.runes.toList();
  int emojiPosition = searchRunes.indexOf(searchEmoji);
  print("Position of 🔍 in runes list: $emojiPosition");
}

