        (key == 'showEmail' && value != false) ||
        (key == 'showActivity' && value != true)) {
      privacyCustomized = true;
    }
  });
  if (privacyCustomized) completionScore++;

  // Check notification customization
  bool notificationCustomized = false;
  profile['notifications'].forEach((key, value) {
    if ((key == 'email' && value != true) ||
        (key == 'push' && value != false) ||
        (key == 'sms' && value != false)) {
      notificationCustomized = true;
    }
  });
  if (notificationCustomized) completionScore++;

  // Check preferences customization
  bool preferencesCustomized = false;
  profile['preferences'].forEach((key, value) {
    if ((key == 'newsletter' && value != true) ||
        (key == 'autoplay' && value != false) ||
        (key == 'soundEffects' && value != true)) {
      preferencesCustomized = true;
    }
  });
  if (preferencesCustomized) completionScore++;

  double completionPercentage = (completionScore / totalFields) * 100;

  print('Profile Completion: ${completionPercentage.toStringAsFixed(0)}%');
