  ];

  // Responsive breakpoints
  const mobileBreakpoint = 600.0;
  const tabletBreakpoint = 1024.0;
  const desktopBreakpoint = 1440.0;

  // Function to determine device type based on width
  String getDeviceType(double width) {
    if (width < mobileBreakpoint) {
      return 'Mobile';
    } else if (width < tabletBreakpoint) {
      return 'Tablet';
    } else if (width < desktopBreakpoint) {
      return 'Desktop';
    } else {
      return 'Large Desktop';
    }
  }

  // Function to calculate responsive font sizes
  double getResponsiveFontSize(double width, String element) {
    final baseSize = {
      'heading': 32.0,
      'subheading': 24.0,
      'body': 16.0,
      'caption': 12.0,
    };

    double scaleFactor;
    if (width < mobileBreakpoint) {
      scaleFactor = 0.8;
    } else if (width < tabletBreakpoint) {
      scaleFactor = 0.9;
    } else if (width < desktopBreakpoint) {
      scaleFactor = 1.0;
    } else {
      scaleFactor = 1.1;
    }

    return (baseSize[element] ?? 16.0) * scaleFactor;
  }

  // Function to calculate responsive padding
  double getResponsivePadding(double width) {
    if (width < mobileBreakpoint) {
      return 16.0;
    } else if (width < tabletBreakpoint) {
      return 24.0;
    } else if (width < desktopBreakpoint) {
      return 32.0;
    } else {
      return 48.0;
    }
  }

  // Function to determine number of columns in grid
  int getGridColumns(double width) {
    if (width < mobileBreakpoint) {
      return 1;
    } else if (width < tabletBreakpoint) {
      return 2;
    } else if (width < desktopBreakpoint) {
      return 3;
    } else {
      return 4;
    }
  }

  // Function to calculate responsive container width
  double getContainerWidth(double screenWidth) {
    if (screenWidth < mobileBreakpoint) {
      return screenWidth * 0.95;
    } else if (screenWidth < tabletBreakpoint) {
      return screenWidth * 0.90;
    } else if (screenWidth < desktopBreakpoint) {
      return screenWidth * 0.85;
    } else {
      return screenWidth * 0.80;
    }
  }

