  print('=== Responsive Scaling Factors ===\n');

  final baseWidth = 1920.0; // Base design width

  for (var screen in screenSizes) {
    final width = screen['width'] as double;
    final name = screen['name'] as String;
    final scaleFactor = width / baseWidth;

    print('$name Scale Factor: ${scaleFactor.toStringAsFixed(3)}');
    print('  Scaled 100px element: ${(100 * scaleFactor).toStringAsFixed(1)}px');
    print('  Scaled 50px margin: ${(50 * scaleFactor).toStringAsFixed(1)}px');
    print('');
  }

  // Demonstrate fluid typography calculations
  print('=== Fluid Typography ===\n');

  // Calculate fluid font size using viewport width units
  for (var screen in screenSizes) {
    final width = screen['width'] as double;
    final name = screen['name'] as String;

    // Fluid calculation: min + (max - min) * ((viewport - minViewport) / (maxViewport - minViewport))
    final minFontSize = 16.0;
    final maxFontSize = 24.0;
    final minViewport = 320.0;
    final maxViewport = 1920.0;

    double fluidFontSize = minFontSize + (maxFontSize - minFontSize) * 
        ((width - minViewport) / (maxViewport - minViewport));

    // Clamp the value
    fluidFontSize = fluidFontSize.clamp(minFontSize, maxFontSize);

    print('$name Fluid Font Size: ${fluidFontSize.toStringAsFixed(1)}px');
  }
