void simulateUI(Theme theme) {
  print('  Header: ${theme.primaryColor.toHex()} background');
  print('  Body: ${theme.backgroundColor.toHex()} background');
  print('  Text: ${theme.textColor.toHex()} color');
  print('  Buttons: ${theme.accentColor.toHex()} color');
  print('  Status: Theme "${theme.name}" applied successfully');
}

class Theme {
  final String name;
  final Color primaryColor;
  final Color backgroundColor;
  final Color textColor;
  final Color accentColor;

  Theme({
    required this.name,
    required this.primaryColor,
    required this.backgroundColor,
    required this.textColor,
    required this.accentColor,
  });
}

class Color {
  final int value;

  const Color(this.value);

  String toHex() {
    return '#${(value & 0xFFFFFF).toRadixString(16).padLeft(6, '0').toUpperCase()}';
  }

  @override
  String toString() => toHex();
}

class ThemeManager {
  final Map<String, Theme> _themes;
  Theme? _currentTheme;
  String? _currentThemeKey;
  final List<String> _themeHistory = [];

  ThemeManager(this._themes);

  Theme? get currentTheme => _currentTheme;

  void setTheme(String themeKey) {
    if (_themes.containsKey(themeKey)) {
      _currentTheme = _themes[themeKey];
      _currentThemeKey = themeKey;
      _themeHistory.add(themeKey);
      print('Theme changed to: ${_currentTheme!.name}');
    } else {
      print('Error: Theme "$themeKey" not found. Current theme unchanged.');
    }
  }

  void addTheme(String key, Theme theme) {
    _themes[key] = theme;
    print('Added new theme: ${theme.name}');
  }

  void cycleTheme() {
    var keys = _themes.keys.toList();
    if (keys.isEmpty) return;

    var currentIndex = _currentThemeKey != null 
        ? keys.indexOf(_currentThemeKey!) 
        : -1;

    var nextIndex = (currentIndex + 1) % keys.length;
    setTheme(keys[nextIndex]);
  }

  void displayCurrentTheme() {
    if (_currentTheme == null) {
      print('No theme currently set');
      return;
    }

    print('Current Theme: ${_currentTheme!.name}');
    print('  Primary Color: ${_currentTheme!.primaryColor}');
    print('  Background Color: ${_currentTheme!.backgroundColor}');
    print('  Text Color: ${_currentTheme!.textColor}');
    print('  Accent Color: ${_currentTheme!.accentColor}');
  }

  void listAvailableThemes() {
    print('Available themes:');
    _themes.forEach((key, theme) {
      var indicator = key == _currentThemeKey ? ' (current)' : '';
      print('  - $key: ${theme.name}$indicator');
    });
  }

  void showThemeHistory() {
    print('Theme history:');
    for (int i = 0; i < _themeHistory.length; i++) {
      print('  ${i + 1}. ${_themeHistory[i]}');
    }
  }
}

