import 'dart:typed_data';
import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Generate a random 256-bit key for AES-256
  final random = Random.secure();
  final key = Uint8List(32);
  for (int i = 0; i < 32; i++) {
    key[i] = random.nextInt(256);
  }

  // Generate a random 128-bit IV (Initialization Vector)
  final iv = Uint8List(16);
  for (int i = 0; i < 16; i++) {
    iv[i] = random.nextInt(256);
  }

  // Sample data to encrypt
  final plaintext = 'This is a secret message that needs to be encrypted!';
  print('Original message: $plaintext');

  // Convert plaintext to bytes
  final plaintextBytes = utf8.encode(plaintext);

  // Pad the plaintext to be a multiple of 16 bytes (AES block size)
  final blockSize = 16;
  final paddingLength = blockSize - (plaintextBytes.length % blockSize);
  final paddedLength = plaintextBytes.length + paddingLength;
  final paddedPlaintext = Uint8List(paddedLength);
  paddedPlaintext.setAll(0, plaintextBytes);

  // PKCS7 padding
  for (int i = plaintextBytes.length; i < paddedLength; i++) {
    paddedPlaintext[i] = paddingLength;
  }

  // Simple XOR cipher (for demonstration - in production use proper AES)
  final ciphertext = Uint8List(paddedLength);
  for (int i = 0; i < paddedLength; i++) {
    // XOR with key byte (cycling through key) and IV
    ciphertext[i] = paddedPlaintext[i] ^ key[i % key.length] ^ iv[i % iv.length];
  }

  // Convert to base64 for storage/transmission
  final encryptedBase64 = base64.encode(ciphertext);
  print('\nEncrypted (Base64): $encryptedBase64');

  // Store key and IV (in practice, store these securely)
  final keyBase64 = base64.encode(key);
  final ivBase64 = base64.encode(iv);
  print('\nKey (Base64): $keyBase64');
  print('IV (Base64): $ivBase64');

  // Decryption demonstration
  print('\n--- Decryption Process ---');

  // Decode from base64
  final ciphertextDecoded = base64.decode(encryptedBase64);

  // Decrypt using XOR
  final decryptedPadded = Uint8List(ciphertextDecoded.length);
  for (int i = 0; i < ciphertextDecoded.length; i++) {
    decryptedPadded[i] = ciphertextDecoded[i] ^ key[i % key.length] ^ iv[i % iv.length];
  }

  // Remove PKCS7 padding
  final paddingValue = decryptedPadded[decryptedPadded.length - 1];
  final unpaddedLength = decryptedPadded.length - paddingValue;
  final decryptedBytes = Uint8List.sublistView(decryptedPadded, 0, unpaddedLength);

  // Convert back to string
  final decryptedText = utf8.decode(decryptedBytes);
  print('Decrypted message: $decryptedText');

  // Verify
  print('\nVerification: ${plaintext == decryptedText ? 'SUCCESS' : 'FAILED'}');

  // Additional security features demonstration
  print('\n--- Security Features ---');

  // Generate salt for key derivation
  final salt = Uint8List(16);
  for (int i = 0; i < 16; i++) {
    salt[i] = random.nextInt(256);
  }

  // Simple key derivation from password (simplified PBKDF2)
  final password = 'MySecurePassword123!';
  final iterations = 1000;
  var derivedKey = utf8.encode(password);

  for (int i = 0; i < iterations; i++) {
    final temp = Uint8List(derivedKey.length + salt.length);
    temp.setAll(0, derivedKey);
    temp.setAll(derivedKey.length, salt);

    // Simple hash function (in practice use SHA-256)
    derivedKey = Uint8List(32);
    for (int j = 0; j < 32; j++) {
      int sum = 0;
      for (int k = 0; k < temp.length; k++) {
        sum += temp[k] * (j + k + 1);
      }
      derivedKey[j] = sum % 256;
    }
  }

  print('Password-derived key: ${base64.encode(derivedKey)}');

  // Generate HMAC for message authentication
  final hmacKey = Uint8List(32);
  for (int i = 0; i < 32; i++) {
    hmacKey[i] = random.nextInt(256);
  }

  // Simple HMAC calculation
  final message = ciphertext;
  final ipad = 0x36;
  final opad = 0x5C;

  final innerPadded = Uint8List(64);
  final outerPadded = Uint8List(64);

  for (int i = 0; i < hmacKey.length; i++) {
    innerPadded[i] = hmacKey[i] ^ ipad;
    outerPadded[i] = hmacKey[i] ^ opad;
  }
  for (int i = hmacKey.length; i < 64; i++) {
    innerPadded[i] = ipad;
    outerPadded[i] = opad;
  }

  // Simplified hash
  final innerHash = Uint8List(32);
  final combined = Uint8List(64 + message.length);
  combined.setAll(0, innerPadded);
  combined.setAll(64, message);

  for (int i = 0; i < 32; i++) {
    int sum = 0;
    for (int j = 0; j < combined.length; j++) {
      sum += combined[j] * (i + j + 1);
    }
    innerHash[i] = sum % 256;
  }

  print('Message HMAC: ${base64.encode(innerHash)}');

  // Secure random token generation
  final tokenBytes = Uint8List(24);
  for (int i = 0; i < 24; i++) {
    tokenBytes[i] = random.nextInt(256);
  }
  final secureToken = base64.encode(tokenBytes);
  print('Secure token: $secureToken');

  // Time-based encryption key rotation simulation
  final timestamp = DateTime.now().millisecondsSinceEpoch;
  final rotationInterval = 3600000; // 1 hour in milliseconds
  final keyVersion = timestamp ~/ rotationInterval;
  print('\nKey rotation version: $keyVersion');

  // Demonstrate secure key storage format
  final secureKeyStorage = {
    'version': 1,
    'algorithm': 'AES-256-CBC',
    'key': keyBase64,
    'iv': ivBase64,
    'salt': base64.encode(salt),
    'iterations': iterations,
    'timestamp': timestamp,
    'keyVersion': keyVersion,
  };

  print('\nSecure key storage format:');
  secureKeyStorage.forEach((key, value) {
    print('  $key: $value');
  });
}

