    print('${error.color}├─────────────────────────────────────────────┤$resetColor');
    print('${error.color}│$resetColor 💡 Suggestion:                              ${error.color}│$resetColor');

    final suggestionLines = _wrapTextMultiline(error.suggestion, 43);
    for (final line in suggestionLines) {
      print('${error.color}│$resetColor $line ${error.color}│$resetColor');
    }

    print('${error.color}└─────────────────────────────────────────────┘$resetColor');

    // Action buttons (simulated)
    print('\n  [Retry] [Report] [Dismiss]');
  }

  String _formatTime(DateTime time) {
    return '${time.hour.toString().padLeft(2, '0')}:'
           '${time.minute.toString().padLeft(2, '0')}:'
           '${time.second.toString().padLeft(2, '0')}';
  }

  String _wrapText(String text, int maxLength) {
    if (text.length <= maxLength) {
      return text.padRight(maxLength);
    }
    return text.substring(0, maxLength - 3) + '...';
  }

  List<String> _wrapTextMultiline(String text, int maxLength) {
    final words = text.split(' ');
    final lines = <String>[];
    var currentLine = '';

    for (final word in words) {
      if (currentLine.isEmpty) {
        currentLine = word;
      } else if ((currentLine + ' ' + word).length <= maxLength) {
        currentLine += ' ' + word;
      } else {
        lines.add(currentLine.padRight(maxLength));
        currentLine = word;
      }
    }

    if (currentLine.isNotEmpty) {
      lines.add(currentLine.padRight(maxLength));
    }

    return lines;
  }

  void printStatistics() {
    print('Total Errors: ${errorHistory.length}');
    print('\nError Breakdown:');
    errorCounts.forEach((type, count) {
      final percentage = (count / errorHistory.length * 100).toStringAsFixed(1);
      final bar = '█' * (count * 5);
      print('  $type: $count ($percentage%) $bar');
    });
  }
}

