enum OverlayPosition { top, bottom, left, right, center }

class TutorialStep {
  final String id;
  final String title;
  final String description;
  final String? targetElement;
  final OverlayPosition position;
  final double highlightPadding;

  TutorialStep({
    required this.id,
    required this.title,
    required this.description,
    this.targetElement,
    required this.position,
    required this.highlightPadding,
  });
}

class TutorialSystem {
  final List<TutorialStep> _steps = [];
  int _currentStepIndex = -1;
  bool _isActive = false;
  final Map<String, dynamic> _analytics = {
    'startTime': null,
    'endTime': null,
    'stepsCompleted': 0,
    'totalSteps': 0,
    'skipped': false,
  };

  bool get isActive => _isActive;

  void addStep(TutorialStep step) {
    _steps.add(step);
    _analytics['totalSteps'] = _steps.length;
  }

  void start() {
    if (_steps.isEmpty) {
      print('No tutorial steps defined.');
      return;
    }

    _isActive = true;
    _currentStepIndex = 0;
    _analytics['startTime'] = DateTime.now();
    _showCurrentStep();
  }

  void next() {
    if (!_isActive) return;

    _currentStepIndex++;
    _analytics['stepsCompleted'] = _currentStepIndex;

    if (_currentStepIndex >= _steps.length) {
      _complete();
    } else {
