ColorScheme generateMonochromaticScheme(Color baseColor) {
  final hsl = baseColor.toHSL();

  return ColorScheme(
    primary: baseColor,
    secondary: Color.fromHSL(HSL(hsl.h, hsl.s * 0.7, hsl.l * 0.8)),
    background: Color.fromHSL(HSL(hsl.h, hsl.s * 0.1, 0.95)),
    surface: Color.fromHSL(HSL(hsl.h, hsl.s * 0.05, 0.98)),
    onPrimary: hsl.l > 0.5 ? Color(0xFF000000) : Color(0xFFFFFFFF),
    onSecondary: Color(0xFF000000),
    onBackground: Color.fromHSL(HSL(hsl.h, hsl.s, 0.2)),
    onSurface: Color.fromHSL(HSL(hsl.h, hsl.s, 0.15)),
  );
}

ColorScheme generateComplementaryScheme(Color baseColor) {
  final hsl = baseColor.toHSL();
  final complementaryHue = (hsl.h + 180) % 360;
  final complementary = Color.fromHSL(HSL(complementaryHue, hsl.s, hsl.l));

  return ColorScheme(
    primary: baseColor,
    secondary: complementary,
    background: Color(0xFFF5F5F5),
    surface: Color(0xFFFFFFFF),
    onPrimary: hsl.l > 0.5 ? Color(0xFF000000) : Color(0xFFFFFFFF),
    onSecondary: hsl.l > 0.5 ? Color(0xFF000000) : Color(0xFFFFFFFF),
    onBackground: Color(0xFF212121),
    onSurface: Color(0xFF212121),
  );
}

ColorScheme generateTriadicScheme(Color baseColor) {
  final hsl = baseColor.toHSL();
  final color2 = Color.fromHSL(HSL((hsl.h + 120) % 360, hsl.s, hsl.l));
  final color3 = Color.fromHSL(HSL((hsl.h + 240) % 360, hsl.s, hsl.l));

  return ColorScheme(
    primary: baseColor,
    secondary: color2,
    background: Color.fromHSL(HSL(hsl.h, 0.05, 0.95)),
    surface: color3.withBrightness(0.3),
    onPrimary: hsl.l > 0.5 ? Color(0xFF000000) : Color(0xFFFFFFFF),
    onSecondary: hsl.l > 0.5 ? Color(0xFF000000) : Color(0xFFFFFFFF),
    onBackground: Color(0xFF212121),
    onSurface: Color(0xFFFFFFFF),
  );
}

ColorScheme generateAnalogousScheme(Color baseColor) {
  final hsl = baseColor.toHSL();
  final color1 = Color.fromHSL(HSL((hsl.h - 30 + 360) % 360, hsl.s, hsl.l));
  final color2 = Color.fromHSL(HSL((hsl.h + 30) % 360, hsl.s, hsl.l));

  return ColorScheme(
    primary: baseColor,
    secondary: color1,
    background: Color.fromHSL(HSL(hsl.h, 0.1, 0.96)),
    surface: color2.withBrightness(0.2),
    onPrimary: hsl.l > 0.5 ? Color(0xFF000000) : Color(0xFFFFFFFF),
    onSecondary: hsl.l > 0.5 ? Color(0xFF000000) : Color(0xFFFFFFFF),
    onBackground: Color(0xFF212121),
    onSurface: Color(0xFFFFFFFF),
  );
}

List<Color> generateGradient(Color start, Color end, int steps) {
  final List<Color> gradient = [];

  for (int i = 0; i < steps; i++) {
    final t = i / (steps - 1);
    final r = (start.red + (end.red - start.red) * t).round();
    final g = (start.green + (end.green - start.green) * t).round();
    final b = (start.blue + (end.blue - start.blue) * t).round();
    gradient.add(Color.fromRGB(r, g, b));
  }

  return gradient;
}

double luminance(Color color) {
  double toLuminance(int channel) {
    final c = channel / 255.0;
    return c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) * ((c + 0.055) / 1.055);
  }

  return 0.2126 * toLuminance(color.red) +
         0.7152 * toLuminance(color.green) +
         0.0722 * toLuminance(color.blue);
}

double contrastRatio(Color color1, Color color2) {
  final l1 = luminance(color1);
  final l2 = luminance(color2);
  final lighter = l1 > l2 ? l1 : l2;
  final darker = l1 > l2 ? l2 : l1;
  return (lighter + 0.05) / (darker + 0.05);
}

