void main() {
  // Sample data to be sorted.
  final List<int> data = [34, 7, 23, 32, 5, 62, 14, 3, 90];

  // In-place quick sort implementation (recursive, Lomuto partition scheme).
  void quickSort(List<int> arr, int low, int high) {
    if (low >= high) return;

    // Partitioning.
    final int pivot = arr[high]; // Choose the last element as pivot.
    int i = low;
    for (int j = low; j < high; j++) {
      if (arr[j] <= pivot) {
        final int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
        i++;
      }
    }
    // Place pivot in its correct position.
    final int temp = arr[i];
    arr[i] = arr[high];
    arr[high] = temp;

    // Recursively sort partitions.
    quickSort(arr, low, i - 1);
    quickSort(arr, i + 1, high);
  }

  quickSort(data, 0, data.length - 1);
  print('Sorted list: $data');
}

