  final root = TreeNode<int>(1);
  root.children.addAll([
    TreeNode<int>(2, [TreeNode<int>(5), TreeNode<int>(6)]),
    TreeNode<int>(3),
    TreeNode<int>(4, [TreeNode<int>(7), TreeNode<int>(8)])
  ]);

  // Breadth-first search (BFS) traversal.
  final queue = Queue<TreeNode<int>>();
  queue.add(root);

  final bfsOrder = <int>[];

  while (queue.isNotEmpty) {
    final node = queue.removeFirst();
    bfsOrder.add(node.value);
    queue.addAll(node.children);
  }

  print('Breadth-first traversal: $bfsOrder');
}

