void main() {
  // Nested implementation of merge sort keeps the script confined to this single top-level function.
  List<int> mergeSort(List<int> items) {
    // A list of length 0 or 1 is already sorted.
    if (items.length < 2) return items;

    final mid = items.length ~/ 2;

    // Recursively split and sort both halves.
    final left  = mergeSort(items.sublist(0, mid));
    final right = mergeSort(items.sublist(mid));

    // Merge the two sorted halves.
    List<int> merge(List<int> a, List<int> b) {
      final merged = <int>[];
      int i = 0, j = 0;

      // Compare the heads of the lists and append the smaller element.
      while (i < a.length && j < b.length) {
        if (a[i] <= b[j]) {
          merged.add(a[i++]);
        } else {
          merged.add(b[j++]);
        }
      }

      // Append any remaining elements.
      if (i < a.length) merged.addAll(a.sublist(i));
      if (j < b.length) merged.addAll(b.sublist(j));

      return merged;
    }

    return merge(left, right);
  }

  // Example usage.
  final numbers = [38, 27, 43, 3, 9, 82, 10];
  print('Original: $numbers');
  final sorted = mergeSort(numbers);
  print('Sorted:   $sorted');
}

