      args.isNotEmpty ? args.map(int.parse).toList() : [12, 11, 13, 5, 6, 7];

  // --- Heap-sort implementation (all helpers are local to main) ----------------
  void heapify(List<int> arr, int size, int root) {
    int largest = root;               // Assume root is largest.
    int left   = 2 * root + 1;        // Left child index.
    int right  = 2 * root + 2;        // Right child index.

    // If left child exists and is greater than root.
    if (left < size && arr[left] > arr[largest]) largest = left;

    // If right child exists and is greater than current largest.
    if (right < size && arr[right] > arr[largest]) largest = right;

    // If largest is not root, swap and continue heapifying.
    if (largest != root) {
      int tmp = arr[root];
      arr[root] = arr[largest];
      arr[largest] = tmp;
      heapify(arr, size, largest);
    }
  }

  void heapSort(List<int> arr) {
    final int n = arr.length;

    // 1. Build max-heap.
    for (int i = n ~/ 2 - 1; i >= 0; i--) {
      heapify(arr, n, i);
    }

    // 2. Repeatedly extract the maximum element from the heap.
    for (int i = n - 1; i > 0; i--) {
      // Move current root (max) to end.
      int tmp = arr[0];
      arr[0] = arr[i];
      arr[i] = tmp;

      // Call heapify on the reduced heap.
      heapify(arr, i, 0);
    }
  }
  // ---------------------------------------------------------------------------

  print('Before sort: $data');
  heapSort(data);
  print('After  sort: $data');
}

