// A complete Dart script that performs topological sorting on a DAG
// using Kahn's (BFS-based) algorithm.  
// ------------------------------------------------------------------
// Input format (from stdin):
//   n m          // number of vertices and edges
//   u1 v1        // m lines of directed edges ui -> vi
//   ...
//
// Vertices are 0-based and must satisfy 0 ≤ v < n.
// If the graph contains a cycle the program reports it; otherwise it
// prints a valid topological ordering (space-separated).
//
// Example:
//   6 6
//   5 2
//   5 0
//   4 0
//   4 1
//   2 3
//   3 1
// Output:
//   4 5 0 2 3 1   (one possible ordering)

import 'dart:io';
import 'dart:collection';

@pragma('vm:entry-point')
void main(List<String> args) {
  // Read the first line: number of vertices (n) and edges (m).
  final firstLine = stdin.readLineSync();
  if (firstLine == null || firstLine.trim().isEmpty) {
    stderr.writeln('No input provided.');
    exit(1);
  }
  final firstParts = firstLine.trim().split(RegExp(r'\s+'));
  if (firstParts.length < 2) {
    stderr.writeln('First line must contain two integers: n m');
    exit(1);
  }

  final int n = int.parse(firstParts[0]);
  final int m = int.parse(firstParts[1]);

  // Build adjacency list and in-degree array.
  final List<List<int>> graph = List.generate(n, (_) => <int>[]);
  final List<int> indegree = List<int>.filled(n, 0);

  for (int i = 0; i < m; i++) {
    final line = stdin.readLineSync();
    if (line == null || line.trim().isEmpty) {
      stderr.writeln('Expected $m edge lines; found fewer.');
      exit(1);
    }
    final parts = line.trim().split(RegExp(r'\s+'));
    if (parts.length < 2) {
      stderr.writeln('Edge line must contain two integers: u v');
      exit(1);
    }

    final int u = int.parse(parts[0]);
    final int v = int.parse(parts[1]);

    if (u < 0 || u >= n || v < 0 || v >= n) {
      stderr.writeln('Vertex index out of range in edge: $u -> $v');
      exit(1);
    }

    graph[u].add(v);
    indegree[v]++;
  }

  // Kahn's algorithm.
  final Queue<int> queue = Queue<int>();
  for (int i = 0; i < n; i++) {
    if (indegree[i] == 0) queue.add(i);
  }

  final List<int> topoOrder = <int>[];
  while (queue.isNotEmpty) {
    final int u = queue.removeFirst();
    topoOrder.add(u);
    for (final int v in graph[u]) {
      if (--indegree[v] == 0) queue.add(v);
    }
  }

  if (topoOrder.length != n) {
    print('Graph has at least one cycle. Topological sort not possible.');
  } else {
    print(topoOrder.join(' '));
