void main() {
  // ------------------------------------------------------------
  // A simple demonstration of radix sort (LSD, base-10) for int.
  // ------------------------------------------------------------

  // Sample data to sort.
  final List<int> numbers = [170, 45, 75, 90, 802, 24, 2, 66];
  print('Before sorting: $numbers');

  // Helper: find the largest value.
  int getMax(List<int> list) {
    int maxVal = list.first;
    for (var value in list.skip(1)) {
      if (value > maxVal) maxVal = value;
    }
    return maxVal;
  }

  // Counting sort sub-routine for a specific digit (10^exp).
  void countingSort(List<int> list, int exp) {
    final int n = list.length;
    final output = List<int>.filled(n, 0); // Sorted by current digit.
    final count  = List<int>.filled(10, 0); // Digit frequency (0-9).

    // 1) Store frequency of each digit.
    for (var value in list) {
      final int digit = (value ~/ exp) % 10;
      count[digit]++;
    }

    // 2) Transform count[] so it contains actual positions.
    for (int i = 1; i < 10; i++) {
      count[i] += count[i - 1];
    }

    // 3) Build output[] from right to left to keep sort stable.
    for (int i = n - 1; i >= 0; i--) {
      final int digit = (list[i] ~/ exp) % 10;
      output[count[digit] - 1] = list[i];
      count[digit]--;
    }

    // 4) Copy the sorted values back to the original list.
    for (int i = 0; i < n; i++) {
      list[i] = output[i];
    }
  }

  // Perform radix sort one digit at a time.
  for (int exp = 1, maxVal = getMax(numbers); maxVal ~/ exp > 0; exp *= 10) {
    countingSort(numbers, exp);
  }

  print('After sorting:  $numbers');
}

