import 'dart:io';
import 'dart:convert';

@pragma('vm:entry-point')
void main() {
  /*  Bellman-Ford shortest paths with negative-weight support.
      Expected input on stdin (whitespace separated):
        n m             – number of vertices and edges
        m lines: u v w  – edge from u to v with weight w  (0-based vertices)
        s               – source vertex
      Output:
        “NEGATIVE CYCLE” if one is reachable from s,
        otherwise distances from s to every vertex (or “INF” if unreachable). */

  // -------- Read entire input as whitespace-separated tokens ----------
  final tokens = <String>[];
  String? line;
  while ((line = stdin.readLineSync(encoding: utf8)) != null) {
    if (line!.trim().isNotEmpty) {
      tokens.addAll(line.trim().split(RegExp(r'\s+')));
    }
  }
  if (tokens.isEmpty) return; // no input

  int idx = 0;
  final int n = int.parse(tokens[idx++]); // vertices
  final int m = int.parse(tokens[idx++]); // edges

  final edges = <List<int>>[];
  for (int i = 0; i < m; i++) {
    final int u = int.parse(tokens[idx++]);
    final int v = int.parse(tokens[idx++]);
    final int w = int.parse(tokens[idx++]);
    edges.add([u, v, w]);
  }
  final int src = int.parse(tokens[idx++]);

  // ------------------- Bellman-Ford core ------------------------------
  const int INF = 1 << 60; // "infinite" distance sentinel
  final dist = List<int>.filled(n, INF);
  dist[src] = 0;

  // Relax edges |V|-1 times
  for (int i = 0; i < n - 1; i++) {
    bool updated = false;
    for (final e in edges) {
      final int u = e[0], v = e[1], w = e[2];
      if (dist[u] != INF && dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
        updated = true;
      }
    }
    if (!updated) break; // Early exit if no change this round
  }

  // Extra pass to detect negative cycles reachable from src
  bool hasNegCycle = false;
  for (final e in edges) {
    final int u = e[0], v = e[1], w = e[2];
    if (dist[u] != INF && dist[u] + w < dist[v]) {
      hasNegCycle = true;
      break;
    }
  }

  // -------------------------- Output ----------------------------------
  if (hasNegCycle) {
    print('NEGATIVE CYCLE');
  } else {
    final buffer = StringBuffer();
    for (int v = 0; v < n; v++) {
      buffer.write(dist[v] >= INF ~/ 2 ? 'INF' : dist[v]);
      if (v + 1 < n) buffer.write(' ');
    }
    print(buffer.toString());
  }
}

