import 'dart:io';

@pragma('vm:entry-point')
void main(List<String> args) {
  // Read two lines from STDIN. Empty strings if nothing was entered.
  final s1 = stdin.readLineSync() ?? '';
  final s2 = stdin.readLineSync() ?? '';

  final m = s1.length;
  final n = s2.length;

  // Dynamic-programming table: dp[i][j] = length of LCS of s1[0‥i) and s2[0‥j)
  final dp = List.generate(m + 1, (_) => List<int>.filled(n + 1, 0));

  // Build the table bottom-up
  for (var i = 1; i <= m; i++) {
    for (var j = 1; j <= n; j++) {
      if (s1[i - 1] == s2[j - 1]) {
        dp[i][j] = dp[i - 1][j - 1] + 1;
      } else {
        dp[i][j] = dp[i - 1][j] > dp[i][j - 1] ? dp[i - 1][j] : dp[i][j - 1];
      }
    }
  }

  // Reconstruct the subsequence by walking the table backwards
  var i = m;
  var j = n;
  final buffer = StringBuffer();
  while (i > 0 && j > 0) {
    if (s1[i - 1] == s2[j - 1]) {
      buffer.write(s1[i - 1]); // add matching character
      i--;
      j--;
    } else if (dp[i - 1][j] >= dp[i][j - 1]) {
      i--;
    } else {
      j--;
    }
  }

  final lcs = buffer.toString().split('').reversed.join();
  print('Length: ${dp[m][n]}');
  print('LCS   : $lcs');
}

