// A stand-alone Dart script that computes the minimum number of
// scalar multiplications needed to multiply a chain of matrices.
// Usage example:
//   dart run mcm.dart 30 35 15 5 10 20 25
// The numbers supplied on the command line are the matrix dimensions
// p0 p1 … pn such that matrix Ai has dimension (pi-1 × pi).

@pragma('vm:entry-point')
void main(List<String> args) {
  // Validate input -----------------------------------------------------------
  if (args.length < 2) {
    print('Matrix Chain Multiplication');
    print('Usage: dart run mcm.dart d0 d1 d2 ... dn');
    print('Example: dart run mcm.dart 30 35 15 5 10 20 25');
    print('Provide at least two dimensions (d0 d1) to define one matrix.');
    return;
  }

  // Parse command-line arguments to integers ---------------------------------
  final List<int> p;
  try {
    p = args.map(int.parse).toList(growable: false);
  } on FormatException {
    print('All dimensions must be valid integers.');
    return;
  }

  final int n = p.length - 1; // number of matrices
  if (n == 0) {
    print('At least one matrix (two dimensions) is required.');
    return;
  }

  // Dynamic programming table m[i][j] holds the minimum cost
  // (scalar multiplications) for Ai…Aj inclusive, 0-indexed.
  final List<List<int>> m =
      List.generate(n, (_) => List<int>.filled(n, 0), growable: false);

  // Fill table, L = chain length (starting from 2 because length 1 is zero).
  const int inf = 0x7FFFFFFFFFFFFFFF; // large sentinel value
  for (int L = 2; L <= n; L++) {
    for (int i = 0; i <= n - L; i++) {
      final int j = i + L - 1;
      int minCost = inf;

      // Try every possible split between k and k+1
      for (int k = i; k < j; k++) {
        final int cost = m[i][k] +
            m[k + 1][j] +
            p[i] * p[k + 1] * p[j + 1]; // cost of multiplying the split

        if (cost < minCost) minCost = cost;
      }
      m[i][j] = minCost;
    }
  }

  // Output -------------------------------------------------------------------
  print('Minimum number of scalar multiplications: ${m[0][n - 1]}');
}

