import 'dart:io';

@pragma('vm:entry-point')
void main() {
  /*
   * Word Break Problem
   * ------------------
   * Input format  (from stdin):
   *   Line 1 : Integer N  – number of words in the dictionary
   *   Line 2 : N words separated by whitespace
   *   Line 3 : String S  – the text to test
   *
   * Output (to stdout):
   *   true  : if S can be segmented into dictionary words
   *   false : otherwise
   */

  // Collect all non-empty input lines
  final List<String> lines = [];
  while (true) {
    final line = stdin.readLineSync();
    if (line == null) break;            // EOF
    if (line.trim().isEmpty) continue;  // skip blank lines
    lines.add(line.trimRight());
  }

  if (lines.length < 3) {
    stderr.writeln('Invalid input: need at least 3 non-empty lines.');
    exit(64); // EX_USAGE
  }

  // 1. Dictionary size
  final int n = int.tryParse(lines[0]) ?? -1;
  if (n < 0) {
    stderr.writeln('First line must be a positive integer.');
    exit(64);
  }

  // 2. Dictionary words
  final List<String> dictWords = lines[1].split(RegExp(r'\s+'));
  if (dictWords.length != n) {
    stderr.writeln('Expected $n words, but found ${dictWords.length}.');
    exit(64);
  }
  final Set<String> wordSet = dictWords.toSet();

  // 3. Target string
  final String s = lines[2];

  // Dynamic-programming table: dp[i] == true ↔ s[0:i] can be segmented
  final List<bool> dp = List<bool>.filled(s.length + 1, false);
  dp[0] = true; // empty prefix is always segmentable

  for (int i = 1; i <= s.length; i++) {
    for (int j = 0; j < i; j++) {
      if (dp[j] && wordSet.contains(s.substring(j, i))) {
        dp[i] = true;
        break; // no need to check other j for this i
      }
    }
  }

  // Result
  print(dp[s.length]);
}

