  // Helper: classic binary-search "lower bound" (first index ≥ key).
  int lowerBound(List<int> list, int key) {
    int lo = 0, hi = list.length;
    while (lo < hi) {
      final mid = (lo + hi) >> 1;
      if (list[mid] < key) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    return lo;
  }

  // Read a single line of integers from STDIN.
  // Example input: 10 9 2 5 3 7 101 18
  final line = stdin.readLineSync();
  if (line == null || line.trim().isEmpty) {
    print(0);
    return;
  }
  final numbers = line
      .trim()
      .split(RegExp(r'\s+'))
      .where((s) => s.isNotEmpty)
      .map(int.parse)
      .toList();

  // Patience-sorting LIS in O(n log n).
  final List<int> tails = [];
  for (final value in numbers) {
    final pos = lowerBound(tails, value);
    if (pos == tails.length) {
      tails.add(value); // Extend the LIS.
    } else {
      tails[pos] = value; // Replace to maintain minimal tail.
    }
  }

  // Output the length of the longest increasing subsequence.
  print(tails.length);
}

