// N-Queens solver in Dart.
// Pass N as command–line argument, otherwise defaults to 8.
@pragma('vm:entry-point')
void main(List<String> args) {
  // Parse board size.
  int n = args.isNotEmpty ? int.tryParse(args[0]) ?? 8 : 8;
  if (n <= 0) {
    print('Board size must be positive.');
    return;
  }

  // Board state: index = row, value = column where a queen sits.
  final positions = List<int>.filled(n, -1);
  int solutions = 0;

  // Check if placing a queen at (row, col) is safe.
  bool isSafe(int row, int col) {
    for (int r = 0; r < row; r++) {
      final c = positions[r];
      if (c == col ||                 // Same column
          (r - row).abs() == (c - col).abs()) { // Same diagonal
        return false;
      }
    }
    return true;
  }

  // Depth-first search through the rows.
  void place(int row) {
    if (row == n) {
      // Found a complete placement.
      solutions++;
      print('Solution #$solutions');
      for (int r = 0; r < n; r++) {
        final line = List.generate(n, (c) => c == positions[r] ? 'Q' : '.').join(' ');
        print(line);
      }
      print('');
      return;
    }

    for (int col = 0; col < n; col++) {
      if (isSafe(row, col)) {
        positions[row] = col;
        place(row + 1);
        // Backtrack automatically when we overwrite positions[row].
      }
    }
  }

  place(0);
  print('Total solutions for N=$n: $solutions');
}

