// Graph coloring using simple back-tracking.
//
// Run with:  dart run <this_file>.dart
//
// The script stores the graph in an adjacency list and tries to color it
// with a fixed number of colors (numColors).  If a valid coloring exists
// it prints the assignment; otherwise it reports failure.

@pragma('vm:entry-point')
void main() {
  // ------------------------------------------------------------------
  // 1. Define the graph as an adjacency list.
  //    Feel free to change this to experiment with other graphs.
  // ------------------------------------------------------------------
  final List<List<int>> graph = <List<int>>[
    /* 0 */ [1, 2, 3],
    /* 1 */ [0, 2, 4],
    /* 2 */ [0, 1, 3, 4],
    /* 3 */ [0, 2, 4],
    /* 4 */ [1, 2, 3],
  ];

  // ------------------------------------------------------------------
  // 2. Number of colors we are allowed to use.
  // ------------------------------------------------------------------
  const int numColors = 3;

  // ------------------------------------------------------------------
  // 3. Storage for the current color of each vertex (-1 means “uncolored”).
  // ------------------------------------------------------------------
  final int n = graph.length;
  final List<int> colorOf = List<int>.filled(n, -1);

  // ------------------------------------------------------------------
  // 4. Helper to check whether assigning color 'c' to vertex 'v' is safe.
  // ------------------------------------------------------------------
  bool isSafe(int v, int c) {
    for (final int neighbor in graph[v]) {
      if (colorOf[neighbor] == c) return false;
    }
    return true;
  }

  // ------------------------------------------------------------------
  // 5. Recursive back-tracking routine that tries to color vertex 'v'
  //    and the remaining vertices.
  // ------------------------------------------------------------------
  bool colorFrom(int v) {
    if (v == n) return true; // All vertices successfully colored.

    for (int c = 0; c < numColors; c++) {
      if (isSafe(v, c)) {
        colorOf[v] = c;
        if (colorFrom(v + 1)) return true; // Recurse.
        colorOf[v] = -1;                    // Back-track.
      }
    }
    return false; // No valid color found for this vertex.
  }

  // ------------------------------------------------------------------
  // 6. Kick everything off and report the result.
  // ------------------------------------------------------------------
  if (colorFrom(0)) {
    print('Successfully colored the graph with $numColors colors:');
    for (int i = 0; i < n; i++) {
      print('  Vertex $i -> Color ${colorOf[i]}');
    }
  } else {
    print('Cannot color the graph with only $numColors colors.');
  }
}

