import 'dart:io';

@pragma('vm:entry-point')
void main(List<String> arguments) {
  /*
    Input format (from stdin):
      V E              // number of vertices and edges
      u1 v1            // E lines with two integers per line (0-based, undirected)
      ...

    Example:
      4 5
      0 1
      0 2
      0 3
      1 2
      2 3
  */

  // -------------------- Read & parse input --------------------
  final tokens = <String>[];
  for (String? line; (line = stdin.readLineSync()) != null;) {
    if (line!.trim().isEmpty) continue;
    tokens.addAll(line.trim().split(RegExp(r'\s+')));
  }
  if (tokens.length < 2) {
    stderr.writeln('Error: Expected at least two integers (V and E).');
    exit(1);
  }

  int cursor = 0;
  final int vCount = int.parse(tokens[cursor++]);
  final int eCount = int.parse(tokens[cursor++]);

  final adj = List.generate(vCount, (_) => <int>{});
  for (int i = 0; i < eCount; ++i) {
    if (cursor + 1 >= tokens.length) {
      stderr.writeln('Error: Not enough edge data.');
      exit(1);
    }
    final int u = int.parse(tokens[cursor++]);
    final int v = int.parse(tokens[cursor++]);
    if (u < 0 || v < 0 || u >= vCount || v >= vCount) {
      stderr.writeln('Error: Vertex id out of range.');
      exit(1);
    }
    adj[u].add(v);
    adj[v].add(u); // undirected
  }

  // -------------------- Hamiltonian path search --------------------
  List<int>? solution;
  final visited = List<bool>.filled(vCount, false);

  bool dfs(int node, int depth, List<int> path) {
    if (depth == vCount) {
      solution = List<int>.from(path);
      return true;
    }
    for (final next in adj[node]) {
      if (!visited[next]) {
        visited[next] = true;
        path.add(next);
        if (dfs(next, depth + 1, path)) return true;
        // back-track
        visited[next] = false;
        path.removeLast();
      }
    }
    return false;
  }

  for (int start = 0; start < vCount && solution == null; ++start) {
    visited.fillRange(0, vCount, false);
    visited[start] = true;
    if (dfs(start, 1, [start])) break;
  }

  // -------------------- Output result --------------------
  if (solution != null) {
    stdout.writeln('Hamiltonian path found: ${solution!.join(' ')}');
  } else {
    stdout.writeln('No Hamiltonian path exists.');
  }
}

