// KMP (Knuth–Morris–Pratt) string-matching demo in a single main() function.
// Reads the text on the first line of stdin and the pattern on the second,
// then prints all zero-based match positions (or a message if none are found).

import 'dart:io';

@pragma('vm:entry-point')
void main(List<String> args) {
  // Read input
  final text = stdin.readLineSync();
  final pattern = stdin.readLineSync();

  if (text == null || pattern == null) {
    stderr.writeln('Error: please supply text and pattern on separate lines.');
    exit(64); // EX_USAGE
  }

  // ---------- Helper functions (defined inside main) ----------

  // Builds the longest-proper-prefix table for the pattern.
  List<int> _buildLps(String pat) {
    final lps = List<int>.filled(pat.length, 0);
    int len = 0; // length of the previous longest prefix suffix

    for (int i = 1; i < pat.length; i++) {
      while (len > 0 && pat[i] != pat[len]) {
        len = lps[len - 1];
      }
      if (pat[i] == pat[len]) {
        len++;
        lps[i] = len;
      }
    }
    return lps;
  }

  // Runs KMP search and returns list of match starting indices.
  List<int> _kmpSearch(String txt, String pat) {
    if (pat.isEmpty || txt.length < pat.length) return [];

    final lps = _buildLps(pat);
    final matches = <int>[];

    int i = 0; // index for txt
    int j = 0; // index for pat

    while (i < txt.length) {
      if (txt[i] == pat[j]) {
        i++;
        j++;
        if (j == pat.length) {
          matches.add(i - j);  // match found
          j = lps[j - 1];      // look for next possible match
        }
      } else if (j != 0) {
        j = lps[j - 1];
      } else {
        i++;
      }
    }
    return matches;
  }

  // ---------- Execute search and report results ----------
  final positions = _kmpSearch(text, pattern);

  if (positions.isEmpty) {
    print('No match found.');
  } else {
    print('Pattern found at positions: ${positions.join(' ')}');
  }
}

