  List<int> _buildBadCharTable(String pat) {
    const int alphabetSize = 0x10000; // Covers Basic Multilingual Plane
    final table = List<int>.filled(alphabetSize, -1);
    for (var i = 0; i < pat.length; i++) {
      table[pat.codeUnitAt(i)] = i; // Record last occurrence of each character
    }
    return table;
  }

  // Helper function to build good suffix tables for Boyer-Moore algorithm.
  void _buildGoodSuffixTables(String pat, List<int> suffix, List<bool> prefix) {
    final m = pat.length;
    // Initialize tables
    for (var i = 0; i < m; i++) {
      suffix[i] = -1;
      prefix[i] = false;
    }

    // Compute suffix and prefix information
    for (var i = 0; i < m - 1; i++) {
      var j = i;
      var k = 0; // Length of matched suffix
      while (j >= 0 && pat.codeUnitAt(j) == pat.codeUnitAt(m - 1 - k)) {
        j--;
        k++;
        suffix[k - 1] = j + 1; // Update suffix start index
      }
      if (j == -1) {
        prefix[k - 1] = true; // Mark if prefix matches suffix
      }
    }
  }

  // Helper function to compute the good suffix shift in Boyer-Moore algorithm.
  int _goodSuffixShift(int j, int m, List<int> suffix, List<bool> prefix) {
    final k = m - 1 - j; // Length of matched suffix
    if (k == 0) return 0; // No suffix matched, rely on bad character

    // Case 1: Check for another occurrence of the suffix
    if (suffix[k - 1] != -1) {
      return j - suffix[k - 1] + 1;
    }

    // Case 2: Check for a matching prefix
    for (var r = j + 2; r < m; r++) {
      if (prefix[m - r]) {
        return r;
      }
    }

    // Case 3: Default shift by pattern length
    return m;
  }

  // Main Boyer-Moore search function.
  List<int> _boyerMooreSearch(String txt, String pat) {
    final n = txt.length;
    final m = pat.length;
    if (m == 0 || n < m) return const []; // Edge cases

    final badChar = _buildBadCharTable(pat);
    final suffix = List<int>.filled(m, -1);
    final prefix = List<bool>.filled(m, false);
    _buildGoodSuffixTables(pat, suffix, prefix);

    final matches = <int>[];
    var i = 0; // Text index

    while (i <= n - m) {
      var j = m - 1; // Pattern index
      // Compare pattern from right to left
      while (j >= 0 && pat.codeUnitAt(j) == txt.codeUnitAt(i + j)) {
        j--;
      }

      if (j < 0) {
        matches.add(i); // Full match found
        i += m; // Shift past the match
        continue;
      }

      // Compute shifts using bad character and good suffix rules
      final badStep = j - badChar[txt.codeUnitAt(i + j)];
      final gsStep = _goodSuffixShift(j, m, suffix, prefix);
      i += (badStep > gsStep ? badStep : gsStep).clamp(1, m); // Take max and clamp
    }

    return matches;
  }

  // Execute search and output results
  final positions = _boyerMooreSearch(text, pattern);
  if (positions.isEmpty) {
    print('No occurrence of "$pattern" found.');
  } else {
    print('Found "$pattern" at position(s): ${positions.join(', ')}');
  }
