  // --- LZW compression (all logic kept inside `main`) -----------------------

  // Inner helper that performs the actual LZW compression.
  List<int> lzwCompress(String input) {
    // 1. Build initial dictionary with all single-byte symbols.
    final dictionary = <String, int>{};
    for (var i = 0; i < 256; i++) {
      dictionary[String.fromCharCode(i)] = i;
    }

    var nextCode = 256;      // Next free dictionary code.
    var w = '';              // Current pattern.
    final output = <int>[];  // Resulting sequence of codes.

    // 2. Main compression loop.
    for (final c in input.split('')) {
      final wc = w + c;
      if (dictionary.containsKey(wc)) {
        w = wc;                       // Pattern already in dictionary.
      } else {
        output.add(dictionary[w]!);   // Emit code for previous pattern.
        dictionary[wc] = nextCode++;  // Add new pattern to dictionary.
        w = c;                        // Reset pattern.
      }
    }

    // 3. Flush remaining pattern to output.
    if (w.isNotEmpty) {
      output.add(dictionary[w]!);
    }

    return output;
  }

  // -------------------------------------------------------------------------

  // Read input: use CLI args if provided, otherwise read everything from stdin.
  final rawInput = args.isNotEmpty
      ? args.join(' ')
      : await stdin.transform(utf8.decoder).join();

  // Compress and print space-separated codes.
  final compressed = lzwCompress(rawInput);
  stdout.writeln(compressed.join(' '));
}

