@pragma('vm:entry-point')
void main(List<String> args) {
  // Expect exactly one command-line argument.
  if (args.isEmpty) {
    stdout.writeln('Usage  : dart primality_sieve.dart <positive-integer>');
    stdout.writeln('Example: dart primality_sieve.dart 97');
    exit(64); // EX_USAGE
  }

  // Parse the argument.
  final n = int.tryParse(args.first);
  if (n == null || n < 2) {
    stderr.writeln('Error: Please supply an integer ≥ 2.');
    exit(64);
  }

  // Build a sieve large enough to decide whether n is prime.
  // The list index represents the number; true means "currently assumed prime".
  final sieve = List<bool>.filled(n + 1, true);
  sieve[0] = sieve[1] = false;

  // Classic Sieve of Eratosthenes.
  for (int p = 2; p * p <= n; p++) {
    if (sieve[p]) {
      for (int multiple = p * p; multiple <= n; multiple += p) {
        sieve[multiple] = false;
      }
    }
  }

  // Report result.
  if (sieve[n]) {
    stdout.writeln('$n is a prime number.');
  } else {
    stdout.writeln('$n is not a prime number.');
  }
}

