    final q  = u3 ~/ v3;              // Integer quotient
    final t1 = u1 - q * v1;
    final t2 = u2 - q * v2;
    final t3 = u3 - q * v3;

    u1 = v1;  u2 = v2;  u3 = v3;
    v1 = t1;  v2 = t2;  v3 = t3;
  }

  if (u3 != BigInt.one) {
    print('No modular inverse exists because gcd($a, $m) = $u3 ≠ 1.');
    return;
  }

  // u1 is the inverse; ensure it is positive.
  var inverse = u1 % m;
  if (inverse < BigInt.zero) inverse += m;

