  final List<int> parent = List<int>.generate(n, (i) => i);
  final List<int> rank   = List<int>.filled(n, 0);

  // Finds the representative of `x` with path compression.
  int find(int x) {
    if (parent[x] != x) {
      parent[x] = find(parent[x]); // Path compression
    }
    return parent[x];
  }

  // Unites the sets containing `x` and `y` using union-by-rank.
  void union(int x, int y) {
    int rootX = find(x);
    int rootY = find(y);
    if (rootX == rootY) return; // Already in the same set

    if (rank[rootX] < rank[rootY]) {
      parent[rootX] = rootY;
    } else if (rank[rootX] > rank[rootY]) {
      parent[rootY] = rootX;
    } else {
      parent[rootY] = rootX;
      rank[rootX]++; // Increase rank only when necessary
    }
  }

  // --------------------------------------------------------------------------
  // Demonstration
  // --------------------------------------------------------------------------
  union(1, 2);
  union(3, 4);
  union(2, 4);
  union(5, 6);
  union(7, 8);
  union(5, 8);

  // Print representatives for all elements
  for (int i = 0; i < n; i++) {
    print('Element $i belongs to set represented by ${find(i)}');
  }
}

