import 'dart:io';

@pragma('vm:entry-point')
void main() {
  // ---------------
  // Segment-tree demo
  // ----------------
  //
  // Expected input:
  //   n q            (array size, number of operations)
  //   a1 a2 … an     (initial array values)
  //   - Next q lines -
  //     Query:  Q l r   (1-indexed, inclusive)
  //     Update: U i v   (set a[i] = v)
  //
  // You can also use 1/2 instead of Q/U if you prefer numbers:
  //   1 l r            (query)
  //   2 i v            (update)
  //
  // All commands are whitespace-separated and case-insensitive.
  //
  // Sample
  // ------
  // 5 4
  // 1 2 3 4 5
  // Q 1 5   -> 15
  // U 3 10  -> -
  // 1 2 4   -> 16
  // q 3 3   -> 10
  //
  // ------------------

  // --- read n & q ---
  final firstLine = stdin.readLineSync();
  if (firstLine == null || firstLine.trim().isEmpty) return;
  final firstParts =
      firstLine.trim().split(RegExp(r'\s+')).map(int.parse).toList();
  if (firstParts.length < 2) {
    stderr.writeln('Invalid input: need "n q"');
    return;
  }
  final int n = firstParts[0];
  final int q = firstParts[1];

  // --- read initial array ---
  final secondLine = stdin.readLineSync();
  if (secondLine == null) {
    stderr.writeln('Missing array line.');
    return;
  }
  final List<int> arr =
      secondLine.trim().split(RegExp(r'\s+')).map(int.parse).toList();
  if (arr.length != n) {
    stderr.writeln('Array length ($n) mismatch: got ${arr.length}.');
    return;
  }

  // Allocate segment tree (4*n is safe upper bound)
  final List<int> seg = List<int>.filled(4 * n + 4, 0);

  // -------- local helpers (all inside main) --------
  void build(int node, int l, int r) {
    if (l == r) {
      seg[node] = arr[l];
      return;
    }
    final mid = (l + r) >> 1;
    build(node << 1, l, mid);
    build(node << 1 | 1, mid + 1, r);
    seg[node] = seg[node << 1] + seg[node << 1 | 1];
  }

  void update(int node, int l, int r, int idx, int val) {
    if (l == r) {
      seg[node] = val;
      return;
    }
    final mid = (l + r) >> 1;
    if (idx <= mid) {
      update(node << 1, l, mid, idx, val);
    } else {
      update(node << 1 | 1, mid + 1, r, idx, val);
    }
    seg[node] = seg[node << 1] + seg[node << 1 | 1];
  }

  int query(int node, int l, int r, int ql, int qr) {
    if (qr < l || r < ql) return 0;                // disjoint
    if (ql <= l && r <= qr) return seg[node];      // fully covered
    final mid = (l + r) >> 1;
    return query(node << 1, l, mid, ql, qr) +
        query(node << 1 | 1, mid + 1, r, ql, qr);
  }
  // -------------------------------------------------

  build(1, 0, n - 1);

  final StringBuffer out = StringBuffer();
  for (int k = 0; k < q; k++) {
    final line = stdin.readLineSync();
    if (line == null) break;
    final parts = line.trim().split(RegExp(r'\s+'));
    if (parts.isEmpty) continue;

    final op = parts[0].toUpperCase();
    if (op == 'Q' || op == '1') {
      if (parts.length < 3) {
        stderr.writeln('Bad query: "$line"');
        continue;
      }
      final l = int.parse(parts[1]) - 1;
      final r = int.parse(parts[2]) - 1;
      out.writeln(query(1, 0, n - 1, l, r));
    } else if (op == 'U' || op == '2') {
      if (parts.length < 3) {
        stderr.writeln('Bad update: "$line"');
        continue;
      }
      final idx = int.parse(parts[1]) - 1;
      final val = int.parse(parts[2]);
      update(1, 0, n - 1, idx, val);
    } else {
      stderr.writeln('Unknown command: "$op"');
    }
  }

  stdout.write(out.toString());
}

