// A standalone Dart script that reads an undirected graph from STDIN
// and prints all its articulation points (cut vertices).
// Input format:
//   n m
//   u1 v1
//   u2 v2
//   ...
//   um vm
//
//   n – number of vertices (1-based indexing assumed)
//   m – number of edges
//
// Output:
//   Space-separated list of articulation points in ascending order.
//   If there are no articulation points, nothing is printed.

import 'dart:io';

@pragma('vm:entry-point')
void main(List<String> args) {
  // Helper to read the next non-empty line.
  String? _nextLine() {
    while (true) {
      final line = stdin.readLineSync();
      if (line == null) return null;
      if (line.trim().isNotEmpty) return line;
    }
  }

  final header = _nextLine();
  if (header == null) return;
  final parts = header.split(RegExp(r'\s+'));
  if (parts.length < 2) {
    stderr.writeln('First line must contain n m');
    return;
  }
  final n = int.parse(parts[0]);
  final m = int.parse(parts[1]);

  // Build adjacency list.
  final adj = List<List<int>>.generate(n, (_) => <int>[]);
  for (var i = 0; i < m; i++) {
    final line = _nextLine();
    if (line == null) {
      stderr.writeln('Unexpected end of input on edge $i');
      return;
    }
    final uv = line.split(RegExp(r'\s+'));
    if (uv.length < 2) {
      stderr.writeln('Edge line must contain two integers');
      return;
    }
    final u = int.parse(uv[0]) - 1; // convert to 0-based
    final v = int.parse(uv[1]) - 1;
    if (u < 0 || v < 0 || u >= n || v >= n) {
      stderr.writeln('Vertex indices must be between 1 and $n');
      return;
    }
    if (u == v) continue; // ignore self-loops
    adj[u].add(v);
    adj[v].add(u);
  }

  // DFS variables.
  final disc = List<int>.filled(n, -1);   // discovery times
  final low  = List<int>.filled(n, -1);   // low-link values
  final isArt = List<bool>.filled(n, false);
  var time = 0;

  void dfs(int u, int parent) {
    disc[u] = low[u] = ++time;
    var childCount = 0;
    for (final v in adj[u]) {
      if (disc[v] == -1) {
        childCount++;
        dfs(v, u);
        low[u] = low[u] < low[v] ? low[u] : low[v];
        if (parent != -1 && low[v] >= disc[u]) {
          isArt[u] = true;
        }
      } else if (v != parent) {
        low[u] = low[u] < disc[v] ? low[u] : disc[v];
      }
    }
    if (parent == -1 && childCount > 1) {
      isArt[u] = true;
    }
  }

  for (var i = 0; i < n; i++) {
    if (disc[i] == -1) dfs(i, -1);
  }

  final result = <int>[];
  for (var i = 0; i < n; i++) {
    if (isArt[i]) result.add(i + 1); // back to 1-based for output
  }
  if (result.isNotEmpty) {
    stdout.writeln(result.join(' '));
  }
}

// Eulerian path / circuit in an undirected graph.
// Input format:
//   n m            (number of vertices, number of edges)
//   u1 v1
//   u2 v2
//   ...
//   um vm
//
// Vertices are indexed 0‒(n-1).  Prints either
//   Eulerian Circuit: v0 v1 … vk
//   Eulerian Path:    v0 v1 … vk
//   Graph is not Eulerian
//
// Compile & run:
//   dart run euler.dart < input.txt

import 'dart:io';

@pragma('vm:entry-point')
void main() {
  // Read first line: n (vertices) and m (edges).
  final header = stdin.readLineSync();
  if (header == null || header.trim().isEmpty) {
    stderr.writeln('Empty input.');
    return;
  }
  final headerParts = header.trim().split(RegExp(r'\s+'));
  if (headerParts.length != 2) {
    stderr.writeln('First line must contain n and m.');
    return;
  }
  final n = int.parse(headerParts[0]);
  final m = int.parse(headerParts[1]);

  // Build undirected adjacency list.
  final List<List<int>> adj = List.generate(n, (_) => <int>[]);
  for (int i = 0; i < m; i++) {
    final line = stdin.readLineSync();
    if (line == null) {
      stderr.writeln('Unexpected end of input at edge $i.');
      return;
    }
    final parts = line.trim().split(RegExp(r'\s+'));
    if (parts.length != 2) {
      stderr.writeln('Edge line must contain two vertices.');
      return;
    }
    final u = int.parse(parts[0]);
    final v = int.parse(parts[1]);
    if (u < 0 || u >= n || v < 0 || v >= n) {
      stderr.writeln('Vertex out of range in edge $u-$v.');
      return;
    }
    adj[u].add(v);
    adj[v].add(u);
  }

  // Helper: DFS to test connectivity ignoring isolated vertices.
  bool isConnected() {
    final visited = List<bool>.filled(n, false);
    int start = -1;
    for (int i = 0; i < n; i++) {
      if (adj[i].isNotEmpty) {
        start = i;
        break;
      }
    }
    if (start == -1) return true; // No edges, vacuously connected.

    void dfs(int v) {
      visited[v] = true;
      for (final u in adj[v]) {
        if (!visited[u]) dfs(u);
      }
    }

    dfs(start);
    for (int i = 0; i < n; i++) {
      if (adj[i].isNotEmpty && !visited[i]) return false;
    }
    return true;
  }

  // Helper: Hierholzer’s algorithm to build Eulerian trail.
  List<int> buildEulerianTrail(int start) {
    // Work on a mutable copy because we destroy edges while traversing.
    final g = [for (final list in adj) List<int>.from(list)];
    final stack = <int>[start];
    final trail = <int>[];

    while (stack.isNotEmpty) {
      final v = stack.last;
      if (g[v].isNotEmpty) {
        final u = g[v].removeLast();
        g[u].remove(v); // Remove the undirected counterpart.
        stack.add(u);
      } else {
        trail.add(stack.removeLast());
      }
    }
    return trail.reversed.toList(); // From start to end.
  }

  // Determine Eulerian property.
  if (!isConnected()) {
    print('Graph is not Eulerian');
    return;
  }

  final oddVertices = [
    for (int i = 0; i < n; i++)
      if (adj[i].length.isOdd) i
  ];

  if (oddVertices.isEmpty) {
    // Eulerian circuit.
    final circuit = buildEulerianTrail(adj.indexWhere((l) => l.isNotEmpty));
    print('Eulerian Circuit: ${circuit.join(' ')}');
  } else if (oddVertices.length == 2) {
    // Eulerian path (non-circuit).
    final path = buildEulerianTrail(oddVertices[0]);
    print('Eulerian Path: ${path.join(' ')}');
  } else {
    print('Graph is not Eulerian');
  }
}

