//   Row 1 -> Col 0
//   Row 2 -> Col 2
//   Minimum cost: 5
//
import 'dart:io';
import 'dart:math';

@pragma('vm:entry-point')
void main(List<String> args) {
  // Helper to read a square/rectangular cost matrix from STDIN.
  List<List<double>> readMatrix() {
    final lines = stdin.readLineSync();
    if (lines == null) exit(0);
    final n = int.parse(lines.trim());
    final matrix = <List<double>>[];
    for (int i = 0; i < n; i++) {
      final parts = stdin.readLineSync()!.trim().split(RegExp(r'\s+'));
      matrix.add(parts.map((e) => double.parse(e)).toList());
    }
    return matrix;
  }

  // Hungarian algorithm implementation (returns assignment list).
  List<int> hungarian(List<List<double>> cost) {
    const double eps = 1e-9;
    final rows = cost.length;
    final cols = cost[0].length;
    final n = max(rows, cols);

    // Build square matrix (padding with 0s for extra rows/cols).
    final matrix =
        List.generate(n, (r) => List<double>.filled(n, 0.0, growable: false));
    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        matrix[r][c] = cost[r][c];
      }
    }

    // STEP 1: Row reduction.
    for (int r = 0; r < n; r++) {
      final minVal = matrix[r].reduce(min);
      for (int c = 0; c < n; c++) {
        matrix[r][c] -= minVal;
      }
    }

    // STEP 2: Column reduction.
    for (int c = 0; c < n; c++) {
      double minVal = matrix[0][c];
      for (int r = 1; r < n; r++) minVal = min(minVal, matrix[r][c]);
      for (int r = 0; r < n; r++) {
        matrix[r][c] -= minVal;
      }
    }

    // Masks: 1 = starred zero, 2 = primed zero.
    final mask =
        List.generate(n, (r) => List<int>.filled(n, 0, growable: false));
    final rowCover = List<bool>.filled(n, false);
    final colCover = List<bool>.filled(n, false);

    bool _findZero(List<int> out) {
      for (int r = 0; r < n; r++) {
        if (rowCover[r]) continue;
        for (int c = 0; c < n; c++) {
          if (!colCover[c] && matrix[r][c].abs() < eps) {
            out[0] = r;
            out[1] = c;
            return true;
          }
        }
      }
      return false;
    }

    int _starInRow(int row) =>
        mask[row].indexWhere((v) => v == 1); // -1 if none
    int _starInCol(int col) {
      for (int r = 0; r < n; r++) if (mask[r][col] == 1) return r;
      return -1;
    }

    int _primeInRow(int row) => mask[row].indexWhere((v) => v == 2);

    // STEP 3: Star initial zeros.
    for (int r = 0; r < n; r++) {
      for (int c = 0; c < n; c++) {
        if (matrix[r][c].abs() < eps && !rowCover[r] && !colCover[c]) {
          mask[r][c] = 1; // star
          rowCover[r] = true;
          colCover[c] = true;
        }
      }
    }
    // Clear covers.
    for (int i = 0; i < n; i++) rowCover[i] = colCover[i] = false;

    // Main loop.
    while (true) {
      // STEP 4: Cover columns containing a starred zero.
      for (int r = 0; r < n; r++) {
        for (int c = 0; c < n; c++) {
          if (mask[r][c] == 1) colCover[c] = true;
        }
      }

      if (colCover.where((c) => c).length == n) break; // Finished.

      List<int> zero = [0, 0];
      bool found;
      while (!(found = _findZero(zero))) {
        // STEP 6: Adjust the matrix.
        double minVal = double.infinity;
        for (int r = 0; r < n; r++) {
          if (rowCover[r]) continue;
          for (int c = 0; c < n; c++) {
            if (!colCover[c]) minVal = min(minVal, matrix[r][c]);
          }
        }
        for (int r = 0; r < n; r++) {
          for (int c = 0; c < n; c++) {
            if (rowCover[r]) matrix[r][c] += minVal;
            if (!colCover[c]) matrix[r][c] -= minVal;
          }
        }
      }

      int row = zero[0], col = zero[1];
      mask[row][col] = 2; // prime

      int starCol = _starInRow(row);
      if (starCol != -1) {
        rowCover[row] = true;
        colCover[starCol] = false;
      } else {
        // STEP 5: Construct alternating path, convert primes to stars.
        final path = <List<int>>[];
        path.add([row, col]);
        while (true) {
          int starRow = _starInCol(path.last[1]);
          if (starRow == -1) break;
          path.add([starRow, path.last[1]]);
          int primeCol = _primeInRow(path.last[0]);
          path.add([path.last[0], primeCol]);
        }
        // Flip stars and primes.
        for (var p in path) {
          if (mask[p[0]][p[1]] == 1) {
            mask[p[0]][p[1]] = 0;
          } else if (mask[p[0]][p[1]] == 2) {
            mask[p[0]][p[1]] = 1;
          }
        }
        // Clear covers and primes.
        for (int r = 0; r < n; r++) {
          rowCover[r] = false;
          for (int c = 0; c < n; c++) {
            if (mask[r][c] == 2) mask[r][c] = 0;
          }
        }
        for (int c = 0; c < n; c++) colCover[c] = false;
      }
    }

    // Extract assignment.
    final assignment = List<int>.filled(rows, -1);
    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        if (mask[r][c] == 1) {
          assignment[r] = c;
          break;
        }
      }
    }
    return assignment;
  }

  // ----------------------------------------
  // Entry: read matrix, solve, print result.
  final matrix = readMatrix();
  final assignment = hungarian(matrix);

  double total = 0;
  for (int r = 0; r < assignment.length; r++) {
    final c = assignment[r];
    if (c >= 0) total += matrix[r][c];
    print('Row $r -> Col $c');
  }
  print('Minimum cost: ${total.toStringAsFixed(10).replaceAll(RegExp(r'\.?0+$'), '')}');
}

