            }
          }
        }
        for (int r = 0; r < n; r++) {
          for (int c = 0; c < n; c++) {
            if (rowCover[r]) matrix[r][c] += minVal;
            if (!colCover[c]) matrix[r][c] -= minVal;
          }
        }
      }

      int row = zero[0], col = zero[1];
      mask[row][col] = 2; // prime

      int starCol = _starInRow(row);
      if (starCol != -1) {
        rowCover[row] = true;
        colCover[starCol] = false;
      } else {
        // STEP 5: Construct alternating path, convert primes to stars.
        final path = <List<int>>[];
        path.add([row, col]);
        while (true) {
          int starRow = _starInCol(path.last[1]);
          if (starRow == -1) break;
          path.add([starRow, path.last[1]]);
          int primeCol = _primeInRow(path.last[0]);
          path.add([path.last[0], primeCol]);
        }
        // Flip stars and primes.
        for (var p in path) {
          if (mask[p[0]][p[1]] == 1) {
            mask[p[0]][p[1]] = 0;
          } else if (mask[p[0]][p[1]] == 2) {
            mask[p[0]][p[1]] = 1;
          }
        }
        // Clear covers and primes.
        for (int r = 0; r < n; r++) {
          rowCover[r] = false;
          for (int c = 0; c < n; c++) {
            if (mask[r][c] == 2) mask[r][c] = 0;
          }
        }
        for (int c = 0; c < n; c++) colCover[c] = false;
      }
    }

    // Extract assignment.
    final assignment = List<int>.filled(rows, -1);
    for (int r = 0; r < rows; r++) {
      for (int c = 0; c < cols; c++) {
        if (mask[r][c] == 1) {
          assignment[r] = c;
          break;
        }
      }
    }
    return assignment;
  }

  // Entry: read matrix, solve, print result.
  final matrix = readMatrix();
  final assignment = hungarian(matrix);

  double total = 0;
  for (int r = 0; r < assignment.length; r++) {
    final c = assignment[r];
    if (c >= 0) {
      total += matrix[r][c];
      print('Row $r -> Col $c');
    }
  }
  // Format total cost to remove trailing zeros and unnecessary decimal points.
  final formattedTotal = total.toStringAsFixed(10).replaceAll(RegExp(r'\.?0+$'), '');
  print('Minimum cost: $formattedTotal');
}
