void main() {
  // Demonstration of the Gale–Shapley stable-marriage algorithm, entirely
  // contained inside this single `main` function.

  // 1. Participants
  const men   = ['A', 'B', 'C', 'D'];
  const women = ['W', 'X', 'Y', 'Z'];

  // 2. Preference lists (from most- to least-preferred).
  final menPrefs = <String, List<String>>{
    'A': ['W', 'X', 'Y', 'Z'],
    'B': ['X', 'W', 'Y', 'Z'],
    'C': ['W', 'Y', 'Z', 'X'],
    'D': ['Z', 'Y', 'X', 'W'],
  };

  final womenPrefs = <String, List<String>>{
    'W': ['B', 'A', 'D', 'C'],
    'X': ['C', 'B', 'A', 'D'],
    'Y': ['A', 'C', 'B', 'D'],
    'Z': ['A', 'B', 'C', 'D'],
  };

  // 3. Pre-compute each woman’s ranking map for O(1) comparisons.
  final womenRank = <String, Map<String, int>>{};
  for (final w in women) {
    final ranking = <String, int>{};
    final prefs = womenPrefs[w]!;
    for (var i = 0; i < prefs.length; i++) {
      ranking[prefs[i]] = i;          // lower index = higher preference
    }
    womenRank[w] = ranking;
  }

  // 4. Data structures for the algorithm.
  final engagedWomen = <String, String>{};          // woman -> man
  final engagedMen   = <String, String>{};          // man   -> woman
  final freeMen      = List<String>.of(men);        // queue of bachelors
  final nextIndex    = {for (var m in men) m: 0};   // next woman to propose to

  // 5. Gale–Shapley proposal loop.
  while (freeMen.isNotEmpty) {
    final man   = freeMen.removeAt(0);
    final prefs = menPrefs[man]!;
    final i     = nextIndex[man]!;
    final woman = prefs[i];               // top remaining choice
    nextIndex[man] = i + 1;               // advance for next time

    if (!engagedWomen.containsKey(woman)) {
      // Woman is free – they become engaged.
      engagedWomen[woman] = man;
      engagedMen[man]     = woman;
    } else {
      // Woman is taken – see whom she prefers.
      final currentFiance = engagedWomen[woman]!;
      final rank          = womenRank[woman]!;
      if (rank[man]! < rank[currentFiance]!) {
        // She prefers the new man.
        engagedWomen[woman] = man;
        engagedMen
          ..remove(currentFiance)
          ..[man] = woman;
        freeMen.add(currentFiance);       // ex-fiancé is now free
      } else {
        // She rejects the proposal.
        freeMen.add(man);
      }
    }
  }

  // 6. Output the final, stable matching.
  print('Stable matches:');
  for (final man in men) {
    print('$man → ${engagedMen[man]}');
  }
}

