import 'dart:io';
import 'dart:math';
import 'dart:convert';

@pragma('vm:entry-point')
Future<void> main() async {
  // ---------- Read input ----------
  //
  // Expected format:
  // n
  // x1 y1
  // x2 y2
  // ...
  // xn yn
  //
  // If there is no input, a demo data-set is used.

  final content = await stdin.transform(utf8.decoder).join();
  final tokens = content
      .split(RegExp(r'\s+'))
      .where((e) => e.isNotEmpty)
      .toList();

  int index = 0;
  int readInt() => int.parse(tokens[index++]);
  double readDouble() => double.parse(tokens[index++]);

  late List<_Point> points;

  if (tokens.isEmpty) {
    // Demo: a rough star shape.
    points = <_Point>[
      _Point(0, 0),
      _Point(1, 2),
      _Point(2, 1),
      _Point(3, 3),
      _Point(4, 0),
      _Point(2, -2),
      _Point(1, -1),
    ];
  } else {
    final n = readInt();
    points = List<_Point>.generate(
        n, (_) => _Point(readDouble(), readDouble()),
        growable: false);
  }

  // ---------- Graham scan ----------
  if (points.length <= 1) {
    _printHull(points);
    return;
  }

  // 1. Find pivot (lowest y, then lowest x).
  _Point pivot = points.reduce((a, b) =>
      (a.y < b.y || (a.y == b.y && a.x < b.x)) ? a : b);

  // 2. Sort by polar angle w.r.t. pivot.
  points.sort((a, b) {
    if (identical(a, pivot)) return -1;
    if (identical(b, pivot)) return 1;
    final double cross = _cross(pivot, a, b);
    if (cross == 0) {
      // Collinear with pivot: nearer one first.
      final da = _dist2(pivot, a);
      final db = _dist2(pivot, b);
      return da.compareTo(db);
    }
    return cross > 0 ? -1 : 1; // Left turn comes first.
  });

  // 3. Build the hull.
  final List<_Point> hull = [];
  for (final p in points) {
    while (hull.length >= 2 &&
        _cross(hull[hull.length - 2], hull.last, p) <= 0) {
      hull.removeLast();
    }
    hull.add(p);
  }

  _printHull(hull);
}

// ---------- Helpers (all local/private) ----------

class _Point {
  final double x, y;
  const _Point(this.x, this.y);
  @override
  String toString() => '($x, $y)';
}

double _cross(_Point o, _Point a, _Point b) =>
    (a.x - o.x) * (b.y - o.y) - (a.y - o.y) * (b.x - o.x);

double _dist2(_Point a, _Point b) =>
    (a.x - b.x) * (a.x - b.x) + (a.y - b.y) * (a.y - b.y);

void _printHull(List<_Point> hull) {
  stdout.writeln(hull.length);
  for (final p in hull) {
    stdout.writeln('${p.x} ${p.y}');
  }
}

