import 'dart:io';
import 'dart:math';

@pragma('vm:entry-point')
void main(List<String> args) {
  // Reads either command–line arguments or a single line from stdin:
  // x1 y1 x2 y2 x3 y3 x4 y4  (two line-segments: P1-P2 and P3-P4)
  List<double> parseInput() {
    if (args.isNotEmpty) {
      return args.map(double.parse).toList();
    }
    final line = stdin.readLineSync();
    if (line == null) return [];
    return line.trim().split(RegExp(r'\s+')).map(double.parse).toList();
  }

  final inVals = parseInput();
  if (inVals.length != 8) {
    stderr.writeln('Provide exactly 8 numeric values: '
        'x1 y1 x2 y2 x3 y3 x4 y4');
    exit(1);
  }

  final x1 = inVals[0], y1 = inVals[1],
        x2 = inVals[2], y2 = inVals[3],
        x3 = inVals[4], y3 = inVals[5],
        x4 = inVals[6], y4 = inVals[7];

  bool onSegment(double xi, double yi,
                 double xj, double yj,
                 double xk, double yk) =>
      min(xi, xk) <= xj && xj <= max(xi, xk) &&
      min(yi, yk) <= yj && yj <= max(yi, yk);

  int orientation(double xa, double ya,
                  double xb, double yb,
                  double xc, double yc) {
    final val = (yb - ya) * (xc - xb) - (xb - xa) * (yc - yb);
    if (val.abs() < 1e-12) return 0;      // colinear
    return val > 0 ? 1 : 2;               // 1: clockwise, 2: counter-clockwise
  }

  bool segmentsIntersect() {
    final o1 = orientation(x1, y1, x2, y2, x3, y3);
    final o2 = orientation(x1, y1, x2, y2, x4, y4);
    final o3 = orientation(x3, y3, x4, y4, x1, y1);
    final o4 = orientation(x3, y3, x4, y4, x2, y2);

    if (o1 != o2 && o3 != o4) return true; // General case

    // Special cases for colinearity
    if (o1 == 0 && onSegment(x1, y1, x3, y3, x2, y2)) return true;
    if (o2 == 0 && onSegment(x1, y1, x4, y4, x2, y2)) return true;
    if (o3 == 0 && onSegment(x3, y3, x1, y1, x4, y4)) return true;
    if (o4 == 0 && onSegment(x3, y3, x2, y2, x4, y4)) return true;

    return false;
  }

  if (!segmentsIntersect()) {
    print('The segments do NOT intersect.');
    return;
  }

  // Compute intersection for non-parallel lines
  final denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
  if (denom.abs() < 1e-12) {
    print('The segments overlap (colinear intersection).');
    return;
  }

  final px = ((x1 * y2 - y1 * x2) * (x3 - x4) -
              (x1 - x2) * (x3 * y4 - y3 * x4)) / denom;
  final py = ((x1 * y2 - y1 * x2) * (y3 - y4) -
              (y1 - y2) * (x3 * y4 - y3 * x4)) / denom;

  print('The segments intersect at '
        '(${px.toStringAsFixed(6)}, ${py.toStringAsFixed(6)}).');
}

