@pragma('vm:entry-point')
void main() {
  // Configuration
  const int filterSize = 1024;      // Number of bits in the Bloom filter
  const int numHashFunctions = 3;   // How many different hashes to use

  // Bit-set backing the Bloom filter.  A value of `true` means “bit set”.
  final List<bool> bitset = List<bool>.filled(filterSize, false);

  // ───────────────────────── Internal helpers ─────────────────────────

  // Simple multiplicative string hash that can be salted with a `seed`.
  int _hash(String item, int seed) {
    int hash = seed;
    for (final unit in item.codeUnits) {
      hash = (hash * 31 + unit) & 0x7fffffff; // keep it positive 32-bit
    }
    return hash;
  }

  // Insert an item into the Bloom filter.
  void add(String item) {
    for (var i = 0; i < numHashFunctions; i++) {
      final index = _hash(item, i) % filterSize;
      bitset[index] = true;
    }
  }

  // Query membership: returns false ↔ definitely not present,
  // true  ↔ possibly present (false positive possible).
  bool contains(String item) {
    for (var i = 0; i < numHashFunctions; i++) {
      final index = _hash(item, i) % filterSize;
      if (!bitset[index]) return false;
    }
    return true;
  }

  // ───────────────────────── Demo usage ─────────────────────────

  // Items we’ll insert.
  const words = ['apple', 'banana', 'cherry', 'date', 'elderberry'];
  for (final w in words) {
    add(w);
  }

  // Membership queries (some in the set, some not).
  const queries = ['banana', 'coconut', 'date', 'fig'];
  for (final q in queries) {
    final result = contains(q)
        ? 'Possibly in set'
        : 'Definitely not in set';
    print('Query "$q": $result');
  }
}

