// Cuckoo Hashing demo written as a single‐file script.
//
// Everything lives inside `main`, so the program contains no other
// top-level functions or classes.

@pragma('vm:entry-point')
void main() {
  // Configuration ------------------------------------------------------------
  const int capacity = 11;          // Size of each table.
  const int maxDisplacements = 2 * capacity; // Abort insertion after this many moves.

  // Internal storage ---------------------------------------------------------
  final List<int?> table1 = List<int?>.filled(capacity, null);
  final List<int?> table2 = List<int?>.filled(capacity, null);

  // Hash functions -----------------------------------------------------------
  int _hash1(int key) => key % capacity;
  int _hash2(int key) => (key ~/ capacity) % capacity; // A simple independent hash.

  // Core helpers -------------------------------------------------------------
  bool _contains(int key) =>
      table1[_hash1(key)] == key || table2[_hash2(key)] == key;

  int? _swap(List<int?> table, int index, int value) {
    final displaced = table[index];
    table[index] = value;
    return displaced;
  }

  bool _insert(int key) {
    if (_contains(key)) return true; // Duplicate → treat as success.

    int current = key;
    bool placeInFirst = true;

    for (int i = 0; i < maxDisplacements; i++) {
      if (placeInFirst) {
        final idx = _hash1(current);
        if (table1[idx] == null) {
          table1[idx] = current;
          return true;
        }
        current = _swap(table1, idx, current)!; // Evict occupant.
        placeInFirst = false;
      } else {
        final idx = _hash2(current);
        if (table2[idx] == null) {
          table2[idx] = current;
          return true;
        }
        current = _swap(table2, idx, current)!;
        placeInFirst = true;
      }
    }
    // Cycle detected. In a full implementation you'd re-hash here.
    return false;
  }

  bool _remove(int key) {
    final idx1 = _hash1(key);
    if (table1[idx1] == key) {
      table1[idx1] = null;
      return true;
    }
    final idx2 = _hash2(key);
    if (table2[idx2] == key) {
      table2[idx2] = null;
      return true;
    }
    return false;
  }

  void _dumpTables() {
    print('Table-1');
    for (var i = 0; i < capacity; i++) {
      print(' [$i] ${table1[i]}');
    }
    print('Table-2');
    for (var i = 0; i < capacity; i++) {
      print(' [$i] ${table2[i]}');
    }
    print('─' * 30);
  }

  // Demo ---------------------------------------------------------------------
  final data = [10, 22, 31, 4, 15, 28, 17, 88, 59];

  for (final key in data) {
    final ok = _insert(key);
    print('Insert $key → ${ok ? "success" : "failed (cycle)"}');
  }

  _dumpTables();

  const probe = 31;
  print('Contains $probe? ${_contains(probe)}');

  print('Deleting $probe...');
  _remove(probe);
  print('Contains $probe? ${_contains(probe)}');

  _dumpTables();
}

