  subsets.sort((a, b) {
    if (a.length != b.length) return a.length - b.length;
    for (var i = 0; i < a.length; ++i) {
      if (a[i] != b[i]) return a[i] - b[i];
    }
    return 0;
  });

  // Print each subset on its own line.
  for (final subset in subsets) {
    stdout.writeln(subset);
