void main(List<String> args) {
  // Desired maze size can be passed on the command line: dart run maze.dart 30 15
  int width  = args.length > 0 ? int.tryParse(args[0]) ?? 20 : 20;
  int height = args.length > 1 ? int.tryParse(args[1]) ?? 10 : 10;

  if (width < 1 || height < 1) {
    stderr.writeln('Width and height must be positive integers.');
    exit(1);
  }

  final Random rand = Random();

  // Each maze cell becomes a 2×2 block of characters plus surrounding walls,
  // so an H×W maze becomes (2H+1)×(2W+1) characters.
  final int rows = 2 * height + 1;
  final int cols = 2 * width + 1;
  final List<List<String>> grid =
      List.generate(rows, (_) => List.filled(cols, '#'));

  // Turn every cell position into a passage (surrounded by walls for now).
  void _openCell(int x, int y) => grid[2 * y + 1][2 * x + 1] = ' ';
  for (int y = 0; y < height; y++) {
    for (int x = 0; x < width; x++) {
      _openCell(x, y);
    }
  }

  final List<List<bool>> visited =
      List.generate(height, (_) => List.filled(width, false));

  const List<int> dx = [0, 1, 0, -1];
  const List<int> dy = [-1, 0, 1, 0];

  // Recursive back-tracker (depth-first search).
  void _dfs(int cx, int cy) {
    visited[cy][cx] = true;
    final List<int> dirs = [0, 1, 2, 3]..shuffle(rand);
    for (final d in dirs) {
      final int nx = cx + dx[d];
      final int ny = cy + dy[d];
      if (nx < 0 ||
          nx >= width ||
          ny < 0 ||
          ny >= height ||
          visited[ny][nx]) continue;

      // Knock down the wall between current cell and the chosen neighbour.
      final int wx = 2 * cx + 1 + dx[d];
      final int wy = 2 * cy + 1 + dy[d];
      grid[wy][wx] = ' ';
      _dfs(nx, ny);
    }
  }

  _dfs(0, 0);                // Generate the maze starting in the top-left cell.
  grid[1][0] = ' ';          // Entrance.
  grid[rows - 2][cols - 1] = ' '; // Exit.

  for (final row in grid) {
    stdout.writeln(row.join());
  }
}

