  // Output: identical maze with the shortest path marked by '*'.
  final List<String> rawMaze = [
    '#########',
    '#S#...#G#',
    '#.#.#.#.#',
    '#.#.#.#.#',
    '#...#...#',
    '#########',
  ];

  final int rows = rawMaze.length;
  final int cols = rawMaze.first.length;

  // Helper to encode a 2-D coordinate as a single int (row * cols + col).
  int id(int r, int c) => r * cols + c;

  // Convert the maze into a mutable 2-D character list.
  final List<List<String>> maze = [];
  for (final row in rawMaze) {
    maze.add(row.split(''));
  }

  // Locate start (S) and goal (G).
  late int sr, sc, gr, gc;
  bool foundStart = false, foundGoal = false;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      if (maze[r][c] == 'S') {
        sr = r;
        sc = c;
        foundStart = true;
      } else if (maze[r][c] == 'G') {
        gr = r;
        gc = c;
        foundGoal = true;
      }
    }
  }
  if (!foundStart || !foundGoal) {
    print('Maze must contain exactly one S (start) and one G (goal).');
    return;
  }

  // Breadth-first search (using a simple list as a queue).
  final List<List<int>> queue = [];
  int head = 0;

  final List<List<bool>> visited =
      List.generate(rows, (_) => List.filled(cols, false));
  final Map<int, int> parent = {}; // child id -> parent id

  final List<List<int>> deltas = [
    [0, 1],   // right
    [1, 0],   // down
    [0, -1],  // left
    [-1, 0],  // up
  ];

  queue.add([sr, sc]);
  visited[sr][sc] = true;

  bool reachedGoal = false;
  while (head < queue.length && !reachedGoal) {
    final int r = queue[head][0];
    final int c = queue[head][1];
    head++;

    for (final d in deltas) {
      final int nr = r + d[0];
      final int nc = c + d[1];

      bool inBounds = nr >= 0 && nr < rows && nc >= 0 && nc < cols;
      if (!inBounds || visited[nr][nc]) {
        continue;
      }

      final String cell = maze[nr][nc];
      bool passable = cell == '.' || cell == 'G';
      if (!passable) {
        continue;
      }

      visited[nr][nc] = true;
      parent[id(nr, nc)] = id(r, c);
      queue.add([nr, nc]);

      if (nr == gr && nc == gc) {
        reachedGoal = true;
        break;
      }
    }
  }

  if (!reachedGoal) {
    print('No path found from S to G.');
    return;
  }

  // Reconstruct path from goal back to start.
  int cr = gr, cc = gc;
  while (!(cr == sr && cc == sc)) {
    final int pid = parent[id(cr, cc)]!;
    cr = pid ~/ cols;
    cc = pid % cols;
    if (!(cr == sr && cc == sc)) {
      // Mark the path, but leave S and G intact.
      maze[cr][cc] = '*';
    }
  }

  // Output solved maze.
  for (final row in maze) {
    print(row.join());
  }
}
