import 'dart:io';
import 'dart:math';

@pragma('vm:entry-point')
void main() {
  const human = 'X';
  const ai = 'O';
  final board = List<String>.filled(9, ' ');

  // Draw the board in a human-friendly way.
  void printBoard() {
    print('''
 ${board[0]} | ${board[1]} | ${board[2]} 
---+---+---
 ${board[3]} | ${board[4]} | ${board[5]} 
---+---+---
 ${board[6]} | ${board[7]} | ${board[8]} 
''');
  }

  // Check for a winner, returning 'X', 'O', or null.
  String? winnerOf(List<String> b) {
    const lines = [
      [0, 1, 2],
      [3, 4, 5],
      [6, 7, 8],
      [0, 3, 6],
      [1, 4, 7],
      [2, 5, 8],
      [0, 4, 8],
      [2, 4, 6],
    ];
    for (final line in lines) {
      final a = b[line[0]];
      if (a != ' ' && a == b[line[1]] && a == b[line[2]]) {
        return a;
      }
    }
    return null;
  }

  bool movesLeft(List<String> b) => b.contains(' ');

  // Classic minimax algorithm: returns score (+1, 0, -1).
  int minimax(List<String> b, bool maximizing) {
    final result = winnerOf(b);
    if (result == ai) return 1;
    if (result == human) return -1;
    if (!movesLeft(b)) return 0;

    if (maximizing) {
      var best = -999;
      for (var i = 0; i < 9; i++) {
        if (b[i] == ' ') {
          b[i] = ai;
          best = max(best, minimax(b, false));
          b[i] = ' ';
        }
      }
      return best;
    } else {
      var best = 999;
      for (var i = 0; i < 9; i++) {
        if (b[i] == ' ') {
          b[i] = human;
          best = min(best, minimax(b, true));
          b[i] = ' ';
        }
      }
      return best;
    }
  }

  // Determine the optimal computer move.
  int bestMove() {
    var bestScore = -999;
    var move = -1;
    for (var i = 0; i < 9; i++) {
      if (board[i] == ' ') {
        board[i] = ai;
        final score = minimax(board, false);
        board[i] = ' ';
        if (score > bestScore) {
          bestScore = score;
          move = i;
        }
      }
    }
    return move;
  }

  // UI helpers.
  void intro() {
    print('Welcome to Tic-Tac-Toe!');
    print('You are X, computer is O.');
    print('Enter a position (1-9) as follows:');
    print('''
 1 | 2 | 3
---+---+---
 4 | 5 | 6
---+---+---
 7 | 8 | 9
''');
  }

  // Game loop.
  intro();
  var humanTurn = Random().nextBool(); // Randomly decide who starts.
  while (true) {
    printBoard();

    final winner = winnerOf(board);
    if (winner != null) {
      print(winner == human ? 'You win!' : 'Computer wins!');
      break;
    }
    if (!movesLeft(board)) {
      print('It\'s a draw!');
      break;
    }

    if (humanTurn) {
      stdout.write('Your move (1-9): ');
      final input = stdin.readLineSync();
      final pos = int.tryParse(input ?? '');
      if (pos == null || pos < 1 || pos > 9 || board[pos - 1] != ' ') {
        print('Invalid move. Try again.');
        continue;
      }
      board[pos - 1] = human;
    } else {
      final move = bestMove();
      board[move] = ai;
      print('Computer chooses position ${move + 1}.');
    }

    humanTurn = !humanTurn;
  }

  printBoard();
}

