import 'dart:io';

@pragma('vm:entry-point')
void main() {
  // Simple Nim variant:
  //  – 21 stones on the table.
  //  – Players alternate taking 1–3 stones.
  //  – Whoever takes the last stone wins.

  const int initialStones = 21;
  const int maxTake       = 3;
  const int inf           = 1 << 30; // A large number for ±infinity.

  int stones = initialStones;

  // Alpha-beta–pruned minimax -------------------------------------------------
  int alphaBeta(int remaining, bool maximizing, int alpha, int beta) {
    // Terminal position: current player cannot move (no stones left),
    // so the previous player has just won.
    if (remaining == 0) return maximizing ? -1 : 1;

    if (maximizing) {
      int value = -inf;
      for (int take = 1; take <= maxTake && take <= remaining; ++take) {
        value = value > (alphaBeta(remaining - take, false, alpha, beta))
            ? value
            : alphaBeta(remaining - take, false, alpha, beta);
        alpha = alpha > value ? alpha : value;
        if (alpha >= beta) break; // β-cutoff
      }
      return value;
    } else {
      int value = inf;
      for (int take = 1; take <= maxTake && take <= remaining; ++take) {
        value = value < (alphaBeta(remaining - take, true, alpha, beta))
            ? value
            : alphaBeta(remaining - take, true, alpha, beta);
        beta = beta < value ? beta : value;
        if (alpha >= beta) break; // α-cutoff
      }
      return value;
    }
  }

  // Choose the move with the best minimax score.
  int bestMove(int remaining) {
    int bestScore = -inf;
    int bestTake  = 1;
    for (int take = 1; take <= maxTake && take <= remaining; ++take) {
      int score = alphaBeta(remaining - take, false, -inf, inf);
      if (score > bestScore) {
        bestScore = score;
        bestTake  = take;
      }
    }
    return bestTake;
  }

  // --------------------------------------------------------------------------
  stdout.writeln('Welcome to Nim!');
  stdout.writeln(
      'There are $initialStones stones. On your turn you may take 1–$maxTake.');
  stdout.writeln('Whoever takes the last stone wins.\n');
  stdout.write('Do you want to move first? (y/n): ');
  bool humanTurn =
      (stdin.readLineSync() ?? '').trim().toLowerCase().startsWith('y');

  while (stones > 0) {
    stdout.writeln('\nStones remaining: $stones');
    if (humanTurn) {
      int? take;
      do {
        stdout.write('Your move (1–$maxTake): ');
        take = int.tryParse(stdin.readLineSync() ?? '');
      } while (take == null || take < 1 || take > maxTake || take > stones);
      stones -= take;
      if (stones == 0) {
        stdout.writeln('You took the last stone. You win!');
        break;
      }
    } else {
      int take = bestMove(stones);
      stdout.writeln('AI takes $take stone(s).');
      stones -= take;
      if (stones == 0) {
        stdout.writeln('AI took the last stone. AI wins!');
        break;
      }
    }
    humanTurn = !humanTurn;
  }
}

