    return sqrt(sum);
  }

  // --- INITIALISE CENTROIDS (random unique points from the data) ---
  final centroids = <List<double>>[];
  final chosenIndices = <int>{};
  while (centroids.length < k) {
    final idx = random.nextInt(data.length);
    if (chosenIndices.add(idx)) {
      centroids.add(List<double>.from(data[idx]));
    }
  }

  // --- K-MEANS LOOP ---
  var assignments = List<int>.filled(data.length, -1);
  var iteration = 0;
  var changed = true;

  while (changed && iteration < maxIterations) {
    changed = false;

    // 1. Assignment step
    for (var i = 0; i < data.length; i++) {
      var bestCluster = -1;
      var bestDistance = double.infinity;

      for (var c = 0; c < k; c++) {
        final d = distance(data[i], centroids[c]);
        if (d < bestDistance) {
          bestDistance = d;
          bestCluster = c;
        }
      }

      if (assignments[i] != bestCluster) {
        assignments[i] = bestCluster;
        changed = true;
      }
    }

    // 2. Update step
    final sums = List.generate(k, (_) => List<double>.filled(data[0].length, 0.0));
    final counts = List<int>.filled(k, 0);

    for (var i = 0; i < data.length; i++) {
      final cluster = assignments[i];
      counts[cluster]++;
      for (var dim = 0; dim < data[i].length; dim++) {
        sums[cluster][dim] += data[i][dim];
      }
    }

    for (var c = 0; c < k; c++) {
      if (counts[c] == 0) continue; // Skip empty clusters
      for (var dim = 0; dim < centroids[c].length; dim++) {
        centroids[c][dim] = sums[c][dim] / counts[c];
      }
    }

    iteration++;
  }

  // --- OUTPUT ---
  print('Converged in $iteration iteration(s).');
  for (var c = 0; c < k; c++) {
    print('Cluster $c centroid: ${centroids[c]}');
    final pts = [
      for (var i = 0; i < data.length; i++)
        if (assignments[i] == c) data[i]
    ];
