  // Example directed graph represented as edge list: [from, to]
  final List<List<int>> edges = [
    [0, 1], [0, 2],
    [1, 2],
    [2, 0], [2, 3],
    [3, 2],
    [4, 2], [4, 3]
  ];

  // Collect unique nodes
  final Set<int> nodes = {};
  for (var e in edges) {
    nodes.add(e[0]);
    nodes.add(e[1]);
  }
  final int n = nodes.length;

  // Build outgoing-adjacency list
  final Map<int, List<int>> outgoing = {for (var v in nodes) v: []};
  for (var e in edges) {
    outgoing[e[0]]!.add(e[1]);
  }

  const double damping = 0.85;   // Probability of following a link
  const int iterations = 20;     // Fixed number of power iterations

  // Initial uniform ranks
  final Map<int, double> rank = {for (var v in nodes) v: 1.0 / n};

  // Power-iteration loop
  for (int it = 0; it < iterations; it++) {
    // Base value (random teleport) added to every node
    final Map<int, double> newRank = {
      for (var v in nodes) v: (1 - damping) / n
    };

    // Distribute rank through outgoing links (or to all nodes if sink)
    for (var v in nodes) {
      final links = outgoing[v]!;
      if (links.isEmpty) {
        // Sink node: spread rank evenly everywhere
        final share = rank[v]! / n;
        for (var u in nodes) {
          newRank[u] = newRank[u]! + damping * share;
        }
      } else {
        final share = rank[v]! / links.length;
        for (var u in links) {
          newRank[u] = newRank[u]! + damping * share;
        }
      }
    }

    // Commit new ranks
    for (var v in nodes) {
      rank[v] = newRank[v]!;
    }
  }

  // Output final PageRank values
  print('PageRank after $iterations iterations:');
  for (var v in nodes) {
    print('Node $v → ${rank[v]!.toStringAsFixed(4)}');
  }
}

