  for (var v in nodes) {
    rank[v] = 1.0 / n;
  }

  // Power iteration loop
  for (int it = 0; it < iterations; it++) {
    final Map<int, double> newRank = {};
    // Base value for random teleport: (1 - damping) / n for each node
    for (var v in nodes) {
