    }

    // Distribute rank through outgoing links
    for (var v in nodes) {
      final links = outgoing[v]!;
      if (links.isEmpty) {
        // Sink node: spread rank evenly to all nodes
        final share = rank[v]! / n;
        for (var u in nodes) {
