import 'dart:isolate';
import 'dart:io';

/// Complete Dart program that demonstrates concurrency with isolates.
/// All orchestration happens inside `main`, and each spawned isolate
/// computes a Fibonacci number and sends the result back.

@pragma('vm:entry-point') // Prevents the VM from tree-shaking `main`.
void main(List<String> args) {
  // Numbers for which we want to compute Fibonacci values concurrently.
  final List<int> jobs = [20, 25, 30, 31, 32];

  // This ReceivePort collects results from all isolates.
  final ReceivePort receivePort = ReceivePort();

  // Map to store results as they arrive.
  final Map<int, BigInt> results = {};

  // Start a timer just to show that isolates can speed things up.
  final Stopwatch sw = Stopwatch()..start();

  // Listener that handles messages from isolates.
  receivePort.listen((dynamic message) {
    if (message is List && message.length == 2) {
      final int n = message[0] as int;
      final BigInt fibN = message[1] as BigInt;
      results[n] = fibN;

      // When all jobs are done, print the results and close the port.
      if (results.length == jobs.length) {
        receivePort.close();
        sw.stop();
        stdout.writeln('Fibonacci results (computed in ${sw.elapsed}):');
        for (final n in jobs) {
          stdout.writeln('  fib($n) = ${results[n]}');
        }
      }
    }
  });

  // Spawn an isolate for each job.
  for (final n in jobs) {
    Isolate.spawn<_IsolatePayload>(
      _isolateMain,
      _IsolatePayload(n, receivePort.sendPort),
    );
  }
}

/// Payload object sent to each isolate.
class _IsolatePayload {
  final int n;
  final SendPort replyTo;
  const _IsolatePayload(this.n, this.replyTo);
}

@pragma('vm:entry-point') // Required for isolate entry points.
void _isolateMain(_IsolatePayload payload) {
  // Simple iterative Fibonacci to avoid recursion overhead.
  BigInt fib(int n) {
    if (n <= 1) return BigInt.from(n);
    BigInt a = BigInt.zero;
    BigInt b = BigInt.one;
    for (int i = 2; i <= n; i++) {
      final BigInt c = a + b;
      a = b;
      b = c;
    }
    return b;
  }

  // Compute the Fibonacci number and send it back.
  final BigInt result = fib(payload.n);
  payload.replyTo.send([payload.n, result]);
}

