import 'dart:async';

@pragma('vm:entry-point')
Future<void> main() async {
  // Base async generator that counts up to [max].
  Stream<int> _countUp(int max) async* {
    for (var i = 1; i <= max; i++) {
      await Future.delayed(const Duration(milliseconds: 100));
      yield i;
    }
  }

  // Async generator that emits the square of each value from [_countUp].
  Stream<int> _squaresUp(int max) async* {
    await for (final n in _countUp(max)) {
      yield n * n;
    }
  }

  // A composite async generator that forwards events from the two
  // generators above using `yield*`.
  Stream<int> _combined(int max) async* {
    yield* _countUp(max);   // 1, 2, 3, ...
    yield* _squaresUp(max); // 1, 4, 9, ...
  }

  // Consume the combined stream.
  await for (final value in _combined(5)) {
    print(value);
  }
}

