// Demonstrates Dart’s null-aware operators in complex, real-world-style
// expressions.  Run with sound null-safety (`dart run`).

import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // 1. Build a *possibly-null* nested structure that mimics an API payload.
  Map<String, dynamic>? payload = Random().nextBool()
      ? {
          'users': [
            {'name': 'Alice', 'age': 30},
            {'name': 'Bob'}, // age intentionally missing
            null              // entire entry is null
          ],
          'settings': null
        }
      : null;

  // 2. Use ?. and ?? to traverse safely and compute the average age.
  int totalAge = 0;
  int counted  = 0;

  for (var user in payload?['users'] ?? []) {
    int? age = user?['age'] as int?;
    totalAge += age ?? 0;
    if (user != null) counted++;
  }

  double averageAge = counted == 0 ? 0 : totalAge / counted;
  print('Average age: $averageAge');

  // 3. Demonstrate ??= for lazy initialization of nested maps.
  payload ??= {};
  payload['settings'] ??= {'theme': 'light', 'notifications': true};
  print('Settings after ??= : ${payload['settings']}');

  // 4. Complex chain mixing ?. with a fallback provided by ??.
  String theme = (payload?['settings']?['theme'] as String?)?.toUpperCase() ??
      'DEFAULT';
  print('Chosen theme (upper-case): $theme');

  // 5. Null-aware list spread inside a literal.
  List<int>? remoteScores =
      Random().nextBool() ? [10, 20, 30] : null; // could be null
  List<int> scores = [5, ...?remoteScores, 40];
  print('Scores list (with spread): $scores');

  // 6. Null-aware cascade (?..) to mutate a map only when it isn’t null.
  (payload?['settings'] as Map?)?..['language'] = 'en'
                                 ..['timezone'] = 'UTC';
  print('Final payload: $payload');
}

