// Demonstrates mixins with super-calls in Dart.

class A {
  void foo() {
    print('A.foo()');
  }
}

mixin B on A {
  @override
  void foo() {
    print('B.foo() – before super');
    super.foo(); // Calls A.foo()
    print('B.foo() – after super');
  }
}

mixin C on A {
  @override
  void foo() {
    print('C.foo() – before super');
    super.foo(); // Calls B.foo() because of mixin application order
    print('C.foo() – after super');
  }
}

class D extends A with B, C {
  @override
  void foo() {
    print('D.foo() – before super');
    super.foo(); // Calls C.foo()
    print('D.foo() – after super');
  }
}

@pragma('vm:entry-point') //
void main() {
  final d = D();
  d.foo();
}

