void main() {
  // A local sync* generator that lazily produces the Fibonacci sequence
  // up to (and including) [max].
  Iterable<int> fibonacci(int max) sync* {
    int a = 0, b = 1;
    while (a <= max) {
      yield a;                 // Emit the next Fibonacci number.
      final next = a + b;
      a = b;
      b = next;
    }
  }

  // A local sync* generator that yields the natural numbers 1‥[n].
  Iterable<int> naturals(int n) sync* {
    for (int i = 1; i <= n; i++) {
      yield i;
    }
  }

  // A sync* generator that delegates with `yield*`, demonstrating
  // composition of iterables.
  Iterable<int> squaresUpTo(int n) sync* {
    // Map each natural number to its square and yield the entire stream.
    yield* naturals(n).map((i) => i * i);
  }

  // Demonstrate each generator.
  print('Fibonacci numbers ≤ 100:');
  for (final value in fibonacci(100)) {
    print(value);
  }

  print('\nSquares of the first 10 natural numbers:');
  for (final value in squaresUpTo(10)) {
    print(value);
  }
}

