// A self-contained Dart program that demonstrates covariant overrides.

abstract class Animal {
  String speak() => 'Some generic animal sound';
}

class Dog extends Animal {
  @override
  String speak() => 'Woof!';
}

class Trainer {
  // Base method expects any Animal.
  void train(Animal animal) {
    print('Trainer: Training an animal that says "${animal.speak()}".');
  }
}

class DogTrainer extends Trainer {
  // Using `covariant` lets us narrow the parameter type from `Animal` to `Dog`.
  @override
  void train(covariant Dog dog) {
    print('DogTrainer: Training a dog that says "${dog.speak()}".');
  }
}

@pragma('vm:entry-point')
void main() {
  final dog = Dog();

  // A generic trainer can handle any Animal.
  final Trainer genericTrainer = Trainer();
  genericTrainer.train(dog); // OK - Dog is an Animal.

  // A specialized trainer works specifically with Dog.
  final DogTrainer specializedTrainer = DogTrainer();
  specializedTrainer.train(dog); // Calls the covariant override.

  // The specialized trainer can still be referenced through the base type.
  final Trainer upcasted = specializedTrainer;
  upcasted.train(dog); // Dynamic dispatch calls DogTrainer.train.
}

