// Demonstrates the use of typedefs for function types in Dart.

import 'dart:math';

/// A typedef representing any binary integer operation.
typedef IntOp = int Function(int a, int b);

/// A generic typedef for a boolean predicate.
typedef Predicate<T> = bool Function(T value);

@pragma('vm:entry-point')
void main() {
  // Using the IntOp typedef with anonymous functions.
  IntOp add      = (a, b) => a + b;
  IntOp subtract = (a, b) => a - b;
  IntOp multiply = (a, b) => a * b;
  IntOp power    = (a, b) => pow(a, b).toInt();

  const int x = 6;
  const int y = 4;

  print('Demonstrating IntOp typedefs:');
  print('$x + $y = ${add(x, y)}');
  print('$x - $y = ${subtract(x, y)}');
  print('$x * $y = ${multiply(x, y)}');
  print('$x ^ $y = ${power(x, y)}');

  // Using the generic Predicate typedef.
  Predicate<int> isEven = (n) => n.isEven;
  final numbers = List<int>.generate(10, (i) => i);
  final evens = numbers.where(isEven);

  print('\nDemonstrating Predicate<int> typedef:');
  print('Original list : $numbers');
  print('Even numbers  : $evens');
}

