// A short demonstration of Dart's callable classes feature.
//
// Run with:
/// dart run callable_classes.dart
///
/// Output will resemble:
/// Starting value: 5
/// After multiplier: 15
/// After adder: 22
/// Pipeline result: 22
/// Original list: [1, 2, 3, 4]
/// Tripled list: [3, 6, 9, 12]
/// Add seven list: [8, 9, 10, 11]

class Multiplier {
  final num factor;
  const Multiplier(this.factor);

  // The "call" method turns this class into a callable object.
  num call(num input) => input * factor;

  @override
  String toString() => 'Multiplier($factor)';
}

class Adder {
  final num addend;
  const Adder(this.addend);

  // Also callable.
  num call(num input) => input + addend;

  @override
  String toString() => 'Adder($addend)';
}

class Composite {
  final num Function(num) first;
  final num Function(num) second;
  const Composite(this.first, this.second);

  // Calling a Composite runs "first" then "second".
  num call(num input) => second(first(input));

  @override
  String toString() => 'Composite($first → $second)';
}

@pragma('vm:entry-point')
void main() {
  // 1. Create a callable object that triples its input.
  final triple = Multiplier(3);

  // 2. Create another callable object that adds seven.
  final addSeven = Adder(7);

  // 3. Compose the two callables.
  final pipeline = Composite(triple, addSeven);

  // 4. Demonstrate basic usage.
  const value = 5;
  print('Starting value: $value');
  print('After multiplier: ${triple(value)}');
  print('After adder: ${addSeven(triple(value))}');
  print('Pipeline result: ${pipeline(value)}');

  // 5. Use them as first-class functions (Map takes a Function).
  final list = [1, 2, 3, 4];
  print('Original list: $list');
  print('Tripled list: ${list.map(triple).toList()}');
  print('Add seven list: ${list.map(addSeven).toList()}');
}

