// A complete, self-contained Dart script that demonstrates using
// Symbol objects as canonical, unique handles for identifier strings.
// The entire program logic lives in `main` as requested.

@pragma('vm:entry-point')
void main() {
  // A sample stream of identifiers (with deliberate duplicates).
  const identifiers = <String>[
    'alpha',
    'beta',
    'gamma',
    'alpha',  // duplicate
    'delta',
    'beta'    // duplicate
  ];

  // A simple symbol table that assigns each *unique* Symbol
  // a monotonically increasing integer id.
  final Map<Symbol, int> symbolIds = <Symbol, int>{};
  var nextId = 0;

  // Convert each identifier to a Symbol and populate the table.
  for (final id in identifiers) {
    symbolIds.putIfAbsent(Symbol(id), () => nextId++);
  }

  // Pretty-print the resulting table.
  print('=== Symbol table ===');
  symbolIds.forEach((sym, id) {
    // sym.toString() yields something like 'Symbol("alpha")'.
    final name = sym.toString()
                    .replaceAll('Symbol("', '')
                    .replaceAll('")', '');
    print('identifier "$name" => id $id');
  });

  // ------------------------------------------------------------------
  // Extra demonstration: compile-time vs run-time symbol equality.
  // #alpha is a compile-time symbol literal; Symbol('alpha') is built
  // at run time.  They compare equal because symbols are canonical.
  print('\nEquality check: #alpha == Symbol(\'alpha\') → ${#alpha == Symbol('alpha')}');

  // Looking up a freshly created symbol returns the same numeric id,
  // proving that the same identifier always maps to the same symbol.
  final lookup = symbolIds[Symbol('beta')];
  print('Lookup with a new Symbol(\'beta\') returned id $lookup');
}

