// A self-contained example that demonstrates Unicode handling with runes.
//
// Run with:  dart run unicode_runes.dart
// You should see correct counts and proper handling of multi-code-unit
// characters such as emojis or CJK ideographs.

@pragma('vm:entry-point') // Prevents the VM from tree-shaking main.
void main() {
  // 1. Mixed-script text containing BMP, astral-plane emojis and CJK.
  const text = 'Hello, 世界 👋🌍';

  print('Original text:               $text');
  // String.length counts UTF-16 code units.
  print('Code-unit length:            ${text.length}');
  // text.runes.length counts actual Unicode scalar values.
  print('Rune (code-point) length:    ${text.runes.length}\n');

  // 2. Iterate over every rune and display its UTF-32 value.
  print('Iterating over runes:');
  for (final rune in text.runes) {
    final char = String.fromCharCode(rune);
    final hex  = rune.toRadixString(16).toUpperCase().padLeft(4, '0');
    print('  $char  ->  U+$hex');
  }

  // 3. Reverse the string safely by runes (not code units).
  final reversed = String.fromCharCodes(text.runes.toList().reversed);
  print('\nReversed (by runes):         $reversed');

  // 4. Construct a new string directly from a list of runes.
  final rocketSparkle = [0x1F680, 0x0020, 0x2728]; // 🚀 ✨
  print('From runes:                  ${String.fromCharCodes(rocketSparkle)}');
}

