/// An enum representing the eight planets.  Each constant carries two
/// associated values: mass (kg) and radius (m).  The enum also includes
/// methods that use those values.
enum Planet {
  mercury(3.303e+23, 2.4397e6),
  venus  (4.869e+24, 6.0518e6),
  earth  (5.976e+24, 6.37814e6),
  mars   (6.421e+23, 3.3972e6),
  jupiter(1.9e+27,   7.1492e7),
  saturn (5.688e+26, 6.0268e7),
  uranus (8.686e+25, 2.5559e7),
  neptune(1.024e+26, 2.4746e7);

  // Instance fields.
  final double mass;   // in kilograms
  final double radius; // in meters

  // Universal gravitational constant.
  static const double _G = 6.67300e-11;

  // Const constructor that assigns the associated values.
  const Planet(this.mass, this.radius);

  // Derived property.
  double get surfaceGravity => _G * mass / (radius * radius);

  // Given an object mass, return the weight on this planet.
  double surfaceWeight(double otherMass) => otherMass * surfaceGravity;
}

@pragma('vm:entry-point')
void main() {
  // Logic goes here: iterate over all planets and print a formatted report.
  const double myMass = 70; // kg

  for (final planet in Planet.values) {
    final weight = planet.surfaceWeight(myMass);
    print('On ${planet.name.padRight(8)} → '
        'gravity: ${planet.surfaceGravity.toStringAsFixed(2)} m/s², '
        'weight: ${weight.toStringAsFixed(2)} N');
  }
}

