  // Sample data to categorise.
  final numbers = <int>[-10, -1, 0, 1, 4, 8, 12, 42, 100];

  for (final n in numbers) {
    // A switch expression that relies exclusively on relational patterns.
    final label = switch (n) {
      < 0                     => 'Negative ($n)',
      0                       => 'Zero',
      > 0 && < 5              => 'Small positive ($n)',
      >= 5 && <= 10           => 'Medium positive ($n)',
      > 10 && <= 50           => 'Large positive ($n)',
      > 50                    => 'Huge positive ($n)',
      _                       => 'Unclassified' // Technically unreachable but required for exhaustiveness.
    };

    print(label);
  }
}

