  // Demonstrating two additional VM hints on local functions.

  @pragma('vm:prefer-inline') // Encourage the VM to inline this tiny helper.
  int fastAdd(int a, int b) => a + b;

  @pragma('vm:never-inline') // Force the VM to keep this heavy function separate.
