  final mutableMap  = {'a': 1, 'b': 2};

  // 2. Produce read-only wrappers/copies.
  final unmodifiableList = List.unmodifiable(mutableList);   // Copy + read-only.
  final unmodifiableSet  = Set.unmodifiable(mutableSet);     // Copy + read-only.
  final unmodifiableMap  = Map.unmodifiable(mutableMap);     // Copy + read-only.
  final listView         = UnmodifiableListView(mutableList); // Live read-only view.

  print('UnmodifiableList      : $unmodifiableList');
  print('UnmodifiableSet       : $unmodifiableSet');
  print('UnmodifiableMap       : $unmodifiableMap');
  print('UnmodifiableListView  : $listView');

  // 3. Attempt (and fail) to mutate them.
  void attempt(String label, void Function() action) {
    try {
      action();
      print('Unexpectedly modified $label!');
    } catch (e) {
      print('Cannot modify $label: $e');
    }
  }

  attempt('unmodifiableList', () => unmodifiableList.add(4));
  attempt('unmodifiableSet' , () => unmodifiableSet.add('date'));
  attempt('unmodifiableMap' , () => unmodifiableMap['c'] = 3);
  attempt('listView'        , () => listView.add(4));

  // 4. Mutate the original collections to show copy vs. live view behavior.
  mutableList.add(4);
  print('\nAfter mutating the original list:');
  print('mutableList          : $mutableList');
  print('unmodifiableList (copy, unchanged) : $unmodifiableList');
  print('listView (live view, updated)      : $listView');
}

