import 'dart:isolate';
import 'dart:async';

@pragma('vm:entry-point')
Future<void> main() async {
  // 1. Create a port the worker isolate can use to talk to the main isolate.
  final ReceivePort mainReceivePort = ReceivePort();

  // 2. Spawn the worker isolate and give it the main isolate’s SendPort.
  await Isolate.spawn(_workerIsolate, mainReceivePort.sendPort);

  // 3. The first message from the worker isolate is its own SendPort.
  final SendPort workerSendPort = await mainReceivePort.first as SendPort;

  // 4. Create a second port to receive a response to our request.
  final ReceivePort responsePort = ReceivePort();

  // 5. Send a message to the worker, attaching the response port’s SendPort.
  workerSendPort.send(['Hello from the main isolate!', responsePort.sendPort]);

  // 6. Await and print the reply.
  final String reply = await responsePort.first as String;
  print('Main isolate received: $reply');

  // 7. Clean up the ports.
