  // Pick a 32-bit unsigned integer, optionally from the command line.
  final int value =
      args.isNotEmpty ? int.parse(args.first) & 0xFFFFFFFF : 0x12345678;

  print('Original value:           0x${value.toRadixString(16).padLeft(8, '0')}');
  print('Host endianness:          ${Endian.host == Endian.little ? 'Little' : 'Big'}');

  // Write the value in little-endian form.
  final ByteData littleData = ByteData(4)..setUint32(0, value, Endian.little);

  // Write the value in big-endian form.
  final ByteData bigData = ByteData(4)..setUint32(0, value, Endian.big);

  // Helper to convert bytes to a printable hex string without extra functions.
  String bytesAsHex(ByteData data) =>
      List<int>.generate(data.lengthInBytes, (i) => data.getUint8(i))
          .map((b) => b.toRadixString(16).padLeft(2, '0'))
          .join(' ');

  print('Little-endian byte order: ${bytesAsHex(littleData)}');
  print('Big-endian byte order:    ${bytesAsHex(bigData)}');

  // Read the values back using explicit endianness.
  final int readLittle = littleData.getUint32(0, Endian.little);
  final int readBig = bigData.getUint32(0, Endian.big);

  // Deliberately misinterpret big-endian bytes as little-endian to show the danger.
  final int misread = bigData.getUint32(0, Endian.little);

  print('\nRound-trip checks:');
  print('  From little-endian bytes -> 0x${readLittle.toRadixString(16).padLeft(8, '0')}');
  print('  From big-endian bytes    -> 0x${readBig.toRadixString(16).padLeft(8, '0')}');
  print('  MISREAD big->little      -> 0x${misread.toRadixString(16).padLeft(8, '0')} (incorrect)');
}

