  // Write various primitives using ByteData’s setters.
  bytes.setInt32(0, 0x12345678, Endian.big);     // 4 bytes at offset 0
  bytes.setFloat32(4, 3.1415926, Endian.little); // 4 bytes at offset 4
  bytes.setUint16(8, 0xABCD, Endian.big);        // 2 bytes at offset 8
