  final Int32List   int32View = bytes.buffer.asInt32List(0, 1);   // offset 0, 1 element
  final Float32List f32View   = bytes.buffer.asFloat32List(4, 1); // offset 4, 1 element
  final Uint16List  u16View   = bytes.buffer.asUint16List(8, 1);  // offset 8, 1 element
  final Int8List    i8View    = bytes.buffer.asInt8List(10, 1);   // offset 10, 1 element

