// A self-contained example showing how to use Dart's `final class` feature.
// Run with:  dart run <filename>.dart

import 'dart:math' as math;

// This class cannot be subclassed outside this library.
final class Circle {
  final double radius;
  const Circle(this.radius);

  double get area => math.pi * radius * radius;
  double get circumference => 2 * math.pi * radius;

  @override
  String toString() =>
      'Circle(radius: $radius, area: ${area.toStringAsFixed(2)}, '
      'circumference: ${circumference.toStringAsFixed(2)})';
}

// Another un-extendable, un-implementable class.
final class Square {
  final double side;
  const Square(this.side);

  double get area => side * side;
  double get perimeter => 4 * side;

  @override
  String toString() =>
      'Square(side: $side, area: ${area.toStringAsFixed(2)}, '
      'perimeter: ${perimeter.toStringAsFixed(2)})';
}

// Utility holder. Private constructor prevents instantiation.
final class Printer {
  Printer._();

  static void printShape(Object shape) => print(shape);
}

@pragma('vm:entry-point')
void main() {
  const circle = Circle(3);
  const square = Square(4);

  Printer.printShape(circle);
  Printer.printShape(square);
}

