class Point {
  final num x;
  final num y;

  const Point(this.x, this.y);

  @override
  String toString() => 'Point($x, $y)';
}

class Rectangle {
  final num width;
  final num height;

  Rectangle(this.width, this.height);

  Rectangle.square(num side) : this(side, side);

  Rectangle.fromPoints(Point p1, Point p2)
      : width = (p1.x - p2.x).abs(),
        height = (p1.y - p2.y).abs();

  num get area => width * height;

  @override
  String toString() => 'Rectangle($width × $height)';
}

@pragma('vm:entry-point')
void main() {
  // 1. Default constructor tear-off.
  Rectangle Function(num, num) rectFactory = Rectangle.new;
  final r1 = rectFactory(3, 4);

  // 2. Named constructor tear-off: Rectangle.square.
  Rectangle Function(num) squareFactory = Rectangle.square;
  final r2 = squareFactory(5);

  // 3. Named constructor tear-off: Rectangle.fromPoints.
  Rectangle Function(Point, Point) fromPointsFactory = Rectangle.fromPoints;
  final r3 = fromPointsFactory(const Point(1, 2), const Point(6, 8));

  // Display results.
  for (final rect in [r1, r2, r3]) {
    print('$rect → area = ${rect.area}');
  }
}

