import 'dart:io';

/// Simple data model representing a message.
class Message {
  final String sender;
  final String recipient;
  final String body;
  final DateTime timestamp;
  Message(this.sender, this.recipient, this.body) : timestamp = DateTime.now();
}

/// Simple data model representing a user with separate inbox/outbox.
class User {
  final String username;
  final List<Message> inbox = [];
  final List<Message> outbox = [];
  User(this.username);
}

@pragma('vm:entry-point')
void main() {
  // In-memory stores.
  final Map<String, User> users = {};
  final List<Message> history = []; // Global history (optional).

  // ─────────────────────────────────────────────────────────────────────────────
  // Helper functions defined _inside_ main to keep the only top-level function.
  // ─────────────────────────────────────────────────────────────────────────────

  void registerUser() {
    stdout.write('Choose a username: ');
    final name = stdin.readLineSync()?.trim();
    if (name == null || name.isEmpty) {
      print('⚠️  Username cannot be empty.');
      return;
    }
    if (users.containsKey(name)) {
      print('⚠️  User "$name" already exists.');
      return;
    }
    users[name] = User(name);
    print('✅ User "$name" registered.\n');
  }

  void sendMessage() {
    stdout.write('Sender username: ');
    final from = stdin.readLineSync()?.trim();
    stdout.write('Recipient username: ');
    final to = stdin.readLineSync()?.trim();

    if (!(users.containsKey(from) && users.containsKey(to))) {
      print('⚠️  Both users must exist before messaging.\n');
      return;
    }

    stdout.write('Enter message: ');
    final body = stdin.readLineSync() ?? '';

    final msg = Message(from!, to!, body);
    users[to]!.inbox.add(msg);
    users[from]!.outbox.add(msg);
    history.add(msg);

    print('📨 Message sent from "$from" to "$to".\n');
  }

  void viewInbox() {
    stdout.write('Username: ');
    final user = stdin.readLineSync()?.trim();
    if (!users.containsKey(user)) {
      print('⚠️  User not found.\n');
      return;
    }
    final inbox = users[user]!.inbox;
    if (inbox.isEmpty) {
      print('📭 Inbox is empty.\n');
      return;
    }
    print('📥 Inbox for "$user":');
    for (var i = 0; i < inbox.length; i++) {
      final m = inbox[i];
      print(' [$i] From: ${m.sender} • ${m.timestamp} \n     ${m.body}');
    }
    print('');
  }

  void deleteMessage() {
    stdout.write('Username: ');
    final user = stdin.readLineSync()?.trim();
    if (!users.containsKey(user)) {
      print('⚠️  User not found.\n');
      return;
    }
    final inbox = users[user]!.inbox;
    if (inbox.isEmpty) {
      print('📭 Nothing to delete, inbox is empty.\n');
      return;
    }
    for (var i = 0; i < inbox.length; i++) {
      print(' [$i] From: ${inbox[i].sender} • ${inbox[i].timestamp}');
    }
    stdout.write('Enter index of message to delete: ');
    final idx = int.tryParse(stdin.readLineSync() ?? '');
    if (idx == null || idx < 0 || idx >= inbox.length) {
      print('⚠️  Invalid index.\n');
      return;
    }
    inbox.removeAt(idx);
    print('🗑️  Message deleted.\n');
  }

  // ───────────────────────────── Main loop ─────────────────────────────
  while (true) {
    print('''
╔═══════════════════════════════════════════╗
║         In-App Messaging Console          ║
╠═══════════════════════════════════════════╣
║ 1. Register user                          ║
║ 2. Send message                           ║
║ 3. View inbox                             ║
║ 4. Delete message                         ║
║ 5. Exit                                   ║
╚═══════════════════════════════════════════╝''');
    stdout.write('Select option (1-5): ');
    switch (stdin.readLineSync()?.trim()) {
      case '1':
        registerUser();
        break;
      case '2':
        sendMessage();
        break;
      case '3':
        viewInbox();
        break;
      case '4':
        deleteMessage();
        break;
      case '5':
        print('👋 Goodbye!');
        return;
      default:
        print('⚠️  Invalid choice.\n');
    }
  }
}

