import 'dart:convert';
import 'dart:io';

/// Stand-alone example showing how you might perform a server-side
/// charge request against a payment gateway (Stripe in this case).
/// The script expects an environment variable named PAYMENT_API_KEY
/// holding your secret key (never hard-code secrets in source code).
/// -----------------------------------------------------------------
/// NOTE: Do *not* run this in production without first understanding
/// your chosen gateway’s authentication, PCI, and fraud guidelines.
/// -----------------------------------------------------------------
@pragma('vm:entry-point')
Future<void> main() async {
  // 1. Load the secret key securely from the environment.
  final apiKey = Platform.environment['PAYMENT_API_KEY'];
  if (apiKey == null || apiKey.isEmpty) {
    stderr.writeln(
        'Missing PAYMENT_API_KEY. Export it first, e.g.:\n'
        '  export PAYMENT_API_KEY=sk_test_XXXXXXXXXXXXXXXXXXXXXXXX');
    exitCode = 64; // EX_USAGE
    return;
  }

  // 2. Collect or hard-code payment details (NEVER log real card data).
  final payload = <String, dynamic>{
    'amount': 1999,          // smallest currency unit (e.g., cents)
    'currency': 'usd',
    'source': 'tok_visa',    // replace with real token from client
    'description': 'Dart CLI charge example'
  };

  // 3. Issue HTTPS POST to the gateway using Dart’s secure HttpClient.
  final client = HttpClient()
    ..badCertificateCallback = (_, __, ___) => false; // enforce TLS by default

  try {
    final url = Uri.parse('https://api.stripe.com/v1/charges');
    final request = await client.postUrl(url);

    // Stripe expects url-encoded form data and Bearer auth.
    request.headers
      ..contentType = ContentType('application', 'x-www-form-urlencoded')
      ..set(HttpHeaders.authorizationHeader, 'Bearer $apiKey');

    // Encode map → x-www-form-urlencoded
    request.write(payload.entries
        .map((e) =>
            '${Uri.encodeQueryComponent(e.key)}=${Uri.encodeQueryComponent(e.value.toString())}')
        .join('&'));

    final response = await request.close();
    final body = await response.transform(utf8.decoder).join();

    if (response.statusCode == 200) {
      stdout.writeln('✅  Payment succeeded:\n$body');
    } else {
      stderr.writeln(
          '❌  Payment failed (HTTP ${response.statusCode}).\n$body');
      exitCode = 1;
    }
  } on SocketException catch (e) {
    stderr.writeln('Network error while contacting gateway: $e');
    exitCode = 2;
  } finally {
    client.close(force: true);
  }
}

