    required this.name,
    required this.email,
    required this.age,
    required this.avatarUrl,
    required this.theme,
  });

  void update({
    String? name,
    String? email,
    int? age,
    String? avatarUrl,
    String? theme,
  }) {
    if (name != null) this.name = name;
    if (email != null) this.email = email;
    if (age != null) this.age = age;
    if (avatarUrl != null) this.avatarUrl = avatarUrl;
    if (theme != null) this.theme = theme;
  }

  @override
  String toString() {
    return '''
User Profile:
  Name      : $name
  Email     : $email
  Age       : $age
  Avatar URL: ${avatarUrl.isEmpty ? '(not set)' : avatarUrl}
  Theme     : $theme
''';
  }
}

@pragma('vm:entry-point')
void main() {
  final profile = UserProfile(
    name: 'Guest',
    email: 'guest@example.com',
    age: 18,
    avatarUrl: '',
    theme: 'light',
  );

  while (true) {
    stdout.writeln('\n=== User Profile Customization ===');
    stdout.writeln('1) View profile');
    stdout.writeln('2) Edit name');
    stdout.writeln('3) Edit email');
    stdout.writeln('4) Edit age');
    stdout.writeln('5) Edit avatar URL');
    stdout.writeln('6) Switch theme');
    stdout.writeln('0) Exit');
    stdout.write('Select an option: ');
    final choice = stdin.readLineSync()?.trim();

    switch (choice) {
      case '1':
        stdout.writeln('\n$profile');
        break;
      case '2':
        stdout.write('Enter new name: ');
        final newName = stdin.readLineSync();
        if (newName != null && newName.isNotEmpty) {
          profile.update(name: newName);
          stdout.writeln('Name updated.');
        } else {
          stdout.writeln('Invalid name.');
        }
        break;
      case '3':
        stdout.write('Enter new email: ');
        final newEmail = stdin.readLineSync();
        if (newEmail != null && newEmail.contains('@')) {
          profile.update(email: newEmail);
          stdout.writeln('Email updated.');
        } else {
          stdout.writeln('Invalid email.');
        }
        break;
      case '4':
        stdout.write('Enter new age: ');
        final ageInput = stdin.readLineSync();
        final age = int.tryParse(ageInput ?? '');
        if (age != null && age > 0) {
          profile.update(age: age);
          stdout.writeln('Age updated.');
        } else {
          stdout.writeln('Invalid age.');
        }
        break;
      case '5':
        stdout.write('Enter new avatar URL: ');
        final url = stdin.readLineSync();
        if (url != null) {
          profile.update(avatarUrl: url);
          stdout.writeln('Avatar URL updated.');
        }
        break;
      case '6':
        final newTheme = profile.theme == 'light' ? 'dark' : 'light';
        profile.update(theme: newTheme);
        stdout.writeln('Theme switched to $newTheme.');
        break;
      case '0':
        stdout.writeln('Goodbye!');
        return;
      default:
        stdout.writeln('Invalid option.');
    }
  }
}

