Future<void> main() async {
  // Simple in–app analytics tracker implemented entirely within `main`.

  // Queue that holds events until they are uploaded.
  final List<Map<String, dynamic>> _eventQueue = [];

  // How often events are flushed automatically.
  const Duration _flushInterval = Duration(seconds: 5);
  Timer? _flushTimer;

  // Sends queued events to a backend (simulated with prints).
  void _flush() {
    if (_eventQueue.isEmpty) return;

    print('\nUploading ${_eventQueue.length} analytics event(s)...');
    for (final event in _eventQueue) {
      print(' • ${event['timestamp']} | '
            '${event['name']} | '
            '${event['params']}');
    }
    _eventQueue.clear();
  }

  // Starts periodic flushing of analytics.
  Timer _startFlushTimer() =>
      Timer.periodic(_flushInterval, (_) => _flush());

  // Public API for tracking an analytics event.
  void trackEvent(String name, [Map<String, dynamic> params = const {}]) {
    _eventQueue.add({
      'name': name,
      'params': params,
      'timestamp': DateTime.now().toIso8601String(),
    });
    print('Queued event: $name (${_eventQueue.length} pending)');

    // Start the periodic flush timer on the first event.
    _flushTimer ??= _startFlushTimer();

    // Optional: flush immediately if queue gets too large.
    if (_eventQueue.length >= 10) {
      _flush();
    }
  }

  // ------------------------------------------------------------------
  // Simulated application lifecycle demonstrating analytics usage.
  // ------------------------------------------------------------------
  trackEvent('app_open');

  await Future.delayed(const Duration(milliseconds: 400));
  trackEvent('screen_view', {'screen': 'Home'});

  await Future.delayed(const Duration(milliseconds: 800));
  trackEvent('button_press', {'id': 'StartTrialButton'});

  await Future.delayed(const Duration(milliseconds: 600));
  trackEvent('screen_view', {'screen': 'Paywall'});

  await Future.delayed(const Duration(milliseconds: 500));
  trackEvent('purchase', {
    'product_id': 'premium_monthly',
    'price': 4.99,
    'currency': 'USD',
  });

  // Wait long enough for periodic flush to trigger at least once.
  await Future.delayed(const Duration(seconds: 6));

  // Graceful shutdown: cancel timer and flush remaining events.
  _flushTimer?.cancel();
  _flush();

  print('\nAnalytics session finished.');
}

