// in_app_purchase_demo.dart
//
// A minimal command-line “in-app purchase” demo written in pure Dart.
// It does NOT talk to the Apple / Google billing APIs; instead it
// simulates the basic purchase flow so you can focus on the business
// logic (catalog management, purchase validation, entitlement tracking).

import 'dart:io';

@pragma('vm:entry-point') // <-- Prevents tree-shaking of `main` on the VM.
void main() {
  // ----- Mock product catalog ------------------------------------------------
  //
  // In a real app this would come from your back-end or the store’s
  // product list.  Each entry maps a productId to a title and price.
  final Map<String, Map<String, dynamic>> catalog = {
    'remove_ads': {
      'title': 'Remove Ads',
      'price': 2.99,
    },
    'coins_100': {
      'title': '100 Coins',
      'price': 0.99,
    },
    'pro_upgrade': {
      'title': 'Pro Upgrade',
      'price': 4.99,
    },
  };

  // A set that tracks the user’s entitlements locally.
  final Set<String> owned = {};

  // ---------------------------------------------------------------------------
  // Utility helpers – everything lives inside `main` for the purposes of this
  // demo, so we use local functions rather than top-level declarations.
  // ---------------------------------------------------------------------------

  void showHelp() {
    print('''
In-App Purchase CLI Demo
────────────────────────
Commands:
  list                   List available products
  buy  <product_id>      Purchase a product
  inventory              Show owned products
  help                   Show this help
  exit                   Quit the program
''');
  }

  void listProducts() {
    print('\nAvailable products:');
    for (final entry in catalog.entries) {
      final id    = entry.key;
      final title = entry.value['title']  as String;
      final price = entry.value['price'] as double;
      final ownedFlag = owned.contains(id) ? '(purchased)' : '';
      print('  $id : $title — \$${price.toStringAsFixed(2)} $ownedFlag');
    }
    print('');
  }

  void buyProduct(String id) {
    if (!catalog.containsKey(id)) {
      print('✗ Product "$id" does not exist.');
      return;
    }
    if (owned.contains(id)) {
      print('✓ You already own "$id".');
      return;
    }

    final title = catalog[id]!['title']  as String;
    final price = catalog[id]!['price'] as double;

    stdout.write(
        'Purchase "$title" for \$${price.toStringAsFixed(2)}? (y/n): ');
    final confirmation = stdin.readLineSync()?.trim().toLowerCase();

    if (confirmation == 'y' || confirmation == 'yes') {
      // Here you would call the real billing API and verify the receipt
      // on your server.  We simply grant the entitlement.
      owned.add(id);
      print('✓ Purchase successful – you now own "$id".\n');
    } else {
      print('↺ Purchase cancelled.\n');
    }
  }

  void showInventory() {
    if (owned.isEmpty) {
      print('You do not own any products yet.\n');
      return;
    }
    print('\nOwned products:');
    for (final id in owned) {
      print('  $id : ${catalog[id]!['title']}');
    }
    print('');
  }

  // ---------------------------------------------------------------------------
  // Main command loop
  // ---------------------------------------------------------------------------
  showHelp();
  while (true) {
    stdout.write('> ');
    final input = stdin.readLineSync();
    if (input == null) continue;

    final parts = input.trim().split(RegExp(r'\s+'));
    if (parts.isEmpty || parts.first.isEmpty) continue;

    switch (parts.first.toLowerCase()) {
      case 'list':
        listProducts();
        break;

      case 'buy':
        if (parts.length < 2) {
          print('Usage: buy <product_id>\n');
        } else {
          buyProduct(parts[1]);
        }
        break;

      case 'inventory':
        showInventory();
        break;

      case 'help':
        showHelp();
        break;

      case 'exit':
        print('Good-bye!');
        return;

      default:
        print('Unknown command "${parts.first}". Type "help" for options.\n');
    }
  }
}

