// Location-based push-notification demo
//
// No external packages are used so that the code compiles and runs
// with `dart run`.  All I/O is done with `print`, so you can observe
// the “push notifications” in your console.
//
// The program
//   1. Creates a few geofences (circular regions).
//   2. Simulates a moving device by emitting random coordinates.
//   3. Triggers a “push notification” whenever the device enters
//      one of the geofences.

import 'dart:async';
import 'dart:math';

/// Lightweight immutable representation of a geographical co-ordinate.
class LatLng {
  final double lat;
  final double lng;
  const LatLng(this.lat, this.lng);

  @override
  String toString() => '(${lat.toStringAsFixed(5)}, ${lng.toStringAsFixed(5)})';
}

/// Simple circular geofence.
class Geofence {
  final String id;
  final LatLng center;
  final double radiusMeters; // Radius of the fence in metres.

  const Geofence({
    required this.id,
    required this.center,
    required this.radiusMeters,
  });

  /// True if [point] is located inside the geofence’s circle.
  bool contains(LatLng point) =>
      _haversineDistanceMeters(center, point) <= radiusMeters;

  /// Haversine distance between two co-ordinates (metres).
  static double _haversineDistanceMeters(LatLng a, LatLng b) {
    const R = 6371000.0; // Earth radius in metres.
    final dLat = _degToRad(b.lat - a.lat);
    final dLng = _degToRad(b.lng - a.lng);

    final lat1 = _degToRad(a.lat);
    final lat2 = _degToRad(b.lat);

    final h = pow(sin(dLat / 2), 2) +
        cos(lat1) * cos(lat2) * pow(sin(dLng / 2), 2);
    final c = 2 * atan2(sqrt(h), sqrt(1 - h));
    return R * c;
  }

  static double _degToRad(double deg) => deg * pi / 180.0;
}

/// In-memory “push” service that just prints notifications.
class PushService {
  void send(String title, String body) =>
      print('[PUSH] $title — $body (${DateTime.now().toIso8601String()})');
}

/// Returns an endless stream of pseudo-random device locations that
/// meander around the planet.
Stream<LatLng> fakeLocationStream({Duration interval = const Duration(seconds: 2)}) async* {
  final rng = Random();
  var current = LatLng(25.0, 0.0); // Some starting point.

  while (true) {
    // Walk a short distance in a random direction (±0.02 degrees).
    current = LatLng(
      current.lat + (rng.nextDouble() - 0.5) * 0.04,
      current.lng + (rng.nextDouble() - 0.5) * 0.04,
    );
    yield current;
    await Future<void>.delayed(interval);
  }
}

@pragma('vm:entry-point')
Future<void> main() async {
  final push = PushService();

  // Define a few sample geofences.
  final fences = <Geofence>[
    Geofence(
      id: 'office',
      center: const LatLng(25.0, 0.0),
      radiusMeters: 1000,
    ),
    Geofence(
      id: 'home',
      center: const LatLng(25.02, 0.02),
      radiusMeters: 600,
    ),
    Geofence(
      id: 'coffee_shop',
      center: const LatLng(24.98, -0.01),
      radiusMeters: 300,
    ),
  ];

  // Keep track of which geofences the user is already inside
  // to avoid repeat notifications.
  final activeFenceIds = <String>{};

  print('Listening for location updates…\n');

  await for (final location in fakeLocationStream()) {
    print('Current location: $location');

    for (final fence in fences) {
      final inFence = fence.contains(location);

      if (inFence && !activeFenceIds.contains(fence.id)) {
        // Newly entered the geofence.
        activeFenceIds.add(fence.id);
        push.send(
          'Entered ${fence.id}',
          'You have entered the ${fence.id.replaceAll("_", " ")} zone at $location.',
        );
      } else if (!inFence && activeFenceIds.contains(fence.id)) {
        // Exited the geofence.
        activeFenceIds.remove(fence.id);
        push.send(
          'Exited ${fence.id}',
          'You have left the ${fence.id.replaceAll("_", " ")} zone.',
        );
      }
    }
  }
}

import 'dart:io';

/// Console-based user feedback form.
///
/// To run:
///   dart run feedback_form.dart
///
/// The program keeps asking for feedback until the user presses ENTER
/// at the “name” prompt or answers anything other than “y” when asked
/// whether to add another entry.
@pragma('vm:entry-point')
void main() {
  print('===== Welcome to the User Feedback Form =====\n'
      'Press ENTER at the name prompt to exit at any time.\n');

  final feedbacks = <Map<String, dynamic>>[];

  while (true) {
    stdout.write('Your name: ');
    final name = stdin.readLineSync()?.trim() ?? '';
    if (name.isEmpty) break;

    // ── Email ───────────────────────────────────────────────────────────
    String email;
    final emailRegExp = RegExp(r'^[\w\.-]+@[\w\.-]+\.\w+$');
    while (true) {
      stdout.write('Your e-mail: ');
      email = stdin.readLineSync()?.trim() ?? '';
      if (emailRegExp.hasMatch(email)) break;
      print('  → Invalid e-mail format, please try again.');
    }

    // ── Rating ──────────────────────────────────────────────────────────
    int rating;
    while (true) {
      stdout.write('Rate us (1-5): ');
      rating = int.tryParse(stdin.readLineSync()?.trim() ?? '') ?? 0;
      if (rating >= 1 && rating <= 5) break;
      print('  → Rating must be an integer between 1 and 5.');
    }

    // ── Optional Comments ───────────────────────────────────────────────
    stdout.write('Any additional comments? (optional): ');
    final comments = stdin.readLineSync()?.trim() ?? '';

    // Store the entry.
    feedbacks.add(<String, dynamic>{
      'name': name,
      'email': email,
      'rating': rating,
      'comments': comments,
    });

    print('\nThank you, $name, for your feedback!\n');

    // Add another?
    stdout.write('Add another feedback? (y/N): ');
    final again = stdin.readLineSync()?.trim().toLowerCase() ?? '';
    if (again != 'y') break;
    print('');
  }

  // ── Summary ───────────────────────────────────────────────────────────
  if (feedbacks.isEmpty) {
    print('\nNo feedback submitted — goodbye!');
    return;
  }

  final totalRating =
      feedbacks.fold<int>(0, (sum, f) => sum + (f['rating'] as int));
  final avgRating =
      (totalRating / feedbacks.length).toStringAsFixed(2);

  print('\n========== Feedback Summary ==========');
  for (final f in feedbacks) {
    print('\nName     : ${f['name']}'
        '\nE-mail   : ${f['email']}'
        '\nRating   : ${f['rating']} / 5'
        '\nComments : '
        '${(f['comments'] as String).isEmpty ? '– none –' : f['comments']}');
  }
  print('\n--------------------------------------'
      '\nTotal submissions : ${feedbacks.length}'
      '\nAverage rating    : $avgRating / 5'
      '\n======================================');
}

