import 'dart:io';
import 'dart:math';

@pragma('vm:entry-point')
void main() {
  /* ---------------------------------------------------------------
   * Simple console-based “user-activity heat-map” (à la GitHub)
   * ---------------------------------------------------------------
   * • Accepts lines on STDIN in the form     YYYY-MM-DD <count>
   *   (press ENTER on an empty line to finish input).
   * • If no data are supplied it synthesises 12 months of
   *   pseudo-random activity so the demo still shows something.
   * • Prints 53 columns (weeks) × 7 rows (days) of shaded blocks.
   *   Each cell’s shade reflects its activity level relative to
   *   the maximum count seen in the data set.
   * ------------------------------------------------------------- */

  //-----------------------------------------------------------------
  // 1) Gather data  (stdin  →  Map<DateTime,int>)
  //-----------------------------------------------------------------
  final Map<DateTime, int> activity = {};
  stderr.writeln(
      'Enter activity as  "YYYY-MM-DD count"  (empty line = end / demo)');
  while (true) {
    final line = stdin.readLineSync();
    if (line == null || line.trim().isEmpty) break;
    final parts = line.trim().split(RegExp(r'\s+'));
    if (parts.length != 2) {
      stderr.writeln('  ⚠️  Expected 2 columns, ignoring: $line');
      continue;
    }
    final day = DateTime.tryParse(parts[0]);
    final count = int.tryParse(parts[1]!) ?? 0;
    if (day == null) {
      stderr.writeln('  ⚠️  Bad date, ignoring: ${parts[0]}');
      continue;
    }
    // Normalise to date-only precision (time-of-day → midnight).
    activity[DateTime(day.year, day.month, day.day)] = max(0, count);
  }

  //-----------------------------------------------------------------
  // 2) Fallback: fabricate demo data if user gave nothing
  //-----------------------------------------------------------------
  if (activity.isEmpty) {
    stderr.writeln('[No input supplied → generating demo data]\n');
    final rand = Random();
    final today = DateTime.now();
    final startDemo = today.subtract(const Duration(days: 365));
    for (int i = 0; i <= 365; i++) {
      final d = startDemo.add(Duration(days: i));
      activity[DateTime(d.year, d.month, d.day)] = rand.nextInt(10);
    }
  }

  //-----------------------------------------------------------------
  // 3) Build a 53-week × 7-day matrix of counts for the past year
  //-----------------------------------------------------------------
  const weeks = 53;
  const daysPerWeek = 7;

  // Anchor weeks to Sundays so columns line up like GitHub’s calendar.
  final today = DateTime.now();
  final midnight = DateTime(today.year, today.month, today.day);
  final daysSinceSunday = midnight.weekday % 7; // Sunday => 0
  final lastSunday = midnight.subtract(Duration(days: daysSinceSunday));
  final heatmapStart =
      lastSunday.subtract(Duration(days: (weeks - 1) * daysPerWeek));

  // grid[row(day:0-6)][col(week:0-52)]  →  activity count
  final grid =
      List.generate(daysPerWeek, (_) => List.filled(weeks, 0, growable: false));

  int maxCount = 0;
  for (int w = 0; w < weeks; w++) {
    for (int d = 0; d < daysPerWeek; d++) {
      final date = heatmapStart.add(Duration(days: w * 7 + d));
      final key = DateTime(date.year, date.month, date.day);
      final count = activity[key] ?? 0;
      grid[d][w] = count;
      if (count > maxCount) maxCount = count;
    }
  }
  if (maxCount == 0) maxCount = 1; // avoid divide-by-zero later

  //-----------------------------------------------------------------
  // 4) Define the “shades” used to visualise activity intensity
  //-----------------------------------------------------------------
  final shades = [
    '  ', // 0   (no activity)
    '░░', // 1
    '▒▒', // 2
    '▓▓', // 3
    '██' // 4   (max activity)
  ];

  String shadeFor(int count) {
    if (count == 0) return shades.first;
    // Normalise [1 .. maxCount] → [1 .. shades.length-1]
    final idx =
        (count / maxCount * (shades.length - 1)).clamp(1, shades.length - 1);
    return shades[idx.round()];
  }

  //-----------------------------------------------------------------
  // 5) Emit the heat-map
  //-----------------------------------------------------------------
  const dayLabels = ['S', 'M', 'T', 'W', 'T', 'F', 'S'];

  // Column headings: months (approx.) every few weeks for context
  final buffer = StringBuffer('    '); // padding for row labels
