    if (line == null || line.trim().isEmpty) break;
    final parts = line.trim().split(RegExp(r'\s+'));
    if (parts.length != 2) {
      stderr.writeln('  ⚠️  Expected 2 columns, ignoring: $line');
      continue;
    }
    final day = DateTime.tryParse(parts[0]);
    final count = int.tryParse(parts[1]) ?? 0;
    if (day == null) {
      stderr.writeln('  ⚠️  Bad date, ignoring: ${parts[0]}');
      continue;
    }
    // Normalize to date-only precision
    activity[DateTime(day.year, day.month, day.day)] = max(0, count);
  }

  // 2) Fallback: generate demo data if no input provided
  if (activity.isEmpty) {
    stderr.writeln('[No input supplied → generating demo data]\n');
    final rand = Random();
    final today = DateTime.now();
    final startDemo = today.subtract(const Duration(days: 365));
    for (int i = 0; i <= 365; i++) {
      final d = startDemo.add(Duration(days: i));
      activity[DateTime(d.year, d.month, d.day)] = rand.nextInt(10);
    }
  }

