  final daysSinceSunday = midnight.weekday % 7; // Sunday is 0
  final lastSunday = midnight.subtract(Duration(days: daysSinceSunday));
  final heatmapStart = lastSunday.subtract(const Duration(days: (53 - 1) * 7));

  final grid = List.generate(daysPerWeek, (_) => List.filled(weeks, 0, growable: false));
  int maxCount = 0;

  for (int w = 0; w < weeks; w++) {
