// in_app_survey.dart
//
// A minimal in-app survey system that runs in the console.  
// The whole program’s behaviour lives inside `main`, as requested.
//
// • Presents a short survey.
// • Persists every submission to `survey_responses.json`.
// • Prints an aggregated summary after each run.
//
// Run with:  dart run in_app_survey.dart

import 'dart:convert';
import 'dart:io';

@pragma('vm:entry-point')
Future<void> main(List<String> args) async {
  // ----------------------- 1. Survey definition -----------------------
  final List<Map<String, dynamic>> questions = [
    {
      'id': 'satisfaction',
      'prompt': 'How satisfied are you with the app? (1 = worst, 5 = best)',
      'type': 'scale',
      'min': 1,
      'max': 5
    },
    {
      'id': 'favourite_feature',
      'prompt': 'What is your favourite feature?',
      'type': 'choice',
      'options': ['Speed', 'UI', 'Offline mode', 'Stability', 'Other']
    },
    {
      'id': 'feedback',
      'prompt': 'Any additional feedback? (press enter to skip)',
      'type': 'text'
    },
  ];

  // ----------------------- 2. Greeting -----------------------
  stdout.writeln('=== Welcome to the In-App Survey ===');
  stdout.write('Would you like to take a quick survey? (y/n): ');
  final decision = stdin.readLineSync()?.trim().toLowerCase();
  if (decision != 'y') {
    stdout.writeln('No problem – maybe next time!');
    return;
  }

  // ----------------------- 3. Collect answers -----------------------
  final Map<String, dynamic> response = {};
  for (final q in questions) {
    final id = q['id'] as String;
    final prompt = q['prompt'] as String;

    switch (q['type']) {
      case 'scale':
        final min = q['min'] as int;
        final max = q['max'] as int;
        int? value;
        while (value == null) {
          stdout.write('$prompt ($min-$max): ');
          final input = int.tryParse(stdin.readLineSync()!.trim());
          if (input != null && input >= min && input <= max) {
            value = input;
          } else {
            stdout.writeln('Please enter a number between $min and $max.');
          }
        }
        response[id] = value;
        break;

      case 'choice':
        final options = List<String>.from(q['options'] as List);
        for (var i = 0; i < options.length; i++) {
          stdout.writeln('  ${i + 1}. ${options[i]}');
        }
        int? idx;
        while (idx == null) {
          stdout.write('$prompt (1-${options.length}): ');
          final input = int.tryParse(stdin.readLineSync()!.trim());
          if (input != null && input >= 1 && input <= options.length) {
            idx = input - 1;
          } else {
            stdout.writeln('Select a number between 1 and ${options.length}.');
          }
        }
        response[id] = options[idx];
        break;

      case 'text':
        stdout.write('$prompt\n> ');
        response[id] = stdin.readLineSync();
        break;

      default:
        stderr.writeln('Unknown question type "${q['type']}". Skipping.');
    }
  }

  // ----------------------- 4. Persist to disk -----------------------
  const filePath = 'survey_responses.json';
  final file = File(filePath);

  List<dynamic> allResponses = [];
  if (await file.exists()) {
    final raw = await file.readAsString();
    if (raw.trim().isNotEmpty) {
      allResponses = jsonDecode(raw) as List<dynamic>;
    }
  }
  allResponses.add(response);
  await file.writeAsString(const JsonEncoder.withIndent('  ').convert(allResponses));

  stdout.writeln('\nThanks! Your responses have been recorded.');

  // ----------------------- 5. Aggregated summary -----------------------
  final Map<String, Map<dynamic, int>> summary = {};
  for (final r in allResponses.cast<Map<String, dynamic>>()) {
    r.forEach((key, value) {
      if (value is String || value is int) {
        summary.putIfAbsent(key, () => <dynamic, int>{});
        summary[key]!.update(value, (c) => c + 1, ifAbsent: () => 1);
      }
    });
  }

  stdout.writeln('\n=== Survey Summary (${allResponses.length} submissions) ===');
  summary.forEach((questionId, counts) {
    stdout.writeln('- $questionId');
    counts.forEach((answer, count) => stdout.writeln('    $answer : $count'));
  });
}

