    'admin':  {'create', 'read', 'update', 'delete'},
    'editor': {'read', 'update'},
    'viewer': {'read'},
  };

  // 2. User directory: username → role.
  final Map<String, String> userRoles = {
    'alice':   'admin',
    'bob':     'editor',
    'charlie': 'viewer',
  };

