    ..writeln('=== Simple RBAC Demo ===')
    ..writeln('Known users: ${userRoles.keys.join(", ")}')
    ..write('Username: ');
  final user = stdin.readLineSync()?.trim().toLowerCase() ?? '';

  if (!userRoles.containsKey(user)) {
    stdout.writeln('Unknown user "$user". Exiting.');
    return;
  }

  final role     = userRoles[user]!;
  final allowed  = rolePermissions[role] ?? const <String>{};

  stdout
    ..writeln('\nHello, $user! Your role is "$role".')
    ..writeln('Permitted actions: ${allowed.join(", ")}')
    ..writeln('Available actions: create, read, update, delete')
    ..write('Enter action to perform: ');
  final action = stdin.readLineSync()?.trim().toLowerCase() ?? '';

  stdout.writeln(
    allowed.contains(action)
      ? 'ACCESS GRANTED: "$role" may "$action".'
      : 'ACCESS DENIED: "$role" cannot "$action".'
  );
}

