  // Convenience helpers declared inside main so that all logic lives here.
  void line([String text = '']) => stdout.writeln(text);

  String ask(String prompt, {String? defaultValue}) {
    stdout.write(prompt);
    final input = stdin.readLineSync();
    if (input == null || input.trim().isEmpty) {
      return defaultValue ?? '';
    }
    return input.trim();
  }

  line('=== Welcome to the Dynamic Onboarding CLI ===\n');

  // STEP 1: Ask for the user’s role.
  final role = ask(
    'Please enter your role (developer / designer / manager / other): ',
  ).toLowerCase();

  // This map will accumulate all collected answers.
  final answers = <String, String>{'role': role};

  // STEP 2-N: Branch the flow based on the chosen role.
  switch (role) {
    case 'developer':
      answers['language'] = ask(
        'What is your primary language? (Dart / JavaScript / Python / Other): ',
      );
      answers['experience'] = ask(
        'How many years of experience do you have? (0-1 / 2-3 / 4+): ',
      );
      break;

    case 'designer':
      answers['specialization'] = ask(
        'What is your specialization? (UI/UX / Graphic / Motion): ',
      );
      answers['tool'] = ask(
        'Which design tool do you prefer? (Figma / Sketch / Adobe XD): ',
      );
      break;

    case 'manager':
      answers['teamSize'] = ask(
        'What is your team size? (1-5 / 6-15 / 16+): ',
      );
      answers['metrics'] = ask(
        'Are you interested in metrics dashboards? (yes / no): ',
      );
      break;

    default:
      answers['background'] = ask(
        'Tell us a bit about your background: ',
      );
  }

  // STEP FINAL: Display a summary of all collected information.
  line('\n--- Onboarding Summary ---');
