    {'id': 2, 'name': 'Bob', 'email': 'bob@example.com', 'age': 25},
    {
      'id': 3,
      'name': 'Charlie, Jr.',
      'email': 'charlie@example.com',
      'age': 35
    },
    {
      'id': 4,
      'name': 'Dana',
      'email': 'dana@example.com',
      'age': 'She said "Hi!"'
    },
  ];

  // 3. Simple CSV escaping (wrap in quotes if value contains comma, quote, or newline)
  String _escape(dynamic value) {
    if (value == null) return '';
    var text = value.toString();
    final bool mustQuote = text.contains(RegExp(r'[,"\n]'));
    text = text.replaceAll('"', '""');
    return mustQuote ? '"$text"' : text;
  }

  // 4. Build CSV
  final buffer = StringBuffer();
  if (data.isEmpty) {
    stderr.writeln('No data to export.');
    exitCode = 1;
    return;
  }

  // Header row
  final List<String> headers = data.first.keys.toList();
  buffer.writeln(headers.map(_escape).join(','));

  // Data rows
  for (final row in data) {
    buffer.writeln(headers.map((h) => _escape(row[h])).join(','));
  }

  // 5. Write to file (create directories if needed)
  final file = File(outputPath);
  await file.create(recursive: true);
  await file.writeAsString(buffer.toString());

  stdout.writeln('Export complete → ${file.path}');
}

