import 'dart:io';

@pragma('vm:entry-point')
void main(List<String> args) {
  // Sample mixed-type list to demonstrate dynamic filtering.
  final items = <dynamic>[1, 2, 3, 4, 5, 'apple', 'banana', 'apricot', 'berry', 42];

  // Show help if no arguments were provided.
  if (args.isEmpty) {
    print('Usage: dart run <script.dart> <filter> [value]\n'
        'Filters:\n'
        '  even                 -> integers that are even\n'
        '  odd                  -> integers that are odd\n'
        '  greater <number>     -> integers greater than <number>\n'
        '  contains <pattern>   -> strings containing <pattern>\n'
        '  starts <pattern>     -> strings starting with <pattern>\n');
    exit(0);
  }

  final command = args[0].toLowerCase();
  Iterable<dynamic> result;

  switch (command) {
    case 'even':
      result = items.where((e) => e is int && e.isEven);
      break;

    case 'odd':
      result = items.where((e) => e is int && e.isOdd);
      break;

    case 'greater':
      if (args.length < 2) {
        stderr.writeln('Error: Missing number for "greater" filter.');
        exit(1);
      }
      final threshold = int.tryParse(args[1]);
      if (threshold == null) {
        stderr.writeln('Error: "${args[1]}" is not a valid integer.');
        exit(1);
      }
      result = items.where((e) => e is int && e > threshold);
      break;

    case 'contains':
      if (args.length < 2) {
        stderr.writeln('Error: Missing pattern for "contains" filter.');
        exit(1);
      }
      final pattern = args[1].toLowerCase();
      result = items.where((e) => e is String && e.toLowerCase().contains(pattern));
      break;

    case 'starts':
      if (args.length < 2) {
        stderr.writeln('Error: Missing pattern for "starts" filter.');
        exit(1);
      }
      final pattern = args[1].toLowerCase();
      result = items.where((e) => e is String && e.toLowerCase().startsWith(pattern));
      break;

    default:
      stderr.writeln('Error: Unknown filter "$command".');
      exit(1);
  }

  print('Original list : $items');
  print('Filtered list : ${result.toList()}');
}

