import 'dart:io';

@pragma('vm:entry-point')                // Prevents the VM from removing `main`.
void main() {
  // In–memory search history.
  final List<String> history = [];

  // Help text shown to the user.
  const String help = '''
In-App Search History Demo
──────────────────────────
Type anything to “search” for it; the query will be saved in history.

Special commands:
  /history          Show the saved search history
  /search <text>    Filter history for items containing <text>
  /clear            Erase the history
  /help             Show this help
  /quit             Exit the program
''';

  // Greet user.
  print(help);

  while (true) {
    stdout.write('> ');
    final String input = stdin.readLineSync() ?? '';
    final String query = input.trim();
    if (query.isEmpty) continue;

    // Quit.
    if (query == '/quit') {
      print('Good-bye!');
      break;
    }

    // Help.
    if (query == '/help') {
      print(help);
      continue;
    }

    // Show full history.
    if (query == '/history') {
      if (history.isEmpty) {
        print('History is empty.');
      } else {
        for (var i = 0; i < history.length; i++) {
          print('${i + 1}. ${history[i]}');
        }
      }
      continue;
    }

    // Filter history.
    if (query.startsWith('/search ')) {
      final String term = query.substring(8).trim();
      if (term.isEmpty) {
        print('Please supply text to search.');
        continue;
      }
      final List<String> matches =
          history.where((h) => h.toLowerCase().contains(term.toLowerCase())).toList();
      if (matches.isEmpty) {
        print('No matches found for "$term".');
      } else {
        print('Matches:');
        for (var i = 0; i < matches.length; i++) {
          print('${i + 1}. ${matches[i]}');
        }
      }
      continue;
    }

    // Clear history.
    if (query == '/clear') {
      history.clear();
      print('History cleared.');
      continue;
    }

    // Treat anything else as a normal search query.
    // Remove previous occurrence to avoid duplicates, then add to front.
    history.remove(query);
    history.insert(0, query);

    // Optionally cap history length.
    const int maxHistory = 50;
    if (history.length > maxHistory) {
      history.removeRange(maxHistory, history.length);
    }

    print('Searching for "$query"... (logic not implemented)');
  }
}

