// dynamic_font_scaling.dart
// A self-contained Dart script demonstrating dynamic font scaling.
// Run with: dart run dynamic_font_scaling.dart [screenWidth]
//
// If a screen width (in logical pixels) is supplied on the command line,
// the script scales a set of design-time font sizes to match that width.
// Otherwise it falls back to a default test width.

import 'dart:io';
import 'dart:math';

@pragma('vm:entry-point')
void main(List<String> args) {
  // 1. Configuration ----------------------------------------------------------------
  const double designWidth = 375.0;                 // Reference device width.
  const List<double> designFontSizes = [            // Font sizes used by designers.
    12, 14, 16, 18, 20, 24, 28, 32
  ];

  // 2. Read input -------------------------------------------------------------------
  // Accept a screen width from the command line, e.g. `dart run script.dart 411`.
  final double actualWidth =
      args.isNotEmpty ? double.tryParse(args.first) ?? 411.0 : 411.0;

  // 3. Calculate scale factor --------------------------------------------------------
  double scaleFactor = actualWidth / designWidth;

  // Optional: Clamp the factor so text never becomes too small or too large.
  scaleFactor = scaleFactor.clamp(0.85, 1.30);

  // 4. Output results ---------------------------------------------------------------
  stdout.writeln('Dynamic Font Scaling');
  stdout.writeln('--------------------');
  stdout.writeln('Design reference width : $designWidth px');
  stdout.writeln('Actual device width    : $actualWidth px');
  stdout.writeln('Resolved scale factor  : ${scaleFactor.toStringAsFixed(2)}\n');

  for (final baseSize in designFontSizes) {
    // Round to the nearest 0.5 for nicer typography.
    final double scaledSize = (baseSize * scaleFactor * 2).round() / 2;
    stdout.writeln(
        'Design ${baseSize.toStringAsFixed(1)} → Scaled ${scaledSize.toStringAsFixed(1)}');
  }
}

