  // 2. Read input: accept a screen width from command line, default to 411.0 if not provided or invalid
  final double actualWidth = args.isNotEmpty ? double.tryParse(args.first) ?? 411.0 : 411.0;

  // 3. Calculate scale factor and clamp it to avoid extreme values
  double scaleFactor = actualWidth / designWidth;
  scaleFactor = scaleFactor.clamp(0.85, 1.30); // Clamp between 0.85 and 1.30

  // 4. Output results
  stdout.writeln('Dynamic Font Scaling');
  stdout.writeln('--------------------');
  stdout.writeln('Design reference width : $designWidth px');
  stdout.writeln('Actual device width    : $actualWidth px');
  stdout.writeln('Resolved scale factor  : ${scaleFactor.toStringAsFixed(2)}\n');

  // Loop through each design font size, scale it, and print the result
  for (final baseSize in designFontSizes) {
    // Round to the nearest 0.5 for better typography
    final double scaledSize = (baseSize * scaleFactor * 2).round() / 2;
    stdout.writeln('Design ${baseSize.toStringAsFixed(1)} → Scaled ${scaledSize.toStringAsFixed(1)}');
  }
}
