import 'dart:io';

/// A very small, self-contained “offline media player” written in pure Dart.
///
/// How it works:
///   • You pass the path to a local video/audio file as the first CLI argument.
///   • The script checks that the file exists.
///   • Depending on the operating system it starts the platform’s default
///     media player in a detached process (no network connection required).
///
/// Supported platforms:
///   • macOS   – uses `afplay` for audio or QuickTime via `open` for video.
///   • Windows – launches the file with the default associated player via
///               `start`.
///   • Linux   – launches the file with the default associated player via
///               `xdg-open`.
///
/// Example:
///   dart offline_player.dart ./movies/big_buck_bunny.mp4
@pragma('vm:entry-point')
void main(List<String> args) async {
  // ---- 1. Validate CLI input -------------------------------------------------
  if (args.isEmpty) {
    stdout
      ..writeln('Offline Media Player')
      ..writeln('Usage: dart offline_player.dart <path_to_media_file>')
      ..writeln();
    exit(0);
  }

  final filePath = args.first;
  final file = File(filePath);

  if (!await file.exists()) {
    stderr.writeln('Error: File not found – "$filePath"');
    exit(1);
  }

  // ---- 2. Decide which platform command to use ------------------------------
  late final Process process;

  try {
    if (Platform.isMacOS) {
      // Simple heuristic: If the file looks like audio, prefer afplay because
      // it has no UI; otherwise open QuickTime Player.
      final isAudio = const [
        '.mp3',
        '.wav',
        '.m4a',
        '.aac',
        '.flac',
        '.ogg'
      ].any((ext) => filePath.toLowerCase().endsWith(ext));

      process = await Process.start(
        isAudio ? 'afplay' : 'open',
        isAudio ? [filePath] : ['-a', 'QuickTime Player', filePath],
      );
    } else if (Platform.isWindows) {
      // “start” opens with the default handler; the empty string isolates the
      // file name from cmd’s optional window title parameter.
      process = await Process.start('cmd', ['/c', 'start', '', filePath]);
    } else if (Platform.isLinux) {
      process = await Process.start('xdg-open', [filePath]);
    } else {
      stderr.writeln('Error: Unsupported operating system.');
      exit(2);
    }
  } on ProcessException catch (e) {
    stderr.writeln('Failed to launch player: $e');
    exit(3);
  }

  // ---- 3. Mirror child process output & wait for it to finish ---------------
  stdout.writeln('Playing "$filePath" … (press Ctrl+C to quit)');
  unawaited(stdout.addStream(process.stdout));
  unawaited(stderr.addStream(process.stderr));

  final exitCode = await process.exitCode;
  stdout.writeln('Player exited with code $exitCode');
}

// Helper to avoid `await`ing when the result is intentionally ignored.
void unawaited(Future<void> _) {}

