void main() {
  // ----------------------------- Simulation ---------------------------------
  // The dashboard works with any event list shaped like the one below.
  // For demo purposes we generate one week of random data.
  final random = Random();
  final now   = DateTime.now();
  final List<Map<String, dynamic>> events = [];

  const daysToSimulate = 7;
  for (int d = 0; d < daysToSimulate; d++) {
    final day = DateTime(now.year, now.month, now.day - d);

    // Random number of users that opened the app that day.
    final int usersToday = 50 + random.nextInt(150);

