      events.add(<String, dynamic>{
        'userId'      : 'user_${random.nextInt(500)}',
        'day'         : day,
        'sessionSecs' : 30 + random.nextInt(600),
      });
    }
  }

  // -------------------------- Metric Aggregation ----------------------------
  // 1. Daily Active Users (DAU)
  final Map<String, Set<String>> dailyUsers = {};
  // 2. Session counters
  int totalSessions    = events.length;
  int totalSessionSecs = 0;

  for (final e in events) {
    final DateTime day = e['day'] as DateTime;
