        h = 60 * (((b - r) / delta) + 2);
      } else {
        h = 60 * (((r - g) / delta) + 4);
      }
    }
    return [h, s, l];
  }

  List<int> hslToRgb(List<double> hsl) {
    double h = hsl[0], s = hsl[1], l = hsl[2];
    final c = (1 - (2 * l - 1).abs()) * s;
    final x = c * (1 - ((h / 60) % 2 - 1).abs());
    final m = l - c / 2;

    double r1 = 0, g1 = 0, b1 = 0;
    if (h < 60) {
      r1 = c;
      g1 = x;
      b1 = 0;
    } else if (h < 120) {
      r1 = x;
      g1 = c;
      b1 = 0;
    } else if (h < 180) {
      r1 = 0;
      g1 = c;
      b1 = x;
    } else if (h < 240) {
      r1 = 0;
      g1 = x;
      b1 = c;
    } else if (h < 300) {
      r1 = x;
      g1 = 0;
      b1 = c;
    } else {
      r1 = c;
      g1 = 0;
      b1 = x;
    }

    return [
      ((r1 + m) * 255).round(),
      ((g1 + m) * 255).round(),
      ((b1 + m) * 255).round(),
    ];
  }

  String rgbToHex(List<int> rgb) =>
      rgb.map((v) => v.toRadixString(16).padLeft(2, '0').toUpperCase()).join();

  // 3. Generate dynamic variants
  List<double> seedHsl = rgbToHsl(seedRgb);

  List<int> complementary =
      hslToRgb([(seedHsl[0] + 180) % 360, seedHsl[1], seedHsl[2]]);

  List<int> analogous1 =
      hslToRgb([_wrap(seedHsl[0] + 30), seedHsl[1], seedHsl[2]]);
  List<int> analogous2 =
      hslToRgb([_wrap(seedHsl[0] - 30), seedHsl[1], seedHsl[2]]);

  List<int> triadic1 =
      hslToRgb([_wrap(seedHsl[0] + 120), seedHsl[1], seedHsl[2]]);
  List<int> triadic2 =
      hslToRgb([_wrap(seedHsl[0] + 240), seedHsl[1], seedHsl[2]]);

  List<int> lighter =
      hslToRgb([seedHsl[0], seedHsl[1], _clamp(seedHsl[2] + 0.2)]);
  List<int> darker =
      hslToRgb([seedHsl[0], seedHsl[1], _clamp(seedHsl[2] - 0.2)]);

  // 4. Display the color scheme
  void show(String name, List<int> rgb) =>
      print('${name.padRight(14)}: #${rgbToHex(rgb)}');

  print('\nDynamic Color Scheme for #${rgbToHex(seedRgb)}');
  show('Seed', seedRgb);
  show('Complementary', complementary);
  show('Analogous 1', analogous1);
  show('Analogous 2', analogous2);
  show('Triadic 1', triadic1);
  show('Triadic 2', triadic2);
  show('Lighter', lighter);
  show('Darker', darker);
}
