  var node4 = createNode(4, [node7]);
  var root = createNode(1, [node2, node3, node4]);

  // Breadth-First Search implementation
  List<int> breadthFirstSearch(Map<String, dynamic> root) {
    if (root.isEmpty) return [];

    List<int> result = [];
    List<Map<String, dynamic>> queue = [root];

    while (queue.isNotEmpty) {
      // Dequeue the first node
      Map<String, dynamic> currentNode = queue.removeAt(0);

      // Process the current node (add its value to result)
      result.add(currentNode['value'] as int);

      // Enqueue all children of the current node
      List<Map<String, dynamic>> children = currentNode['children'] as List<Map<String, dynamic>>;
      for (var child in children) {
        queue.add(child);
      }
    }

    return result;
  }

