      Map<String, dynamic> currentNode = queue.removeAt(0);

      if (currentNode['value'] == target) {
        return true;
      }

      List<Map<String, dynamic>> children = currentNode['children'] as List<Map<String, dynamic>>;
      for (var child in children) {
        queue.add(child);
      }
    }

    return false;
  }

