void main() {
  // Item weights and values
  List<int> weights = [2, 1, 3, 2, 4, 5];
  List<int> values = [12, 10, 20, 15, 25, 30];

  // Knapsack capacity
  int capacity = 10;
  int n = weights.length;

  // Initialize DP table with dimensions (n+1) x (capacity+1), filled with zeros
  List<List<int>> dp = List.generate(
    n + 1,
    (_) => List.filled(capacity + 1, 0),
  );

  // Fill the DP table using dynamic programming
  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {
      if (weights[i - 1] > w) {
        // Current item's weight exceeds capacity, so exclude it
        dp[i][w] = dp[i - 1][w];
      } else {
        // Consider including or excluding the current item
        int includeItem = values[i - 1] + dp[i - 1][w - weights[i - 1]];
        int excludeItem = dp[i - 1][w];
        dp[i][w] = includeItem > excludeItem ? includeItem : excludeItem;
      }
    }
  }

  // Backtrack to find the selected items
  List<int> selectedItems = [];
  int currentWeight = capacity;
  for (int i = n; i > 0 && currentWeight > 0; i--) {
    if (dp[i][currentWeight] != dp[i - 1][currentWeight]) {
      // Item i-1 was included
      selectedItems.add(i - 1);
      currentWeight -= weights[i - 1];
    }
  }

  // Print the solution details
  print('Knapsack Problem Solution:');
  print('==========================');

  print('Items available:');
  for (int i = 0; i < n; i++) {
    print('  Item ${i + 1}: weight = ${weights[i]}, value = ${values[i]}');
  }

  print('\nKnapsack capacity: $capacity');
  print('\nMaximum value achievable: ${dp[n][capacity]}');

  print('\nSelected items:');
  int totalWeight = 0;
  int totalValue = 0;
  // Print selected items in reverse order for better readability (from first to last)
  for (int index in selectedItems.reversed) {
    print('  Item ${index + 1}: weight = ${weights[index]}, value = ${values[index]}');
    totalWeight += weights[index];
    totalValue += values[index];
  }

  print('\nTotal weight used: $totalWeight / $capacity');
  print('Total value obtained: $totalValue');

  // Optional: Print the DP table for visualization
  print('\nDP Table:');
  // Header row with column indices (weights)
  String header = '    ' + List.generate(capacity + 1, (j) => j.toString().padLeft(3)).join(' ');
  print(header);

  // Each row shows the DP values for a given number of items
  for (int i = 0; i <= n; i++) {
    String row = i.toString().padLeft(2) + ': ';
    for (int j = 0; j <= capacity; j++) {
      row += dp[i][j].toString().padLeft(3) + ' ';
    }
    print(row);
  }
}
