    [0, 2, 4],
    [1, 2, 3],
    [1, 3, 2],
    [1, 4, 2],
    [3, 2, 5],
    [3, 1, 1],
    [4, 3, -3],
  ];

  final numVertices = 5;
  final source = 0;

  // Initialize distances
  final distances = List<int>.filled(numVertices, 999999999);
  distances[source] = 0;

  // Parent array to track shortest path
  final parent = List<int>.filled(numVertices, -1);

  // Relax edges V-1 times
  for (int i = 0; i < numVertices - 1; i++) {
    for (final edge in edges) {
      int u = edge[0];
      int v = edge[1];
      int weight = edge[2];

      if (distances[u] != 999999999 && 
          distances[u] + weight < distances[v]) {
        distances[v] = distances[u] + weight;
        parent[v] = u;
      }
    }
  }

  // Check for negative weight cycles
  bool hasNegativeCycle = false;
  for (final edge in edges) {
    int u = edge[0];
    int v = edge[1];
    int weight = edge[2];

    if (distances[u] != 999999999 && 
        distances[u] + weight < distances[v]) {
      hasNegativeCycle = true;
      break;
    }
  }

  // Print results
  print('Bellman-Ford Shortest Path Algorithm');
  print('=====================================');

  if (hasNegativeCycle) {
    print('Graph contains negative weight cycle!');
  } else {
    print('Shortest distances from vertex $source:');
