void main() {
  // Rod cutting problem: Given a rod of length n and prices for different lengths,
  // find the maximum revenue obtainable by cutting the rod and selling the pieces

  // Example: prices[i] represents the price of a rod of length i+1
  // prices[0] = price of length 1, prices[1] = price of length 2, etc.
  List<int> prices = [1, 5, 8, 9, 10, 17, 17, 20, 24, 30];
  int rodLength = 8; // Length of rod to cut

  // Dynamic Programming approach - Bottom-up
  // dp[i] will store the maximum revenue for rod of length i
  List<int> dp = List.filled(rodLength + 1, 0);

  // Build the dp table bottom-up
  for (int i = 1; i <= rodLength; i++) {
    int maxRevenue = 0;

    // Try all possible first cuts
    for (int j = 1; j <= i; j++) {
      // Check if we have a price for length j
      if (j <= prices.length) {
        // Revenue = price of cut piece + optimal revenue from remaining rod
        int currentRevenue = prices[j - 1] + dp[i - j];
        if (currentRevenue > maxRevenue) {
          maxRevenue = currentRevenue;
        }
      }
    }

    dp[i] = maxRevenue;
  }

  // Reconstruct the solution to find which cuts were made
  List<int> cuts = [];
  int remainingLength = rodLength;

  while (remainingLength > 0) {
    for (int j = 1; j <= remainingLength && j <= prices.length; j++) {
      if (dp[remainingLength] == prices[j - 1] + dp[remainingLength - j]) {
        cuts.add(j);
        remainingLength -= j;
        break;
      }
    }
  }

  // Print results
  print('Rod Cutting Problem Solution');
  print('============================');
  print('Rod length: $rodLength');
  print('Prices for lengths 1 to ${prices.length}:');
  for (int i = 0; i < prices.length && i < rodLength; i++) {
    print('  Length ${i + 1}: \$${prices[i]}');
