  print('\nDP Table (Maximum revenue for each length):');
  for (int i = 0; i <= rodLength; i++) {
    print('  Length $i: \$${dp[i]}');
  }
  print('\nMaximum revenue: \$${dp[rodLength]}');
  print('Optimal cuts: ${cuts.join(', ')} (lengths)');
  print('Total length check: ${cuts.reduce((a, b) => a + b)} = $rodLength');

  // Alternative test case
  print('\n--- Alternative Test Case ---');
  List<int> prices2 = [3, 5, 8, 9, 10, 17, 17, 20];
