void main() {
  // Graph represented as adjacency list
  // Example graph with 5 vertices (0-4)
  final Map<int, List<int>> graph = {
    0: [1, 2, 3],
    1: [0, 2],
    2: [0, 1, 3],
    3: [0, 2, 4],
    4: [3]
  };

  final int numVertices = graph.length;
  final int maxColors = 3; // Maximum number of colors to try

  // Array to store color assignment for each vertex (-1 means no color)
  final List<int> colors = List.filled(numVertices, -1);

  // Function to check if a color is safe for a vertex
  bool isSafeColor(int vertex, int color, Map<int, List<int>> graph, List<int> colors) {
    for (int neighbor in graph[vertex]!) {
      if (colors[neighbor] == color) {
        return false;
      }
    }
    return true;
  }

  // Recursive function to solve graph coloring using backtracking
  bool graphColoringUtil(int vertex, Map<int, List<int>> graph, List<int> colors, int maxColors) {
    // Base case: all vertices are colored
    if (vertex == graph.length) {
      return true;
    }

    // Try different colors for current vertex
    for (int color = 0; color < maxColors; color++) {
      if (isSafeColor(vertex, color, graph, colors)) {
        colors[vertex] = color;

        // Recur for next vertex
        if (graphColoringUtil(vertex + 1, graph, colors, maxColors)) {
          return true;
        }

        // Backtrack if solution not found
        colors[vertex] = -1;
      }
    }

    return false;
  }

  // Function to solve graph coloring problem
  bool solveGraphColoring(Map<int, List<int>> graph, int maxColors, List<int> colors) {
    return graphColoringUtil(0, graph, colors, maxColors);
  }

  // Print the graph structure
  print('Graph Structure:');
  graph.forEach((vertex, neighbors) {
    print('Vertex $vertex -> Neighbors: $neighbors');
  });
  print('');

  // Try to color the graph with different number of colors
  for (int numColors = 1; numColors <= maxColors; numColors++) {
    // Reset colors
    for (int i = 0; i < numVertices; i++) {
      colors[i] = -1;
    }

    print('Attempting to color graph with $numColors color(s)...');

    if (solveGraphColoring(graph, numColors, colors)) {
      print('Success! Graph can be colored with $numColors color(s)');
      print('Color assignment:');
      for (int i = 0; i < numVertices; i++) {
        String colorName;
