          case 0:
            colorName = 'Red';
            break;
          case 1:
            colorName = 'Blue';
            break;
          case 2:
            colorName = 'Green';
            break;
          default:
            colorName = 'Color${colors[i]}';
        }
        print('  Vertex $i -> $colorName');
      }
      print('');

      // Verify the coloring is valid
      bool isValid = true;
      for (int vertex in graph.keys) {
        for (int neighbor in graph[vertex]!) {
          if (colors[vertex] == colors[neighbor]) {
            isValid = false;
            print('ERROR: Vertex $vertex and $neighbor have the same color!');
          }
        }
      }

      if (isValid) {
        print('Coloring verification: VALID ✓');
      } else {
        print('Coloring verification: INVALID ✗');
      }

      print('\nMinimum colors needed: $numColors');
      break;
    } else {
      print('Cannot color graph with $numColors color(s)');
      print('');
    }
  }

