  // Test strings
  String text = "ABABDABACDABABCABAB";
  String pattern = "ABABCABAB";

  // Build the LPS (Longest Proper Prefix which is also Suffix) array
  List<int> computeLPS(String pattern) {
    int m = pattern.length;
    List<int> lps = List.filled(m, 0);
    int len = 0;
    int i = 1;

    while (i < m) {
      if (pattern[i] == pattern[len]) {
        len++;
        lps[i] = len;
        i++;
      } else {
        if (len != 0) {
          len = lps[len - 1];
        } else {
          lps[i] = 0;
          i++;
        }
      }
    }
    return lps;
  }

  // KMP search function
  List<int> kmpSearch(String text, String pattern) {
    List<int> matches = [];
    int n = text.length;
    int m = pattern.length;

    if (m == 0) return matches;

    List<int> lps = computeLPS(pattern);

    int i = 0; // index for text
    int j = 0; // index for pattern

    while (i < n) {
      if (text[i] == pattern[j]) {
        i++;
        j++;
      }

      if (j == m) {
        matches.add(i - j);
        j = lps[j - 1];
      } else if (i < n && text[i] != pattern[j]) {
        if (j != 0) {
          j = lps[j - 1];
        } else {
          i++;
        }
      }
    }

    return matches;
  }

  // Test the KMP algorithm
  print("Text: $text");
  print("Pattern: $pattern");
  print("Pattern length: ${pattern.length}");

  // Compute and display LPS array
  List<int> lps = computeLPS(pattern);
  print("\nLPS array for pattern:");
  for (int i = 0; i < pattern.length; i++) {
    print("  ${pattern[i]}: ${lps[i]}");
  }

  // Find all matches
