void main() {
  // Test cases
  String text1 = "HERE IS A SIMPLE EXAMPLE";
  String pattern1 = "EXAMPLE";

  String text2 = "AABAACAADAABAABA";
  String pattern2 = "AABA";

  String text3 = "THIS IS A TEST TEXT FOR TESTING";
  String pattern3 = "TEST";

  // Boyer-Moore implementation
  List<int> boyerMooreSearch(String text, String pattern) {
    List<int> matches = [];

    if (pattern.isEmpty || text.isEmpty || pattern.length > text.length) {
      return matches;
    }

    // Build bad character table
    Map<String, int> badCharTable = {};
    for (int i = 0; i < pattern.length; i++) {
      badCharTable[pattern[i]] = i;
    }

    // Build good suffix table
    List<int> goodSuffixTable = List.filled(pattern.length, 0);
    List<int> borderPos = List.filled(pattern.length + 1, 0);

    // Preprocessing for good suffix rule
    void preprocessGoodSuffix() {
      int i = pattern.length;
      int j = pattern.length + 1;
      borderPos[i] = j;

      while (i > 0) {
        while (j <= pattern.length && pattern[i - 1] != pattern[j - 1]) {
          if (goodSuffixTable[j - 1] == 0) {
            goodSuffixTable[j - 1] = j - i;
          }
          j = borderPos[j];
        }
        i--;
        j--;
        borderPos[i] = j;
      }

      j = borderPos[0];
      for (i = 0; i < pattern.length; i++) {
        if (goodSuffixTable[i] == 0) {
          goodSuffixTable[i] = j;
        }
        if (i == j) {
          j = borderPos[j];
        }
      }
    }

    preprocessGoodSuffix();

    // Search phase
    int textIndex = 0;

    while (textIndex <= text.length - pattern.length) {
      int patternIndex = pattern.length - 1;

      // Match pattern from right to left
      while (patternIndex >= 0 && 
             pattern[patternIndex] == text[textIndex + patternIndex]) {
        patternIndex--;
      }

      if (patternIndex < 0) {
        // Pattern found
