void main() {
  // Extended Euclidean Algorithm to find modular inverse
  // Returns x such that (a * x) % m = 1
  int? modularInverse(int a, int m) {
    if (m == 1) return 0;

    int m0 = m;
    int x0 = 0;
    int x1 = 1;

    // Apply extended Euclidean algorithm
    while (a > 1) {
      // q is quotient
      int q = a ~/ m;

      // Update m and a
      int temp = m;
      m = a % m;
      a = temp;

      // Update x0 and x1
      temp = x0;
      x0 = x1 - q * x0;
      x1 = temp;
    }

    // Make x1 positive
    if (x1 < 0) {
      x1 += m0;
    }

    return x1;
  }

  // Extended Euclidean Algorithm (full version)
  // Returns gcd and coefficients x, y such that ax + by = gcd(a, b)
  List<int> extendedGCD(int a, int b) {
    if (b == 0) {
      return [a, 1, 0]; // gcd, x, y
    }

    int x1 = 1, x2 = 0;
    int y1 = 0, y2 = 1;

    while (b != 0) {
      int q = a ~/ b;

      // Update a and b
      int temp = b;
      b = a % b;
      a = temp;

      // Update x coefficients
      temp = x2;
      x2 = x1 - q * x2;
      x1 = temp;

      // Update y coefficients
      temp = y2;
      y2 = y1 - q * y2;
      y1 = temp;
    }

    return [a, x1, y1]; // gcd, x, y
  }

  // Test cases
  print("=== Modular Inverse Examples ===");

  // Example 1: Find modular inverse of 3 mod 11
  int a1 = 3;
  int m1 = 11;
  int? inverse1 = modularInverse(a1, m1);
  print("Modular inverse of $a1 mod $m1 = $inverse1");
  if (inverse1 != null) {
    print("Verification: ($a1 * $inverse1) mod $m1 = ${(a1 * inverse1) % m1}");
  }

