void main() {
  // Sample array for Range Minimum Query
  final arr = [7, 2, 3, 0, 5, 10, 3, 12, 18, 1, 9, 6];
  final n = arr.length;

  // Calculate the maximum power of 2 needed
  int logN = 0;
  int temp = n;
  while (temp > 0) {
    logN++;
    temp ~/= 2;
  }

  // Create sparse table
  // sparseTable[i][j] stores minimum of range [i, i + 2^j - 1]
  final sparseTable = List.generate(n, (_) => List.filled(logN, 0));

  // Initialize sparse table for intervals of length 1
  for (int i = 0; i < n; i++) {
    sparseTable[i][0] = arr[i];
  }

  // Build sparse table using dynamic programming
  // For each power of 2 length
  for (int j = 1; j < logN; j++) {
    // For each possible starting position
    for (int i = 0; i + (1 << j) <= n; i++) {
      // Minimum of two halves
      int leftHalf = sparseTable[i][j - 1];
      int rightHalf = sparseTable[i + (1 << (j - 1))][j - 1];
      sparseTable[i][j] = leftHalf < rightHalf ? leftHalf : rightHalf;
    }
  }

  // Precompute logarithms for O(1) query
  final log = List.filled(n + 1, 0);
  log[1] = 0;
  for (int i = 2; i <= n; i++) {
    log[i] = log[i ~/ 2] + 1;
  }

  // Function to query minimum in range [left, right]
  int query(int left, int right) {
    int length = right - left + 1;
    int k = log[length];
    int leftMin = sparseTable[left][k];
    int rightMin = sparseTable[right - (1 << k) + 1][k];
    return leftMin < rightMin ? leftMin : rightMin;
  }

  // Print the original array
  print('Original array: $arr');
  print('Array length: $n\n');

  // Print sparse table
  print('Sparse Table:');
  for (int j = 0; j < logN; j++) {
    if ((1 << j) > n) break;
    print('Length ${1 << j}:');
    for (int i = 0; i < n && i + (1 << j) <= n; i++) {
      print('  [$i, ${i + (1 << j) - 1}] = ${sparseTable[i][j]}');
    }
  }
  print('');

  // Test queries
  final testQueries = [
    [0, 5],   // Should return 0
    [1, 3],   // Should return 0
    [5, 8],   // Should return 3
    [7, 11],  // Should return 1
    [0, 11],  // Should return 0
    [9, 10],  // Should return 1
    [2, 2],   // Should return 3
  ];

  print('Range Minimum Queries:');
  for (final range in testQueries) {
    int left = range[0];
    int right = range[1];
    int minValue = query(left, right);

    // Extract the subarray for display
    final subarray = [];
    for (int i = left; i <= right; i++) {
      subarray.add(arr[i]);
    }

    print('RMQ[$left, $right] = $minValue (subarray: $subarray)');
  }

  // Verify correctness with brute force
  print('\nVerification with brute force:');
  bool allCorrect = true;
  for (final range in testQueries) {
    int left = range[0];
    int right = range[1];

    // Brute force minimum
    int bruteMin = arr[left];
    for (int i = left + 1; i <= right; i++) {
      if (arr[i] < bruteMin) {
        bruteMin = arr[i];
      }
    }

    int sparseMin = query(left, right);
    bool isCorrect = bruteMin == sparseMin;
    allCorrect = allCorrect && isCorrect;

    print('Range [$left, $right]: Sparse=$sparseMin, Brute=$bruteMin, ${isCorrect ? "✓" : "✗"}');
  }

  print('\nAll queries ${allCorrect ? "passed ✓" : "failed ✗"}');

  // Time complexity analysis
  print('\nTime Complexity:');
  print('Preprocessing: O(n log n)');
  print('Query: O(1)');
  print('Space: O(n log n)');
}

