void main() {
  // Example cost matrix for assignment problem
  var costMatrix = [
    [10, 19, 8, 15],
    [10, 18, 7, 17],
    [13, 16, 9, 14],
    [12, 19, 8, 18]
  ];

  print('Original Cost Matrix:');
  for (var row in costMatrix) {
    print(row);
  }

  int n = costMatrix.length;

  // Create a copy of the cost matrix for manipulation
  var matrix = List.generate(n, (i) => List<int>.from(costMatrix[i]));

  // Step 1: Subtract row minimums
  for (int i = 0; i < n; i++) {
    int minVal = matrix[i].reduce((a, b) => a < b ? a : b);
    for (int j = 0; j < n; j++) {
      matrix[i][j] -= minVal;
    }
  }

  // Step 2: Subtract column minimums
  for (int j = 0; j < n; j++) {
    int minVal = matrix[0][j];
    for (int i = 1; i < n; i++) {
      if (matrix[i][j] < minVal) {
        minVal = matrix[i][j];
      }
    }
    for (int i = 0; i < n; i++) {
      matrix[i][j] -= minVal;
    }
  }

  // Main loop for finding optimal assignment
  while (true) {
    // Mark zeros and find assignments
    var rowCovered = List<bool>.filled(n, false);
    var colCovered = List<bool>.filled(n, false);
    var assignment = List<int>.filled(n, -1);

    // Find initial assignments (one zero per row and column)
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        if (matrix[i][j] == 0 && !rowCovered[i] && !colCovered[j]) {
          assignment[i] = j;
          rowCovered[i] = true;
          colCovered[j] = true;
          break;
        }
      }
    }

    // Count assignments
    int assignmentCount = 0;
    for (int i = 0; i < n; i++) {
      if (assignment[i] != -1) assignmentCount++;
    }

    if (assignmentCount == n) {
      // Solution found
      print('\nOptimal Assignment:');
      int totalCost = 0;
      for (int i = 0; i < n; i++) {
        print('Worker ${i + 1} -> Task ${assignment[i] + 1}, Cost: ${costMatrix[i][assignment[i]]}');
        totalCost += costMatrix[i][assignment[i]];
      }
      print('Total Cost: $totalCost');
      break;
    }

    // Find minimum lines to cover all zeros
    rowCovered = List<bool>.filled(n, false);
    colCovered = List<bool>.filled(n, false);

    // Mark rows with no assignments
    var markedRows = List<bool>.filled(n, false);
    for (int i = 0; i < n; i++) {
      if (assignment[i] == -1) {
        markedRows[i] = true;
      }
    }

    // Mark columns with zeros in marked rows
    bool changed = true;
    while (changed) {
      changed = false;
      for (int i = 0; i < n; i++) {
        if (markedRows[i]) {
          for (int j = 0; j < n; j++) {
            if (matrix[i][j] == 0 && !colCovered[j]) {
              colCovered[j] = true;
              changed = true;

              // Mark rows with assignments in marked columns
              for (int k = 0; k < n; k++) {
                if (assignment[k] == j && !markedRows[k]) {
                  markedRows[k] = true;
                  changed = true;
                }
              }
            }
          }
        }
      }
    }

    // Cover unmarked rows and marked columns
    for (int i = 0; i < n; i++) {
      rowCovered[i] = !markedRows[i];
    }

    // Find minimum uncovered value
    int minUncovered = 999999;
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        if (!rowCovered[i] && !colCovered[j]) {
          if (matrix[i][j] < minUncovered) {
            minUncovered = matrix[i][j];
          }
        }
      }
    }

    // Update matrix
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < n; j++) {
        if (rowCovered[i] && colCovered[j]) {
          matrix[i][j] += minUncovered;
        } else if (!rowCovered[i] && !colCovered[j]) {
          matrix[i][j] -= minUncovered;
        }
      }
    }
  }
}

