@pragma('vm:entry-point')
void main() {
  // Men's preferences (each man ranks women from most to least preferred)
  Map<String, List<String>> menPrefs = {
    'A': ['X', 'Y', 'Z'],
    'B': ['Y', 'Z', 'X'],
    'C': ['Z', 'X', 'Y'],
  };

  // Women's preferences (each woman ranks men from most to least preferred)
  Map<String, List<String>> womenPrefs = {
    'X': ['B', 'A', 'C'],
    'Y': ['C', 'B', 'A'],
    'Z': ['A', 'C', 'B'],
  };

  // Initialize data structures
  Map<String, String?> menPartners = {};
  Map<String, String?> womenPartners = {};
  Map<String, int> menNextProposal = {};
  List<String> freeMen = [];

  // Initialize all men as free and women as unengaged
  for (String man in menPrefs.keys) {
    menPartners[man] = null;
    menNextProposal[man] = 0;
    freeMen.add(man);
  }

  for (String woman in womenPrefs.keys) {
    womenPartners[woman] = null;
  }

  // Create ranking maps for women (for O(1) preference comparison)
  Map<String, Map<String, int>> womenRankings = {};
  for (String woman in womenPrefs.keys) {
    womenRankings[woman] = {};
    for (int i = 0; i < womenPrefs[woman]!.length; i++) {
      womenRankings[woman]![womenPrefs[woman]![i]] = i;
    }
  }

  // Gale-Shapley algorithm
  while (freeMen.isNotEmpty) {
    String man = freeMen.first;

    // Get the next woman on this man's preference list
    int proposalIndex = menNextProposal[man]!;
    if (proposalIndex >= menPrefs[man]!.length) {
      freeMen.remove(man);
      continue;
    }

    String woman = menPrefs[man]![proposalIndex];
    menNextProposal[man] = proposalIndex + 1;

    // If woman is free, engage them
    if (womenPartners[woman] == null) {
      menPartners[man] = woman;
      womenPartners[woman] = man;
      freeMen.remove(man);
      print('$man and $woman are now engaged');
    } else {
      // Woman is already engaged, check if she prefers the new proposer
      String currentPartner = womenPartners[woman]!;

      // Compare rankings (lower rank number means higher preference)
      if (womenRankings[woman]![man]! < womenRankings[woman]![currentPartner]!) {
        // Woman prefers new proposer
        print('$woman breaks up with $currentPartner and engages with $man');

        // Break current engagement
        menPartners[currentPartner] = null;
        freeMen.add(currentPartner);

        // Create new engagement
        menPartners[man] = woman;
        womenPartners[woman] = man;
        freeMen.remove(man);
      } else {
        // Woman rejects the proposal
        print('$woman rejects $man');
      }
    }
  }

  // Print final stable matching
  print('\n=== Final Stable Matching ===');
  for (String man in menPrefs.keys) {
    String? partner = menPartners[man];
    if (partner != null) {
      print('$man is matched with $partner');
    } else {
      print('$man is unmatched');
    }
  }

  // Verify stability
  print('\n=== Verifying Stability ===');
  bool isStable = true;

  for (String man in menPrefs.keys) {
    String? currentPartner = menPartners[man];
    if (currentPartner == null) continue;

    int currentPartnerRank = menPrefs[man]!.indexOf(currentPartner);

    // Check all women this man prefers over his current partner
    for (int i = 0; i < currentPartnerRank; i++) {
      String preferredWoman = menPrefs[man]![i];
      String? herPartner = womenPartners[preferredWoman];

      if (herPartner == null) {
        print('Instability: $man prefers $preferredWoman over $currentPartner, and $preferredWoman is free');
        isStable = false;
      } else if (womenRankings[preferredWoman]![man]! < womenRankings[preferredWoman]![herPartner]!) {
        print('Instability: $man and $preferredWoman would prefer each other over their current partners');
        isStable = false;
      }
    }
  }

  if (isStable) {
    print('The matching is stable!');
  } else {
    print('The matching is NOT stable!');
  }
}

