  // Stream of data to sample from (simulating a large/unknown size stream)
  final stream = List.generate(100, (i) => i + 1); // Numbers 1 to 100
  final k = 10; // Size of reservoir (number of samples to keep)

  // Reservoir to hold our samples
  final reservoir = <int>[];
  final random = Random();

  // Process the stream using reservoir sampling algorithm
  for (int i = 0; i < stream.length; i++) {
    if (i < k) {
      // First k elements go directly into reservoir
      reservoir.add(stream[i]);
    } else {
      // For elements after the first k, randomly decide whether to include
      // Probability of inclusion = k / (i + 1)
      final j = random.nextInt(i + 1);
      if (j < k) {
        // Replace element at random position j with current element
        reservoir[j] = stream[i];
      }
    }
  }

  // Sort for display purposes (not part of algorithm)
  reservoir.sort();

  // Display results
  print('Reservoir Sampling Results:');
  print('Stream size: ${stream.length}');
  print('Reservoir size: $k');
  print('Selected samples: $reservoir');

  // Verify uniform distribution by running multiple iterations
  print('\nVerifying uniform distribution (1000 iterations):');
  final frequency = <int, int>{};

  for (int iteration = 0; iteration < 1000; iteration++) {
    final testReservoir = <int>[];

    for (int i = 0; i < stream.length; i++) {
      if (i < k) {
        testReservoir.add(stream[i]);
      } else {
        final j = random.nextInt(i + 1);
        if (j < k) {
          testReservoir[j] = stream[i];
        }
      }
    }

    for (final sample in testReservoir) {
      frequency[sample] = (frequency[sample] ?? 0) + 1;
    }
  }

  // Show frequency of first 10 numbers to verify uniform distribution
  print('Frequency of first 10 numbers (expected ~${1000 * k / stream.length} each):');
  for (int i = 1; i <= 10; i++) {
    print('  $i: ${frequency[i] ?? 0} times');
  }
}

