import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Simulated Annealing implementation to find minimum of a function
  // Example: Finding minimum of f(x) = (x-3)^2 + sin(x*5) + 0.1*x^3

  final random = Random();

  // Objective function to minimize
  double objectiveFunction(double x) {
    return pow(x - 3, 2) + sin(x * 5) + 0.1 * pow(x, 3);
  }

  // Simulated annealing parameters
  double currentSolution = random.nextDouble() * 10 - 5; // Random initial solution [-5, 5]
  double currentCost = objectiveFunction(currentSolution);
  double bestSolution = currentSolution;
  double bestCost = currentCost;

  // Temperature parameters
  double temperature = 100.0;
  final double coolingRate = 0.995;
  final double minTemperature = 0.001;

  // Neighborhood search parameters
  final double stepSize = 0.5;

  int iteration = 0;
  final int maxIterations = 10000;

  print('Simulated Annealing Optimization');
  print('================================');
  print('Minimizing: f(x) = (x-3)^2 + sin(x*5) + 0.1*x^3');
  print('Initial solution: x = ${currentSolution.toStringAsFixed(4)}');
  print('Initial cost: ${currentCost.toStringAsFixed(4)}');
  print('\nStarting optimization...\n');

  // Main simulated annealing loop
  while (temperature > minTemperature && iteration < maxIterations) {
    // Generate neighbor solution
    double neighborSolution = currentSolution + (random.nextDouble() * 2 - 1) * stepSize;

    // Constrain solution to reasonable bounds
    neighborSolution = neighborSolution.clamp(-10.0, 10.0);

    double neighborCost = objectiveFunction(neighborSolution);

    // Calculate acceptance probability
    double deltaCost = neighborCost - currentCost;
    double acceptanceProbability = deltaCost < 0 ? 1.0 : exp(-deltaCost / temperature);

    // Accept or reject the neighbor
    if (random.nextDouble() < acceptanceProbability) {
      currentSolution = neighborSolution;
      currentCost = neighborCost;

      // Update best solution if necessary
      if (currentCost < bestCost) {
        bestSolution = currentSolution;
        bestCost = currentCost;

        if (iteration % 100 == 0) {
          print('Iteration $iteration: New best found! x = ${bestSolution.toStringAsFixed(4)}, cost = ${bestCost.toStringAsFixed(4)}');
        }
      }
    }

    // Cool down temperature
    temperature *= coolingRate;
    iteration++;

    // Progress reporting
    if (iteration % 1000 == 0) {
      print('Iteration $iteration: Temperature = ${temperature.toStringAsFixed(4)}, Current cost = ${currentCost.toStringAsFixed(4)}');
    }
  }

  print('\nOptimization completed!');
  print('=======================');
  print('Best solution found: x = ${bestSolution.toStringAsFixed(6)}');
  print('Best cost: ${bestCost.toStringAsFixed(6)}');
  print('Total iterations: $iteration');
  print('Final temperature: ${temperature.toStringAsFixed(6)}');

  // Verify by checking nearby points
  print('\nVerification (checking nearby points):');
  for (double offset in [-0.1, -0.05, 0, 0.05, 0.1]) {
    double x = bestSolution + offset;
    double cost = objectiveFunction(x);
    print('  f(${x.toStringAsFixed(4)}) = ${cost.toStringAsFixed(6)}');
  }

  // Example 2: Traveling Salesman Problem (TSP) using Simulated Annealing
  print('\n\n=================================');
  print('Traveling Salesman Problem (TSP)');
  print('=================================');

  // Define cities with coordinates
  final List<List<double>> cities = [
    [0, 0], [1, 5], [5, 6], [6, 1], [8, 3],
    [3, 7], [9, 9], [4, 2], [7, 8], [2, 3]
  ];

  // Calculate distance between two cities
  double distance(List<double> city1, List<double> city2) {
    return sqrt(pow(city1[0] - city2[0], 2) + pow(city1[1] - city2[1], 2));
  }

  // Calculate total tour distance
  double tourDistance(List<int> tour) {
    double totalDistance = 0;
    for (int i = 0; i < tour.length; i++) {
      int nextCity = (i + 1) % tour.length;
      totalDistance += distance(cities[tour[i]], cities[tour[nextCity]]);
    }
    return totalDistance;
  }

  // Generate initial random tour
  List<int> currentTour = List.generate(cities.length, (i) => i);
  currentTour.shuffle(random);
  double currentTourCost = tourDistance(currentTour);

  List<int> bestTour = List.from(currentTour);
  double bestTourCost = currentTourCost;

  // TSP parameters
  double tspTemperature = 100.0;
  final double tspCoolingRate = 0.999;
  final double tspMinTemperature = 0.01;
  int tspIteration = 0;
  final int tspMaxIterations = 50000;

  print('Number of cities: ${cities.length}');
  print('Initial tour: $currentTour');
  print('Initial tour distance: ${currentTourCost.toStringAsFixed(2)}');
  print('\nOptimizing tour...\n');

  while (tspTemperature > tspMinTemperature && tspIteration < tspMaxIterations) {
    // Generate neighbor by swapping two random cities
    List<int> neighborTour = List.from(currentTour);
    int city1 = random.nextInt(cities.length);
    int city2 = random.nextInt(cities.length);
    while (city2 == city1) {
      city2 = random.nextInt(cities.length);
    }

    // Swap cities
    int temp = neighborTour[city1];
    neighborTour[city1] = neighborTour[city2];
    neighborTour[city2] = temp;

    double neighborTourCost = tourDistance(neighborTour);

    // Calculate acceptance probability
    double deltaTourCost = neighborTourCost - currentTourCost;
    double tourAcceptanceProbability = deltaTourCost < 0 ? 1.0 : exp(-deltaTourCost / tspTemperature);

    // Accept or reject the neighbor
    if (random.nextDouble() < tourAcceptanceProbability) {
      currentTour = neighborTour;
      currentTourCost = neighborTourCost;

      // Update best tour if necessary
      if (currentTourCost < bestTourCost) {
        bestTour = List.from(currentTour);
        bestTourCost = currentTourCost;

        if (tspIteration % 5000 == 0) {
          print('Iteration $tspIteration: New best tour found! Distance = ${bestTourCost.toStringAsFixed(2)}');
        }
      }
    }

    // Cool down temperature
    tspTemperature *= tspCoolingRate;
    tspIteration++;

    // Progress reporting
    if (tspIteration % 10000 == 0) {
      print('Iteration $tspIteration: Temperature = ${tspTemperature.toStringAsFixed(4)}, Current distance = ${currentTourCost.toStringAsFixed(2)}');
    }
  }

  print('\nTSP Optimization completed!');
  print('===========================');
  print('Best tour found: $bestTour');
  print('Best tour distance: ${bestTourCost.toStringAsFixed(4)}');
  print('Total iterations: $tspIteration');
  print('Final temperature: ${tspTemperature.toStringAsFixed(6)}');

  // Display tour coordinates
