import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Genetic Algorithm to find a target string
  final random = Random();
  final targetString = "HELLO WORLD";
  final populationSize = 100;
  final mutationRate = 0.01;
  final eliteSize = 20;
  final maxGenerations = 1000;

  // Character set for generating random strings
  final charset = "ABCDEFGHIJKLMNOPQRSTUVWXYZ ";

  // Generate random individual
  String generateIndividual(int length) {
    return List.generate(length, (_) => charset[random.nextInt(charset.length)]).join();
  }

  // Calculate fitness (how close to target)
  int calculateFitness(String individual) {
    int fitness = 0;
    for (int i = 0; i < individual.length; i++) {
      if (i < targetString.length && individual[i] == targetString[i]) {
        fitness++;
      }
    }
    return fitness;
  }

  // Selection - Tournament selection
  String tournamentSelection(List<Map<String, dynamic>> population) {
    final tournamentSize = 5;
    List<Map<String, dynamic>> tournament = [];

    for (int i = 0; i < tournamentSize; i++) {
      tournament.add(population[random.nextInt(population.length)]);
    }

    tournament.sort((a, b) => b['fitness'].compareTo(a['fitness']));
    return tournament[0]['individual'];
  }

  // Crossover - Single point crossover
  String crossover(String parent1, String parent2) {
    final crossoverPoint = random.nextInt(parent1.length);
    return parent1.substring(0, crossoverPoint) + 
           parent2.substring(crossoverPoint);
  }

  // Mutation - Random character mutation
  String mutate(String individual) {
    List<String> chars = individual.split('');
    for (int i = 0; i < chars.length; i++) {
      if (random.nextDouble() < mutationRate) {
        chars[i] = charset[random.nextInt(charset.length)];
      }
    }
    return chars.join();
  }

  // Initialize population
  List<Map<String, dynamic>> population = [];
  for (int i = 0; i < populationSize; i++) {
    String individual = generateIndividual(targetString.length);
    population.add({
      'individual': individual,
      'fitness': calculateFitness(individual)
    });
  }

  // Evolution loop
  int generation = 0;
  bool solutionFound = false;

  while (generation < maxGenerations && !solutionFound) {
    // Sort population by fitness
    population.sort((a, b) => b['fitness'].compareTo(a['fitness']));

    // Check if solution found
    if (population[0]['fitness'] == targetString.length) {
      solutionFound = true;
      print('Solution found in generation $generation!');
      print('Best individual: ${population[0]['individual']}');
      break;
    }

    // Print progress every 10 generations
    if (generation % 10 == 0) {
      print('Generation $generation:');
      print('  Best fitness: ${population[0]['fitness']}/${targetString.length}');
      print('  Best individual: ${population[0]['individual']}');
      print('  Average fitness: ${population.map((p) => p['fitness']).reduce((a, b) => a + b) / population.length}');
    }

    // Create new generation
    List<Map<String, dynamic>> newPopulation = [];

    // Keep elite individuals
    for (int i = 0; i < eliteSize && i < population.length; i++) {
      newPopulation.add(population[i]);
    }

    // Generate rest of population through crossover and mutation
    while (newPopulation.length < populationSize) {
      // Select parents
      String parent1 = tournamentSelection(population);
      String parent2 = tournamentSelection(population);

      // Crossover
      String child = crossover(parent1, parent2);

      // Mutation
      child = mutate(child);

      // Add to new population
      newPopulation.add({
        'individual': child,
        'fitness': calculateFitness(child)
      });
    }

    population = newPopulation;
    generation++;
  }

  if (!solutionFound) {
    print('\nMax generations reached without finding exact solution.');
    population.sort((a, b) => b['fitness'].compareTo(a['fitness']));
    print('Best result: ${population[0]['individual']}');
    print('Fitness: ${population[0]['fitness']}/${targetString.length}');
  }

  // Additional statistics
  print('\n--- Final Statistics ---');
  print('Total generations: $generation');
  print('Population size: $populationSize');
  print('Mutation rate: $mutationRate');
  print('Elite size: $eliteSize');

  // Show top 5 individuals
  print('\nTop 5 individuals:');
  for (int i = 0; i < 5 && i < population.length; i++) {
    print('  ${i + 1}. ${population[i]['individual']} (fitness: ${population[i]['fitness']})');
  }
}

