List<List<int>> generateSubsetsBitwise(List<int> set) {
  List<List<int>> allSubsets = [];
  int n = set.length;
  int totalSubsets = 1 << n; // 2^n subsets

  for (int i = 0; i < totalSubsets; i++) {
    List<int> subset = [];
    for (int j = 0; j < n; j++) {
      // Check if jth bit is set in i
      if ((i & (1 << j)) != 0) {
        subset.add(set[j]);
      }
    }
    allSubsets.add(subset);
  }

  return allSubsets;
}

void generateSubsetsRecursive(List<int> set, int index, List<int> current, List<List<int>> result) {
  if (index == set.length) {
    result.add(List.from(current));
    return;
  }

  // Exclude current element
  generateSubsetsRecursive(set, index + 1, current, result);

  // Include current element
  current.add(set[index]);
  generateSubsetsRecursive(set, index + 1, current, result);
  current.removeLast(); // Backtrack
}

List<List<int>> generateSubsetsIterative(List<int> set) {
  List<List<int>> subsets = [[]]; // Start with empty subset

  for (int element in set) {
    List<List<int>> newSubsets = [];
    for (List<int> subset in subsets) {
      List<int> newSubset = List.from(subset);
      newSubset.add(element);
      newSubsets.add(newSubset);
    }
    subsets.addAll(newSubsets);
  }

  return subsets;
}

void printSubsets(List<List<int>> subsets) {
  print("Total subsets: ${subsets.length}");
  for (int i = 0; i < subsets.length; i++) {
    if (subsets[i].isEmpty) {
      print("  Subset ${i + 1}: []");
    } else {
      print("  Subset ${i + 1}: {${subsets[i].join(', ')}}");
    }
  }
}

