@pragma('vm:entry-point')
void main() {
  // Initialize the board (0 = empty, 1 = X, 2 = O)
  List<int> board = List.filled(9, 0);

  // Helper function to print the board
  void printBoard() {
    for (int i = 0; i < 9; i += 3) {
      String row = '';
      for (int j = 0; j < 3; j++) {
        if (board[i + j] == 0) {
          row += '${i + j} ';
        } else if (board[i + j] == 1) {
          row += 'X ';
        } else {
          row += 'O ';
        }
      }
      print(row);
    }
    print('');
  }

  // Check if there's a winner
  int checkWinner() {
    // Check rows
    for (int i = 0; i < 9; i += 3) {
      if (board[i] != 0 && board[i] == board[i + 1] && board[i] == board[i + 2]) {
        return board[i];
      }
    }

    // Check columns
    for (int i = 0; i < 3; i++) {
      if (board[i] != 0 && board[i] == board[i + 3] && board[i] == board[i + 6]) {
        return board[i];
      }
    }

    // Check diagonals
    if (board[0] != 0 && board[0] == board[4] && board[0] == board[8]) {
      return board[0];
    }
    if (board[2] != 0 && board[2] == board[4] && board[2] == board[6]) {
      return board[2];
    }

    return 0; // No winner
  }

  // Check if board is full
  bool isBoardFull() {
    for (int i = 0; i < 9; i++) {
      if (board[i] == 0) return false;
    }
    return true;
  }

  // Minimax algorithm
  int minimax(bool isMaximizing, int depth) {
    int winner = checkWinner();

    if (winner == 2) return 10 - depth; // O wins (AI)
    if (winner == 1) return depth - 10; // X wins (Human)
    if (isBoardFull()) return 0; // Draw

    if (isMaximizing) {
      int maxEval = -1000;
      for (int i = 0; i < 9; i++) {
        if (board[i] == 0) {
          board[i] = 2; // AI move
          int eval = minimax(false, depth + 1);
          board[i] = 0;
          if (eval > maxEval) {
            maxEval = eval;
          }
        }
      }
      return maxEval;
    } else {
      int minEval = 1000;
      for (int i = 0; i < 9; i++) {
        if (board[i] == 0) {
          board[i] = 1; // Human move
          int eval = minimax(true, depth + 1);
          board[i] = 0;
          if (eval < minEval) {
            minEval = eval;
          }
        }
      }
      return minEval;
    }
  }

  // Find best move for AI
  int findBestMove() {
    int bestMove = -1;
    int bestValue = -1000;

    for (int i = 0; i < 9; i++) {
      if (board[i] == 0) {
        board[i] = 2; // AI move
        int moveValue = minimax(false, 0);
        board[i] = 0;

        if (moveValue > bestValue) {
          bestValue = moveValue;
          bestMove = i;
        }
      }
    }

    return bestMove;
  }

  // Game loop
  print('Tic-Tac-Toe with Minimax AI');
  print('You are X, AI is O');
  print('Enter position (0-8) to make your move:\n');

  printBoard();

  // Simulate a game
  List<int> humanMoves = [4, 0, 2]; // Example human moves
  int moveIndex = 0;

  while (true) {
    // Human move (simulated)
    if (moveIndex < humanMoves.length) {
      int humanMove = humanMoves[moveIndex];
      if (board[humanMove] == 0) {
        board[humanMove] = 1;
        print('Human plays at position $humanMove');
        printBoard();
        moveIndex++;
      }
    } else {
      // Find first empty spot for human
      for (int i = 0; i < 9; i++) {
        if (board[i] == 0) {
          board[i] = 1;
          print('Human plays at position $i');
          printBoard();
          break;
        }
      }
    }

    // Check game state
    int winner = checkWinner();
    if (winner == 1) {
      print('Human wins!');
      break;
    }
    if (isBoardFull()) {
      print('It\'s a draw!');
      break;
    }

    // AI move
    int aiMove = findBestMove();
    if (aiMove != -1) {
      board[aiMove] = 2;
      print('AI plays at position $aiMove');
      printBoard();
    }

    // Check game state again
    winner = checkWinner();
    if (winner == 2) {
      print('AI wins!');
      break;
    }
    if (isBoardFull()) {
      print('It\'s a draw!');
      break;
    }
  }
}

