import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Sample 2D data points to cluster
  final List<List<double>> dataPoints = [
    [1.0, 2.0], [1.5, 1.8], [3.0, 4.0], [5.0, 7.0],
    [3.5, 5.0], [4.5, 5.0], [3.5, 4.5], [2.0, 2.5],
    [5.5, 6.0], [6.0, 7.5], [1.2, 1.9], [2.3, 2.8],
    [8.0, 8.0], [8.5, 9.0], [7.5, 8.5], [9.0, 9.5],
    [1.8, 2.2], [2.5, 3.0], [7.0, 8.0], [8.2, 8.8]
  ];

  final int k = 3; // Number of clusters
  final int maxIterations = 100;
  final Random random = Random(42); // Seed for reproducibility

  // Initialize centroids by randomly selecting k data points
  List<List<double>> centroids = [];
  Set<int> selectedIndices = {};
  while (centroids.length < k) {
    int index = random.nextInt(dataPoints.length);
    if (!selectedIndices.contains(index)) {
      selectedIndices.add(index);
      centroids.add(List<double>.from(dataPoints[index]));
    }
  }

  // Store cluster assignments for each data point
  List<int> clusterAssignments = List.filled(dataPoints.length, -1);

  // K-means iterations
  for (int iteration = 0; iteration < maxIterations; iteration++) {
    bool hasChanged = false;

    // Assignment step: assign each point to nearest centroid
    for (int i = 0; i < dataPoints.length; i++) {
      double minDistance = double.infinity;
      int nearestCluster = -1;

      for (int j = 0; j < k; j++) {
        // Calculate Euclidean distance
        double distance = 0.0;
        for (int dim = 0; dim < dataPoints[i].length; dim++) {
          double diff = dataPoints[i][dim] - centroids[j][dim];
          distance += diff * diff;
        }
        distance = sqrt(distance);

        if (distance < minDistance) {
          minDistance = distance;
          nearestCluster = j;
        }
      }

      if (clusterAssignments[i] != nearestCluster) {
        hasChanged = true;
        clusterAssignments[i] = nearestCluster;
      }
    }

    // If no assignments changed, we've converged
    if (!hasChanged) {
      print('Converged after $iteration iterations');
      break;
    }

    // Update step: recalculate centroids
    for (int j = 0; j < k; j++) {
      List<double> newCentroid = List.filled(dataPoints[0].length, 0.0);
      int count = 0;

      for (int i = 0; i < dataPoints.length; i++) {
        if (clusterAssignments[i] == j) {
          for (int dim = 0; dim < dataPoints[i].length; dim++) {
            newCentroid[dim] += dataPoints[i][dim];
          }
          count++;
        }
      }

      // Calculate mean for new centroid
      if (count > 0) {
        for (int dim = 0; dim < newCentroid.length; dim++) {
          centroids[j][dim] = newCentroid[dim] / count;
        }
      }
    }
  }

  // Print results
  print('\nK-Means Clustering Results:');
  print('Number of clusters: $k');
  print('\nFinal Centroids:');
  for (int i = 0; i < centroids.length; i++) {
    print('Centroid ${i + 1}: [${centroids[i].map((v) => v.toStringAsFixed(2)).join(', ')}]');
  }

  print('\nCluster Assignments:');
  for (int i = 0; i < k; i++) {
    List<List<double>> clusterPoints = [];
    for (int j = 0; j < dataPoints.length; j++) {
      if (clusterAssignments[j] == i) {
        clusterPoints.add(dataPoints[j]);
      }
    }
    print('\nCluster ${i + 1} (${clusterPoints.length} points):');
    for (var point in clusterPoints) {
      print('  [${point.map((v) => v.toStringAsFixed(1)).join(', ')}]');
    }
  }

  // Calculate and print Within-Cluster Sum of Squares (WCSS)
  double wcss = 0.0;
  for (int i = 0; i < dataPoints.length; i++) {
    double distance = 0.0;
    int cluster = clusterAssignments[i];
    for (int dim = 0; dim < dataPoints[i].length; dim++) {
      double diff = dataPoints[i][dim] - centroids[cluster][dim];
      distance += diff * diff;
    }
    wcss += distance;
  }
  print('\nWithin-Cluster Sum of Squares (WCSS): ${wcss.toStringAsFixed(2)}');
}

