void main() {
  // Training data for AND gate
  final List<List<double>> inputs = [
    [0, 0],
    [0, 1],
    [1, 0],
    [1, 1],
  ];

  final List<double> targets = [0, 0, 0, 1]; // AND gate outputs

  // Initialize weights and bias randomly
  double weight1 = 0.5;
  double weight2 = 0.5;
  double bias = -0.7;

  // Learning rate
  final double learningRate = 0.1;

  // Training parameters
  final int maxEpochs = 100;
  bool trained = false;

  print('Training Perceptron for AND gate...');
  print('Initial weights: w1=$weight1, w2=$weight2, bias=$bias\n');

  // Training loop
  for (int epoch = 0; epoch < maxEpochs && !trained; epoch++) {
    int correctPredictions = 0;

    print('Epoch ${epoch + 1}:');

    for (int i = 0; i < inputs.length; i++) {
      // Forward pass
      double x1 = inputs[i][0];
      double x2 = inputs[i][1];
      double target = targets[i];

      // Calculate weighted sum
      double weightedSum = x1 * weight1 + x2 * weight2 + bias;

      // Apply activation function (step function)
      double output = weightedSum > 0 ? 1.0 : 0.0;

      // Calculate error
      double error = target - output;

      // Update weights if there's an error
      if (error != 0) {
        weight1 += learningRate * error * x1;
        weight2 += learningRate * error * x2;
        bias += learningRate * error;

        print('  Input: [${x1.toInt()}, ${x2.toInt()}], Target: ${target.toInt()}, Output: ${output.toInt()}, Error: $error');
        print('  Updated weights: w1=$weight1, w2=$weight2, bias=$bias');
      } else {
        correctPredictions++;
      }
    }

    // Check if all predictions are correct
    if (correctPredictions == inputs.length) {
      trained = true;
      print('\nTraining completed at epoch ${epoch + 1}!');
    }
  }

  if (!trained) {
    print('\nMax epochs reached. Training may not be complete.');
  }

  // Final weights
  print('\nFinal weights:');
  print('  w1 = $weight1');
  print('  w2 = $weight2');
  print('  bias = $bias');

  // Test the trained perceptron
  print('\nTesting the trained perceptron:');
  print('Input | Target | Prediction');
  print('------|--------|------------');

  for (int i = 0; i < inputs.length; i++) {
    double x1 = inputs[i][0];
    double x2 = inputs[i][1];
    double target = targets[i];

    // Calculate prediction
    double weightedSum = x1 * weight1 + x2 * weight2 + bias;
    double prediction = weightedSum > 0 ? 1.0 : 0.0;

    print('[${x1.toInt()}, ${x2.toInt()}] |   ${target.toInt()}    |     ${prediction.toInt()}');
  }

  // Test with OR gate data to show it needs retraining for different logic
  print('\n--- Testing with OR gate (without retraining) ---');
  final List<List<double>> orInputs = [
    [0, 0],
    [0, 1],
    [1, 0],
