    print('[${x1.toInt()}, ${x2.toInt()}] |     ${target.toInt()}     |     ${prediction.toInt()}');
  }

  double accuracy = (orCorrect / orInputs.length) * 100;
  print('\nAccuracy on OR gate: $orCorrect/${orInputs.length} = ${accuracy.toStringAsFixed(1)}%');
  print('\nNote: The perceptron was trained for AND gate, not OR gate.');
  print('Different logic gates require different weight configurations.');
}
