  print("Past date time ago: ${pastDate.timeAgo()}");

  // Map extensions
  Map<String, int> scores = {"Alice": 95, "Bob": 87, "Charlie": 92};
  print("\nScores: $scores");
  print("Inverted: ${scores.invert()}");
  print("Filtered (>90): ${scores.filter((key, value) => value > 90)}");

