// String extensions
extension StringExtensions on String {
  String capitalize() {
    if (isEmpty) return this;
    return this[0].toUpperCase() + substring(1).toLowerCase();
  }

  bool isPalindrome() {
    String cleaned = replaceAll(RegExp(r'[^a-zA-Z0-9]'), '').toLowerCase();
    return cleaned == cleaned.split('').reversed.join('');
  }

  int wordCount() {
    if (trim().isEmpty) return 0;
    return trim().split(RegExp(r'\s+')).length;
  }

  String reverseWords() {
    return split(' ').reversed.join(' ');
  }
}

// Int extensions
extension IntExtensions on int {
  bool isPrime() {
    if (this < 2) return false;
    for (int i = 2; i * i <= this; i++) {
      if (this % i == 0) return false;
    }
    return true;
  }

  int factorial() {
    if (this < 0) throw ArgumentError('Factorial not defined for negative numbers');
    if (this == 0 || this == 1) return 1;
    int result = 1;
    for (int i = 2; i <= this; i++) {
      result *= i;
    }
    return result;
  }

  String toBinary() => toRadixString(2);

  String toHex() => '0x${toRadixString(16).toUpperCase()}';

  int digitSum() {
    int sum = 0;
    int n = abs();
    while (n > 0) {
      sum += n % 10;
      n ~/= 10;
    }
    return sum;
  }
}

// List extensions
extension ListExtensions<T> on List<T> {
  T? randomElement() {
    if (isEmpty) return null;
    return this[DateTime.now().millisecondsSinceEpoch % length];
  }

  List<List<T>> chunk(int size) {
    List<List<T>> chunks = [];
    for (int i = 0; i < length; i += size) {
      int end = (i + size < length) ? i + size : length;
      chunks.add(sublist(i, end));
    }
    return chunks;
  }
}

extension NumListExtensions on List<num> {
  num sum() => fold(0, (prev, element) => prev + element);

  double average() => isEmpty ? 0 : sum() / length;
}

// Double extensions
extension DoubleExtensions on double {
  double roundToDecimals(int decimals) {
    num mod = 1;
    for (int i = 0; i < decimals; i++) {
      mod *= 10;
    }
    return (this * mod).round() / mod;
  }

  bool isWhole() => this == truncateToDouble();
}

// DateTime extensions
extension DateTimeExtensions on DateTime {
  bool isWeekend() => weekday == DateTime.saturday || weekday == DateTime.sunday;

  bool isWeekday() => !isWeekend();

  int daysInMonth() {
    return DateTime(year, month + 1, 0).day;
  }

  String format() {
    return '${year.toString().padLeft(4, '0')}-'
           '${month.toString().padLeft(2, '0')}-'
           '${day.toString().padLeft(2, '0')} '
           '${hour.toString().padLeft(2, '0')}:'
           '${minute.toString().padLeft(2, '0')}:'
           '${second.toString().padLeft(2, '0')}';
