  print('Mixed record: ${mixed.$1}, status: ${mixed.status}, priority: ${mixed.priority}');

  // Using records as function return types
  (double, double) calculateStats(List<int> numbers) {
    var sum = numbers.reduce((a, b) => a + b);
    var avg = sum / numbers.length;
    return (sum.toDouble(), avg);
  }

  var stats = calculateStats([10, 20, 30, 40, 50]);
  print('Sum: ${stats.$1}, Average: ${stats.$2}');

  // Pattern matching with records
  var coordinate = (x: 5.0, y: 10.0);
  var (x: xVal, y: yVal) = coordinate;
  print('Destructured: x=$xVal, y=$yVal');

  // Records in collections
  var employees = [
    (id: 1, name: 'Bob', department: 'Engineering'),
    (id: 2, name: 'Carol', department: 'Marketing'),
    (id: 3, name: 'Dave', department: 'Engineering'),
  ];

  print('\nEmployees:');
  for (var emp in employees) {
    print('  ${emp.id}: ${emp.name} - ${emp.department}');
  }

  // Filtering with records
  var engineers = employees.where((e) => e.department == 'Engineering').toList();
  print('\nEngineers: ${engineers.map((e) => e.name).join(', ')}');

  // Nested records
  var company = (
    name: 'TechCorp',
    location: (city: 'San Francisco', country: 'USA', zip: '94105'),
    employees: 150,
  );
  print('\nCompany: ${company.name}');
  print('Location: ${company.location.city}, ${company.location.country} ${company.location.zip}');
  print('Employees: ${company.employees}');

  // Using records for multiple return values
  (bool success, String? error, dynamic data) processData(String input) {
    if (input.isEmpty) {
      return (false, 'Input cannot be empty', null);
    }
    if (input.length < 3) {
      return (false, 'Input too short', null);
    }
    return (true, null, input.toUpperCase());
  }

  var result1 = processData('hello');
  if (result1.$1) {
    print('\nProcessed successfully: ${result1.$3}');
  } else {
    print('\nError: ${result1.$2}');
  }

  var result2 = processData('hi');
  if (!result2.$1) {
    print('Failed: ${result2.$2}');
  }

  // Record equality
  var point1 = (x: 10, y: 20);
  var point2 = (x: 10, y: 20);
  var point3 = (x: 15, y: 20);
  print('\npoint1 == point2: ${point1 == point2}'); // true
  print('point1 == point3: ${point1 == point3}'); // false

  // Using records with switch expressions
  String describePoint((int, int) point) {
    return switch (point) {
      (0, 0) => 'Origin',
      (var x, 0) => 'On X-axis at $x',
      (0, var y) => 'On Y-axis at $y',
      (var x, var y) when x == y => 'On diagonal at ($x, $y)',
      (var x, var y) => 'Point at ($x, $y)',
    };
  }

  print('\n${describePoint((0, 0))}');
  print('${describePoint((5, 0))}');
  print('${describePoint((0, 3))}');
  print('${describePoint((7, 7))}');
  print('${describePoint((2, 8))}');

  // Record type annotations
  ({String title, int year, double rating}) movie = (
    title: 'Inception',
    year: 2010,
    rating: 8.8,
  );
  print('\nMovie: ${movie.title} (${movie.year}) - Rating: ${movie.rating}');

  // Using records for configuration
  var config = (
    debug: true,
    timeout: Duration(seconds: 30),
    retries: 3,
    baseUrl: 'https://api.example.com',
  );

  print('\nConfiguration:');
  print('  Debug: ${config.debug}');
  print('  Timeout: ${config.timeout.inSeconds}s');
  print('  Retries: ${config.retries}');
  print('  Base URL: ${config.baseUrl}');

  // Records with methods (via extension)
  var rectangle = (width: 10.0, height: 5.0);
  double area = rectangle.width * rectangle.height;
  double perimeter = 2 * (rectangle.width + rectangle.height);
  print('\nRectangle: ${rectangle.width} x ${rectangle.height}');
  print('Area: $area, Perimeter: $perimeter');
}

