void main() async {
  // Example 1: Simple number generator
  print('Example 1: Number generator');
  await for (int number in generateNumbers(5)) {
    print('Generated: $number');
  }

  print('\nExample 2: Fibonacci sequence');
  await for (int fib in fibonacci(10)) {
    print('Fibonacci: $fib');
  }

  print('\nExample 3: Periodic timer stream');
  int count = 0;
  await for (String message in periodicMessages()) {
    print(message);
    count++;
    if (count >= 3) break; // Stop after 3 messages
  }

  print('\nExample 4: Stream with error handling');
  try {
    await for (int value in streamWithErrors()) {
      print('Value: $value');
    }
  } catch (e) {
    print('Caught error: $e');
  }

  print('\nExample 5: Nested async* streams');
  await for (String result in processData()) {
    print(result);
  }

  print('\nExample 6: Stream transformation');
  await for (int squared in transformStream(generateNumbers(4))) {
    print('Squared: $squared');
  }
}

// Simple async* generator function
Stream<int> generateNumbers(int max) async* {
  for (int i = 1; i <= max; i++) {
    await Future.delayed(Duration(milliseconds: 100));
    yield i;
  }
}

// Fibonacci sequence generator
Stream<int> fibonacci(int limit) async* {
  int a = 0, b = 1;
  while (a < limit) {
    yield a;
    int temp = a;
    a = b;
    b = temp + b;
    await Future.delayed(Duration(milliseconds: 50));
  }
}

// Periodic message generator
Stream<String> periodicMessages() async* {
  int counter = 0;
  while (true) {
    await Future.delayed(Duration(milliseconds: 200));
    yield 'Message ${++counter} at ${DateTime.now().millisecondsSinceEpoch}';
  }
}

// Stream that throws an error
Stream<int> streamWithErrors() async* {
  yield 1;
  await Future.delayed(Duration(milliseconds: 100));
  yield 2;
  await Future.delayed(Duration(milliseconds: 100));
  yield 3;
  throw Exception('Intentional error after 3');
}

// Nested async* with yield*
Stream<String> processData() async* {
  yield 'Starting processing...';
  yield* fetchDataChunks();
  yield 'Processing complete!';
}

Stream<String> fetchDataChunks() async* {
  for (int i = 1; i <= 3; i++) {
    await Future.delayed(Duration(milliseconds: 150));
    yield 'Data chunk $i';
  }
}

// Stream transformation
Stream<int> transformStream(Stream<int> input) async* {
  await for (int value in input) {
    yield value * value;
  }
}

