void main() {
  // Simple number generator
  Iterable<int> generateNumbers(int max) sync* {
    for (int i = 1; i <= max; i++) {
      yield i;
    }
  }

  // Fibonacci sequence generator
  Iterable<int> fibonacci(int count) sync* {
    int a = 0, b = 1;
    for (int i = 0; i < count; i++) {
      yield a;
      int temp = a + b;
      a = b;
      b = temp;
    }
  }

  // Generator with yield*
  Iterable<int> rangeWithStep(int start, int end, int step) sync* {
    for (int i = start; i <= end; i += step) {
      yield i;
    }
  }

  Iterable<int> combinedRanges() sync* {
    yield* rangeWithStep(0, 10, 2);  // Even numbers 0-10
    yield -1;  // Separator
    yield* rangeWithStep(1, 9, 2);   // Odd numbers 1-9
  }

  // Generator that filters another iterable
  Iterable<T> filter<T>(Iterable<T> source, bool Function(T) predicate) sync* {
    for (var item in source) {
      if (predicate(item)) {
        yield item;
      }
    }
  }

  // Recursive generator for tree traversal simulation
  Iterable<String> generateTree(String node, int depth) sync* {
    if (depth <= 0) return;

    yield node;
    yield* generateTree('$node.left', depth - 1);
    yield* generateTree('$node.right', depth - 1);
  }

  // Using the generators
  print('Numbers 1-5:');
  for (var num in generateNumbers(5)) {
    print('  $num');
  }

  print('\nFirst 10 Fibonacci numbers:');
  var fibs = fibonacci(10).toList();
  print('  $fibs');

  print('\nCombined ranges:');
  for (var num in combinedRanges()) {
    print('  $num');
  }

  print('\nFiltered even numbers from 1-20:');
  var allNumbers = generateNumbers(20);
  var evenNumbers = filter(allNumbers, (n) => n % 2 == 0);
  print('  ${evenNumbers.toList()}');

  print('\nTree traversal (depth 3):');
  for (var node in generateTree('root', 3)) {
    var indent = '  ' * node.split('.').length;
    print('$indent$node');
  }

  // Lazy evaluation demonstration
  print('\nLazy evaluation:');
  Iterable<int> expensiveGenerator() sync* {
    for (int i = 1; i <= 100; i++) {
      print('  Generating $i');
      yield i * i;
    }
  }

