    yield 'Starting';
    yield 'Processing';
    for (int i in [1, 2, 3]) {
      yield 'Step $i';
    }
    yield 'Finishing';
    yield 'Done';
  }

  print('\nState progression:');
  for (var state in stateGenerator()) {
    print('  State: $state');
  }

  // Infinite generator with take
  Iterable<int> infiniteCounter() sync* {
    int i = 0;
    while (true) {
      yield i++;
    }
  }

  print('\nFirst 10 from infinite counter:');
  var tenNumbers = infiniteCounter().take(10).toList();
  print('  $tenNumbers');

  // Generator composition
  Iterable<int> doubler(Iterable<int> source) sync* {
    for (var value in source) {
      yield value * 2;
    }
  }

  Iterable<int> addOne(Iterable<int> source) sync* {
    for (var value in source) {
      yield value + 1;
    }
  }

  print('\nComposed generators (double then add one):');
  var composed = addOne(doubler(generateNumbers(5)));
  print('  ${composed.toList()}');
}

