  // Any class can implement another class as if it were an interface

  // Create instances using different implementations
  var regularEmployee = Employee('Alice', 30, 'E001', 75000);
  var contractEmployee = Contractor('Bob', 35, 'C001', 500);
  var managerEmployee = Manager('Charlie', 40, 'M001', 95000, 5000);

  // All can be treated as Person since they implement the Person "interface"
  List<Person> people = [regularEmployee, contractEmployee, managerEmployee];

  print('=== Demonstrating Implicit Interfaces ===\n');

  // Polymorphic behavior through implicit interfaces
  for (var person in people) {
    person.introduce();
    person.work();
    print('');
  }

