void checkUserAccess(int age, bool isVerified, String role) {
  String accessLevel = switch (role) {
    'admin' when age >= 21 && isVerified => 'Full Admin Access',
    'admin' when age >= 21 && !isVerified => 'Limited Admin Access',
    'admin' => 'No Admin Access - Age/Verification Requirements Not Met',
    'moderator' when isVerified => 'Moderator Access Granted',
    'moderator' => 'Moderator Access Pending Verification',
    'user' when age >= 18 => 'Standard User Access',
    'user' when age >= 13 => 'Teen User Access',
    'user' => 'Child Safety Mode',
    _ => 'Unknown Role'
  };

  print('User: age=$age, verified=$isVerified, role=$role -> $accessLevel');
}

