  String grade = switch (score) {
    >= 90 when hasBonus && !hasLatePenalty => 'A+ with distinction',
    >= 90 when hasBonus => 'A+',
    >= 90 when hasLatePenalty => 'A-',
    >= 90 => 'A',
    >= 80 when hasBonus => 'B+',
    >= 80 when hasLatePenalty => 'B-',
    >= 80 => 'B',
    >= 70 when hasBonus => 'C+',
    >= 70 when hasLatePenalty => 'C-',
    >= 70 => 'C',
    >= 60 when !hasLatePenalty => 'D',
    >= 60 => 'D-',
    _ => 'F'
  };

  print('Score: $score, bonus=$hasBonus, late=$hasLatePenalty -> Grade: $grade');
}

void calculateDiscount(String membershipLevel, double purchaseAmount, bool isFirstPurchase) {
  double discount = switch (membershipLevel) {
    'gold' when purchaseAmount > 100 && isFirstPurchase => 0.30,
    'gold' when purchaseAmount > 100 => 0.25,
    'gold' when isFirstPurchase => 0.20,
    'gold' => 0.15,
    'silver' when purchaseAmount > 100 && isFirstPurchase => 0.20,
