    'silver' => 0.10,
    'bronze' when purchaseAmount > 150 => 0.10,
    'bronze' when isFirstPurchase => 0.08,
    'bronze' => 0.05,
    _ when isFirstPurchase => 0.05,
    _ => 0.0
  };

  double finalAmount = purchaseAmount * (1 - discount);
  print('Membership: $membershipLevel, Amount: \$${purchaseAmount.toStringAsFixed(2)}, '
        'First purchase: $isFirstPurchase -> Discount: ${(discount * 100).toStringAsFixed(0)}%, '
        'Final: \$${finalAmount.toStringAsFixed(2)}');
}

