bool matchWildcard(String pattern, String text) {
  int m = pattern.length;
  int n = text.length;

  // Create a 2D DP table
  List<List<bool>> dp = List.generate(m + 1, (_) => List.filled(n + 1, false));

  // Empty pattern matches empty string
  dp[0][0] = true;

  // Handle patterns with * at the beginning
  for (int i = 1; i <= m; i++) {
    if (pattern[i - 1] == '*') {
      dp[i][0] = dp[i - 1][0];
    }
  }

  // Fill the DP table
  for (int i = 1; i <= m; i++) {
    for (int j = 1; j <= n; j++) {
      if (pattern[i - 1] == '*') {
        // * matches zero or more characters
        dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
      } else if (pattern[i - 1] == '?' || pattern[i - 1] == text[j - 1]) {
        // ? matches exactly one character, or characters match
        dp[i][j] = dp[i - 1][j - 1];
      }
    }
  }

  return dp[m][n];
}

