  // Dart has limited SIMD support through Float32x4 and Int32x4
  // These provide 128-bit SIMD operations

  print('=== SIMD Operations Demo ===\n');

  // Float32x4 operations
  print('Float32x4 Operations:');

  // Create two Float32x4 vectors
  var vector1 = Float32x4(1.0, 2.0, 3.0, 4.0);
  var vector2 = Float32x4(5.0, 6.0, 7.0, 8.0);

  print('Vector 1: ${vector1.x}, ${vector1.y}, ${vector1.z}, ${vector1.w}');
  print('Vector 2: ${vector2.x}, ${vector2.y}, ${vector2.z}, ${vector2.w}');

  // Addition
  var sum = vector1 + vector2;
  print('Sum: ${sum.x}, ${sum.y}, ${sum.z}, ${sum.w}');

  // Subtraction
  var diff = vector2 - vector1;
  print('Difference: ${diff.x}, ${diff.y}, ${diff.z}, ${diff.w}');

  // Multiplication
  var product = vector1 * vector2;
  print('Product: ${product.x}, ${product.y}, ${product.z}, ${product.w}');

  // Division
  var quotient = vector2 / vector1;
  print('Quotient: ${quotient.x}, ${quotient.y}, ${quotient.z}, ${quotient.w}');

  // Square root
  var sqrt = vector1.sqrt();
  print('Square root of vector1: ${sqrt.x}, ${sqrt.y}, ${sqrt.z}, ${sqrt.w}');

  // Min and Max
  var minVec = vector1.min(vector2);
  var maxVec = vector1.max(vector2);
  print('Min: ${minVec.x}, ${minVec.y}, ${minVec.z}, ${minVec.w}');
  print('Max: ${maxVec.x}, ${maxVec.y}, ${maxVec.z}, ${maxVec.w}');

  // Shuffle operations
  var shuffled = vector1.shuffle(Float32x4.wzyx);
  print('Shuffled (wzyx): ${shuffled.x}, ${shuffled.y}, ${shuffled.z}, ${shuffled.w}');

  // Int32x4 operations
  print('\nInt32x4 Operations:');

  var intVec1 = Int32x4(10, 20, 30, 40);
  var intVec2 = Int32x4(5, 15, 25, 35);

  print('Int Vector 1: ${intVec1.x}, ${intVec1.y}, ${intVec1.z}, ${intVec1.w}');
  print('Int Vector 2: ${intVec2.x}, ${intVec2.y}, ${intVec2.z}, ${intVec2.w}');

  // Bitwise operations
  var andResult = intVec1 & intVec2;
  var orResult = intVec1 | intVec2;
  var xorResult = intVec1 ^ intVec2;

  print('AND: ${andResult.x}, ${andResult.y}, ${andResult.z}, ${andResult.w}');
  print('OR: ${orResult.x}, ${orResult.y}, ${orResult.z}, ${orResult.w}');
  print('XOR: ${xorResult.x}, ${xorResult.y}, ${xorResult.z}, ${xorResult.w}');

  // Addition and subtraction
  var intSum = intVec1 + intVec2;
  var intDiff = intVec1 - intVec2;

  print('Sum: ${intSum.x}, ${intSum.y}, ${intSum.z}, ${intSum.w}');
  print('Difference: ${intDiff.x}, ${intDiff.y}, ${intDiff.z}, ${intDiff.w}');

  // Practical example: Vector dot product using SIMD
  print('\nPractical Example - Dot Product:');

  var a = Float32x4(2.0, 3.0, 4.0, 5.0);
  var b = Float32x4(6.0, 7.0, 8.0, 9.0);

  // Element-wise multiplication
  var mult = a * b;
  // Sum all components for dot product
  var dotProduct = mult.x + mult.y + mult.z + mult.w;
  print('Dot product of [2,3,4,5] and [6,7,8,9]: $dotProduct');

  // Performance comparison example
  print('\nPerformance Comparison:');

  const iterations = 1000000;
  var list1 = Float32List(4);
  var list2 = Float32List(4);
  var result = Float32List(4);

  // Initialize arrays
  for (int i = 0; i < 4; i++) {
    list1[i] = i + 1.0;
    list2[i] = i + 5.0;
  }

  // Traditional approach
  var startTime = DateTime.now().microsecondsSinceEpoch;
  for (int iter = 0; iter < iterations; iter++) {
    for (int i = 0; i < 4; i++) {
      result[i] = list1[i] + list2[i];
    }
  }
  var traditionalTime = DateTime.now().microsecondsSinceEpoch - startTime;

  // SIMD approach
  var simdVec1 = Float32x4(list1[0], list1[1], list1[2], list1[3]);
  var simdVec2 = Float32x4(list2[0], list2[1], list2[2], list2[3]);
  Float32x4 simdResult;

  startTime = DateTime.now().microsecondsSinceEpoch;
  for (int iter = 0; iter < iterations; iter++) {
    simdResult = simdVec1 + simdVec2;
  }
  var simdTime = DateTime.now().microsecondsSinceEpoch - startTime;

  print('Traditional approach time: ${traditionalTime} microseconds');
  print('SIMD approach time: ${simdTime} microseconds');
  print('Speedup: ${(traditionalTime / simdTime).toStringAsFixed(2)}x');

  // Matrix operations example using SIMD
  print('\nMatrix Row Addition using SIMD:');

  var row1 = Float32x4(1.0, 2.0, 3.0, 4.0);
  var row2 = Float32x4(5.0, 6.0, 7.0, 8.0);
  var row3 = Float32x4(9.0, 10.0, 11.0, 12.0);
  var row4 = Float32x4(13.0, 14.0, 15.0, 16.0);

  var scalar = Float32x4.splat(2.0); // Create vector with all same values

  // Scale each row by 2
  var scaledRow1 = row1 * scalar;
  var scaledRow2 = row2 * scalar;
  var scaledRow3 = row3 * scalar;
  var scaledRow4 = row4 * scalar;

  print('Scaled Row 1: ${scaledRow1.x}, ${scaledRow1.y}, ${scaledRow1.z}, ${scaledRow1.w}');
  print('Scaled Row 2: ${scaledRow2.x}, ${scaledRow2.y}, ${scaledRow2.z}, ${scaledRow2.w}');
  print('Scaled Row 3: ${scaledRow3.x}, ${scaledRow3.y}, ${scaledRow3.z}, ${scaledRow3.w}');
  print('Scaled Row 4: ${scaledRow4.x}, ${scaledRow4.y}, ${scaledRow4.z}, ${scaledRow4.w}');

  // Color manipulation example (RGBA)
  print('\nColor Manipulation Example:');

  var color1 = Float32x4(0.5, 0.3, 0.8, 1.0); // RGBA
  var color2 = Float32x4(0.2, 0.6, 0.1, 1.0);

  // Blend colors (50% mix)
  var blendFactor = Float32x4.splat(0.5);
  var blended = (color1 * blendFactor) + (color2 * blendFactor);

  print('Color 1 (RGBA): ${color1.x}, ${color1.y}, ${color1.z}, ${color1.w}');
  print('Color 2 (RGBA): ${color2.x}, ${color2.y}, ${color2.z}, ${color2.w}');
  print('Blended (RGBA): ${blended.x}, ${blended.y}, ${blended.z}, ${blended.w}');

  // Clamp values between 0 and 1
  var clamped = blended.clamp(Float32x4.zero(), Float32x4(1.0, 1.0, 1.0, 1.0));
  print('Clamped (RGBA): ${clamped.x}, ${clamped.y}, ${clamped.z}, ${clamped.w}');
}

