import 'dart:isolate';
import 'dart:async';

@pragma('vm:entry-point')
void main() async {
  // Create a ReceivePort for the main isolate
  final mainReceivePort = ReceivePort();

  // Spawn a new isolate with the entry point function
  final isolate = await Isolate.spawn(
    (SendPort sendPort) {
      // This code runs in the spawned isolate
      print('Spawned isolate started');

      // Create a ReceivePort for bidirectional communication
      final isolateReceivePort = ReceivePort();

      // Send the isolate's SendPort back to main
      sendPort.send(isolateReceivePort.sendPort);

      // Listen for messages from main isolate
      isolateReceivePort.listen((message) {
        print('Spawned isolate received: $message');

        if (message is String) {
          // Process the message
          final processed = 'Processed: ${message.toUpperCase()}';
          sendPort.send(processed);

          // Exit condition
          if (message == 'exit') {
            print('Spawned isolate shutting down');
            isolateReceivePort.close();
          }
        } else if (message is List<int>) {
          // Calculate sum of numbers
          final sum = message.reduce((a, b) => a + b);
          sendPort.send('Sum of ${message}: $sum');
        }
      });
    },
    mainReceivePort.sendPort,
  );

  // Variables to store the spawned isolate's SendPort
  SendPort? isolateSendPort;
  final completer = Completer<void>();

  // Listen for messages from the spawned isolate
  mainReceivePort.listen((message) {
    if (message is SendPort) {
      // First message should be the SendPort from spawned isolate
      isolateSendPort = message;
      completer.complete();
      print('Main: Received SendPort from spawned isolate');
    } else {
      // Handle other messages from spawned isolate
      print('Main received response: $message');
    }
  });

  // Wait for the SendPort from spawned isolate
  await completer.future;

  // Send various messages to the spawned isolate
  print('\nSending messages to spawned isolate...\n');

  isolateSendPort!.send('hello world');
  await Future.delayed(Duration(milliseconds: 100));

  isolateSendPort!.send('dart isolates');
  await Future.delayed(Duration(milliseconds: 100));

  isolateSendPort!.send([1, 2, 3, 4, 5]);
  await Future.delayed(Duration(milliseconds: 100));

  isolateSendPort!.send([10, 20, 30, 40, 50]);
  await Future.delayed(Duration(milliseconds: 100));

  // Demonstrate concurrent processing
  print('\nSending multiple messages concurrently...\n');
  for (int i = 0; i < 5; i++) {
    isolateSendPort!.send('message $i');
  }

  // Wait a bit for processing
  await Future.delayed(Duration(milliseconds: 500));

  // Send exit signal
  print('\nSending exit signal...\n');
  isolateSendPort!.send('exit');

  // Wait before cleaning up
  await Future.delayed(Duration(milliseconds: 200));

  // Clean up
  isolate.kill(priority: Isolate.immediate);
  mainReceivePort.close();

  print('Main: Program completed');
}

