void main() async {
  // Create a ReceivePort for the main isolate
  final mainReceivePort = ReceivePort();

  // Spawn a new isolate and pass the SendPort
  final isolate = await Isolate.spawn(
    (SendPort sendPort) async {
      // Create a ReceivePort in the spawned isolate
      final isolateReceivePort = ReceivePort();

      // Send the isolate's SendPort back to main
      sendPort.send(['ready', isolateReceivePort.sendPort]);

      // Listen for messages in the spawned isolate
      await for (final message in isolateReceivePort) {
        print('Isolate received: $message');

        if (message is String) {
          if (message == 'exit') {
            sendPort.send(['response', 'Goodbye from isolate!']);
            isolateReceivePort.close();
            break;
          } else {
            // Process the message and send response
            final processed = 'Processed: ${message.toUpperCase()}';
            sendPort.send(['response', processed]);
          }
        } else if (message is int) {
          // Square the number and send back
          final result = message * message;
          sendPort.send(['response', 'Square of $message is $result']);
        }
      }
    },
    mainReceivePort.sendPort,
  );

  // Variable to store the isolate's SendPort
  SendPort? isolateSendPort;

  // Create a completer to wait for the isolate to be ready
  final readyCompleter = Completer<void>();

  // Listen for messages from the spawned isolate
  final subscription = mainReceivePort.listen((message) {
    if (message is List && message.length == 2) {
      final type = message[0];
      final data = message[1];

      if (type == 'ready' && data is SendPort) {
        isolateSendPort = data;
        readyCompleter.complete();
        print('Main: Isolate is ready');
      } else if (type == 'response') {
        print('Main received response: $data');
      }
    }
  });

  // Wait for the isolate to be ready
  await readyCompleter.future;

  // Send various messages to the isolate
  print('\n--- Sending messages to isolate ---');

  isolateSendPort!.send('hello world');
  await Future.delayed(Duration(milliseconds: 100));

  isolateSendPort!.send('dart isolates');
  await Future.delayed(Duration(milliseconds: 100));

  isolateSendPort!.send(42);
  await Future.delayed(Duration(milliseconds: 100));

  isolateSendPort!.send(7);
  await Future.delayed(Duration(milliseconds: 100));

  // Send exit message
  print('\n--- Sending exit command ---');
  isolateSendPort!.send('exit');

  // Wait a bit for final response
  await Future.delayed(Duration(milliseconds: 200));

  // Clean up
  subscription.cancel();
  mainReceivePort.close();
  isolate.kill(priority: Isolate.immediate);

  print('\n--- Program completed ---');
}

