void main() {
  // Fixed-point math implementation using 16-bit fractional part
  // Format: 32.16 (32 bits for integer part, 16 bits for fractional part)
  const int FIXED_POINT_SHIFT = 16;
  const int FIXED_POINT_SCALE = 1 << FIXED_POINT_SHIFT; // 65536
  const int FRACTIONAL_MASK = FIXED_POINT_SCALE - 1;

  // Convert floating point to fixed point
  int toFixed(double value) {
    return (value * FIXED_POINT_SCALE).round();
  }

  // Convert fixed point to floating point (for display)
  double fromFixed(int fixed) {
    return fixed / FIXED_POINT_SCALE;
  }

  // Extract integer part
  int getIntegerPart(int fixed) {
    return fixed >> FIXED_POINT_SHIFT;
  }

  // Extract fractional part
  int getFractionalPart(int fixed) {
    return fixed & FRACTIONAL_MASK;
  }

  // Fixed-point addition
  int fixedAdd(int a, int b) {
    return a + b;
  }

  // Fixed-point subtraction
  int fixedSubtract(int a, int b) {
    return a - b;
  }

  // Fixed-point multiplication
  int fixedMultiply(int a, int b) {
    // Multiply and shift right to maintain scale
    int result = (a * b) >> FIXED_POINT_SHIFT;
    return result;
  }

  // Fixed-point division
  int fixedDivide(int a, int b) {
    if (b == 0) {
      throw ArgumentError('Division by zero');
    }
    // Shift left before division to maintain precision
    int result = (a << FIXED_POINT_SHIFT) ~/ b;
    return result;
  }

  // Fixed-point square root using Newton-Raphson method
  int fixedSqrt(int x) {
    if (x < 0) {
      throw ArgumentError('Cannot compute square root of negative number');
    }
    if (x == 0) return 0;

    // Initial guess (convert to fixed point space)
    int guess = x;
    int prev = 0;
    int one = toFixed(1.0);

    // Newton-Raphson iterations
    for (int i = 0; i < 20; i++) {
      if (guess == prev) break;
      prev = guess;
      // guess = (guess + x/guess) / 2
      int quotient = fixedDivide(x, guess);
      guess = (guess + quotient) >> 1;
    }

    return guess;
  }

  // Fixed-point sine approximation using Taylor series
  int fixedSin(int angle) {
    // Normalize angle to [-π, π]
    int twoPi = toFixed(6.283185307179586);
    int pi = toFixed(3.141592653589793);

    // Reduce angle to primary range
    while (angle > pi) angle -= twoPi;
    while (angle < -pi) angle += twoPi;

    // Taylor series: sin(x) = x - x³/3! + x⁵/5! - x⁷/7! + ...
    int x = angle;
    int x2 = fixedMultiply(x, x);
    int x3 = fixedMultiply(x2, x);
    int x5 = fixedMultiply(x3, x2);
    int x7 = fixedMultiply(x5, x2);

    // Factorial constants in fixed point
    int fact3 = toFixed(1.0 / 6.0);
    int fact5 = toFixed(1.0 / 120.0);
    int fact7 = toFixed(1.0 / 5040.0);

    int result = x;
    result = fixedSubtract(result, fixedMultiply(x3, fact3));
    result = fixedAdd(result, fixedMultiply(x5, fact5));
    result = fixedSubtract(result, fixedMultiply(x7, fact7));

    return result;
  }

  // Fixed-point cosine using sine
  int fixedCos(int angle) {
    int halfPi = toFixed(1.5707963267948966);
    return fixedSin(fixedAdd(angle, halfPi));
  }

  // Demonstration
