  List<int> toLittleEndianBytes(int value) {
    return [
      value & 0xFF,
      (value >> 8) & 0xFF,
      (value >> 16) & 0xFF,
      (value >> 24) & 0xFF,
    ];
  }

  // Convert bytes to 32-bit integer (Big Endian)
  int fromBigEndianBytes(List<int> bytes) {
    return (bytes[0] << 24) | (bytes[1] << 16) | (bytes[2] << 8) | bytes[3];
  }

  // Convert bytes to 32-bit integer (Little Endian)
  int fromLittleEndianBytes(List<int> bytes) {
    return (bytes[3] << 24) | (bytes[2] << 16) | (bytes[1] << 8) | bytes[0];
  }

