    'Small Mobile': {'width': 320.0, 'height': 568.0}, // iPhone SE
  };

  // Breakpoint definitions
  const mobileBreakpoint = 600.0;
  const tabletBreakpoint = 1024.0;

  // Component sizing ratios
  const headerHeightRatio = 0.08;
  const sidebarWidthRatio = 0.25;
  const cardMinWidth = 280.0;
  const spacing = 16.0;

  print('=== Responsive UI Layout Calculator ===\n');

  for (var entry in devices.entries) {
    final deviceName = entry.key;
    final width = entry.value['width']!;
    final height = entry.value['height']!;

    print('Device: $deviceName (${width}x${height})');
    print('-' * 40);

    // Determine device type based on breakpoints
    String deviceType;
    if (width < mobileBreakpoint) {
      deviceType = 'Mobile';
    } else if (width < tabletBreakpoint) {
      deviceType = 'Tablet';
    } else {
      deviceType = 'Desktop';
    }
    print('Device Type: $deviceType');

    // Calculate responsive header height
    double headerHeight = height * headerHeightRatio;
    if (deviceType == 'Mobile') {
      headerHeight = headerHeight.clamp(56.0, 64.0);
    } else if (deviceType == 'Tablet') {
      headerHeight = headerHeight.clamp(64.0, 80.0);
    } else {
      headerHeight = headerHeight.clamp(80.0, 100.0);
    }
    print('Header Height: ${headerHeight.toStringAsFixed(1)}px');

    // Calculate sidebar width (only for tablet and desktop)
    double sidebarWidth = 0;
    if (deviceType != 'Mobile') {
      sidebarWidth = width * sidebarWidthRatio;
      sidebarWidth = sidebarWidth.clamp(200.0, 350.0);
      print('Sidebar Width: ${sidebarWidth.toStringAsFixed(1)}px');
    } else {
      print('Sidebar: Hidden (Mobile View)');
    }

    // Calculate main content area
    double contentWidth = width - sidebarWidth - (sidebarWidth > 0 ? spacing * 2 : spacing * 2);
    double contentHeight = height - headerHeight - spacing * 2;
    print('Content Area: ${contentWidth.toStringAsFixed(1)} x ${contentHeight.toStringAsFixed(1)}px');

    // Calculate grid layout for cards
    int columns = (contentWidth / cardMinWidth).floor();
    columns = columns.clamp(1, 6);
    double actualCardWidth = (contentWidth - (columns - 1) * spacing) / columns;
    print('Card Grid: $columns columns, ${actualCardWidth.toStringAsFixed(1)}px per card');

    // Calculate responsive font sizes
    double baseFontSize;
    double headingMultiplier;
    if (deviceType == 'Mobile') {
      baseFontSize = 14.0;
      headingMultiplier = 1.5;
    } else if (deviceType == 'Tablet') {
      baseFontSize = 16.0;
      headingMultiplier = 1.75;
    } else {
      baseFontSize = 18.0;
      headingMultiplier = 2.0;
