    print('\nTypography:');
    print('  Base Font: ${baseFontSize.toStringAsFixed(1)}px');
    print('  Heading 1: ${(baseFontSize * headingMultiplier).toStringAsFixed(1)}px');
    print('  Heading 2: ${(baseFontSize * (headingMultiplier * 0.8)).toStringAsFixed(1)}px');
    print('  Body Text: ${baseFontSize.toStringAsFixed(1)}px');
    print('  Caption: ${(baseFontSize * 0.85).toStringAsFixed(1)}px');

    // Calculate responsive padding and margins
    double containerPadding;
    double elementSpacing;
    if (deviceType == 'Mobile') {
      containerPadding = 12.0;
      elementSpacing = 8.0;
    } else if (deviceType == 'Tablet') {
      containerPadding = 20.0;
      elementSpacing = 12.0;
    } else {
