    print('  Element Spacing: ${elementSpacing.toStringAsFixed(1)}px');

    // Calculate navigation layout
    print('\nNavigation:');
    if (deviceType == 'Mobile') {
      print('  Type: Bottom Navigation Bar');
      print('  Height: 56px');
      print('  Items: Icons only');
    } else if (deviceType == 'Tablet') {
      print('  Type: Side Navigation Rail');
      print('  Width: 72px (collapsed) / ${sidebarWidth.toStringAsFixed(1)}px (expanded)');
      print('  Items: Icons with labels');
    } else {
      print('  Type: Full Sidebar');
      print('  Width: ${sidebarWidth.toStringAsFixed(1)}px');
      print('  Items: Icons with full text labels');
    }

    // Calculate modal/dialog sizes
    double modalWidth;
    double modalHeight;
    if (deviceType == 'Mobile') {
      modalWidth = width * 0.9;
      modalHeight = height * 0.7;
    } else if (deviceType == 'Tablet') {
      modalWidth = width * 0.7;
      modalHeight = height * 0.6;
