void main() {
  // In-App Purchase System Simulation
  print('=== In-App Purchase System ===\n');

  // Product catalog
  final products = {
    'premium_upgrade': Product('premium_upgrade', 'Premium Upgrade', 9.99, ProductType.nonConsumable),
    'remove_ads': Product('remove_ads', 'Remove Ads', 4.99, ProductType.nonConsumable),
