    'yearly_subscription': Product('yearly_subscription', 'Yearly VIP', 39.99, ProductType.subscription),
  };

  // User account
  final user = User('user123', 'John Doe');
  final purchaseManager = PurchaseManager();

  // Display available products
  print('Available Products:');
  products.forEach((id, product) {
    print('  ${product.id}: ${product.name} - \$${product.price}');
  });
  print('');

  // Simulate purchase flow
  print('Simulating purchase flow...\n');

  // Purchase 100 coins
  var coinsPurchase = products['100_coins']!;
  print('Attempting to purchase: ${coinsPurchase.name}');
  var transaction = purchaseManager.initiatePurchase(user, coinsPurchase);

  if (purchaseManager.processPurchase(transaction)) {
    print('✓ Purchase successful!');
    user.addPurchase(transaction);
    if (coinsPurchase.type == ProductType.consumable) {
      user.coins += 100;
      print('  Added 100 coins to account. Total coins: ${user.coins}');
    }
  }
  print('');

  // Purchase premium upgrade
  var premiumPurchase = products['premium_upgrade']!;
  print('Attempting to purchase: ${premiumPurchase.name}');
  transaction = purchaseManager.initiatePurchase(user, premiumPurchase);

  if (purchaseManager.processPurchase(transaction)) {
    print('✓ Purchase successful!');
    user.addPurchase(transaction);
    user.isPremium = true;
    print('  Account upgraded to Premium!');
  }
  print('');

  // Try to purchase premium again (should fail - already owned)
  print('Attempting to purchase Premium again...');
  if (user.hasPurchased('premium_upgrade')) {
    print('✗ Already owned! Purchase cancelled.');
  }
  print('');

  // Purchase monthly subscription
  var subscription = products['monthly_subscription']!;
  print('Attempting to purchase: ${subscription.name}');
  transaction = purchaseManager.initiatePurchase(user, subscription);

  if (purchaseManager.processPurchase(transaction)) {
    print('✓ Subscription activated!');
    user.addPurchase(transaction);
    user.activeSubscription = subscription.id;
    print('  Monthly VIP subscription active until: ${DateTime.now().add(Duration(days: 30))}');
  }
  print('');

  // Restore purchases
  print('Restoring purchases...');
  var restoredPurchases = purchaseManager.restorePurchases(user.id);
  print('  Found ${restoredPurchases.length} purchases to restore');
  for (var purchase in restoredPurchases) {
    print('  ✓ Restored: ${purchase.productId}');
  }
  print('');

  // Display user account summary
  print('=== Account Summary ===');
  print('User: ${user.name}');
  print('Premium Status: ${user.isPremium ? "Active" : "Inactive"}');
  print('Coins: ${user.coins}');
  print('Active Subscription: ${user.activeSubscription ?? "None"}');
  print('Total Purchases: ${user.purchaseHistory.length}');
  print('Total Spent: \$${user.getTotalSpent().toStringAsFixed(2)}');
  print('');

  // Display purchase history
  print('=== Purchase History ===');
  for (var purchase in user.purchaseHistory) {
    var product = products[purchase.productId]!;
    print('  ${purchase.timestamp}: ${product.name} - \$${product.price}');
  }
  print('');

  // Validate receipts
