    userPreferences.forEach((user, theme) {
      print('  $user: $theme');
    });
  }
}

// Contrast ratio calculator
double calculateContrastRatio(Color bg, Color fg) {
  double bgLuminance = bg.luminance;
  double fgLuminance = fg.luminance;

  double lighter = bgLuminance > fgLuminance ? bgLuminance : fgLuminance;
  double darker = bgLuminance > fgLuminance ? fgLuminance : bgLuminance;

  return (lighter + 0.05) / (darker + 0.05);
}

