      'email': true,
      'push': false,
      'sms': true
    },
    'privacy': {
      'profileVisibility': 'public',
      'showEmail': false,
      'showPhone': false,
      'allowDataCollection': true
    },
    'display': {
      'fontSize': 14,
      'fontFamily': 'Arial',
      'compactMode': false,
      'showAvatars': true
    },
    'accessibility': {
      'highContrast': false,
      'screenReader': false,
      'reduceMotion': false,
      'keyboardNavigation': true
    },
    'account': {
      'username': 'john_doe',
      'email': 'john@example.com',
      'timezone': 'UTC',
      'dateFormat': 'MM/DD/YYYY'
    }
  };

  // Function to display current settings
  void displaySettings() {
    print('\n' + '=' * 50);
    print('CURRENT USER SETTINGS');
    print('=' * 50);

    userSettings.forEach((category, value) {
      print('\n[$category]');
      if (value is Map) {
        value.forEach((key, val) {
          print('  $key: $val');
        });
      } else {
        print('  $value');
      }
    });
  }

  // Function to update a setting
  void updateSetting(String category, String key, dynamic value) {
    if (userSettings.containsKey(category)) {
      if (userSettings[category] is Map) {
        userSettings[category][key] = value;
        print('✓ Updated $category.$key to $value');
      } else {
        userSettings[category] = value;
        print('✓ Updated $category to $value');
      }
    } else {
      print('✗ Category "$category" not found');
    }
  }

  // Function to validate settings
  bool validateSettings() {
    bool isValid = true;
    List<String> errors = [];

    // Validate theme
    List<String> validThemes = ['light', 'dark', 'auto'];
    if (!validThemes.contains(userSettings['theme'])) {
      errors.add('Invalid theme: ${userSettings['theme']}');
      isValid = false;
    }

    // Validate language
    List<String> validLanguages = ['en', 'es', 'fr', 'de', 'ja'];
    if (!validLanguages.contains(userSettings['language'])) {
      errors.add('Invalid language: ${userSettings['language']}');
      isValid = false;
    }

    // Validate font size
    int fontSize = userSettings['display']['fontSize'];
    if (fontSize < 8 || fontSize > 32) {
      errors.add('Font size must be between 8 and 32');
      isValid = false;
    }

    // Validate profile visibility
    List<String> validVisibility = ['public', 'private', 'friends'];
    if (!validVisibility.contains(userSettings['privacy']['profileVisibility'])) {
      errors.add('Invalid profile visibility setting');
      isValid = false;
    }

    if (!isValid) {
      print('\n⚠ Validation Errors:');
      errors.forEach((error) => print('  - $error'));
    } else {
      print('\n✓ All settings are valid');
    }

    return isValid;
  }

  // Function to reset settings to defaults
  void resetToDefaults() {
    userSettings = {
      'theme': 'light',
      'language': 'en',
      'notifications': {
        'email': true,
        'push': true,
        'sms': false
      },
      'privacy': {
        'profileVisibility': 'friends',
        'showEmail': false,
        'showPhone': false,
        'allowDataCollection': false
      },
      'display': {
        'fontSize': 14,
        'fontFamily': 'Arial',
        'compactMode': false,
        'showAvatars': true
      },
      'accessibility': {
        'highContrast': false,
        'screenReader': false,
        'reduceMotion': false,
        'keyboardNavigation': true
      },
      'account': {
        'username': 'user',
        'email': 'user@example.com',
        'timezone': 'UTC',
        'dateFormat': 'MM/DD/YYYY'
      }
    };
    print('\n✓ Settings reset to defaults');
  }

  // Function to export settings as JSON-like string
  String exportSettings() {
    StringBuffer buffer = StringBuffer();
    buffer.writeln('{');

    int categoryIndex = 0;
    userSettings.forEach((category, value) {
      buffer.write('  "$category": ');
      if (value is Map) {
        buffer.writeln('{');
        int itemIndex = 0;
        value.forEach((key, val) {
          buffer.write('    "$key": ');
          if (val is String) {
            buffer.write('"$val"');
          } else {
            buffer.write(val);
          }
          if (itemIndex < value.length - 1) buffer.write(',');
          buffer.writeln();
          itemIndex++;
        });
        buffer.write('  }');
      } else {
        if (value is String) {
          buffer.write('"$value"');
        } else {
          buffer.write(value);
        }
      }
      if (categoryIndex < userSettings.length - 1) buffer.write(',');
      buffer.writeln();
      categoryIndex++;
    });

    buffer.writeln('}');
    return buffer.toString();
  }

  // Function to create a settings profile
  Map<String, dynamic> createProfile(String profileName) {
    return {
      'name': profileName,
      'created': DateTime.now().toIso8601String(),
      'settings': Map<String, dynamic>.from(userSettings)
    };
  }

