  print('=' * 50);

  // Display initial settings
  displaySettings();

  // Demonstrate updating settings
  print('\n\n--- UPDATING SETTINGS ---');
  updateSetting('theme', '', 'dark');
  updateSetting('display', 'fontSize', 16);
  updateSetting('notifications', 'push', true);
  updateSetting('privacy', 'profileVisibility', 'private');
  updateSetting('accessibility', 'highContrast', true);

  // Validate settings
  print('\n--- VALIDATING SETTINGS ---');
  validateSettings();

  // Display updated settings
  print('\n--- UPDATED SETTINGS ---');
  displaySettings();

  // Create a profile
  print('\n\n--- CREATING PROFILE ---');
  Map<String, dynamic> workProfile = createProfile('Work Profile');
  print('Created profile: ${workProfile['name']}');
  print('Created at: ${workProfile['created']}');

  // Export settings
  print('\n--- EXPORTED SETTINGS ---');
  String exported = exportSettings();
  print(exported);

  // Demonstrate invalid setting
  print('\n--- TESTING INVALID SETTINGS ---');
  updateSetting('theme', '', 'invalid_theme');
  updateSetting('display', 'fontSize', 100);
  validateSettings();

  // Reset to defaults
  print('\n--- RESETTING TO DEFAULTS ---');
  resetToDefaults();
  displaySettings();

  // Settings statistics
  print('\n\n--- SETTINGS STATISTICS ---');
  int totalSettings = 0;
  int enabledSettings = 0;

  userSettings.forEach((category, value) {
    if (value is Map) {
      value.forEach((key, val) {
        totalSettings++;
        if (val == true) enabledSettings++;
      });
    } else {
      totalSettings++;
    }
  });

  print('Total settings: $totalSettings');
  print('Enabled boolean settings: $enabledSettings');
  print('Categories: ${userSettings.keys.length}');

  // Privacy report
  print('\n--- PRIVACY REPORT ---');
  Map privacy = userSettings['privacy'];
  print('Profile Visibility: ${privacy['profileVisibility']}');
  print('Data Sharing:');
  print('  - Email visible: ${privacy['showEmail']}');
  print('  - Phone visible: ${privacy['showPhone']}');
  print('  - Data collection: ${privacy['allowDataCollection']}');

  // Accessibility report
  print('\n--- ACCESSIBILITY REPORT ---');
  Map accessibility = userSettings['accessibility'];
  int accessibilityEnabled = 0;
  accessibility.forEach((key, value) {
    if (value == true) {
      print('  ✓ $key enabled');
      accessibilityEnabled++;
    } else {
      print('  ✗ $key disabled');
    }
  });
  print('Accessibility features enabled: $accessibilityEnabled/${accessibility.length}');
}

