  final gesturePatterns = {
    'swipe_left': 'left',
    'swipe_right': 'right',
    'swipe_up': 'up',
    'swipe_down': 'down',
    'double_tap': 'back',
    'long_press': 'home',
    'pinch': 'menu',
    'rotate': 'refresh'
  };

  // Function to process gesture
  void processGesture(String gesture) {
    print('\n🎯 Gesture detected: $gesture');
    gestureHistory.add(gesture);

    if (gesture == 'double_tap') {
      // Go back
      if (navigationStack.length > 1) {
        navigationStack.removeLast();
        currentScreen = navigationStack.last;
        print('↩️  Navigating back to: $currentScreen');
      } else {
        print('⚠️  Already at root screen');
      }
    } else if (gesture == 'long_press') {
      // Go home
      currentScreen = 'Home';
      navigationStack = ['Home'];
      print('🏠 Returning to Home');
    } else if (gesture == 'pinch') {
      // Show menu
      print('📱 Opening menu...');
      print('   Available screens: ${screens.keys.join(', ')}');
