      // Refresh current screen
      print('🔄 Refreshing $currentScreen...');
    } else if (gesturePatterns.containsKey(gesture)) {
      // Navigate based on swipe direction
      var direction = gesturePatterns[gesture]!;
      if (screens[currentScreen]?.containsKey(direction) ?? false) {
        var nextScreen = screens[currentScreen]![direction]!;
        currentScreen = nextScreen;
        navigationStack.add(nextScreen);
        print('➡️  Navigating to: $nextScreen');
      } else {
        print('⚠️  No navigation available for $gesture from $currentScreen');
