  int paddingLength = blockSize - (plaintextBytes.length % blockSize);
  if (paddingLength == 0) paddingLength = blockSize;

  // PKCS7 padding
  final paddedData = Uint8List(plaintextBytes.length + paddingLength);
  paddedData.setRange(0, plaintextBytes.length, plaintextBytes);
  for (int i = plaintextBytes.length; i < paddedData.length; i++) {
    paddedData[i] = paddingLength;
  }

