  Uint8List innerData = Uint8List(ipad.length + encrypted.length);
  innerData.setRange(0, ipad.length, ipad);
  innerData.setRange(ipad.length, innerData.length, encrypted);

  int innerHash = simpleHash(innerData);
  Uint8List innerHashBytes = Uint8List(4);
  innerHashBytes[0] = (innerHash >> 24) & 0xFF;
  innerHashBytes[1] = (innerHash >> 16) & 0xFF;
  innerHashBytes[2] = (innerHash >> 8) & 0xFF;
  innerHashBytes[3] = innerHash & 0xFF;

  Uint8List outerData = Uint8List(opad.length + 4);
  outerData.setRange(0, opad.length, opad);
  outerData.setRange(opad.length, outerData.length, innerHashBytes);

  int hmac = simpleHash(outerData);
  print("\nHMAC: ${hmac.toRadixString(16).padLeft(8, '0')}");

  // Key derivation using PBKDF2-like function
  String password = "MySecurePassword123!";
  Uint8List salt = Uint8List.fromList(List.generate(16, (_) => random.nextInt(256)));
  int iterations = 1000;

  Uint8List derivedKey = Uint8List(32);
  Uint8List passwordBytes = Uint8List.fromList(utf8.encode(password));

  for (int i = 0; i < derivedKey.length; i++) {
    int value = passwordBytes[i % passwordBytes.length];
    for (int j = 0; j < iterations; j++) {
      value = (value + salt[j % salt.length]) & 0xFF;
      value = ((value << 1) | (value >> 7)) & 0xFF;
      value ^= (j & 0xFF);
    }
    derivedKey[i] = value;
  }

  print("\nDerived key from password: ${base64.encode(derivedKey)}");

  // Secure random token generation
  Uint8List secureToken = Uint8List(32);
  for (int i = 0; i < secureToken.length; i++) {
    secureToken[i] = random.nextInt(256);
  }

  String tokenHex = secureToken.map((b) => b.toRadixString(16).padLeft(2, '0')).join();
  print("\nSecure token (hex): $tokenHex");

  // Verification
  if (decryptedText == plaintext) {
    print("\n✓ Encryption and decryption successful!");
  } else {
    print("\n✗ Encryption/decryption failed!");
  }

  // Security summary
  print("\n=== Security Summary ===");
  print("Key size: ${key.length * 8} bits");
  print("IV size: ${iv.length * 8} bits");
  print("Block size: $blockSize bytes");
  print("Padding scheme: PKCS7");
  print("Mode of operation: CBC");
  print("HMAC key size: ${hmacKey.length * 8} bits");
  print("PBKDF iterations: $iterations");
  print("Salt size: ${salt.length * 8} bits");
}
