@pragma('vm:entry-point')
void main() {
  // Sample data - list of products
  final products = [
    {'name': 'Laptop', 'category': 'Electronics', 'price': 999.99, 'inStock': true},
    {'name': 'Mouse', 'category': 'Electronics', 'price': 25.50, 'inStock': true},
    {'name': 'Desk', 'category': 'Furniture', 'price': 450.00, 'inStock': false},
    {'name': 'Chair', 'category': 'Furniture', 'price': 199.99, 'inStock': true},
    {'name': 'Monitor', 'category': 'Electronics', 'price': 350.00, 'inStock': true},
    {'name': 'Keyboard', 'category': 'Electronics', 'price': 75.00, 'inStock': false},
    {'name': 'Bookshelf', 'category': 'Furniture', 'price': 120.00, 'inStock': true},
    {'name': 'Headphones', 'category': 'Electronics', 'price': 89.99, 'inStock': true},
  ];

  // Dynamic filter function
  List<Map<String, dynamic>> dynamicFilter(
    List<Map<String, dynamic>> items,
    Map<String, dynamic> filters,
  ) {
    return items.where((item) {
      for (final entry in filters.entries) {
        final key = entry.key;
        final filterValue = entry.value;

        if (!item.containsKey(key)) return false;

        final itemValue = item[key];

        // Handle different filter types
        if (filterValue is Function) {
          if (!filterValue(itemValue)) return false;
        } else if (filterValue is List) {
          if (!filterValue.contains(itemValue)) return false;
        } else if (filterValue is Map) {
          // Range filter for numeric values
          if (filterValue.containsKey('min') && itemValue is num) {
            if (itemValue < filterValue['min']) return false;
          }
          if (filterValue.containsKey('max') && itemValue is num) {
            if (itemValue > filterValue['max']) return false;
          }
        } else {
          // Direct equality check
          if (itemValue != filterValue) return false;
        }
      }
      return true;
    }).toList();
  }

  // Example 1: Filter by category
  print('=== Filter by Electronics Category ===');
  var filtered = dynamicFilter(products, {'category': 'Electronics'});
  for (var product in filtered) {
    print('${product['name']} - \$${product['price']}');
  }

  // Example 2: Filter by multiple criteria
  print('\n=== Filter by Furniture Category and In Stock ===');
  filtered = dynamicFilter(products, {
    'category': 'Furniture',
    'inStock': true,
  });
  for (var product in filtered) {
    print('${product['name']} - \$${product['price']} - In Stock: ${product['inStock']}');
  }

  // Example 3: Filter by price range
  print('\n=== Filter by Price Range (\$50 - \$200) ===');
  filtered = dynamicFilter(products, {
    'price': {'min': 50, 'max': 200},
  });
  for (var product in filtered) {
    print('${product['name']} - \$${product['price']}');
  }

  // Example 4: Filter using custom function
  print('\n=== Filter using Custom Function (Price < \$100) ===');
  filtered = dynamicFilter(products, {
    'price': (price) => price < 100,
  });
  for (var product in filtered) {
    print('${product['name']} - \$${product['price']}');
  }

  // Example 5: Filter by multiple categories using list
  print('\n=== Filter by Multiple Categories ===');
  filtered = dynamicFilter(products, {
    'category': ['Electronics', 'Furniture'],
  });
  for (var product in filtered) {
    print('${product['name']} - Category: ${product['category']}');
  }

  // Example 6: Complex filter combining all types
  print('\n=== Complex Filter (Electronics, In Stock, Price \$50-\$400) ===');
  filtered = dynamicFilter(products, {
    'category': 'Electronics',
    'inStock': true,
    'price': {'min': 50, 'max': 400},
  });
  for (var product in filtered) {
    print('${product['name']} - \$${product['price']} - ${product['category']}');
  }

  // Example 7: Chain filters
  print('\n=== Chained Filters ===');
  var step1 = dynamicFilter(products, {'inStock': true});
  var step2 = dynamicFilter(step1, {'price': (price) => price <= 200});
  var step3 = dynamicFilter(step2, {'category': ['Electronics', 'Furniture']});

  print('Products in stock, under \$200, in Electronics or Furniture:');
  for (var product in step3) {
    print('${product['name']} - \$${product['price']} - ${product['category']}');
  }

  // Example 8: Filter with string pattern matching
  print('\n=== Filter by Name Pattern (contains "o") ===');
  filtered = dynamicFilter(products, {
    'name': (name) => name.toString().toLowerCase().contains('o'),
  });
  for (var product in filtered) {
    print('${product['name']}');
  }

  // Performance test with larger dataset
  print('\n=== Performance Test ===');
  final largeDataset = List.generate(10000, (i) => {
    'id': i,
    'value': i % 100,
    'category': i % 3 == 0 ? 'A' : (i % 3 == 1 ? 'B' : 'C'),
    'active': i % 2 == 0,
  });

  final stopwatch = Stopwatch()..start();
  final performanceFiltered = dynamicFilter(largeDataset, {
    'category': 'A',
    'active': true,
    'value': {'min': 25, 'max': 75},
  });
  stopwatch.stop();

  print('Filtered ${performanceFiltered.length} items from 10,000 in ${stopwatch.elapsedMilliseconds}ms');
}

