void main() {
  // Base configuration
  const double baseFontSize = 16.0;
  const double minFontSize = 12.0;
  const double maxFontSize = 32.0;

  // Simulated screen dimensions and user preferences
  final screenWidths = [320.0, 375.0, 414.0, 768.0, 1024.0, 1920.0];
  final userScalePreferences = [0.8, 1.0, 1.2, 1.5, 2.0];

  // Reference width for scaling calculations
  const double referenceWidth = 375.0; // iPhone 6/7/8 width

  // Font scale calculator function
  double calculateFontScale(double screenWidth, double userScale) {
    // Calculate responsive scale based on screen width
    double responsiveScale = screenWidth / referenceWidth;

    // Apply limits to responsive scaling
    if (responsiveScale < 0.85) responsiveScale = 0.85;
    if (responsiveScale > 1.5) responsiveScale = 1.5;

    // Combine responsive scale with user preference
    double combinedScale = responsiveScale * userScale;

    // Calculate final font size
    double scaledFontSize = baseFontSize * combinedScale;

    // Apply min/max constraints
    if (scaledFontSize < minFontSize) scaledFontSize = minFontSize;
    if (scaledFontSize > maxFontSize) scaledFontSize = maxFontSize;

    return scaledFontSize;
  }

