void main() {
  // Session storage
  Map<String, Session> sessions = {};
  Map<String, User> users = {
    'alice@example.com': User('alice@example.com', 'Alice Smith', 'pass123'),
    'bob@example.com': User('bob@example.com', 'Bob Jones', 'secret456'),
  };

  // Helper function to generate session ID
  String generateSessionId() {
    final now = DateTime.now().millisecondsSinceEpoch;
    final random = (now * 31).hashCode.abs();
    return 'sess_${now}_${random}';
  }

  // Helper function to check if session is expired
  bool isSessionExpired(Session session) {
    return DateTime.now().isAfter(session.expiresAt);
  }

  // Login function
  String? login(String email, String password) {
    print('\n[LOGIN] Attempting login for: $email');

    final user = users[email];
    if (user == null) {
      print('  ❌ User not found');
      return null;
    }

    if (user.password != password) {
      print('  ❌ Invalid password');
      return null;
    }

    // Create new session
    final sessionId = generateSessionId();
    final session = Session(
      id: sessionId,
      userId: email,
      createdAt: DateTime.now(),
      expiresAt: DateTime.now().add(Duration(hours: 2)),
      lastActivity: DateTime.now(),
      metadata: {
        'userAgent': 'Dart/2.0',
        'ipAddress': '192.168.1.100',
      },
    );

    sessions[sessionId] = session;
    print('  ✅ Login successful. Session ID: $sessionId');
    return sessionId;
  }

  // Validate session function
  bool validateSession(String? sessionId) {
    if (sessionId == null) {
      print('[VALIDATE] No session ID provided');
      return false;
    }

    final session = sessions[sessionId];
    if (session == null) {
      print('[VALIDATE] Session not found: $sessionId');
      return false;
    }

    if (isSessionExpired(session)) {
      print('[VALIDATE] Session expired: $sessionId');
      sessions.remove(sessionId);
      return false;
    }

    // Update last activity
    session.lastActivity = DateTime.now();
    print('[VALIDATE] Session valid: $sessionId');
    return true;
  }

  // Get user from session
  User? getUserFromSession(String? sessionId) {
    if (!validateSession(sessionId)) {
      return null;
    }

    final session = sessions[sessionId!];
    return users[session!.userId];
  }

  // Logout function
  void logout(String? sessionId) {
    print('\n[LOGOUT] Logging out session: $sessionId');
    if (sessionId != null && sessions.containsKey(sessionId)) {
      sessions.remove(sessionId);
      print('  ✅ Session removed successfully');
    } else {
      print('  ⚠️ Session not found');
    }
  }

  // Refresh session
  String? refreshSession(String? oldSessionId) {
    print('\n[REFRESH] Refreshing session: $oldSessionId');

    if (oldSessionId == null || !sessions.containsKey(oldSessionId)) {
      print('  ❌ Invalid session');
      return null;
    }

    final oldSession = sessions[oldSessionId]!;
    if (isSessionExpired(oldSession)) {
      print('  ❌ Cannot refresh expired session');
      sessions.remove(oldSessionId);
      return null;
    }

    // Create new session with same user
    final newSessionId = generateSessionId();
    final newSession = Session(
      id: newSessionId,
      userId: oldSession.userId,
      createdAt: DateTime.now(),
      expiresAt: DateTime.now().add(Duration(hours: 2)),
      lastActivity: DateTime.now(),
      metadata: oldSession.metadata,
    );

    sessions.remove(oldSessionId);
    sessions[newSessionId] = newSession;

    print('  ✅ Session refreshed. New ID: $newSessionId');
    return newSessionId;
  }

  // Clean expired sessions
  void cleanExpiredSessions() {
    print('\n[CLEANUP] Cleaning expired sessions...');
    final expiredKeys = <String>[];

    sessions.forEach((key, session) {
      if (isSessionExpired(session)) {
        expiredKeys.add(key);
      }
    });

    for (final key in expiredKeys) {
      sessions.remove(key);
      print('  🗑️ Removed expired session: $key');
    }

    print('  ✅ Cleanup complete. Removed ${expiredKeys.length} sessions');
  }

  // Display active sessions
  void displayActiveSessions() {
    print('\n[ACTIVE SESSIONS]');
    if (sessions.isEmpty) {
      print('  No active sessions');
      return;
    }

    sessions.forEach((id, session) {
      final user = users[session.userId];
      final remaining = session.expiresAt.difference(DateTime.now());
      print('  📍 Session: ${id.substring(0, 20)}...');
      print('     User: ${user?.name} (${user?.email})');
      print('     Expires in: ${remaining.inMinutes} minutes');
      print('     Last activity: ${session.lastActivity}');
    });
  }

  // Demo usage
  print('=== SESSION MANAGEMENT SYSTEM ===\n');

  // Test login with invalid credentials
  var sessionId = login('alice@example.com', 'wrongpass');

  // Test successful login
  sessionId = login('alice@example.com', 'pass123');

  // Test session validation
  print('\n[TEST] Validating session...');
  if (validateSession(sessionId)) {
    final user = getUserFromSession(sessionId);
    print('  Current user: ${user?.name} (${user?.email})');
  }

  // Test second user login
  final bobSession = login('bob@example.com', 'secret456');

  // Display active sessions
  displayActiveSessions();

  // Test session refresh
  final newSessionId = refreshSession(sessionId);

  // Display sessions after refresh
  displayActiveSessions();

  // Test logout
  logout(bobSession);

  // Create expired session for testing
  final expiredSession = Session(
    id: 'expired_session',
    userId: 'alice@example.com',
    createdAt: DateTime.now().subtract(Duration(hours: 3)),
    expiresAt: DateTime.now().subtract(Duration(hours: 1)),
    lastActivity: DateTime.now().subtract(Duration(hours: 1)),
    metadata: {},
  );
  sessions['expired_session'] = expiredSession;

  // Clean expired sessions
  cleanExpiredSessions();

  // Final display
  displayActiveSessions();

  // Test concurrent session limit
  print('\n[TEST] Testing concurrent session limit...');
  final maxSessionsPerUser = 3;
  var userSessionCount = 0;

  sessions.forEach((_, session) {
    if (session.userId == 'alice@example.com') {
      userSessionCount++;
    }
  });

  if (userSessionCount >= maxSessionsPerUser) {
    print('  ⚠️ Maximum concurrent sessions reached for user');
  } else {
    print('  ✅ User can create more sessions (${userSessionCount}/$maxSessionsPerUser)');
  }

  // Session statistics
  print('\n[STATISTICS]');
  print('  Total active sessions: ${sessions.length}');
  print('  Total registered users: ${users.length}');

  final sessionsByUser = <String, int>{};
  sessions.forEach((_, session) {
    sessionsByUser[session.userId] = (sessionsByUser[session.userId] ?? 0) + 1;
  });

  sessionsByUser.forEach((userId, count) {
    print('  User $userId: $count active session(s)');
  });
}

