void main() {
  // Sample directed, weighted graph represented as an adjacency list.
  // Each key is a node, and its value is a map of neighbor → edge weight.
  final Map<int, Map<int, double>> graph = {
    0: {1: 4, 2: 1},
    1: {3: 1},
    2: {1: 2, 3: 5},
    3: {}
  };

  final int source = 0;

  // Distance from source to each node (initialized to ∞).
  final Map<int, double> distances = {};
  // To reconstruct the shortest-path tree.
  final Map<int, int?> previous = {};
  // Track which nodes have been visited (finalized).
  final Set<int> visited = {};

  // Initialization
  for (var node in graph.keys) {
    distances[node] = double.infinity;
    previous[node] = null;
  }
  distances[source] = 0;

  // Main loop of Dijkstra's algorithm
  while (visited.length < graph.length) {
    // Select the unvisited node with the smallest tentative distance.
    int? u;
    double minDist = double.infinity;
    for (var node in graph.keys) {
      if (!visited.contains(node) && distances[node]! < minDist) {
        minDist = distances[node]!;
        u = node;
      }
    }
    // If no reachable unvisited node remains, we're done.
    if (u == null) break;

    visited.add(u);

    // Relaxation step for all neighbors of u.
    for (var entry in graph[u]!.entries) {
      var v = entry.key;
      var weight = entry.value;
      if (!visited.contains(v)) {
        var alt = distances[u]! + weight;
        if (alt < distances[v]!) {
          distances[v] = alt;
          previous[v] = u;
        }
      }
    }
  }

  // Helper to reconstruct the path from source to target.
  List<int> getPath(int target) {
    var path = <int>[];
    int? current = target;
    while (current != null) {
      path.insert(0, current);
      current = previous[current];
    }
    return path;
  }

  // Output the results.
  for (var node in graph.keys) {
    if (distances[node] == double.infinity) {
      print('Node $node is unreachable from source $source.');
    } else {
      var path = getPath(node);
      print(
        'Shortest path from $source to $node: '
        'distance = ${distances[node]}, path = $path'
      );
    }
  }
}

