    return;
  }

  final n = int.tryParse(args[0]);
  if (n == null || n < 0) {
    print('Please provide a non-negative integer.');
    return;
  }

  // Memoization cache: seed with base cases
  final memo = <int, int>{0: 0, 1: 1};

  // Recursive Fibonacci with memoization
  int fib(int k) {
    if (memo.containsKey(k)) {
      return memo[k]!;
    }
    final value = fib(k - 1) + fib(k - 2);
    memo[k] = value;
    return value;
  }

  print('Fibonacci($n) = ${fib(n)}');
}

