void main() {
  // Sample data
  List<int> weights = [2, 3, 4, 5];
  List<int> values  = [3, 4, 5, 6];
  int capacity = 5;
  int n = weights.length;

  // dp[i][w] will hold the max value for the first i items and capacity w
  var dp = List.generate(n + 1, (_) => List.filled(capacity + 1, 0));

  for (int i = 1; i <= n; i++) {
    for (int w = 0; w <= capacity; w++) {
      if (weights[i - 1] <= w) {
        int includeValue = values[i - 1] + dp[i - 1][w - weights[i - 1]];
        int excludeValue = dp[i - 1][w];
        dp[i][w] = includeValue > excludeValue ? includeValue : excludeValue;
      } else {
        dp[i][w] = dp[i - 1][w];
      }
    }
  }

  print('Maximum value achievable: ${dp[n][capacity]}');
