void main() {
  // Sample array to sort
  List<int> arr = [12, 11, 13, 5, 6, 7];

  // Heapify a subtree rooted with node i which is an index in list.
  // heapSize is size of heap
  void heapify(List<int> list, int heapSize, int rootIndex) {
    int largest = rootIndex;
    int leftChild = 2 * rootIndex + 1;
    int rightChild = 2 * rootIndex + 2;

    if (leftChild < heapSize && list[leftChild] > list[largest]) {
      largest = leftChild;
    }

    if (rightChild < heapSize && list[rightChild] > list[largest]) {
      largest = rightChild;
    }

    if (largest != rootIndex) {
      int temp = list[rootIndex];
      list[rootIndex] = list[largest];
      list[largest] = temp;
      heapify(list, heapSize, largest);
    }
  }

  // Main heapsort routine
  void heapSort(List<int> list) {
    int n = list.length;

    // Build max heap
    for (int i = n ~/ 2 - 1; i >= 0; i--) {
      heapify(list, n, i);
    }

    // One by one extract elements from heap
    for (int i = n - 1; i > 0; i--) {
      // Move current root to end
      int temp = list[0];
      list[0] = list[i];
      list[i] = temp;

      // call max heapify on the reduced heap
      heapify(list, i, 0);
    }
  }

  print('Original array: \$arr');
  heapSort(arr);
  print('Sorted array:   \$arr');
}

