void main() {
  // Number of cities
  const int n = 4;

  // Distance matrix: dist[i][j] is the distance from city i to city j
  List<List<int>> dist = [
    [0, 29, 20, 21],
    [29, 0, 15, 17],
    [20, 15, 0, 28],
    [21, 17, 28, 0],
  ];

  // Initial list of cities [0, 1, 2, ..., n-1]
  List<int> cities = List.generate(n, (i) => i);

  int bestCost = 1 << 30;  // A large initial cost
  List<int> bestRoute = [];

  // Swap helper
  void swap(List<int> arr, int i, int j) {
    final tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
  }

  // Recursive permutation generator
  void permute(List<int> arr, int l) {
    if (l == arr.length - 1) {
      // Compute tour cost, including return to start
      int cost = 0;
      for (int i = 0; i < arr.length - 1; i++) {
        cost += dist[arr[i]][arr[i + 1]];
      }
      cost += dist[arr[arr.length - 1]][arr[0]];

      if (cost < bestCost) {
        bestCost = cost;
        bestRoute = List.from(arr);
      }
    } else {
      for (int i = l; i < arr.length; i++) {
        swap(arr, l, i);
        permute(arr, l + 1);
        swap(arr, l, i);
      }
    }
  }

  // Run brute-force permutation search
  permute(cities, 0);

  // Display results
  String routeStr = bestRoute.join(' -> ') + ' -> ${bestRoute[0]}';
  print('Best route: $routeStr');
  print('Minimum cost: $bestCost');
}

