  // Change this matrix to test other graphs.
  List<List<int>> graph = [
    [0, 1, 1, 1],  // Vertex 0 is adjacent to 1, 2 and 3
    [1, 0, 1, 0],  // Vertex 1 is adjacent to 0 and 2
    [1, 1, 0, 1],  // Vertex 2 is adjacent to 0, 1 and 3
    [1, 0, 1, 0],  // Vertex 3 is adjacent to 0 and 2
  ];

  int n = graph.length;    // Number of vertices
  int m = 3;               // Number of colors available

  // colors[i] will hold the color assigned to vertex i (1..m), 0 means unassigned
  List<int> colors = List.filled(n, 0);

  // Check if it's safe to color vertex v with color c
  bool isSafe(int v, int c) {
    for (int i = 0; i < n; i++) {
      if (graph[v][i] == 1 && colors[i] == c) {
        return false;
      }
    }
    return true;
  }

  // Backtracking routine to assign colors to vertices one by one
  bool graphColoring(int v) {
    if (v == n) {
      // All vertices have been assigned a color
      return true;
    }
    // Try all colors for vertex v
    for (int c = 1; c <= m; c++) {
      if (isSafe(v, c)) {
        colors[v] = c;
        if (graphColoring(v + 1)) {
          return true;
        }
        // Backtrack
        colors[v] = 0;
      }
    }
    // No valid color found
    return false;
  }

  // Kick off the coloring from vertex 0
  if (graphColoring(0)) {
    print('Solution found with $m colors:');
    for (int i = 0; i < n; i++) {
      print('Vertex $i -> Color ${colors[i]}');
    }
  } else {
    print('No solution exists with $m colors.');
  }
}

