void main(List<String> args) {
  // Usage: dart run your_script.dart "text to search in" "pattern"
  if (args.length < 2) {
    print('Usage: dart run <script.dart> <text> <pattern>');
    return;
  }

  String text = args[0];
  String pattern = args[1];
  int n = text.length;
  int m = pattern.length;

  if (m > n) {
    print('Pattern length is greater than text length. No match.');
    return;
  }

  // Rabin–Karp parameters
  const int base = 256;                // Number of possible characters
  const int mod = 1000000007;          // A large prime for hash modulus

  // Precompute the high-order multiplier: (base^(m-1)) % mod
  int highMul = 1;
  for (int i = 0; i < m - 1; i++) {
    highMul = (highMul * base) % mod;
  }

  // Compute initial hashes for pattern and first window of text
  int hashPattern = 0;
  int hashWindow = 0;
  for (int i = 0; i < m; i++) {
    hashPattern = (hashPattern * base + pattern.codeUnitAt(i)) % mod;
    hashWindow  = (hashWindow  * base + text.codeUnitAt(i))    % mod;
  }

  List<int> matches = [];

  // Slide the window over text
  for (int i = 0; i <= n - m; i++) {
    // If the hash matches, double-check the actual substring
    if (hashPattern == hashWindow) {
      if (text.substring(i, i + m) == pattern) {
        matches.add(i);
      }
    }
    // Compute hash of next window
    if (i < n - m) {
      int leading = (text.codeUnitAt(i) * highMul) % mod;
      hashWindow = (hashWindow - leading) % mod;
      if (hashWindow < 0) hashWindow += mod;
      hashWindow = (hashWindow * base + text.codeUnitAt(i + m)) % mod;
    }
  }

  if (matches.isEmpty) {
    print('Pattern not found.');
  } else {
    print('Pattern found at positions: $matches');
  }
}

