  // Prompt the user for the upper bound
  stdout.write('Enter the maximum number to test for primes (>= 2): ');
  String? input = stdin.readLineSync();
  if (input == null) {
    print('No input provided. Exiting.');
    return;
  }

  final max = int.tryParse(input);
  if (max == null || max < 2) {
    print('Invalid input. Please enter an integer >= 2.');
    return;
  }

  // Initialize the sieve list: true means "is prime" until proven otherwise
  List<bool> isPrime = List<bool>.filled(max + 1, true);
  isPrime[0] = false;
  isPrime[1] = false;

  // Sieve of Eratosthenes
  for (int p = 2; p * p <= max; p++) {
    if (isPrime[p]) {
      for (int multiple = p * p; multiple <= max; multiple += p) {
        isPrime[multiple] = false;
      }
    }
  }

  // Collect and print primes
  print('Primes up to $max:');
  for (int i = 2; i <= max; i++) {
    if (isPrime[i]) {
      stdout.write('$i ');
    }
  }
  stdout.writeln();
}

