// A complete Dart script implementing Union-Find (Disjoint Set Union)
// with path compression and union by rank, all within main.

@pragma('vm:entry-point')
void main() {
  // Number of elements in the disjoint set
  int n = 10;

  // parent[i] points to the parent of i; if parent[i] == i, i is a root
  List<int> parent = List<int>.generate(n, (i) => i);

  // rank[i] is an upper bound on the height of the subtree rooted at i
  List<int> rank = List<int>.filled(n, 0);

  // Find with path compression
  int findSet(int x) {
    if (parent[x] != x) {
      parent[x] = findSet(parent[x]);
    }
    return parent[x];
  }

  // Union by rank
  void unionSets(int x, int y) {
    int rootX = findSet(x);
    int rootY = findSet(y);
    if (rootX == rootY) return;

    if (rank[rootX] < rank[rootY]) {
      parent[rootX] = rootY;
    } else if (rank[rootX] > rank[rootY]) {
      parent[rootY] = rootX;
    } else {
      parent[rootY] = rootX;
      rank[rootX]++;
    }
  }

  // Example usage
  unionSets(1, 2);
  unionSets(2, 3);
  unionSets(4, 5);
  unionSets(6, 7);
  unionSets(5, 6);

  // Display each element's root
  for (int i = 0; i < n; i++) {
    print('Element $i → Root ${findSet(i)}');
  }

  // Check connectivity
  print('Are 3 and 1 connected? ${findSet(3) == findSet(1)}');
  print('Are 3 and 4 connected? ${findSet(3) == findSet(4)}');
  print('Are 4 and 7 connected? ${findSet(4) == findSet(7)}');
}

