void main() {
  // Example array
  List<int> arr = [1, 3, 2, 7, 9, 11, 3, 5];
  int n = arr.length;

  // Compute maximum power of two needed
  int maxLog = (log(n) / log(2)).floor() + 1;

  // Build sparse table: st[k][i] = min over interval of length 2^k starting at i
  List<List<int>> st = List.generate(maxLog, (_) => List.filled(n, 0));
  for (int i = 0; i < n; i++) {
    st[0][i] = arr[i];
  }
  for (int k = 1; k < maxLog; k++) {
    for (int i = 0; i + (1 << k) <= n; i++) {
      st[k][i] = min(
        st[k - 1][i],
        st[k - 1][i + (1 << (k - 1))],
      );
    }
  }

  // Query function (0-based, inclusive)
  int query(int l, int r) {
    int length = r - l + 1;
    int k = (log(length) / log(2)).floor();
    return min(
      st[k][l],
      st[k][r - (1 << k) + 1],
    );
  }

  // Demonstration of some queries
  List<List<int>> queries = [
    [0, 2],
    [1, 5],
    [3, 7],
    [2, 4],
  ];
  for (var qr in queries) {
    int l = qr[0], r = qr[1];
    int ans = query(l, r);
    print('RMQ($l, $r) = $ans');
  }
}

