import 'dart:core';

@pragma('vm:entry-point')
void main() {
  // Sample directed graph represented as an adjacency list.
  // Each index is a vertex, and the list contains its outgoing neighbors.
  final graph = <List<int>>[
    [1],       // 0 → 1
    [2, 4, 5], // 1 → 2, 4, 5
    [3, 6],    // 2 → 3, 6
    [2, 7],    // 3 → 2, 7
    [0, 5],    // 4 → 0, 5
    [6],       // 5 → 6
    [5],       // 6 → 5
    [3, 6],    // 7 → 3, 6
  ];

  final int n = graph.length;
  final indices = List<int>.filled(n, -1);   // To record the order in which nodes are visited
  final lowlink = List<int>.filled(n, 0);    // To record the lowest index reachable from each node
  final onStack = List<bool>.filled(n, false);
  final stack = <int>[];
  final sccs = <List<int>>[];
  var indexCounter = 0;

  // The recursive function implementing Tarjan's DFS.
  void strongConnect(int v) {
    indices[v] = indexCounter;
    lowlink[v] = indexCounter;
    indexCounter++;
    stack.add(v);
    onStack[v] = true;

    for (final w in graph[v]) {
      if (indices[w] == -1) {
        // Node w has not yet been visited; recurse on it.
        strongConnect(w);
        lowlink[v] = lowlink[v] < lowlink[w] ? lowlink[v] : lowlink[w];
      } else if (onStack[w]) {
        // Node w is in the current SCC stack.
        lowlink[v] = lowlink[v] < indices[w] ? lowlink[v] : indices[w];
      }
    }

    // If v is a root node, pop the stack to generate an SCC.
    if (lowlink[v] == indices[v]) {
      final scc = <int>[];
      int w;
      do {
        w = stack.removeLast();
        onStack[w] = false;
        scc.add(w);
      } while (w != v);
      sccs.add(scc);
    }
  }

  // Run Tarjan's algorithm for each node that has not yet been visited.
  for (var v = 0; v < n; v++) {
    if (indices[v] == -1) {
      strongConnect(v);
    }
  }

  // Output the strongly connected components.
  print('Strongly Connected Components:');
  for (var component in sccs) {
    print(component);
  }
}

