import 'dart:io';

@pragma('vm:entry-point')
void main() {
  // Read number of vertices (n) and edges (m) from stdin
  var line = stdin.readLineSync();
  if (line == null) return;
  var parts = line.trim().split(RegExp(r'\s+')).map(int.parse).toList();
  if (parts.length < 2) {
    stderr.writeln('Invalid input. Expected: n m');
    return;
  }
  var n = parts[0];
  var m = parts[1];

  // Initialize adjacency lists for the graph and its reverse
  var graph = List<List<int>>.generate(n, (_) => []);
  var reverseGraph = List<List<int>>.generate(n, (_) => []);

  // Read edges
  for (var i = 0; i < m; i++) {
    var edgeLine = stdin.readLineSync();
    if (edgeLine == null) break;
    var edgeParts = edgeLine.trim().split(RegExp(r'\s+')).map(int.parse).toList();
    if (edgeParts.length < 2) continue;
    var u = edgeParts[0];
    var v = edgeParts[1];
    if (u < 0 || u >= n || v < 0 || v >= n) continue;
    graph[u].add(v);
    reverseGraph[v].add(u);
  }

  // First DFS: compute vertices in order of finish times
  var visited = List<bool>.filled(n, false);
  var order = <int>[];

  void dfs1(int u) {
    visited[u] = true;
    for (var v in graph[u]) {
      if (!visited[v]) dfs1(v);
    }
    order.add(u);
  }

  for (var i = 0; i < n; i++) {
    if (!visited[i]) dfs1(i);
  }

  // Second DFS on reversed graph: discover strongly connected components
  visited.fillRange(0, n, false);
  var sccs = <List<int>>[];

  void dfs2(int u, List<int> component) {
    visited[u] = true;
    component.add(u);
    for (var v in reverseGraph[u]) {
      if (!visited[v]) dfs2(v, component);
    }
  }

  for (var i = order.length - 1; i >= 0; i--) {
    var u = order[i];
    if (!visited[u]) {
      var component = <int>[];
      dfs2(u, component);
      sccs.add(component);
    }
  }

  // Output the strongly connected components
  for (var i = 0; i < sccs.length; i++) {
    stdout.writeln('SCC ${i + 1}: ${sccs[i]}');
  }
}

