import 'dart:math';

class Point {
  final double x, y;
  Point(this.x, this.y);
  @override
  String toString() => 'Point($x, $y)';
}

class Rectangle {
  final double x, y, halfWidth, halfHeight;
  Rectangle(this.x, this.y, this.halfWidth, this.halfHeight);

  bool contains(Point p) {
    return (p.x >= x - halfWidth &&
            p.x <= x + halfWidth &&
            p.y >= y - halfHeight &&
            p.y <= y + halfHeight);
  }

  bool intersects(Rectangle range) {
    return !(range.x - range.halfWidth > x + halfWidth ||
             range.x + range.halfWidth < x - halfWidth ||
             range.y - range.halfHeight > y + halfHeight ||
             range.y + range.halfHeight < y - halfHeight);
  }

  @override
  String toString() =>
      'Rectangle(center: ($x, $y), halfWidth: $halfWidth, halfHeight: $halfHeight)';
}

class Quadtree {
  final Rectangle boundary;
  final int capacity;
  final List<Point> points = [];
  bool divided = false;
  Quadtree? northeast, northwest, southeast, southwest;

  Quadtree(this.boundary, this.capacity);

  void subdivide() {
    final x = boundary.x;
    final y = boundary.y;
    final hw = boundary.halfWidth / 2;
    final hh = boundary.halfHeight / 2;

    northeast = Quadtree(Rectangle(x + hw, y - hh, hw, hh), capacity);
    northwest = Quadtree(Rectangle(x - hw, y - hh, hw, hh), capacity);
    southeast = Quadtree(Rectangle(x + hw, y + hh, hw, hh), capacity);
    southwest = Quadtree(Rectangle(x - hw, y + hh, hw, hh), capacity);

    divided = true;
  }

  void insert(Point p) {
    if (!boundary.contains(p)) {
      return;
    }
    if (points.length < capacity) {
      points.add(p);
    } else {
      if (!divided) {
        subdivide();
      }
      northeast!.insert(p);
      northwest!.insert(p);
      southeast!.insert(p);
      southwest!.insert(p);
    }
  }

  List<Point> query(Rectangle range, [List<Point>? found]) {
    found ??= [];
    if (!boundary.intersects(range)) {
      return found;
    }
    for (var p in points) {
      if (range.contains(p)) {
        found.add(p);
      }
    }
    if (divided) {
      northeast!.query(range, found);
      northwest!.query(range, found);
      southeast!.query(range, found);
      southwest!.query(range, found);
    }
    return found;
  }
}

@pragma('vm:entry-point')
void main() {
  // Define the boundary of the quadtree (center at 0,0, width/height 400)
  final boundary = Rectangle(0, 0, 200, 200);
  final qt = Quadtree(boundary, 4);

  // Insert 25 random points into the quadtree
  final rand = Random();
  for (var i = 0; i < 25; i++) {
    final x = rand.nextDouble() * 400 - 200;
    final y = rand.nextDouble() * 400 - 200;
    qt.insert(Point(x, y));
  }

  // Define a query range and retrieve points within it
  final range = Rectangle(0, 0, 50, 50);
  final pointsFound = qt.query(range);

  print('Points within range $range:');
  for (var p in pointsFound) {
    print('  $p');
  }
  print('Total points found: ${pointsFound.length}');
}

