@pragma('vm:entry-point')
void main() {
  // Bloom filter parameters
  const int m = 1000; // size of bit array
  const int k = 3;    // number of hash functions

  // Bit array initialized to false
  final List<bool> bitArray = List<bool>.filled(m, false);

  // FNV-1a 32-bit hash
  int fnv1a(String s) {
    const int fnvOffsetBasis = 0x811C9DC5;
    const int fnvPrime = 0x01000193;
    int hash = fnvOffsetBasis;
    for (int byte in s.codeUnits) {
      hash ^= byte;
      hash = (hash * fnvPrime) & 0xFFFFFFFF;
    }
    return hash;
  }

  // djb2 32-bit hash
  int djb2(String s) {
    int hash = 5381;
    for (int byte in s.codeUnits) {
      hash = ((hash << 5) + hash + byte) & 0xFFFFFFFF;
    }
    return hash;
  }

  // Generate k hash indices using double hashing
  List<int> _getIndices(String value) {
    final int h1 = fnv1a(value);
    final int h2 = djb2(value);
    final List<int> indices = <int>[];
    for (int i = 0; i < k; i++) {
      // (h1 + i * h2) mod m
      final int idx = (h1 + i * h2) % m;
      indices.add(idx < 0 ? idx + m : idx);
    }
    return indices;
  }

  // Add an element to the Bloom filter
  void add(String value) {
    for (final idx in _getIndices(value)) {
      bitArray[idx] = true;
    }
  }

  // Check membership: returns true if value may be in set, false if definitely not
  bool mightContain(String value) {
    for (final idx in _getIndices(value)) {
      if (!bitArray[idx]) {
        return false;
      }
    }
    return true;
  }

  // Demo: insert some items and test membership
  final List<String> itemsToAdd = ['apple', 'banana', 'cherry'];
  for (final item in itemsToAdd) {
    add(item);
    print('Added "$item" to Bloom filter.');
  }

  print('\nMembership tests:');
  final List<String> tests = ['apple', 'grape', 'cherry', 'orange'];
  for (final test in tests) {
    final result = mightContain(test)
        ? 'maybe in set'
        : 'definitely not in set';
    print('  "$test": $result');
  }
}

