  // Define integration parameters
  const int samples = 1000000;       // Number of random samples
  const double a = 0.0;              // Lower bound of integration
  const double b = pi;               // Upper bound of integration

  // Define the function to integrate: f(x) = sin(x)
  double f(double x) => sin(x);

  // Monte Carlo integration loop
  double sum = 0.0;
  for (int i = 0; i < samples; i++) {
    double x = a + random.nextDouble() * (b - a);
    sum += f(x);
  }

  // Estimate the integral as the average value times the interval length
  double integralEstimate = (b - a) * sum / samples;

  print('Estimating ∫ₐᵇ sin(x) dx with $samples samples:');
  print('  Interval: [$a, $b]');
  print('  Estimated integral = $integralEstimate');
  print('  Exact value        = 2.0');
}

