import 'dart:math';

@pragma('vm:entry-point')
void main() {
  final random = Random();

  // Rastrigin benchmark function in 2D
  double rastrigin(List<double> x) {
    return 10 * x.length +
        x.fold(0.0, (sum, xi) => sum + (xi * xi - 10 * cos(2 * pi * xi)));
  }

  final int dimensions = 2;
  final double minX = -5.12, maxX = 5.12;
  double temperature = 100.0;
  final double finalTemp = 1e-8;
  final double alpha = 0.99;

  // Initialize current solution randomly in the domain
  List<double> current = List.generate(
      dimensions, (_) => minX + random.nextDouble() * (maxX - minX));
  double currentEnergy = rastrigin(current);

  // Track the best solution found
  List<double> best = List.from(current);
  double bestEnergy = currentEnergy;

  // Simulated annealing main loop
  while (temperature > finalTemp) {
    // Inner loop: sample a number of neighbors at current temperature
    for (int i = 0; i < 100; i++) {
      // Generate a candidate by small perturbation
      List<double> candidate = current
          .map((xi) =>
              xi + (random.nextDouble() * 2 - 1) * (maxX - minX) * 0.01)
          .toList();

      // Clamp to bounds
      for (int j = 0; j < dimensions; j++) {
        if (candidate[j] < minX) candidate[j] = minX;
        if (candidate[j] > maxX) candidate[j] = maxX;
      }

      double candidateEnergy = rastrigin(candidate);
      double delta = candidateEnergy - currentEnergy;

      // Acceptance criterion
      if (delta < 0 || exp(-delta / temperature) > random.nextDouble()) {
        current = candidate;
        currentEnergy = candidateEnergy;
        if (currentEnergy < bestEnergy) {
          best = List.from(current);
          bestEnergy = currentEnergy;
        }
      }
    }
    // Cool down
    temperature *= alpha;
  }

  print('Best solution: $best');
  print('Best energy: $bestEnergy');
}

