import 'dart:math';

@pragma('vm:entry-point')
void main() {
  final rand = Random();
  const int chromosomeLength = 20;
  const int populationSize = 50;
  const double crossoverRate = 0.7;
  const double mutationRate = 0.01;
  const int generations = 100;

  // Initialize population with random bitstrings
  List<List<int>> population = List.generate(
    populationSize,
    (_) => List.generate(chromosomeLength, (_) => rand.nextBool() ? 1 : 0),
  );

  // Fitness function: count number of 1s
  int fitness(List<int> chrom) => chrom.fold(0, (sum, gene) => sum + gene);

  // Tournament selection
  List<int> selectParent() {
    const int tournamentSize = 3;
    List<List<int>> tournament = List.generate(
      tournamentSize,
      (_) => population[rand.nextInt(populationSize)],
    );
    tournament.sort((a, b) => fitness(b) - fitness(a));
    return List<int>.from(tournament.first);
  }

  // One-point crossover
  List<int> crossover(List<int> p1, List<int> p2) {
    if (rand.nextDouble() > crossoverRate) {
      return List<int>.from(rand.nextBool() ? p1 : p2);
    }
    int point = rand.nextInt(chromosomeLength);
    var child = <int>[];
    child.addAll(p1.sublist(0, point));
    child.addAll(p2.sublist(point));
    return child;
  }

  // Bit-flip mutation
  void mutate(List<int> chrom) {
    for (int i = 0; i < chrom.length; i++) {
      if (rand.nextDouble() < mutationRate) {
        chrom[i] = 1 - chrom[i];
      }
    }
  }

  // Evolutionary loop
  List<int> bestIndividual = [];
  int bestFit = -1;
  for (int gen = 0; gen < generations; gen++) {
    List<List<int>> newPopulation = [];
    while (newPopulation.length < populationSize) {
      var parent1 = selectParent();
      var parent2 = selectParent();
      var child = crossover(parent1, parent2);
      mutate(child);
      newPopulation.add(child);
    }
    population = newPopulation;

    // Track best individual
    var currentBest = population.reduce(
      (a, b) => fitness(a) > fitness(b) ? a : b,
    );
    var currentBestFit = fitness(currentBest);
    if (currentBestFit > bestFit) {
      bestFit = currentBestFit;
      bestIndividual = List<int>.from(currentBest);
    }

    print('Generation $gen: Best Fitness = $currentBestFit');
  }

  print('Best individual: $bestIndividual');
  print('Best fitness: $bestFit');
}

