void main() {
  // Example input list
  List<int> nums = [1, 2, 3];

  // This will hold all the generated permutations
  List<List<int>> permutations = [];

  // Backtracking helper defined as a local function
  void backtrack(List<int> current, List<bool> used) {
    if (current.length == nums.length) {
      // A full permutation has been built; add a copy to results
      permutations.add(List.from(current));
      return;
    }

    for (int i = 0; i < nums.length; i++) {
      if (used[i]) continue;
      // Choose nums[i]
      used[i] = true;
      current.add(nums[i]);
      // Explore further
      backtrack(current, used);
      // Undo choice
      current.removeLast();
      used[i] = false;
    }
  }

  // Kick off backtracking with an empty current list and all items unused
  backtrack([], List.filled(nums.length, false));

  // Print out all the permutations
  for (var perm in permutations) {
    print(perm);
  }
}

