import 'dart:math';

@pragma('vm:entry-point')
void main() {
  final int width = 20;
  final int height = 10;
  final Random rand = Random();

  // Directions as bit flags
  const int N = 1, S = 2, E = 4, W = 8;
  final Map<int, int> dx = {E: 1, W: -1, N: 0, S: 0};
  final Map<int, int> dy = {E: 0, W: 0, N: -1, S: 1};
  final Map<int, int> opposite = {N: S, S: N, E: W, W: E};

  // Initialize grid: every cell starts with all walls (N|S|E|W)
  final grid = List.generate(
    height,
    (_) => List.filled(width, N | S | E | W),
  );

  // Track visited cells
  final visited = List.generate(
    height,
    (_) => List.filled(width, false),
  );

  // DFS stack
  final stack = <Point<int>>[];

  // Start at (0,0)
  visited[0][0] = true;
  stack.add(Point(0, 0));

  while (stack.isNotEmpty) {
    final current = stack.last;
    final x = current.x;
    final y = current.y;

    // Gather unvisited neighbors
    final neighbors = <int>[];
    for (final dir in [N, S, E, W]) {
      final nx = x + dx[dir]!;
      final ny = y + dy[dir]!;
      if (nx >= 0 &&
          nx < width &&
          ny >= 0 &&
          ny < height &&
          !visited[ny][nx]) {
        neighbors.add(dir);
      }
    }

    if (neighbors.isNotEmpty) {
      // Choose a random unvisited neighbor
      final dir = neighbors[rand.nextInt(neighbors.length)];
      final nx = x + dx[dir]!;
      final ny = y + dy[dir]!;

      // Carve passage between current and neighbor
      grid[y][x] &= ~dir;
      grid[ny][nx] &= ~opposite[dir]!;

      visited[ny][nx] = true;
      stack.add(Point(nx, ny));
    } else {
      // Backtrack
      stack.removeLast();
    }
  }

  // Render the maze as ASCII
  // Top border
  print(' ' + List.filled(width, '_').join());

  for (int y = 0; y < height; y++) {
    var line = '|';
    for (int x = 0; x < width; x++) {
      // Floor: if there's a south wall, draw '_', else ' '
      line += (grid[y][x] & S != 0) ? '_' : ' ';
      // East wall: if present, draw '|', else draw '_' if there's a south wall, or ' '
      if (grid[y][x] & E != 0) {
        line += '|';
      } else {
        line += (grid[y][x] & S != 0) ? '_' : ' ';
      }
    }
    print(line);
  }
}

