@pragma('vm:entry-point')
void main() {
  // Maximum depth of the game tree
  const int MAX_DEPTH = 3;
  // A large value representing infinity
  const int INF = 1000000;
  // Leaf‐node scores for a complete binary tree of depth 3 (8 leaf nodes)
  List<int> scores = [3, 5, 6, 9, 1, 2, 0, -1];

  // Helper functions
  int max2(int a, int b) => a > b ? a : b;
  int min2(int a, int b) => a < b ? a : b;

  // Alpha–beta pruning implementation
  int alphaBeta(int depth, int nodeIndex, bool maximizingPlayer, int alpha, int beta) {
    // If we’ve reached the bottom, return the heuristic score
    if (depth == MAX_DEPTH) {
      return scores[nodeIndex];
    }

    if (maximizingPlayer) {
      int value = -INF;
      // Explore each child
      for (int i = 0; i < 2; i++) {
        value = max2(
          value,
          alphaBeta(depth + 1, nodeIndex * 2 + i, false, alpha, beta),
        );
        alpha = max2(alpha, value);
        // Beta cut‐off
        if (alpha >= beta) {
          break;
        }
      }
      return value;
    } else {
      int value = INF;
      for (int i = 0; i < 2; i++) {
        value = min2(
          value,
          alphaBeta(depth + 1, nodeIndex * 2 + i, true, alpha, beta),
        );
        beta = min2(beta, value);
        // Alpha cut‐off
        if (alpha >= beta) {
          break;
        }
      }
      return value;
    }
  }

  // Run alpha–beta from the root of the tree
  int bestValue = alphaBeta(0, 0, true, -INF, INF);
  print('The optimal value is: $bestValue');
}

