void main() {
  // Example directed graph represented as an adjacency list.
  // graph[u] contains all nodes v such that there is an edge u → v.
  List<List<int>> graph = [
    [1, 2], // Node 0 points to 1 and 2
    [2],    // Node 1 points to 2
    [0],    // Node 2 points to 0
    [2]     // Node 3 points to 2
  ];

  final int N = graph.length;

  // Build the list of incoming links for each node,
  // and compute out‐degrees at the same time.
  List<List<int>> incoming = List.generate(N, (_) => []);
  List<int> outDegree = List<int>.filled(N, 0);
  for (int u = 0; u < N; u++) {
    outDegree[u] = graph[u].length;
    for (int v in graph[u]) {
      incoming[v].add(u);
    }
  }

  const double dampingFactor = 0.85;  // Typical choice for PageRank
  const int maxIterations = 100;
  const double tolerance = 1e-6;

  // Initialize PageRank values to 1/N.
  List<double> rank = List<double>.filled(N, 1.0 / N);
  List<double> newRank = List<double>.filled(N, 0.0);

  for (int iter = 0; iter < maxIterations; iter++) {
    // 1) Compute total rank "leaking" from sink nodes (nodes with no out‐links).
    double sinkPR = 0.0;
    for (int i = 0; i < N; i++) {
      if (outDegree[i] == 0) {
        sinkPR += rank[i];
      }
    }

    // 2) Distribute ranks.
    for (int i = 0; i < N; i++) {
      // Teleportation contribution:
      newRank[i] = (1.0 - dampingFactor) / N;
      // Spread sink PR evenly:
      newRank[i] += dampingFactor * sinkPR / N;
      // Sum contributions from incoming links:
      double sum = 0.0;
      for (int j in incoming[i]) {
        sum += rank[j] / outDegree[j];
      }
      newRank[i] += dampingFactor * sum;
    }

    // 3) Check convergence.
    double diff = 0.0;
    for (int i = 0; i < N; i++) {
      diff += (newRank[i] - rank[i]).abs();
      rank[i] = newRank[i];
    }
    if (diff < tolerance) {
      print('Converged after $iter iterations.');
      break;
    }
    if (iter == maxIterations - 1) {
      print('Reached max iterations ($maxIterations) without full convergence.');
    }
  }

  // 4) Output final PageRank values.
  for (int i = 0; i < N; i++) {
    print('Node $i: ${rank[i].toStringAsFixed(6)}');
  }
}

