import 'dart:math';

@pragma('vm:entry-point')
void main() {
  // Sample 2D points: two clusters and one noise point
  List<List<double>> points = [
    [1.0, 2.0],
    [2.0, 2.0],
    [2.0, 3.0],
    [8.0, 8.0],
    [8.5, 8.1],
    [7.9, 8.2],
    [100.0, 100.0], // noise
  ];

  double eps = 1.5; // maximum neighborhood radius
  int minPts = 3;   // minimum number of points to form a dense region

  int n = points.length;
  List<int> labels = List.filled(n, 0); // 0 = unvisited, -1 = noise, >0 = cluster id
  int clusterId = 0;

  // Find indices of all points within eps of point at index `idx`.
  List<int> regionQuery(int idx) {
    List<int> neighbors = [];
    for (int i = 0; i < n; i++) {
      double dx = points[idx][0] - points[i][0];
      double dy = points[idx][1] - points[i][1];
      double dist = sqrt(dx * dx + dy * dy);
      if (dist <= eps) {
        neighbors.add(i);
      }
    }
    return neighbors;
  }

  // Expand cluster with id `cid` starting from point `idx` and its neighbors.
  void expandCluster(int idx, List<int> neighbors, int cid) {
    labels[idx] = cid;
    List<int> seeds = List<int>.from(neighbors);
    for (int i = 0; i < seeds.length; i++) {
      int current = seeds[i];
      if (labels[current] == -1) {
        labels[current] = cid; // change noise to border point
      }
      if (labels[current] != 0) {
        continue; // already processed in this or another cluster
      }
      labels[current] = cid;
      List<int> result = regionQuery(current);
      if (result.length >= minPts) {
        for (int r in result) {
          if (!seeds.contains(r)) {
            seeds.add(r);
          }
        }
      }
    }
  }

  // Main DBSCAN loop
  for (int i = 0; i < n; i++) {
    if (labels[i] != 0) {
      continue; // already processed
    }
    List<int> neighbors = regionQuery(i);
    if (neighbors.length < minPts) {
      labels[i] = -1; // mark as noise
    } else {
      clusterId++;
      expandCluster(i, neighbors, clusterId);
    }
  }

  // Collect and print clusters
  Map<int, List<int>> clusters = {};
  for (int i = 0; i < n; i++) {
    clusters.putIfAbsent(labels[i], () => []).add(i);
  }

  clusters.forEach((label, idxs) {
    if (label == -1) {
      print('Noise:');
    } else {
      print('Cluster $label:');
    }
    for (int idx in idxs) {
      print('  Point $idx -> ${points[idx]}');
    }
  });
}

