abstract class Shape {
  double get area;

  factory Shape(String type, double dimension) {
    if (type == 'circle') {
      return Circle(dimension);
    } else if (type == 'square') {
      return Square(dimension);
    } else {
      throw ArgumentError('Unknown shape type: $type');
    }
  }
}

class Circle implements Shape {
  final double radius;

  Circle(this.radius);

  @override
  double get area => 3.14159 * radius * radius;
}

class Square implements Shape {
  final double side;

  Square(this.side);

  @override
  double get area => side * side;
}

void main() {
  // Create a Circle using the factory constructor and print its area
  Shape circle = Shape('circle', 5);
  print('Circle area (radius 5): ${circle.area}');

  // Create a Square using the factory constructor and print its area
