@pragma('vm:entry-point')
void main(List<String> args) {
  // Nested function to perform wildcard matching.
  // Supports '?' for any single character and '*' for any sequence (including empty).
  bool wildcardMatch(String pattern, String text) {
    final int pLen = pattern.length;
    final int tLen = text.length;
    // dp[i][j] is true if pattern[0..i-1] matches text[0..j-1]
    List<List<bool>> dp = List.generate(
      pLen + 1,
      (_) => List<bool>.filled(tLen + 1, false),
    );

    dp[0][0] = true;
    // Patterns like '*', '**', '***', ... can match empty text
    for (int i = 1; i <= pLen; i++) {
      if (pattern[i - 1] == '*') {
        dp[i][0] = dp[i - 1][0];
      }
    }

    for (int i = 1; i <= pLen; i++) {
      for (int j = 1; j <= tLen; j++) {
        if (pattern[i - 1] == '*') {
          // '*' matches zero characters (dp[i-1][j]) or one more char (dp[i][j-1])
          dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
        } else if (pattern[i - 1] == '?' || pattern[i - 1] == text[j - 1]) {
          // '?' matches any single char, or exact character match
          dp[i][j] = dp[i - 1][j - 1];
        } else {
          dp[i][j] = false;
        }
      }
    }

    return dp[pLen][tLen];
  }

  if (args.length != 2) {
    print('Usage: dart run <script.dart> <pattern> <text>');
    return;
  }

  final String pattern = args[0];
  final String text = args[1];
  final bool isMatch = wildcardMatch(pattern, text);

  print('Pattern: "$pattern"');
  print('Text:    "$text"');
  print(isMatch ? 'Match' : 'No Match');
}

