class Complex {
  final int real;
  final int imag;

  Complex(this.real, this.imag);

  // Conjugate inverse (e.g., 2+4i -> 2-4i)
  Complex inv() => Complex(real, -imag);

  // Complex multiplication: (a+bi)*(c+di) = (ac−bd) + (ad+bc)i
  static Complex mult(Complex a, Complex b) {
    return Complex(
      a.real * b.real - a.imag * b.imag,
      a.real * b.imag + a.imag * b.real,
    );
  }

  @override
  String toString() => imag >= 0 
      ? '($real + ${imag}i)' 
      : '($real - ${-imag}i)';
}

