String ibwt(String transformedString) {
  // Step 1: Initialize parameters
  final n = transformedString.length;

  // Step 2: Create initial matrix with empty strings
  final matrix = List<String>.filled(n, '');

  // Step 3: Reconstruct matrix columns
  for (var col = 0; col < n; col++) {
    // Append corresponding character to each row
    for (var row = 0; row < n; row++) {
      matrix[row] = matrix[row] + transformedString[row];
    }

    // Sort lexicographically after each column addition
    matrix.sort();
  }

  // Step 4: Find and return original string
  const endMarker = '\u0000'; // BWT end marker (null char)

  for (final candidate in matrix) {
    if (candidate.isNotEmpty && candidate.endsWith(endMarker)) {
      // Return string without first character and end marker
      return candidate.substring(1, candidate.length - 1);
    }
  }

  return ''; // Fallback (should not occur in valid BWT)
}
```

