BigInt changes(int n, List<BigInt> coins) {
  // Step 1: Initialize DP table with zeros; dp[0] = 1 (base case)
  final dp = List<BigInt>.filled(n + 1, BigInt.zero);
  dp[0] = BigInt.one;

  // Save initial length to detect concurrent modifications
