  // Convert string to iterable of Unicode code points
  final runes = input.runes;

  // Apply ROT13 transformation to each character
  final transformed = runes.map((charCode) {
    if (charCode >= 65 && charCode <= 90) {    // Uppercase letters (A-Z)
