```dart
void heapify(List<num> heap, int n) {
  if (n <= 1) return;

  final size = n - 1;
  int current = (n - 2) ~/ 2;  // Last parent node index

  while (current >= 0) {
    int i = current;

    while (true) {
      final left = 2 * i + 1;   // Left child index
      if (left > size) break;

      final right = left + 1;   // Right child index
      int largest = left;

      // Compare children to find largest
      if (right <= size && heap[right] > heap[left]) {
        largest = right;
      }

      // Stop if parent >= largest child
      if (heap[i] >= heap[largest]) break;

      // Swap parent with largest child
      final temp = heap[i];
      heap[i] = heap[largest];
      heap[largest] = temp;

      i = largest;  // Move to swapped child position
    }

    current--;  // Process previous parent node
  }
}
```

