import 'dart:math';

int sigmaSum(int n) {
  // Handle non-positive inputs
  if (n <= 0) {
    return 0;
  }

  int sum = 0;
  final int limit = sqrt(n).floor();  // Integer square root of n

  // Iterate through potential divisors from 1 to sqrt(n)
  for (int k = 1; k <= limit; k++) {
    if (n % k != 0) continue;  // Skip non-divisors

    // Add divisor pair: k and n/k
    sum += k;
    final quotient = n ~/ k;

    // Avoid double-counting perfect squares
    if (quotient != k) {
      sum += quotient;
    }
  }

  return 2 * sum;  // Return twice the divisor sum
}
```

